String _supportTicketFormatAdminDateTime(DateTime value) {
  final hh = value.hour.toString().padLeft(2, '0');
  final mm = value.minute.toString().padLeft(2, '0');
  final dd = value.day.toString().padLeft(2, '0');
  final mo = value.month.toString().padLeft(2, '0');
  return '${value.year}-$mo-$dd $hh:$mm';
}

String? _pendingReferralCode;

void _captureIncomingReferralCode() {
  try {
    final candidates = <String>[
      Uri.base.toString(),
      WidgetsBinding.instance.platformDispatcher.defaultRouteName,
    ];
    for (final raw in candidates) {
      final value = raw.trim();
      if (value.isEmpty || value == '/') continue;
      final uri = Uri.tryParse(value);
      final code =
          (uri?.queryParameters['ref'] ??
                  uri?.queryParameters['referral'] ??
                  '')
              .trim();
      if (code.isNotEmpty) {
        _pendingReferralCode = code.toUpperCase();
        return;
      }
      final match = RegExp(
        r'(?:^|[/#?&])ref(?:erral)?[=/]([A-Za-z0-9_-]{4,64})',
        caseSensitive: false,
      ).firstMatch(value);
      if (match != null) {
        _pendingReferralCode = match.group(1)?.toUpperCase();
        return;
      }
    }
  } catch (_) {}
}

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  _captureIncomingReferralCode();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  runApp(const CryptoDoctorsHub());
}

final ValueNotifier<String> appThemePreference = ValueNotifier<String>(
  'current',
);

final ValueNotifier<_CdhConnectionState> _cdhConnectionState =
    ValueNotifier<_CdhConnectionState>(_CdhConnectionState.online);
bool _cdhConnectionProbeRunning = false;

enum _CdhConnectionState { online, slow, offline }

Future<void> _probeCdhConnection() async {
  if (_cdhConnectionProbeRunning) return;
  _cdhConnectionProbeRunning = true;
  final started = DateTime.now();
  try {
    // "No internet" is reserved for a real browser-offline signal on web.
    // When the browser is online, a slow/unreachable Firestore response is
    // reported as "Slow internet" instead of a false offline warning.
    if (kIsWeb && html.window.navigator.onLine == false) {
      _cdhConnectionState.value = _CdhConnectionState.offline;
      return;
    }

    try {
      await FirebaseFirestore.instance
          .collection('users')
          .limit(1)
          .get(const GetOptions(source: Source.server))
          .timeout(const Duration(seconds: 5));
    } on FirebaseException catch (e) {
      // A permission response still proves the Firebase server is reachable.
      if (e.code != 'permission-denied') rethrow;
    }

    final elapsed = DateTime.now().difference(started).inMilliseconds;
    _cdhConnectionState.value = elapsed >= 1800
        ? _CdhConnectionState.slow
        : _CdhConnectionState.online;
  } catch (_) {
    if (kIsWeb) {
      _cdhConnectionState.value = html.window.navigator.onLine == false
          ? _CdhConnectionState.offline
          : _CdhConnectionState.slow;
    } else {
      _cdhConnectionState.value = _CdhConnectionState.offline;
    }
  } finally {
    _cdhConnectionProbeRunning = false;
  }
}

class _CdhConnectionBanner extends StatelessWidget {
  const _CdhConnectionBanner();

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<_CdhConnectionState>(
      valueListenable: _cdhConnectionState,
      builder: (context, state, _) {
        if (state == _CdhConnectionState.online) return const SizedBox.shrink();
        final offline = state == _CdhConnectionState.offline;
        return IgnorePointer(
          child: SafeArea(
            bottom: false,
            child: Align(
              alignment: Alignment.topCenter,
              child: Container(
                margin: const EdgeInsets.fromLTRB(8, 4, 8, 0),
                padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 5),
                constraints: const BoxConstraints(maxWidth: 210),
                decoration: BoxDecoration(
                  color:
                      (offline
                              ? const Color(0xFFE53935)
                              : const Color(0xFFE39A16))
                          .withValues(alpha: .42),
                  borderRadius: BorderRadius.circular(20),
                  border: Border.all(
                    color: Colors.white.withValues(alpha: .18),
                  ),
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(
                      offline
                          ? Icons.wifi_off_rounded
                          : Icons.wifi_find_rounded,
                      size: 13,
                      color: Colors.white,
                    ),
                    const SizedBox(width: 5),
                    Flexible(
                      child: Text(
                        offline ? 'No internet' : 'Slow internet',
                        overflow: TextOverflow.ellipsis,
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                          color: Colors.white,
                          fontSize: 10.5,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}

Future<bool> _hasFirebaseAdminClaim(User user) async {
  try {
    final token = await user.getIdTokenResult(true);
    if (token.claims?['admin'] == true) return true;
  } catch (_) {}
  // Keep the app-side admin check aligned with the production authorization
  // model: Firebase custom claim first, then the protected admin/role fields
  // already used by the CDH backend. These fields are not client-self-editable
  // under firestore.rules.
  try {
    final data =
        (await FirebaseFirestore.instance
                .collection('users')
                .doc(user.uid)
                .get())
            .data() ??
        <String, dynamic>{};
    return data['admin'] == true || data['role'] == 'admin';
  } catch (_) {
    return false;
  }
}

DateTime? _premiumExpiryFromUserData(Map<String, dynamic>? data) {
  if (data == null) return null;
  final raw = (data['premiumExpiresAt'] ?? '').toString().trim();
  if (raw.isEmpty) return null;
  return DateTime.tryParse(raw);
}

bool _isActivePremiumUserData(Map<String, dynamic>? data) {
  if (data == null || data['isPremium'] != true) return false;
  final plan = (data['premiumPaymentPlan'] ?? '').toString().trim();
  if (plan == 'premium_one_time' || plan == 'premium_lifetime') return true;
  final expiry = _premiumExpiryFromUserData(data);
  return expiry == null || DateTime.now().isBefore(expiry);
}

class CryptoDoctorsHub extends StatefulWidget {
  const CryptoDoctorsHub({super.key});

  @override
  State<CryptoDoctorsHub> createState() => _CryptoDoctorsHubState();
}

class _CryptoDoctorsHubState extends State<CryptoDoctorsHub> {
  @override
  void initState() {
    super.initState();
    _loadSavedTheme();
    _testBackendAuthentication();
    _startCdhConnectionMonitor();
  }

  void _startCdhConnectionMonitor() {
    unawaited(_probeCdhConnection());
    Timer.periodic(const Duration(seconds: 10), (_) {
      unawaited(_probeCdhConnection());
    });
  }

  Future<void> _testBackendAuthentication() async {
    try {
      final result = await AutomaticPaymentService.testAuthenticatedIdentity();
      debugPrint(
        'CDH BACKEND AUTH TEST SUCCESS: uid=${result['uid']}, '
        'email=${result['email']}, '
        'emailVerified=${result['emailVerified']}, '
        'disabled=${result['disabled']}',
      );
    } catch (error) {
      debugPrint('CDH BACKEND AUTH TEST FAILED: $error');
    }
  }

  Future<void> _loadSavedTheme() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;
    try {
      final data = await ProfileService.loadUserProfile(user.uid);
      final saved = (data?['themePreference'] ?? 'current').toString();
      if (saved == 'light' || saved == 'dark' || saved == 'current') {
        appThemePreference.value = saved;
      }
    } catch (_) {}
  }

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<String>(
      valueListenable: appThemePreference,
      builder: (context, choice, _) {
        final selectedTheme = switch (choice) {
          'light' => AppTheme.light(),
          'dark' => AppTheme.matteBlack(),
          _ => AppTheme.dark(),
        };
        return MaterialApp(
          debugShowCheckedModeBanner: false,
          title: 'CRYPTO-DOCTORS-HUB',
          theme: selectedTheme,
          builder: (context, child) {
            final light = choice == 'light';
            return DefaultTextStyle.merge(
              style: TextStyle(
                color: light ? const Color(0xFF1A1A18) : Colors.white,
              ),
              child: IconTheme.merge(
                data: IconThemeData(
                  color: light ? const Color(0xFF4A463E) : Colors.white70,
                ),
                child: Stack(
                  children: [
                    child ?? const SizedBox.shrink(),
                    const Positioned.fill(child: _CdhConnectionBanner()),
                  ],
                ),
              ),
            );
          },
          home: const SplashScreen(),
        );
      },
    );
  }
}

