class SplashScreen extends StatefulWidget {
  const SplashScreen({super.key});

  @override
  State<SplashScreen> createState() => _SplashScreenState();
}

class _SplashScreenState extends State<SplashScreen>
    with SingleTickerProviderStateMixin {
  late AnimationController controller;

  @override
  void initState() {
    super.initState();

    // One cinematic build pass: the mark assembles first, then settles into a
    // slow orbital motion while the seven-second splash remains on screen.
    controller = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 7),
    )..forward();

    Timer(const Duration(seconds: 7), () {
      if (!mounted) return;

      Navigator.pushReplacement(
        context,
        MaterialPageRoute(builder: (_) => const AuthGate()),
      );
    });
  }

  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Stack(
        children: [
          const GalaxyBackground(
            animatePlanets: false,
            animateCryptoCoins: false,
            cinematicEntrance: true,
            animationDuration: Duration(seconds: 72),
          ),

          Center(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                _CryptoDoctorsSplashLogo(animation: controller),

                const SizedBox(height: 30),

                const Text(
                  'CRYPTO DOCTORS HUB',
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    color: Color(0xFFB9C3CF),
                    fontSize: 10,
                    fontWeight: FontWeight.w800,
                    letterSpacing: 2.6,
                  ),
                ),

                const SizedBox(height: 24),

                SizedBox(
                  width: 180,
                  child: LinearProgressIndicator(
                    minHeight: 3,
                    backgroundColor: Color(0x3359D7FF),
                    valueColor: AlwaysStoppedAnimation(AppTheme.neonGreen),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

// ============================================================
// AUTH SESSION GATE
// ============================================================

class AuthGate extends StatefulWidget {
  const AuthGate({super.key});

  @override
  State<AuthGate> createState() => _AuthGateState();
}

class _AuthGateState extends State<AuthGate> {
  @override
  void initState() {
    super.initState();
    _continueFromSession();
  }

  Future<void> _continueFromSession() async {
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      if (!mounted) return;

      final user = AuthService.currentUser;
      if (user == null) {
        Navigator.pushReplacement(
          context,
          MaterialPageRoute(builder: (_) => const LoginScreen()),
        );
        return;
      }

      final email = user.email ?? '';
      final isAdmin = await _hasFirebaseAdminClaim(user);
      Map<String, dynamic> userData = <String, dynamic>{};
      try {
        userData =
            (await FirebaseFirestore.instance
                    .collection('users')
                    .doc(user.uid)
                    .get())
                .data() ??
            <String, dynamic>{};
      } catch (_) {}
      final isPremium = _isActivePremiumUserData(userData);
      if (!mounted) return;

      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (_) => HubHome(
            accountEmail: email,
            isAdmin: isAdmin,
            isPremium: isPremium,
          ),
        ),
      );
    });
  }

  @override
  Widget build(BuildContext context) {
    return const Scaffold(body: Center(child: CircularProgressIndicator()));
  }
}

class _CryptoDoctorsSplashLogo extends StatelessWidget {
  final Animation<double> animation;

  const _CryptoDoctorsSplashLogo({required this.animation});

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: animation,
      builder: (context, _) {
        final p = animation.value;
        // Cinematic sequence:
        // 0.00-0.46: fragments fly in from outside the screen.
        // 0.38-0.64: the mark forms/evolves in the centre.
        // 0.62-1.00: the completed atom begins its slow orbital life.
        final assembly = Curves.easeOutCubic.transform(
          (p / 0.46).clamp(0.0, 1.0).toDouble(),
        );
        final formation = Curves.easeInOutCubic.transform(
          ((p - 0.30) / 0.34).clamp(0.0, 1.0).toDouble(),
        );
        final orbitProgress = Curves.easeInOut.transform(
          ((p - 0.62) / 0.38).clamp(0.0, 1.0).toDouble(),
        );
        final logoOpacity = Curves.easeOut.transform(
          ((p - 0.30) / 0.34).clamp(0.0, 1.0).toDouble(),
        );
        final logoScale = 0.42 + 0.46 * formation;
        final orbitScale =
            0.985 + 0.015 * math.sin(orbitProgress * math.pi * 2);

        return SizedBox(
          width: 380,
          height: 250,
          child: Stack(
            alignment: Alignment.center,
            clipBehavior: Clip.none,
            children: [
              Positioned.fill(
                child: IgnorePointer(
                  child: CustomPaint(
                    painter: _SplashAssemblyPainter(
                      progress: p,
                      assembly: assembly,
                      formation: formation,
                    ),
                  ),
                ),
              ),

              // Back orbital layer starts faintly during formation and becomes
              // fully alive only after the logo has assembled.
              Positioned.fill(
                child: CustomPaint(
                  painter: _SplashAtomOrbitPainter(
                    progress: orbitProgress,
                    front: false,
                    reveal: Curves.easeOut.transform(formation),
                  ),
                ),
              ),

              IgnorePointer(
                child: Opacity(
                  opacity: logoOpacity,
                  child: Transform.scale(
                    scale: logoScale * orbitScale,
                    child: Container(
                      width: 92,
                      height: 92,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        gradient: const RadialGradient(
                          colors: [
                            Color(0xDFFFFFFF),
                            Color(0x7759D7FF),
                            Color(0x00131C32),
                          ],
                          stops: [0.0, 0.25, 1.0],
                        ),
                        boxShadow: const [
                          BoxShadow(
                            color: Color(0x7759D7FF),
                            blurRadius: 28,
                            spreadRadius: 4,
                          ),
                          BoxShadow(color: Color(0x55FFD54A), blurRadius: 34),
                        ],
                      ),
                    ),
                  ),
                ),
              ),

              Opacity(
                opacity: logoOpacity,
                child: Transform.scale(
                  scale: logoScale * orbitScale,
                  child: _SplashTypewriterTitle(progress: formation),
                ),
              ),

              Positioned.fill(
                child: IgnorePointer(
                  child: CustomPaint(
                    painter: _SplashAtomOrbitPainter(
                      progress: orbitProgress,
                      front: true,
                      reveal: Curves.easeOut.transform(formation),
                    ),
                  ),
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

class _SplashTypewriterTitle extends StatelessWidget {
  final double progress;

  const _SplashTypewriterTitle({required this.progress});

  @override
  Widget build(BuildContext context) {
    // Medium-fast typewriter reveal: the lettering appears character by
    // character while the cinematic mark is forming, then holds cleanly.
    final typed = Curves.easeOut.transform(
      ((progress - 0.08) / 0.92).clamp(0.0, 1.0).toDouble(),
    );
    final showCursor = typed < 0.995;

    return SizedBox(
      width: 270,
      height: 48,
      child: Stack(
        alignment: Alignment.center,
        children: [
          ClipRect(
            child: Align(
              alignment: Alignment.centerLeft,
              widthFactor: typed.clamp(0.0, 1.0),
              child: ShaderMask(
                blendMode: BlendMode.srcIn,
                shaderCallback: (bounds) => const LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: [
                    Color(0xFFFFFFFF),
                    Color(0xFFE7EBF0),
                    Color(0xFF9EA7B2),
                    Color(0xFFF8FAFC),
                  ],
                  stops: [0.0, 0.34, 0.68, 1.0],
                ).createShader(bounds),
                child: Text(
                  'CRYPTO DOCTORS',
                  maxLines: 1,
                  softWrap: false,
                  textAlign: TextAlign.left,
                  style: TextStyle(
                    color: AppTheme.textPrimary,
                    fontSize: 26,
                    fontWeight: FontWeight.w900,
                    letterSpacing: 2.8,
                    height: 1.0,
                    shadows: [
                      Shadow(color: Color(0x88FFFFFF), blurRadius: 10),
                      Shadow(color: Color(0x665D6875), blurRadius: 18),
                    ],
                  ),
                ),
              ),
            ),
          ),
          if (showCursor)
            Positioned(
              left: 135 * typed,
              child: Container(
                width: 2,
                height: 27,
                decoration: const BoxDecoration(
                  color: Color(0xFFF5F7FA),
                  boxShadow: [
                    BoxShadow(
                      color: Color(0x99FFFFFF),
                      blurRadius: 8,
                      spreadRadius: 1,
                    ),
                  ],
                ),
              ),
            ),
        ],
      ),
    );
  }
}

class _SplashAssemblyPainter extends CustomPainter {
  final double progress;
  final double assembly;
  final double formation;

  const _SplashAssemblyPainter({
    required this.progress,
    required this.assembly,
    required this.formation,
  });

  static const List<Offset> _targets = [
    Offset(-150, -72),
    Offset(-132, -38),
    Offset(-112, -12),
    Offset(-92, 18),
    Offset(-72, 48),
    Offset(-48, -54),
    Offset(-26, -28),
    Offset(-8, 54),
    Offset(16, -58),
    Offset(38, 28),
    Offset(62, -46),
    Offset(84, 12),
    Offset(108, 42),
    Offset(132, -18),
    Offset(150, 64),
    Offset(-146, 56),
    Offset(-120, 2),
    Offset(-88, -62),
    Offset(-56, 70),
    Offset(-18, 4),
    Offset(20, 6),
    Offset(58, 62),
    Offset(92, -68),
    Offset(126, -4),
    Offset(-174, 30),
    Offset(174, -36),
    Offset(-30, 88),
    Offset(44, -86),
    Offset(-188, -78),
    Offset(188, 76),
    Offset(12, 92),
    Offset(-8, -92),
  ];

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height / 2);
    final easedAssembly = Curves.easeOutBack.transform(
      assembly.clamp(0.0, 1.0),
    );

    // The pieces start beyond the visible logo area on multiple axes, then
    // converge into the centre as if the mark is being constructed in space.
    for (int i = 0; i < _targets.length; i++) {
      final target = center + _targets[i];
      final side = i % 4;
      final outside = switch (side) {
        0 => Offset(-size.width * 0.72 - i * 4.0, -70 + i * 9.0),
        1 => Offset(size.width * 0.72 + i * 3.5, 55 - i * 7.0),
        2 => Offset(35 + i * 8.0, -size.height * 0.78 - i * 4.0),
        _ => Offset(-45 - i * 7.0, size.height * 0.78 + i * 5.0),
      };

      final stagger = (i % 5) * 0.035;
      final local = ((easedAssembly - stagger) / (1.0 - stagger))
          .clamp(0.0, 1.0)
          .toDouble();
      final localEase = Curves.easeOutCubic.transform(local);
      final wobble = Offset(
        math.sin(progress * math.pi * 7 + i * 1.7) * (1.0 - localEase) * 12,
        math.cos(progress * math.pi * 6 + i * 1.3) * (1.0 - localEase) * 9,
      );
      final point = Offset.lerp(outside, target, localEase)! + wobble;

      final alpha = (0.12 + 0.88 * localEase) * (1.0 - formation * 0.72);
      final color = i.isEven
          ? const Color(0xFF8FE8FF)
          : const Color(0xFFFFD86A);

      final glow = Paint()
        ..color = color.withValues(alpha: alpha * 0.24)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6);
      canvas.drawCircle(point, 5.0 - 1.7 * localEase, glow);

      final core = Paint()..color = color.withValues(alpha: alpha);
      canvas.drawCircle(point, 1.15 + 1.0 * localEase, core);
    }

    // A compact burst of construction energy appears immediately before the
    // completed logo settles into its orbital motion.
    final burst = Curves.easeOut.transform(
      ((formation - 0.55) / 0.45).clamp(0.0, 1.0).toDouble(),
    );
    if (burst > 0) {
      final burstPaint = Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 0.9
        ..color = const Color(0xFFBFEFFF).withValues(alpha: 0.45 * (1 - burst));
      canvas.drawCircle(center, 30 + burst * 54, burstPaint);
      canvas.drawCircle(
        center,
        18 + burst * 30,
        burstPaint
          ..color = const Color(0xFFFFD86A)
              .withValues(alpha: 0.20 * (1 - burst)),
      );
    }
  }

  @override
  bool shouldRepaint(covariant _SplashAssemblyPainter oldDelegate) =>
      oldDelegate.progress != progress ||
      oldDelegate.assembly != assembly ||
      oldDelegate.formation != formation;
}

