class _SplashAtomOrbitPainter extends CustomPainter {
  final double progress;
  final bool front;
  final double reveal;

  const _SplashAtomOrbitPainter({
    required this.progress,
    required this.front,
    this.reveal = 1.0,
  });

  static List<_SplashOrbit> _orbits = [
    _SplashOrbit(224, 39, -0.12, 0.00, 0.14, AppTheme.neonGreen),
    _SplashOrbit(212, 52, 0.30, 0.31, 0.12, AppTheme.luxuryGold),
    _SplashOrbit(200, 66, -0.52, 0.61, 0.13, Color(0xFF6D78FF)),
    _SplashOrbit(188, 79, 0.82, 0.18, 0.11, AppTheme.neonGreen),
    _SplashOrbit(180, 94, -0.96, 0.49, 0.12, AppTheme.luxuryGold),
    _SplashOrbit(170, 106, 0.15, 0.79, 0.13, Color(0xFF7F91FF)),
    _SplashOrbit(160, 61, -1.18, 0.37, 0.11, AppTheme.neonGreen),
    _SplashOrbit(150, 87, 0.56, 0.67, 0.12, AppTheme.luxuryGold),
    _SplashOrbit(140, 112, -0.35, 0.08, 0.13, Color(0xFF65B8FF)),
    _SplashOrbit(128, 73, 1.05, 0.55, 0.11, AppTheme.luxuryGold),
  ];

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height / 2);

    canvas.save();
    canvas.translate(center.dx, center.dy);

    // The same smooth orbital language as the Alpha Den portal:
    // continuous elliptical motion with no abrupt direction changes.
    for (int i = 0; i < _orbits.length; i++) {
      final orbit = _orbits[i];

      // Five paths sit behind the logo and five cross the foreground.
      final isFront = i >= 5;
      if (isFront != front) continue;

      // All orbital paths now travel clockwise (rightward on screen),
      // with a deliberately slow cinematic pace.
      const direction = 1.0;
      final rotation =
          orbit.baseRotation + direction * progress * math.pi * 2 * orbit.speed;

      canvas.save();
      canvas.rotate(rotation);

      final rect = Rect.fromCenter(
        center: Offset.zero,
        width: orbit.width,
        height: orbit.height,
      );

      final opacity = front ? 0.58 : 0.25;

      final ringPaint = Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 0.72
        ..isAntiAlias = true
        ..color = orbit.color.withValues(alpha: opacity);

      canvas.drawArc(
        rect,
        -math.pi / 2,
        math.pi * 2 * reveal,
        false,
        ringPaint,
      );

      // A small atmospheric glow follows each thin orbital path.
      final glowPaint = Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.8
        ..isAntiAlias = true
        ..color = orbit.color.withValues(alpha: front ? 0.055 : 0.025);

      canvas.drawArc(
        rect,
        -math.pi / 2,
        math.pi * 2 * reveal,
        false,
        glowPaint,
      );

      // Orbiting particle / electron.
      final theta =
          orbit.phase * math.pi * 2 +
          direction * progress * math.pi * 2 * orbit.speed;

      final electron = Offset(
        math.cos(theta) * orbit.width / 2,
        math.sin(theta) * orbit.height / 2,
      );

      final glow = Paint()
        ..color = orbit.color.withValues(alpha: (front ? 0.22 : 0.10) * reveal)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 5);

      canvas.drawCircle(electron, front ? 5.0 : 4.0, glow);

      final core = Paint()
        ..color = orbit.color.withValues(alpha: (front ? 0.95 : 0.62) * reveal);

      canvas.drawCircle(electron, front ? 1.9 : 1.45, core);

      canvas.restore();
    }

    // Tiny central particles give the logo the same living,
    // atomic energy as the reference image without overpowering the text.
    for (int i = 0; i < 8; i++) {
      final angle = progress * math.pi * 2 * 0.20 + i * math.pi / 4;
      final radius = 31.0 + (i % 3) * 4.0;

      final p = Offset(
        math.cos(angle) * radius,
        math.sin(angle) * radius * 0.54,
      );

      final color = i.isEven ? AppTheme.neonGreen : AppTheme.luxuryGold;

      final particleGlow = Paint()
        ..color = color.withValues(alpha: (front ? 0.18 : 0.08) * reveal)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4);

      canvas.drawCircle(p, 3.5, particleGlow);

      final particle = Paint()
        ..color = color.withValues(alpha: (front ? 0.82 : 0.38) * reveal);

      canvas.drawCircle(p, 1.15, particle);
    }

    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _SplashAtomOrbitPainter oldDelegate) {
    return oldDelegate.progress != progress ||
        oldDelegate.front != front ||
        oldDelegate.reveal != reveal;
  }
}

class _SplashOrbit {
  final double width;
  final double height;
  final double baseRotation;
  final double phase;
  final double speed;
  final Color color;

  const _SplashOrbit(
    this.width,
    this.height,
    this.baseRotation,
    this.phase,
    this.speed,
    this.color,
  );
}

