class LoginScreen extends StatefulWidget {
  const LoginScreen({super.key});

  @override
  State<LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends State<LoginScreen> {
  final emailController = TextEditingController();
  final passwordController = TextEditingController();

  bool _isSigningIn = false;

  @override
  void dispose() {
    emailController.dispose();
    passwordController.dispose();
    super.dispose();
  }

  Future<void> enterApp() async {
    if (_isSigningIn) return;

    final email = emailController.text.trim();
    final password = passwordController.text;

    if (email.isEmpty || password.isEmpty) {
      _showAuthMessage(
        'Sign-in required',
        'Please enter your email and password to continue.',
      );
      return;
    }

    setState(() => _isSigningIn = true);

    try {
      final credential = await AuthService.signIn(
        email: email,
        password: password,
      );

      final user = credential.user;
      if (user == null) {
        throw FirebaseAuthException(
          code: 'user-null',
          message: 'Authentication could not be completed.',
        );
      }

      final authenticatedEmail = user.email ?? email;
      final isAdmin = await _hasFirebaseAdminClaim(user);

      if (!mounted) return;

      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (_) =>
              HubHome(accountEmail: authenticatedEmail, isAdmin: isAdmin),
        ),
      );
    } on FirebaseAuthException catch (e) {
      if (!mounted) return;

      String title;
      String message;
      switch (e.code) {
        case 'invalid-credential':
        case 'wrong-password':
        case 'user-not-found':
          title = 'Sign-in failed';
          message = 'We couldnÃ¢â‚¬â„¢t verify those credentials. Check your email and password, then try again.';
          break;
        case 'invalid-email':
          title = 'Invalid email address';
          message = 'Please check your email address and try again.';
          break;
        case 'user-disabled':
          title = 'Account unavailable';
          message = 'This account is currently unavailable. Please contact support if you need assistance.';
          break;
        case 'invalid-referral':
          title = 'Referral code not found';
          message = 'Please check the referral code and try again, or leave it blank.';
          break;
        case 'too-many-requests':
          title = 'Please try again later';
          message = 'Too many sign-in attempts were made. Please wait a moment and try again.';
          break;
        case 'network-request-failed':
          title = 'Connection problem';
          message = 'We couldnÃ¢â‚¬â„¢t reach the secure sign-in service. Check your connection and try again.';
          break;
        default:
          title = 'Sign-in unavailable';
          message = 'We couldnÃ¢â‚¬â„¢t complete your secure sign-in. Please try again in a moment.';
      }

      _showAuthMessage(title, message);
    } catch (_) {
      if (!mounted) return;
      _showAuthMessage(
        'Sign-in unavailable',
        'We couldnÃ¢â‚¬â„¢t complete your secure sign-in. Please try again in a moment.',
      );
    } finally {
      if (mounted) setState(() => _isSigningIn = false);
    }
  }

  void _showAuthMessage(String title, String message) {
    if (!mounted) return;

    final messenger = ScaffoldMessenger.of(context);
    messenger
      ..hideCurrentSnackBar()
      ..showSnackBar(
        SnackBar(
          behavior: SnackBarBehavior.floating,
          margin: const EdgeInsets.fromLTRB(16, 0, 16, 18),
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
          duration: const Duration(seconds: 4),
          backgroundColor: AppTheme.adaptiveSurface(Color(0xFF151A1F)),
          elevation: 8,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
            side: const BorderSide(color: Color(0xFF26343C), width: 1),
          ),
          content: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                width: 34,
