class SignUpScreen extends StatefulWidget {
  const SignUpScreen({super.key});

  @override
  State<SignUpScreen> createState() => _SignUpScreenState();
}

class _SignUpScreenState extends State<SignUpScreen> {
  final emailController = TextEditingController();
  final passwordController = TextEditingController();
  final confirmPasswordController = TextEditingController();
  final referralController = TextEditingController();

  bool _isCreatingAccount = false;
  bool _obscurePassword = true;
  bool _obscureConfirmPassword = true;

  @override
  void initState() {
    super.initState();
    try {
      final params = Uri.base.queryParameters;
      final incoming = (params['ref'] ?? params['referral'] ?? '').trim();
      if (incoming.isNotEmpty) {
        referralController.text = incoming.toUpperCase();
      } else if ((_pendingReferralCode ?? '').isNotEmpty) {
        referralController.text = _pendingReferralCode!;
      }
    } catch (_) {}
  }

  @override
  void dispose() {
    emailController.dispose();
    passwordController.dispose();
    confirmPasswordController.dispose();
    referralController.dispose();
    super.dispose();
  }

  Future<void> _createAccount() async {
    if (_isCreatingAccount) return;

    final email = emailController.text.trim();
    final password = passwordController.text;
    final confirmPassword = confirmPasswordController.text;

    if (email.isEmpty || password.isEmpty || confirmPassword.isEmpty) {
      _showMessage(
        'Account details required',
        'Please complete all fields to create your account.',
      );
      return;
    }

    if (password.length < 6) {
      _showMessage(
        'Password too short',
        'Choose a password with at least 6 characters.',
      );
      return;
    }

    if (password != confirmPassword) {
      _showMessage(
        'Passwords do not match',
        'Please make sure both password fields match.',
      );
      return;
    }

    setState(() => _isCreatingAccount = true);

    try {
      final credential = await AuthService.createAccount(
        email: email,
        password: password,
      );

      final user = credential.user;
      if (user == null) {
        throw FirebaseAuthException(
          code: 'user-null',
          message: 'Account creation could not be completed.',
        );
      }

      final enteredReferral = referralController.text.trim().toUpperCase();
      String? referredByUid;
      if (enteredReferral.isNotEmpty) {
        final referralQuery = await FirebaseFirestore.instance
            .collection('users')
            .where('referralCode', isEqualTo: enteredReferral)
            .limit(1)
            .get();
        if (referralQuery.docs.isNotEmpty &&
            referralQuery.docs.first.id != user.uid) {
          referredByUid = referralQuery.docs.first.id;
        } else {
          await user.delete();
          throw FirebaseAuthException(
            code: 'invalid-referral',
            message: 'That referral code could not be verified.',
          );
        }
      }

      final ownReferralCode = ProfileService.referralCodeForUid(user.uid);
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
        'uid': user.uid,
        'email': user.email ?? email,
        'createdAt': FieldValue.serverTimestamp(),
        'role': 'user',
        'displayName': '',
        'referralCode': ownReferralCode,
        'referredByUid': referredByUid,
        'referredByCode': referredByUid == null ? '' : enteredReferral,
      });

      _pendingReferralCode = null;
      final isAdmin = await _hasFirebaseAdminClaim(user);

      if (!mounted) return;
      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (_) =>
              HubHome(accountEmail: user.email ?? email, isAdmin: isAdmin),
        ),
      );
    } on FirebaseAuthException catch (e) {
      if (!mounted) return;

      String title;
      String message;

      switch (e.code) {
        case 'email-already-in-use':
          title = 'Account already exists';
          message = 'An account is already registered with this email. Try signing in instead.';
          break;
        case 'invalid-email':
          title = 'Invalid email address';
          message = 'Please enter a valid email address and try again.';
          break;
        case 'weak-password':
          title = 'Choose a stronger password';
          message =
              'Please choose a stronger password with at least 6 characters.';
          break;
        case 'network-request-failed':
          title = 'Connection problem';
          message = 'We couldnÃ¢â‚¬â„¢t reach the secure account service. Check your connection and try again.';
          break;
        case 'too-many-requests':
          title = 'Please try again later';
          message = 'Too many account requests were made. Please wait a moment and try again.';
          break;
        default:
          title = 'Account creation unavailable';
          message = 'We couldnÃ¢â‚¬â„¢t create your account right now. Please try again in a moment.';
      }

      _showMessage(title, message);
    } catch (_) {
      if (!mounted) return;
      _showMessage(
        'Account creation unavailable',
        'We couldnÃ¢â‚¬â„¢t create your account right now. Please try again in a moment.',
      );
    } finally {
      if (mounted) setState(() => _isCreatingAccount = false);
    }
  }

  void _showMessage(String title, String message, {bool isSuccess = false}) {
    if (!mounted) return;

    final messenger = ScaffoldMessenger.of(context);
    messenger
      ..hideCurrentSnackBar()
      ..showSnackBar(
        SnackBar(
          behavior: SnackBarBehavior.floating,
          margin: const EdgeInsets.fromLTRB(16, 0, 16, 18),
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
          duration: const Duration(seconds: 4),
          backgroundColor: AppTheme.adaptiveSurface(Color(0xFF151A1F)),
          elevation: 8,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
            side: BorderSide(
              color: isSuccess
                  ? const Color(0x6659D7FF)
                  : const Color(0xFF26343C),
              width: 1,
            ),
          ),
          content: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                width: 34,
                height: 34,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: isSuccess
                      ? const Color(0x1A59D7FF)
                      : AppTheme.adaptiveSurface(Color(0xFF0E242B)),
                  border: Border.all(
                    color: isSuccess
                        ? AppTheme.neonGreen
                        : const Color(0xFF5CD6FF),
                    width: 1,
                  ),
                ),
                child: Icon(
                  isSuccess
                      ? Icons.check_rounded
                      : Icons.person_add_alt_1_outlined,
                  color: isSuccess
                      ? AppTheme.neonGreen
                      : const Color(0xFF5CD6FF),
                  size: 18,
                ),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      title,
                      style: TextStyle(
                        color: AppTheme.textPrimary,
                        fontSize: 15,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    const SizedBox(height: 3),
                    Text(
                      message,
                      style: const TextStyle(
                        color: Color(0xFFB7C0C6),
                        fontSize: 13,
                        height: 1.25,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Stack(
        children: [
          const GalaxyBackground(),
          SafeArea(
            child: Center(
              child: SingleChildScrollView(
                padding: const EdgeInsets.all(24),
                child: ConstrainedBox(
                  constraints: const BoxConstraints(maxWidth: 480),
                  child: Card(
                    child: Padding(
                      padding: const EdgeInsets.all(26),
                      child: Column(
                        children: [
                          Container(
                            width: 72,
                            height: 72,
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
                              color: const Color(0xFF101812),
                              border: Border.all(color: AppTheme.neonGreen),
                              boxShadow: const [
                                BoxShadow(
                                  color: Color(0x6659D7FF),
                                  blurRadius: 22,
                                ),
                              ],
                            ),
                            child: Icon(
                              Icons.person_add_alt_1_rounded,
                              size: 36,
                              color: AppTheme.luxuryGold,
                            ),
                          ),
                          const SizedBox(height: 18),
                          Text(
                            'CREATE ACCOUNT',
                            style: TextStyle(
                              color: AppTheme.luxuryGold,
                              fontSize: 24,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                          const SizedBox(height: 8),
                          Text(
                            'Create your secure CRYPTO-DOCTORS-HUB account',
                            textAlign: TextAlign.center,
                            style: TextStyle(color: AppTheme.textMuted),
                          ),
                          const SizedBox(height: 24),
                          TextField(
                            controller: emailController,
                            keyboardType: TextInputType.emailAddress,
                            textInputAction: TextInputAction.next,
                            decoration: const InputDecoration(
                              labelText: 'Email',
                              prefixIcon: Icon(Icons.email_outlined),
                            ),
                          ),
                          const SizedBox(height: 14),
                          TextField(
                            controller: passwordController,
                            obscureText: _obscurePassword,
                            textInputAction: TextInputAction.next,
                            decoration: InputDecoration(
                              labelText: 'Password',
                              prefixIcon: const Icon(
                                Icons.lock_outline_rounded,
                              ),
                              suffixIcon: IconButton(
                                tooltip: 'Show or hide password',
                                onPressed: () {
                                  setState(() {
                                    _obscurePassword = !_obscurePassword;
                                  });
                                },
                                icon: Icon(
                                  _obscurePassword
                                      ? Icons.visibility_outlined
                                      : Icons.visibility_off_outlined,
                                ),
                              ),
                            ),
                          ),
                          const SizedBox(height: 14),
                          TextField(
                            controller: confirmPasswordController,
                            obscureText: _obscureConfirmPassword,
                            textInputAction: TextInputAction.done,
                            onSubmitted: (_) => _createAccount(),
                            decoration: InputDecoration(
                              labelText: 'Confirm password',
                              prefixIcon: const Icon(Icons.lock_reset_outlined),
                              suffixIcon: IconButton(
                                tooltip: 'Show or hide password',
                                onPressed: () {
                                  setState(() {
                                    _obscureConfirmPassword =
                                        !_obscureConfirmPassword;
                                  });
                                },
                                icon: Icon(
                                  _obscureConfirmPassword
                                      ? Icons.visibility_outlined
                                      : Icons.visibility_off_outlined,
                                ),
                              ),
                            ),
                          ),
                          const SizedBox(height: 14),
                          TextField(
                            controller: referralController,
                            textCapitalization: TextCapitalization.characters,
                            textInputAction: TextInputAction.done,
                            decoration: const InputDecoration(
                              labelText: 'Referral code (optional)',
                              hintText: 'Example: CD-A1B2C3D4',
                              prefixIcon: Icon(Icons.card_giftcard_outlined),
