class HubHome extends StatefulWidget {
  final String accountEmail;
  final bool isAdmin;
  final bool isPremium;

  const HubHome({
    super.key,
    required this.accountEmail,
    this.isAdmin = false,
    this.isPremium = false,
  });

  @override
  State<HubHome> createState() => _HubHomeState();
}

class _HubHomeState extends State<HubHome> {
  int selectedIndex = 0;
  final Set<int> _visitedTabs = <int>{0};
  Offset? _pointerDownPosition;
  Offset _pointerDelta = Offset.zero;
  bool _pointerSwipeTriggered = false;

  // Keep page instances stable. The Feed subtree must not be recreated when
  // the user switches tabs.
  final GlobalKey<_FeedPageState> _feedKey = GlobalKey<_FeedPageState>();
  final GlobalKey<_AnalysisPageState> _analysisKey =
      GlobalKey<_AnalysisPageState>();
  final GlobalKey<_LiveCallsPageState> _liveCallsKey =
      GlobalKey<_LiveCallsPageState>();
  final GlobalKey<_JournalPageState> _journalKey =
      GlobalKey<_JournalPageState>();

  late final List<Widget> pages = [
    FeedPage(key: _feedKey, isAdmin: widget.isAdmin),
    AnalysisPage(
      key: _analysisKey,
      isAdmin: widget.isAdmin,
      accountEmail: widget.accountEmail,
    ),
    LiveCallsPage(
      key: _liveCallsKey,
      isAdmin: widget.isAdmin,
      isPremium: widget.isPremium,
      onCreate: _createLiveCall,
    ),
    JournalPage(key: _journalKey),
    MentorshipPage(isAdmin: widget.isAdmin),
    const _TradePage(),
    _CommunityChatPage(isAdmin: widget.isAdmin),
  ];

  final List<int> _unreadCounts = [3, 0, 2, 1, 0, 0, 0];

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _showEntryPromotions();
    });
  }

  Future<void> _showEntryPromotions() async {
    await showDialog<void>(
      context: context,
      barrierDismissible: false,
      barrierColor: const Color(0xD9000000),
      builder: (_) => _EntryPromotionsDialog(
        onReferral: () {
          Navigator.pop(context);
          Navigator.push(
            context,
            MaterialPageRoute(builder: (_) => const _ReferralCenterPage()),
          );
        },
        onAlphaDen: () {
          Navigator.pop(context);
          _openAlphaDen();
        },
        onLiveCalls: () {
          Navigator.pop(context);
          _changeTab(2);
        },
        onMentorship: () {
          Navigator.pop(context);
          _changeTab(4);
        },
        onJournal: () {
          Navigator.pop(context);
          _changeTab(3);
        },
      ),
    );
  }

  void _changeTab(int index) {
    if (index < 0 || index >= pages.length || index == selectedIndex) return;
    setState(() {
      _visitedTabs.add(index);
      selectedIndex = index;
      _unreadCounts[index] = 0;
    });
  }

  void _handlePointerDown(PointerDownEvent event) {
    _pointerDownPosition = event.position;
    _pointerDelta = Offset.zero;
    _pointerSwipeTriggered = false;
  }

  void _handlePointerMove(PointerMoveEvent event) {
    if (_pointerDownPosition == null || _pointerSwipeTriggered) return;
    _pointerDelta += event.delta;

    final dx = _pointerDelta.dx;
    final dy = _pointerDelta.dy;
    if (dx.abs() < 56 || dx.abs() <= dy.abs() * 1.15) return;

    _pointerSwipeTriggered = true;
    if (dx < 0) {
      _changeTab(selectedIndex + 1);
    } else {
      _changeTab(selectedIndex - 1);
    }
  }

  void _handlePointerUp(PointerUpEvent event) {
    _pointerDownPosition = null;
    _pointerDelta = Offset.zero;
    _pointerSwipeTriggered = false;
  }

  void _handlePointerCancel(PointerCancelEvent event) {
    _pointerDownPosition = null;
    _pointerDelta = Offset.zero;
    _pointerSwipeTriggered = false;
  }

  void _openCustomerSupport() {
    showCustomerSupportSheet(context);
  }

  Future<void> _openAlphaDen() async {
    await Navigator.push(
      context,
      PageRouteBuilder(
        transitionDuration: const Duration(milliseconds: 700),
        pageBuilder: (_, _, _) => AlphaDenLoadingPage(isAdmin: widget.isAdmin),
        transitionsBuilder: (_, animation, _, child) {
          return FadeTransition(
            opacity: CurvedAnimation(parent: animation, curve: Curves.easeOut),
            child: ScaleTransition(
              scale: Tween<double>(begin: 1.08, end: 1.0).animate(
                CurvedAnimation(parent: animation, curve: Curves.easeOutCubic),
              ),
              child: child,
            ),
          );
        },
      ),
    );

    if (!mounted) return;
  }

