class _EntryPromotionsDialog extends StatefulWidget {
  final VoidCallback onReferral;
  final VoidCallback onAlphaDen;
  final VoidCallback onLiveCalls;
  final VoidCallback onMentorship;
  final VoidCallback onJournal;

  const _EntryPromotionsDialog({
    required this.onReferral,
    required this.onAlphaDen,
    required this.onLiveCalls,
    required this.onMentorship,
    required this.onJournal,
  });

  @override
  State<_EntryPromotionsDialog> createState() => _EntryPromotionsDialogState();
}

class _EntryPromotionsDialogState extends State<_EntryPromotionsDialog>
    with TickerProviderStateMixin {
  late final AnimationController _motion = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1800),
  )..repeat(reverse: true);

  late final AnimationController _swipe = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 420),
  );

  int _page = 0;
  double _dragX = 0;
  double _promote = 0;
  double _swipeStart = 0;
  double _swipeTarget = 0;
  bool _animating = false;
  bool _incomingAnimating = false;
  bool _showClose = false;
  Timer? _closeTimer;

  static const int _pageCount = 5;

  @override
  void dispose() {
    _closeTimer?.cancel();
    _motion.dispose();
    _swipe.dispose();
    super.dispose();
  }

  @override
  void initState() {
    super.initState();
    _closeTimer = Timer(const Duration(seconds: 2), () {
      if (mounted) setState(() => _showClose = true);
    });
    _swipe.addListener(() {
      if (!mounted) return;
      final eased = Curves.easeOutCubic.transform(_swipe.value);
      if (_incomingAnimating) {
        setState(() => _promote = eased);
        return;
      }
      setState(() {
        _dragX =
            ui.lerpDouble(_swipeStart, _swipeTarget, eased) ?? _swipeTarget;
      });
    });
  }

  void _finishSwipe(double target) {
    if (_animating) return;
    _animating = true;
    _swipeStart = _dragX;
    _swipeTarget = target;
    _swipe.duration = const Duration(milliseconds: 420);
    _swipe.forward(from: 0).whenComplete(() async {
      if (!mounted) return;
      if (target < -120) {
        setState(() {
          _page = (_page + 1) % _pageCount;
          _dragX = 0;
          _promote = 0;
          _incomingAnimating = true;
        });
        _swipe
          ..duration = const Duration(milliseconds: 360)
          ..value = 0;
        await _swipe.forward(from: 0);
        if (!mounted) return;
        setState(() {
          _promote = 1;
          _incomingAnimating = false;
        });
      } else {
        setState(() => _dragX = 0);
      }
      _swipe.duration = const Duration(milliseconds: 420);
      _animating = false;
    });
  }

  void _onDragEnd(DragEndDetails details) {
    if (_dragX < -65 ||
        details.primaryVelocity != null && details.primaryVelocity! < -350) {
      _finishSwipe(-430);
    } else {
      _finishSwipe(0);
    }
  }

  void _openCurrent() {
    switch (_page) {
      case 0:
        widget.onReferral();
        break;
      case 1:
        widget.onAlphaDen();
        break;
      case 2:
        widget.onLiveCalls();
        break;
      case 3:
        widget.onMentorship();
        break;
      case 4:
        widget.onJournal();
        break;
    }
  }

  Widget _pageCard(int index, {required bool top}) {
    final isReferral = index == 0;
    final isAlpha = index == 1;
    final isCalls = index == 2;
    final isMentorship = index == 3;
    final title = isReferral
        ? 'START EARNING'
        : isAlpha
        ? 'ALPHA DEN'
        : isCalls
        ? 'LIVE CALLS'
        : isMentorship
        ? 'MENTORSHIP'
        : 'TRADING JOURNAL';
    final headline = isReferral
        ? 'Turn your network into real rewards.'
        : isAlpha
        ? 'Prove your knowledge. Build your name.'
        : isCalls
        ? 'Trade with the official signal system.'
        : isMentorship
        ? 'Learn. Practice. Graduate.'
        : 'Be responsible. Trade more profitably.';
    final body = isReferral
        ? 'Start from \$0 and earn up to \$300 monthly.'
        : isAlpha
        ? 'Publish your ideas, grow your visibility, earn recognition and build your name in the community.'
        : isCalls
        ? 'First 2 daily calls are free. Premium and Lifetime unlock the full signal experience and eligible badge benefits.'
        : isMentorship
        ? 'Daily lessons, practical work, backtesting and live classes built around a structured learning path.'
        : 'Follow your rules, track your progress, manage risk and build disciplined trading habits with your Personal Task.';
    final accent = isReferral
        ? const Color(0xFF63D7FF)
        : isAlpha
        ? const Color(0xFF9BB7D7)
        : isCalls
        ? const Color(0xFF9C8BFF)
        : isMentorship
        ? const Color(0xFF8FAFFF)
        : const Color(0xFF5BBEFF);

    final incoming = top && _incomingAnimating;
    // Solitaire-style stack: the active card leans slightly left, the card
    // behind it leans slightly right. When the behind card becomes active,
    // its rotation eases continuously from right-lean to left-lean during the
    // existing promotion animation; no hard rotation jump is introduced.
    const behindX = 220.0;
    const frontLean = -.025;
    const behindLean = .025;
    final nextOffset = top ? _dragX - 12.0 : behindX * (1 - _promote);
    final baseScale = incoming
        ? (.965 + .035 * _promote)
        : (top ? 1.0 : (.97 + .03 * _promote));
    final baseY = top ? 0.0 : 14.0 * (1 - _promote);
    final incomingRotation =
        ui.lerpDouble(behindLean, frontLean, _promote) ?? frontLean;
    final nextRotation = incoming
        ? incomingRotation
        : (top
              ? (frontLean + (_dragX / 5200).clamp(-.10, .10))
              : behindLean * (1 - _promote));
    final nextX = incoming
        ? 0.0
        : (top ? nextOffset : behindX * (1 - _promote));
    final topDrop = incoming
        ? 72.0 * (1 - _promote)
        : (top ? math.min(44.0, (-_dragX) * .10) : baseY);
    return Positioned.fill(
      child: Transform.translate(
        offset: Offset(nextX, topDrop),
        child: Transform.rotate(
          angle: nextRotation,
          alignment: Alignment.bottomLeft,
          child: Transform.scale(
            scale: baseScale,
            alignment: Alignment.topCenter,
            child: Opacity(
              opacity: incoming
                  ? (.58 + .42 * _promote)
                  : (top ? 1 : (.88 + .12 * _promote)),
              child: IgnorePointer(
                ignoring: !top || _animating,
                child: GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTap: _openCurrent,
                  onHorizontalDragUpdate: (details) {
                    if (!top || _animating) return;
                    setState(
                      () => _dragX = math.min(0, _dragX + details.delta.dx),
                    );
                  },
                  onHorizontalDragEnd: top ? _onDragEnd : null,
                  child: _PromoCard(
                    index: index,
                    title: title,
                    headline: headline,
                    body: body,
                    accent: accent,
                    animation: _motion,
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final next = (_page + 1) % _pageCount;
    return Dialog(
      backgroundColor: Colors.transparent,
      insetPadding: const EdgeInsets.symmetric(horizontal: 18, vertical: 22),
      child: ConstrainedBox(
        constraints: const BoxConstraints(maxWidth: 405, maxHeight: 365),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            SizedBox(
              height: 304,
              child: ClipRRect(
                borderRadius: BorderRadius.circular(26),
                child: Stack(
                  clipBehavior: Clip.hardEdge,
                  children: [
                    _pageCard(next, top: false),
                    _pageCard(_page, top: true),
                  ],
                ),
              ),
            ),
            const SizedBox(height: 4),
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: List.generate(
                _pageCount,
                (i) => AnimatedContainer(
                  duration: const Duration(milliseconds: 180),
                  margin: const EdgeInsets.symmetric(horizontal: 3),
                  width: _page == i ? 19 : 5,
                  height: 4,
                  decoration: BoxDecoration(
                    color: _page == i
                        ? AppTheme.luxuryGold
                        : AppTheme.textVeryFaint,
                    borderRadius: BorderRadius.circular(4),
                  ),
                ),
              ),
            ),
            const SizedBox(height: 5),
            Text(
              'SWIPE LEFT FOR MORE',
              style: TextStyle(
                color: AppTheme.textFaint,
                fontSize: 7,
                fontWeight: FontWeight.w800,
