class _PromoLiveCallsEntryPage extends StatefulWidget {
  const _PromoLiveCallsEntryPage();

  @override
  State<_PromoLiveCallsEntryPage> createState() =>
      _PromoLiveCallsEntryPageState();
}

class _PromoLiveCallsEntryPageState extends State<_PromoLiveCallsEntryPage> {
  bool _loading = true;
  bool _isAdmin = false;
  bool _isPremium = false;

  @override
  void initState() {
    super.initState();
    _loadAccess();
  }

  Future<void> _loadAccess() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      if (mounted) setState(() => _loading = false);
      return;
    }
    try {
      _isAdmin = await _hasFirebaseAdminClaim(user);
      final data = await ProfileService.loadUserProfile(user.uid);
      _isPremium = _isActivePremiumUserData(data);
    } catch (_) {}
    if (mounted) setState(() => _loading = false);
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) {
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }
    return LiveCallsPage(isAdmin: _isAdmin, isPremium: _isPremium);
  }
}

