  final List<_AdminUser> _users = [];
  final List<_AdminVerification> _verifications = [];
  String? _selectedGraduatedTargetUid;
  bool _graduatedInventoryReady = false;

  @override
  void initState() {
    super.initState();
    _prepareGraduatedBadgeInventory();
  }

  Future<void> _prepareGraduatedBadgeInventory() async {
    try {
      await BadgeService.ensureGraduatedBadgeInventory();
      if (mounted) setState(() => _graduatedInventoryReady = true);
    } catch (_) {
      if (mounted) setState(() => _graduatedInventoryReady = false);
    }
  }

  String get _sectionTitle => const [
    'Overview',
    'Users & Sign-ups',
    'Pending Payments',
    'Posts & Activity',
    'Verification Requests',
    'Reports & Moderation',
    'Admin Controls',
  ][_section];

  void _approvePayment(_AdminPayment payment) {
    setState(() {
      payment.status = 'Approved';
      final user = _users.cast<_AdminUser?>().firstWhere(
        (u) => u!.email == payment.email,
        orElse: () => null,
      );
      user?.status = 'Active';
      final verification = _verifications
          .cast<_AdminVerification?>()
          .firstWhere((v) => v!.txHash == payment.txHash, orElse: () => null);
      verification?.status = 'Approved';
    });
  }

  void _cancelPayment(_AdminPayment payment) {
    setState(() {
      payment.status = 'Cancelled';
      final user = _users.cast<_AdminUser?>().firstWhere(
        (u) => u!.email == payment.email,
        orElse: () => null,
      );
      user?.status = 'Payment cancelled';
      final verification = _verifications
          .cast<_AdminVerification?>()
          .firstWhere((v) => v!.txHash == payment.txHash, orElse: () => null);
      verification?.status = 'Cancelled';
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppTheme.deepBlack,
      appBar: AppBar(
        title: Row(
          children: [
            Icon(Icons.admin_panel_settings, color: AppTheme.luxuryGold),
            const SizedBox(width: 10),
            Flexible(
              child: Text(
                'ADMIN Ã¢â‚¬Â¢ $_sectionTitle',
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
              ),
            ),
          ],
        ),
      ),
      body: Stack(
        children: [
          const GalaxyBackground(animatePlanets: true),
          SafeArea(
            child: LayoutBuilder(
              builder: (context, constraints) {
                final wide = constraints.maxWidth >= 850;
                final content = Expanded(
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(18, 12, 18, 18),
                    child: AnimatedSwitcher(
                      duration: const Duration(milliseconds: 300),
                      child: SingleChildScrollView(
                        key: ValueKey<int>(_section),
                        physics: const BouncingScrollPhysics(),
                        child: _buildSection(),
                      ),
                    ),
                  ),
                );

                if (wide) {
                  return Row(children: [_buildRail(), content]);
                }

                return Column(children: [content, _buildMobileNav()]);
              },
            ),
          ),
        ],
      ),
    );
  }

