  Widget _adminNavIcon(IconData icon, int index, {bool selected = false}) {
    final unread = _adminUnreadCounts[index];
    return Stack(
      clipBehavior: Clip.none,
      children: [
        Icon(icon, color: selected ? AppTheme.luxuryGold : null),
        if (unread > 0)
          Positioned(
            right: -10,
            top: -8,
            child: Container(
              constraints: const BoxConstraints(minWidth: 16, minHeight: 16),
              padding: const EdgeInsets.symmetric(horizontal: 3),
              decoration: BoxDecoration(
                color: Colors.red,
                borderRadius: BorderRadius.circular(20),
              ),
              alignment: Alignment.center,
              child: Text(
                unread > 99 ? '99+' : '$unread',
                style: TextStyle(
                  color: AppTheme.textPrimary,
                  fontSize: 8,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ),
          ),
      ],
    );
  }

  Widget _buildSection() {
    switch (_section) {
      case 1:
        return _buildUsers();
      case 2:
        return _buildPayments();
      case 3:
        return _buildActivity();
      case 4:
        return _buildVerifications();
      case 5:
        return _buildReports();
      case 6:
        return _buildControls();
      default:
        return _buildOverview();
    }
  }

