  Widget _realCountStatCard(
    String title,
    IconData icon,
    String collection,
    VoidCallback onTap,
  ) {
    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance.collection(collection).snapshots(),
      builder: (context, snapshot) {
        final count = snapshot.data?.docs.length ?? 0;
        return _statCard(
          title,
          snapshot.connectionState == ConnectionState.waiting
              ? 'Ã¢â‚¬Â¦'
              : '$count',
          icon,
          onTap,
        );
      },
    );
  }

  Widget _buildRecentActivityPanel() {
    return _panel(
      title: 'Recent community activity',
      icon: Icons.timeline,
      child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
        stream: FirebaseFirestore.instance
            .collection('feed_posts')
            .where('isPublished', isEqualTo: true)
            .orderBy('createdAt', descending: true)
            .limit(8)
            .snapshots(),
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting)
            return const Center(
              child: Padding(
                padding: EdgeInsets.all(18),
                child: CircularProgressIndicator(),
              ),
            );
          if (snapshot.hasError)
            return Text(
              'Unable to load live activity: ${snapshot.error}',
              style: TextStyle(color: AppTheme.textMuted),
            );
          final docs =
              snapshot.data?.docs ??
              const <QueryDocumentSnapshot<Map<String, dynamic>>>[];
          if (docs.isEmpty)
            return Text(
              'No community activity yet.',
              style: TextStyle(color: AppTheme.textMuted),
            );
          return Column(children: docs.map(_realActivityTile).toList());
        },
      ),
    );
  }

  Widget _realActivityTile(QueryDocumentSnapshot<Map<String, dynamic>> doc) {
    final data = doc.data();
    final author = (data['authorDisplayName'] ?? '').toString().trim();
    final uid = (data['authorUid'] ?? '').toString();
    final sourceType = (data['sourceType'] ?? 'community').toString();
    final text = (data['text'] ?? '').toString().trim();
    final ts = data['createdAt'];
    final time = ts is Timestamp
        ? _formatAdminDateTime(ts.toDate())
        : 'Time unavailable';
    final shortUid = uid.isEmpty
        ? 'Unknown account'
        : 'UID ${uid.substring(0, math.min(8, uid.length))}';
    final name = author.isEmpty ? shortUid : author;
    final action = sourceType == 'alpha_den'
        ? 'Alpha Den post'
        : sourceType == 'analysis'
        ? 'Analysis post'
        : sourceType == 'live_call'
        ? 'Live Call'
        : 'Community post';
    return ListTile(
      contentPadding: const EdgeInsets.symmetric(vertical: 3),
      leading: Icon(
        sourceType == 'analysis'
            ? Icons.analytics_outlined
            : sourceType == 'live_call'
            ? Icons.campaign_outlined
            : Icons.article_outlined,
        color: AppTheme.neonGreen,
      ),
      title: Text(
        '$name Ã¢â‚¬Â¢ $action',
        style: const TextStyle(fontWeight: FontWeight.w800),
      ),
      subtitle: Text(
        '${text.isEmpty ? 'No text content' : text}\n$time',
        maxLines: 3,
        overflow: TextOverflow.ellipsis,
        style: TextStyle(color: AppTheme.textMuted, height: 1.35),
      ),
      isThreeLine: true,
    );
  }

  String _formatAdminDateTime(DateTime value) {
    final hh = value.hour.toString().padLeft(2, '0');
    final mm = value.minute.toString().padLeft(2, '0');
    return '${_formatAdminDate(value)} $hh:$mm';
  }

