  Widget _buildUsers() {
    return _panel(
      title: 'User / Sign-up Management',
      icon: Icons.people_outline,
      child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
        stream: FirebaseFirestore.instance
            .collection('users')
            .orderBy('createdAt', descending: true)
            .limit(200)
            .snapshots(),
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Padding(
              padding: EdgeInsets.symmetric(vertical: 28),
              child: Center(child: CircularProgressIndicator()),
            );
          }

          if (snapshot.hasError) {
            return Padding(
              padding: const EdgeInsets.symmetric(vertical: 18),
              child: Text(
                'Unable to load real sign-ups: ${snapshot.error}',
                style: TextStyle(color: AppTheme.textMuted),
              ),
            );
          }

          final docs =
              snapshot.data?.docs ??
              const <QueryDocumentSnapshot<Map<String, dynamic>>>[];
          if (docs.isEmpty) {
            return Padding(
              padding: EdgeInsets.symmetric(vertical: 28),
              child: Center(
                child: Text(
                  'No registered users found yet.',
                  style: TextStyle(color: AppTheme.textMuted),
                ),
              ),
            );
          }

          return ListView.separated(
            shrinkWrap: true,
            physics: const NeverScrollableScrollPhysics(),
            itemCount: docs.length,
            separatorBuilder: (_, _) => Divider(color: AppTheme.fillFaint),
            itemBuilder: (_, index) {
              final doc = docs[index];
              final data = doc.data();
              final name = (data['displayName'] ?? '').toString().trim();
              final email = (data['email'] ?? '').toString().trim();
              final uid = (data['uid'] ?? doc.id).toString();
              final role = (data['role'] ?? 'user').toString();
              final createdAt = data['createdAt'];
              final joined = createdAt is Timestamp
                  ? _formatAdminDate(createdAt.toDate())
                  : 'Date unavailable';
              final displayName = name.isEmpty ? 'Unnamed user' : name;
              final badge = role == 'admin' ? 'ADMIN' : 'USER';

              return ListTile(
                contentPadding: EdgeInsets.zero,
                leading: CircleAvatar(
                  backgroundColor: AppTheme.neonGreen.withValues(alpha: 0.12),
                  child: Text(
                    displayName.substring(0, 1).toUpperCase(),
                    style: TextStyle(color: AppTheme.neonGreen),
                  ),
                ),
                title: Text(
                  displayName,
                  style: const TextStyle(fontWeight: FontWeight.w800),
                ),
                subtitle: Text(
                  '${email.isEmpty ? 'Email unavailable' : email}\nJoined $joined',
                  style: TextStyle(color: AppTheme.textMuted, height: 1.4),
                ),
                isThreeLine: true,
                trailing: Chip(label: Text(badge)),
                onTap: () => _showFirestoreUserDetails(
                  context,
                  uid: uid,
                  name: displayName,
                  email: email,
                  role: role,
                  joined: joined,
                  data: data,
                ),
              );
            },
          );
        },
      ),
    );
  }

  String _formatAdminDate(DateTime value) {
    const months = <String>[
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];
    return '${months[value.month - 1]} ${value.day}, ${value.year}';
  }

  void _showFirestoreUserDetails(
    BuildContext context, {
    required String uid,
    required String name,
    required String email,
    required String role,
    required String joined,
    required Map<String, dynamic> data,
  }) {
    showModalBottomSheet<void>(
      context: context,
      backgroundColor: AppTheme.adaptiveSurface(Color(0xFF0A1012)),
      isScrollControlled: true,
      builder: (_) => Padding(
        padding: const EdgeInsets.fromLTRB(22, 22, 22, 30),
        child: Wrap(
          runSpacing: 10,
          children: [
            Text(
              name,
              style: const TextStyle(fontSize: 22, fontWeight: FontWeight.w900),
            ),
            Text(
              email.isEmpty ? 'Email unavailable' : email,
              style: TextStyle(color: AppTheme.textMuted),
            ),
            Text(
              'UID: $uid',
              style: TextStyle(color: AppTheme.textMuted, fontSize: 11),
            ),
            Text('Role: $role'),
            Text(
              'Premium: ${data['isPremium'] == true ? 'APPROVED' : 'NOT APPROVED'}',
              style: TextStyle(
                color: data['isPremium'] == true
                    ? AppTheme.neonGreen
                    : AppTheme.textMuted,
                fontWeight: FontWeight.w800,
              ),
            ),
            ElevatedButton.icon(
              onPressed: () async {
                final approved = data['isPremium'] == true;
                try {
                  final now = DateTime.now();
                  final expiry = now.add(const Duration(days: 30));
                  await FirebaseFirestore.instance
                      .collection('users')
                      .doc(uid)
                      .update({
                        'isPremium': !approved,
                        'premiumApprovedAt': !approved
                            ? FieldValue.serverTimestamp()
                            : FieldValue.delete(),
                        'premiumPaymentPlan': !approved
                            ? 'premium_monthly'
                            : FieldValue.delete(),
                        'premiumExpiresAt': !approved
                            ? expiry.toIso8601String()
                            : FieldValue.delete(),
                        'premiumExpiresAtEpochSeconds': !approved
                            ? expiry.millisecondsSinceEpoch ~/ 1000
                            : FieldValue.delete(),
                        'confirmedPremiumBadgeType': !approved
                            ? 'premium_monthly'
                            : FieldValue.delete(),
                        'premiumExpiredAt': FieldValue.delete(),
                      });
                  if (context.mounted) Navigator.pop(context);
                } catch (_) {}
              },
              icon: Icon(
                data['isPremium'] == true
                    ? Icons.lock_outline
                    : Icons.workspace_premium_outlined,
              ),
              label: Text(
                data['isPremium'] == true
                    ? 'REMOVE PREMIUM'
                    : 'APPROVE PREMIUM',
              ),
            ),
            Builder(
              builder: (_) {
                final mentorshipApproved =
                    data['mentorshipApproved'] == true ||
                    data['isMentorship'] == true ||
                    data['mentorship'] == true;
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Mentorship: ${mentorshipApproved ? 'APPROVED' : 'NOT APPROVED'}',
                      style: TextStyle(
                        color: mentorshipApproved
                            ? AppTheme.neonGreen
                            : AppTheme.textMuted,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    ElevatedButton.icon(
                      onPressed: () async {
                        try {
                          await MentorshipService.adminSetStudent(
                            uid: uid,
                            approved: !mentorshipApproved,
                            name: (data['displayName'] ?? 'Unnamed user')
                                .toString()
                                .trim(),
                          );
                          if (context.mounted) Navigator.pop(context);
                        } catch (_) {}
                      },
                      icon: const Icon(Icons.school_rounded),
                      label: Text(
                        mentorshipApproved
                            ? 'REMOVE MENTORSHIP'
                            : 'APPROVE MENTORSHIP',
                      ),
                    ),
                  ],
                );
              },
            ),
            Text('Joined: $joined'),
            Text(
              'Referral code: ${(data['referralCode'] ?? 'Not set').toString()}',
            ),
            if ((data['referredByCode'] ?? '').toString().isNotEmpty)
              Text('Referred by code: ${data['referredByCode']}'),
          ],
        ),
      ),
    );
  }

  void _syncPaymentUnreadCount(int count) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final target = _section == 2 ? 0 : count;
      if (_adminUnreadCounts[2] != target) {
        setState(() => _adminUnreadCounts[2] = target);
      }
    });
  }

  Widget _buildPayments() {
    final user = FirebaseAuth.instance.currentUser;
    return _panel(
      title: 'Pending Payments',
      icon: Icons.payments_outlined,
      child: user == null
          ? Text(
              'Admin session required.',
              style: TextStyle(color: AppTheme.textMuted),
            )
          : FutureBuilder<bool>(
              future: _hasFirebaseAdminClaim(user),
              builder: (context, claimSnapshot) {
                if (claimSnapshot.connectionState == ConnectionState.waiting)
                  return const Center(
                    child: Padding(
                      padding: EdgeInsets.all(20),
                      child: CircularProgressIndicator(),
                    ),
                  );
                if (claimSnapshot.data != true)
                  return Text(
                    'Admin access required.',
                    style: TextStyle(color: AppTheme.textMuted),
                  );
                return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                  stream: PaymentService.watchAdminRequests(),
                  builder: (context, snapshot) {
                    if (snapshot.connectionState == ConnectionState.waiting)
                      return const Center(
                        child: Padding(
                          padding: EdgeInsets.all(20),
                          child: CircularProgressIndicator(),
                        ),
                      );
                    if (snapshot.hasError)
                      return Text(
                        'Payment requests could not be loaded. Check Firestore rules.',
                        style: TextStyle(color: AppTheme.textMuted),
                      );
                    final docs =
                        snapshot.data?.docs ??
                        const <QueryDocumentSnapshot<Map<String, dynamic>>>[];
                    final intents = docs
                        .where(
                          (d) =>
                              (d.data()['status'] ?? '').toString() == 'intent',
                        )
                        .toList();
                    final pending = docs
                        .where(
                          (d) =>
                              (d.data()['status'] ?? '').toString() ==
                              'pending',
                        )
                        .toList();
                    _syncPaymentUnreadCount(intents.length + pending.length);
                    return Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Manual payments are stored in Firebase. When you approve a verified proof, the user entitlement is updated automatically.',
                          style: TextStyle(
                            color: AppTheme.textMuted,
                            fontSize: 11,
                            height: 1.4,
                          ),
                        ),
                        if (intents.isNotEmpty) ...[
                          const SizedBox(height: 12),
                          Container(
                            padding: const EdgeInsets.all(12),
                            decoration: BoxDecoration(
                              color: const Color(0x22FFD166),
                              borderRadius: BorderRadius.circular(12),
                              border: Border.all(
                                color: AppTheme.luxuryGold.withValues(
                                  alpha: .28,
                                ),
                              ),
                            ),
                            child: Row(
                              children: [
                                Icon(
                                  Icons.notifications_active_rounded,
                                  color: AppTheme.luxuryGold,
                                  size: 20,
                                ),
                                const SizedBox(width: 9),
