    final d = doc.data();
    final uid = (d['uid'] ?? '').toString();
    final username = (d['username'] ?? 'User').toString();
    final product = (d['product'] ?? '').toString();
    final plan = (d['planName'] ?? d['planId'] ?? '').toString();
    final amount = (d['amount'] ?? '').toString();
    final currency = (d['currency'] ?? 'USD').toString();
    final method = (d['paymentMethodName'] ?? d['paymentMethodType'] ?? '')
        .toString();
    final tx = (d['transactionReference'] ?? '').toString();
    final proof = (d['proofUrl'] ?? '').toString();
    final installment = (d['installmentNumber'] ?? 0).toString();
    final status = (d['status'] ?? 'pending').toString();
    final isIntent = status == 'intent';
