        (d['paymentMethodId'] ?? d['paymentMethodName'] ?? '')
            .toString()
            .toLowerCase()
            .contains('easypaisa') &&
        status == 'awaiting_admin_verification';
    final ts = d['submittedAt'];
    final submitted = ts is Timestamp
        ? _formatAdminDateTime(ts.toDate())
        : 'Just submitted';
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(13),
      decoration: BoxDecoration(
        color: AppTheme.adaptiveSurface(const Color(0xAA11191B)),
        borderRadius: BorderRadius.circular(15),
        border: Border.all(
          color: isIntent
              ? AppTheme.luxuryGold.withValues(alpha: .30)
              : AppTheme.luxuryGold.withValues(alpha: .18),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                child: Text(
                  username,
                  style: const TextStyle(
                    fontWeight: FontWeight.w900,
                    fontSize: 14,
                  ),
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                decoration: BoxDecoration(
                  color: isIntent
                      ? const Color(0x33FFD166)
                      : const Color(0x22FFFFFF),
                  borderRadius: BorderRadius.circular(20),
                ),
                child: Text(
                  isIntent
                      ? 'WANTS TO PAY'
                      : isEasypaisaProof
                      ? 'AWAITING ADMIN VERIFICATION'
                      : 'PAYMENT REVIEW',
                  style: TextStyle(
                    color: AppTheme.luxuryGold,
                    fontSize: 9,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 6),
          Text(
            'UID: $uid',
            style: TextStyle(color: AppTheme.textSecondary, fontSize: 10),
          ),
          Text(
            'Product: ${product.toUpperCase()} Ã¢â‚¬Â¢ $plan',
            style: TextStyle(
              color: AppTheme.textSecondary,
              fontSize: 11,
              fontWeight: FontWeight.w700,
            ),
          ),
          Text(
            'Amount: $amount $currency Ã¢â‚¬Â¢ Method: $method',
            style: TextStyle(color: AppTheme.textSecondary, fontSize: 11),
          ),
          if ((d['paymentDetails'] ?? '').toString().isNotEmpty)
            Text(
              'Easypaisa details: ${(d['paymentDetails'] ?? '').toString()}',
              style: TextStyle(color: AppTheme.textSecondary, fontSize: 10),
            ),
          if (product == 'mentorship' && installment != '0')
            Text(
              'Installment: #$installment',
              style: TextStyle(color: AppTheme.textSecondary, fontSize: 11),
            ),
          if (tx.isNotEmpty)
            Text(
              'Reference: $tx',
              style: TextStyle(color: AppTheme.textSecondary, fontSize: 10),
            ),
          Text(
            'Submitted: $submitted',
            style: TextStyle(color: AppTheme.textFaint, fontSize: 9),
          ),
          const SizedBox(height: 10),
          if (proof.isNotEmpty)
            GestureDetector(
              onTap: () => _showPaymentProof(proof, username),
              child: ClipRRect(
                borderRadius: BorderRadius.circular(10),
                child: _DriveAwareImage(
                  source: proof,
                  height: 180,
                  width: double.infinity,
                  fit: BoxFit.contain,
                  errorText: 'Proof image unavailable',
                ),
              ),
            )
          else
            Text(
              isIntent
                  ? 'No screenshot yet Ã¢â‚¬â€ waiting for the user to submit payment proof.'
                  : 'No screenshot attached.',
              style: TextStyle(color: AppTheme.textMuted, fontSize: 10),
            ),
          if (isEasypaisaProof) ...[
            const SizedBox(height: 10),
            Row(
              children: [
                Expanded(
                  child: FilledButton.icon(
                    onPressed: () => _approveManualPayment(doc.id),
                    icon: const Icon(Icons.check_rounded),
                    label: const Text('CONFIRM PAYMENT'),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: OutlinedButton.icon(
                    onPressed: () => _rejectManualPayment(doc.id),
                    icon: const Icon(Icons.close_rounded),
                    label: const Text('REJECT'),
                  ),
                ),
              ],
            ),
          ],
        ],
      ),
    );
  }

  Future<void> _approveManualPayment(String requestId) async {
    try {
      await PaymentService.adminApproveRequest(requestId);
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Easypaisa payment confirmed. Purchased entitlement activated automatically.',
            ),
          ),
        );
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context)
            .showSnackBar(SnackBar(content: Text('Approval failed: $e')));
    }
  }

  Future<void> _rejectManualPayment(String requestId) async {
    final reason = TextEditingController();
    final result = await showDialog<bool>(
      context: context,
      builder: (dc) => AlertDialog(
        title: const Text('REJECT PAYMENT'),
        content: TextField(
          controller: reason,
          maxLines: 3,
          decoration: const InputDecoration(hintText: 'Optional reason'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dc, false),
            child: const Text('CANCEL'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dc, true),
            child: const Text('REJECT'),
          ),
        ],
      ),
    );
    if (result != true) return;
    try {
      await PaymentService.adminRejectRequest(requestId, reason: reason.text);
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Easypaisa payment rejected.')),
        );
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context)
            .showSnackBar(SnackBar(content: Text('Rejection failed: $e')));
    } finally {
      reason.dispose();
    }
  }

