  Widget _buildUserPayoutDetails() {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return const SizedBox.shrink();
    return FutureBuilder<bool>(
      future: _hasFirebaseAdminClaim(user),
      builder: (context, claimSnapshot) {
        if (claimSnapshot.data != true) return const SizedBox.shrink();
        return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
          stream: PayoutService.watchAll(),
          builder: (context, snapshot) {
            if (snapshot.hasError) {
              return Text(
                'User payout details could not be loaded. Check Firestore rules.',
                style: TextStyle(color: AppTheme.textMuted, fontSize: 11),
              );
            }
            final docs =
                snapshot.data?.docs ??
                const <QueryDocumentSnapshot<Map<String, dynamic>>>[];
            return Container(
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(
                color: AppTheme.adaptiveSurface(const Color(0xAA11191B)),
                borderRadius: BorderRadius.circular(16),
                border: Border.all(
                  color: AppTheme.luxuryGold.withValues(alpha: .20),
                ),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Icon(
                        Icons.account_balance_wallet_outlined,
                        color: AppTheme.luxuryGold,
                        size: 20,
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          'USER PAYOUT DETAILS',
                          style: const TextStyle(
                            fontWeight: FontWeight.w900,
                            letterSpacing: .6,
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 5),
                  Text(
                    'Users save their own payout destination here. These details are separate from CDH platform payment receiving methods.',
                    style: TextStyle(
                      color: AppTheme.textMuted,
                      fontSize: 10,
                      height: 1.4,
                    ),
                  ),
                  const SizedBox(height: 12),
                  if (docs.isEmpty)
                    Text(
                      'No user payout details submitted yet.',
                      style: TextStyle(color: AppTheme.textMuted, fontSize: 11),
                    )
                  else
                    for (final doc in docs) _adminUserPayoutTile(doc),
                ],
              ),
            );
          },
        );
      },
    );
  }

