  Future<void> _showUserPayoutDetailsDialog(
    BuildContext context, {
    required String uid,
    required String name,
    required String method,
    required String detail,
  }) async {
    final text =
        'Name: ${name.isEmpty ? 'Unnamed user' : name}\nUID: $uid\nPayout method: ${method.isEmpty ? 'Unavailable' : method}\nPayout details: ${detail.isEmpty ? 'Unavailable' : detail}';
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text(
          'USER PAYOUT DETAILS',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
        content: SelectableText(text, style: const TextStyle(height: 1.5)),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('CLOSE'),
          ),
          FilledButton.icon(
            onPressed: detail.isEmpty
                ? null
                : () async {
                    await Clipboard.setData(ClipboardData(text: text));
                    if (dialogContext.mounted) {
                      Navigator.pop(dialogContext);
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(
                          content: Text('User payout details copied.'),
                        ),
                      );
                    }
                  },
            icon: const Icon(Icons.copy_rounded),
            label: const Text('COPY DETAILS'),
          ),
        ],
      ),
    );
  }

  Widget _buildManualPayoutRequests() {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return const SizedBox.shrink();
    return FutureBuilder<bool>(
      future: _hasFirebaseAdminClaim(user),
      builder: (context, claimSnapshot) {
        if (claimSnapshot.data != true) return const SizedBox.shrink();
        return FutureBuilder<List<Map<String, dynamic>>>(
          future: PayoutService.adminListPayoutRequests(),
          builder: (context, snapshot) {
            if (snapshot.connectionState == ConnectionState.waiting) {
              return const Center(
                child: Padding(
                  padding: EdgeInsets.all(12),
                  child: CircularProgressIndicator(),
                ),
              );
            }
            if (snapshot.hasError) {
              return Text(
                'Payout requests could not be loaded: ${snapshot.error}',
                style: TextStyle(color: AppTheme.textMuted, fontSize: 10),
              );
            }
            final payouts = snapshot.data ?? const <Map<String, dynamic>>[];
            return Container(
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(
                color: AppTheme.adaptiveSurface(const Color(0xAA11191B)),
                borderRadius: BorderRadius.circular(16),
                border: Border.all(
                  color: AppTheme.luxuryGold.withValues(alpha: .20),
                ),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Icon(
                        Icons.payments_outlined,
                        color: AppTheme.luxuryGold,
                        size: 20,
                      ),
                      const SizedBox(width: 8),
                      const Expanded(
                        child: Text(
                          'PAYOUT REQUESTS',
                          style: TextStyle(
                            fontWeight: FontWeight.w900,
                            letterSpacing: .6,
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 5),
                  Text(
                    'Easypaisa requests are manual. Admin confirmation is the authoritative credited state.',
                    style: TextStyle(
                      color: AppTheme.textMuted,
                      fontSize: 10,
                      height: 1.4,
                    ),
                  ),
                  const SizedBox(height: 12),
                  if (payouts.isEmpty)
                    Text(
                      'No payout requests.',
                      style: TextStyle(color: AppTheme.textMuted, fontSize: 11),
                    ),
                  for (final payout in payouts) ...[
                    Card(
                      color: AppTheme.adaptiveSurface(const Color(0xFF12171A)),
                      child: ListTile(
                        title: Text(
                          '${payout['userName'] ?? 'Unnamed user'} Ã¢â‚¬Â¢ ${payout['paymentMethod'] ?? ''}',
                          style: const TextStyle(
                            fontWeight: FontWeight.w900,
                            fontSize: 12,
                          ),
                        ),
                        subtitle: Text(
                          'UID: ${payout['uid'] ?? ''}\nRequested payout: ${payout['amount'] ?? ''} USDT\nReferral/incentive amount: ${payout['referralAmount'] ?? payout['amount'] ?? ''} USDT\nDestination: ${payout['paymentDetail'] ?? ''}\nStatus: ${(payout['status'] ?? '').toString().toUpperCase()}',
                          style: TextStyle(
                            color: AppTheme.textMuted,
                            fontSize: 9.5,
                            height: 1.35,
                          ),
                        ),
                        isThreeLine: true,
                        trailing:
                            (payout['paymentMethod'] == 'Easypaisa' &&
                                payout['status'] == 'pending_admin')
                            ? IconButton(
                                icon: const Icon(
                                  Icons.check_circle_outline_rounded,
                                ),
                                tooltip: 'Confirm manual payment',
                                onPressed: () async {
                                  try {
                                    await PayoutService.adminConfirmEasypaisaPayout(
                                      payoutRequestId:
                                          (payout['payoutRequestId'] ?? '')
                                              .toString(),
                                    );
                                    if (mounted) {
                                      ScaffoldMessenger.of(context)
                                          .showSnackBar(
                                            const SnackBar(
                                              content: Text(
                                                'Easypaisa payout marked as Credited.',
                                              ),
                                            ),
                                          );
                                      setState(() {});
                                    }
                                  } catch (e) {
                                    if (mounted)
                                      ScaffoldMessenger.of(context)
                                          .showSnackBar(
                                            SnackBar(
                                              content: Text(
                                                'Confirmation failed: $e',
                                              ),
                                            ),
                                          );
                                  }
                                },
                              )
                            : null,
                      ),
                    ),
                  ],
                ],
              ),
            );
          },
        );
      },
    );
  }

