  Widget _realReportTile(QueryDocumentSnapshot<Map<String, dynamic>> doc) {
    final data = doc.data();
    final type = (data['type'] ?? 'content').toString();
    final reason = (data['reason'] ?? 'No reason supplied').toString();
    final details = (data['details'] ?? '').toString().trim();
    final reporterUid = (data['reporterUid'] ?? 'Unknown').toString();
    final postId = (data['postId'] ?? '').toString();
    final commentId = (data['commentId'] ?? '').toString();
    final status = (data['status'] ?? 'open').toString();
    final ts = data['createdAt'];
    final created = ts is Timestamp
        ? _formatAdminDateTime(ts.toDate())
        : 'Time unavailable';
    final high =
        reason.toLowerCase().contains('fraud') ||
        reason.toLowerCase().contains('scam');
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: AppTheme.adaptiveSurface(Color(0xAA11191B)),
        borderRadius: BorderRadius.circular(15),
        border: Border.all(
          color: high ? const Color(0x66FF5252) : AppTheme.fillFaint,
        ),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Icon(
            high ? Icons.warning_amber : Icons.flag_outlined,
            color: high ? Colors.redAccent : AppTheme.luxuryGold,
          ),
          const SizedBox(width: 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  reason,
                  style: const TextStyle(fontWeight: FontWeight.w900),
                ),
                const SizedBox(height: 4),
                Text(
                  'Type: $type Ã¢â‚¬Â¢ Status: $status',
                  style: TextStyle(color: AppTheme.textMuted, fontSize: 12),
                ),
                Text(
                  'Reporter UID: $reporterUid',
                  style: TextStyle(color: AppTheme.textMuted, fontSize: 11),
                ),
                if (postId.isNotEmpty)
                  Text(
                    'Post: $postId',
                    style: TextStyle(color: AppTheme.textFaint, fontSize: 10),
                  ),
                if (commentId.isNotEmpty)
                  Text(
                    'Comment: $commentId',
                    style: TextStyle(color: AppTheme.textFaint, fontSize: 10),
                  ),
                if (details.isNotEmpty)
                  Text(
                    details,
                    style: TextStyle(color: AppTheme.textSecondary),
                  ),
                const SizedBox(height: 4),
                Text(
                  created,
                  style: TextStyle(color: AppTheme.textFaint, fontSize: 10),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

