  Future<void> _sendGraduatedBadge(int badgeNumber) async {
    final uid = _selectedGraduatedTargetUid;
    if (uid == null || uid.isEmpty) return;
    try {
      await BadgeService.grantGraduatedBadge(
        badgeNumber: badgeNumber,
        targetUid: uid,
      );
      if (!mounted) return;
      setState(() => _selectedGraduatedTargetUid = null);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'Graduated Badge #${badgeNumber.toString().padLeft(2, '0')} sent. The user will receive it in CDH Mail.',
          ),
        ),
      );
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not send Graduated badge: $e')),
        );
    }
  }

