final ValueNotifier<List<_CommunityPost>> _communityFeed =
    ValueNotifier<List<_CommunityPost>>(<_CommunityPost>[]);

String _referralBadgeLabel(int referrals) {
  if (referrals >= 100) return 'PLATINUM';
  if (referrals >= 25) return 'GOLD';
  if (referrals >= 5) return 'SILVER';
  return 'BRONZE';
}

Future<Uint8List?> _pickImageBytes() async {
  try {
    final picker = ImagePicker();
    final picked = await picker.pickImage(
      source: ImageSource.gallery,
      imageQuality: 68,
      maxWidth: 1280,
      maxHeight: 1280,
    );
    if (picked == null) return null;
    final bytes = await picked.readAsBytes();
    if (bytes.isEmpty) return null;
    if (bytes.length > 600000) return null;
    return bytes;
  } catch (_) {
    return null;
  }
}

Uint8List? _tryDecodeBase64(String value) {
  try {
    return base64Decode(value);
  } catch (_) {
    return null;
  }
}

String? _safeImageBase64(Uint8List? bytes) {
  if (bytes == null || bytes.isEmpty) return null;
  // Firestore documents are limited in size. Keep embedded images conservative
  // so a post can be persisted reliably without exceeding the document limit.
  if (bytes.length > 600000) return null;
  return base64Encode(bytes);
}

Future<String> _publishToCommunityFeed(
  _CommunityPost post, {
  String sourceType = 'alpha_den',
  String? sourceId,
}) async {
  final user = FirebaseAuth.instance.currentUser;
  var localPost = post;
  var persistedId = post.id;

  // Persist first. The Firestore document id is the single identity used by
  // the local feed as well, so returning from Alpha Den can never create a
  // duplicate card for the same backend post.
  if (user != null) {
    persistedId = await FeedService.createPost(
      FeedPostModel(
        id: '',
        authorUid: user.uid,
        authorDisplayName: post.username,
        authorPhotoUrl: post.profilePicUrl,
        authorPhotoBase64: _safeImageBase64(post.profilePicBytes),
        badge: post.badge,
        referralsCount: post.referrals,
        verified: post.verified,
        text: post.text,
        bullish: post.bullish,
        hashtags: post.hashtags,
        coins: post.coins,
        signalAsset: post.signalAsset,
        signalEntry: post.signalEntry,
        signalLongDirection: post.signalLongDirection,
        signalLeverage: post.signalLeverage,
        signalTp1: post.signalTp1,
        signalTp2: post.signalTp2,
        signalTp3: post.signalTp3,
        signalStopLoss: post.signalStopLoss,
        imageBase64: _safeImageBase64(post.imageBytes),
        articleTitle: sourceType == 'article'
            ? (post.text.split('\n\n').isNotEmpty
                  ? post.text.split('\n\n').first
                  : null)
            : null,
        articleBody: sourceType == 'article'
            ? (post.text.split('\n\n').length > 1
                  ? post.text.split('\n\n').sublist(1).join('\n\n')
                  : post.text)
            : null,
        articleThumbnailBase64: null,
        createdAt: post.createdAt,
        likesCount: post.likes,
        commentsCount: post.comments,
        tp1Hit: post.tp1Hit,
        tp2Hit: post.tp2Hit,
        tp3Hit: post.tp3Hit,
        stopLossHit: post.stopLossHit,
        breakEven: post.breakEven,
        winTradeCounted: post.winTradeCounted,
        tp1Profit: post.tp1Profit,
        tp2Profit: post.tp2Profit,
        tp3Profit: post.tp3Profit,
        stopLossProfit: post.stopLossProfit,
        breakEvenProfit: post.breakEvenProfit,
        winResultImageBase64: _safeImageBase64(post.winResultImageBytes),
        winTrades: post.winTrades,
        repostsCount: post.reposts,
        followersCount: post.followers,
        viewsCount: post.views,
        sharesCount: post.shares,
        sourceType: sourceType,
        sourceId: sourceId ?? post.id,
        isPublished: true,
      ),
    );
    localPost =
        _CommunityPost(
            id: persistedId,
            authorUid: post.authorUid,
            username: post.username,
            nickname: post.nickname,
            profilePicUrl: post.profilePicUrl,
            profilePicBytes: post.profilePicBytes,
            badge: post.badge,
            referrals: post.referrals,
            verified: post.verified,
            isPremium: post.isPremium,
            text: post.text,
            imageBytes: post.imageBytes,
            thumbnailBytes: post.thumbnailBytes,
            bullish: post.bullish,
            hashtags: post.hashtags,
            coins: post.coins,
            signalAsset: post.signalAsset,
            signalEntry: post.signalEntry,
            signalLongDirection: post.signalLongDirection,
            signalLeverage: post.signalLeverage,
            signalTp1: post.signalTp1,
            signalTp2: post.signalTp2,
            signalTp3: post.signalTp3,
            signalStopLoss: post.signalStopLoss,
            sourceType: sourceType,
            sourceId: sourceId ?? post.sourceId,
            createdAt: post.createdAt,
            tp1Hit: post.tp1Hit,
            tp2Hit: post.tp2Hit,
            tp3Hit: post.tp3Hit,
            stopLossHit: post.stopLossHit,
            breakEven: post.breakEven,
            winTradeCounted: post.winTradeCounted,
            tp1Profit: post.tp1Profit,
            tp2Profit: post.tp2Profit,
            tp3Profit: post.tp3Profit,
            stopLossProfit: post.stopLossProfit,
            breakEvenProfit: post.breakEvenProfit,
            winResultImageBytes: post.winResultImageBytes,
            winTrades: post.winTrades,
            commentItems: post.commentItems,
          )
          ..likes = post.likes
          ..comments = post.comments
          ..reposts = post.reposts
          ..followers = post.followers
          ..views = post.views
          ..shares = post.shares;
  }

  final next = <_CommunityPost>[localPost, ..._communityFeed.value];
  next.sort((a, b) => b.createdAt.compareTo(a.createdAt));
  _communityFeed.value = next;
  return persistedId;
}

