class FeedPage extends StatefulWidget {
  final bool isAdmin;

  const FeedPage({super.key, this.isAdmin = false});

  @override
  State<FeedPage> createState() => _FeedPageState();
}

class _FeedPageState extends State<FeedPage> {
  List<FeedPostModel> _backendPosts = const <FeedPostModel>[];
  final Map<String, Map<String, dynamic>> _publicAlphaProfiles =
      <String, Map<String, dynamic>>{};
  final Map<String, bool> _publicPremiumByUid = <String, bool>{};
  final Map<String, bool> _publicMentorshipByUid = <String, bool>{};
  final Map<String, String> _publicPremiumBadgeByUid = <String, String>{};
  final Map<String, String> _publicMentorshipBadgeByUid = <String, String>{};
  final Map<String, bool> _publicGraduatedByUid = <String, bool>{};
  List<_CommunityPost> _localPosts = const <_CommunityPost>[];
  bool _loading = true;
  String? _loadError;
  StreamSubscription<List<FeedPostModel>>? _feedSubscription;

  @override
  void initState() {
    super.initState();
    _localPosts = List<_CommunityPost>.of(_communityFeed.value);
    _communityFeed.addListener(_onLocalFeedChanged);

    _feedSubscription = FeedService.watchFeed(limit: 500).listen(
      (posts) {
        if (!mounted) return;

        setState(() {
          _backendPosts = posts;
          _loading = false;
          _loadError = null;
        });

        _loadPublicAuthorProfiles(posts);
      },
      onError: (Object error) {
        if (!mounted) return;
        setState(() {
          _loading = false;
          _loadError = error.toString();
        });
      },
    );
  }

  void _onLocalFeedChanged() {
    if (!mounted) return;
    final next = List<_CommunityPost>.of(_communityFeed.value);
    setState(() => _localPosts = next);
  }

  @override
  void dispose() {
    _communityFeed.removeListener(_onLocalFeedChanged);
    _feedSubscription?.cancel();
    super.dispose();
  }

  Future<void> _loadPublicAuthorProfiles(
    List<FeedPostModel> posts, {
    bool forceRefresh = false,
  }) async {
    final authorUids = posts
        .where((p) => p.authorUid.trim().isNotEmpty)
        .map((p) => p.authorUid)
        .toSet()
        .where(
          (uid) => forceRefresh || !_publicAlphaProfiles.containsKey(uid),
        )
        .toList();

    if (authorUids.isEmpty) return;

    final publicProfiles = <String, Map<String, dynamic>>{};
    final publicPremium = <String, bool>{};
    final publicMentorship = <String, bool>{};
    final publicPremiumBadges = <String, String>{};
    final publicMentorshipBadges = <String, String>{};
    final publicGraduatedByUid = <String, bool>{};

    for (var i = 0; i < authorUids.length; i += 30) {
      final chunk = authorUids.skip(i).take(30).toList();
      if (chunk.isEmpty) continue;

      try {
        final snap = await FirebaseFirestore.instance
            .collection('users')
            .where(FieldPath.documentId, whereIn: chunk)
            .get();

        for (final doc in snap.docs) {
          final data = doc.data();
          final raw = data['alphaDenProfile'];

          if (raw is Map) {
            publicProfiles[doc.id] = Map<String, dynamic>.from(raw);
          }

          publicPremium[doc.id] = data['isPremium'] == true;

          publicMentorship[doc.id] =
              data['mentorshipApproved'] == true ||
              data['isMentorship'] == true ||
              data['mentorship'] == true ||
              data['studentApproved'] == true ||
              data['isStudent'] == true;

          final premiumBadge =
              (data['confirmedPremiumBadgeType'] ?? '').toString();
          final mentorshipBadge =
              (data['confirmedMentorshipBadgeType'] ?? '').toString();

          if (premiumBadge.isNotEmpty) {
            publicPremiumBadges[doc.id] = premiumBadge;
          }

          if (mentorshipBadge.isNotEmpty) {
            publicMentorshipBadges[doc.id] = mentorshipBadge;
          }

          publicGraduatedByUid[doc.id] = data['graduated'] == true;
        }
      } catch (_) {}
    }

    if (!mounted) return;

    setState(() {
      _publicAlphaProfiles.addAll(publicProfiles);
      _publicPremiumByUid.addAll(publicPremium);
      _publicMentorshipByUid.addAll(publicMentorship);
      _publicPremiumBadgeByUid.addAll(publicPremiumBadges);
      _publicMentorshipBadgeByUid.addAll(publicMentorshipBadges);
      _publicGraduatedByUid.addAll(publicGraduatedByUid);
    });
  }

  Future<void> _loadFeed() async {
    try {
      // Explicit refresh only. Initial Feed loading is handled by the
      // realtime listener so we do not perform duplicate startup reads.
      final posts = await FeedService.loadFeed(limit: 500);

      if (!mounted) return;

      setState(() {
        _backendPosts = posts;
        _loading = false;
        _loadError = null;
      });

      await _loadPublicAuthorProfiles(posts, forceRefresh: true);
    } catch (error) {
      if (!mounted) return;

      setState(() {
        _loading = false;
        _loadError = error.toString();
      });
    }
  }

  Future<void> _refresh() async {
    if (!mounted) return;

    setState(() {
      _loading = true;
      _loadError = null;
    });

    await _loadFeed();
  }

  _CommunityPost _toCommunity(FeedPostModel p) {
    final publicProfile = _publicAlphaProfiles[p.authorUid];
    final publicUsername = (publicProfile?['username'] ?? p.authorDisplayName)
        .toString();
    final publicNickname =
        (publicProfile?['nickname'] ?? publicProfile?['handle'] ?? '')
            .toString();
    final publicReferrals =
        (publicProfile?['referrals'] as num?)?.toInt() ?? p.referralsCount;
    final publicWinTrades =
        (publicProfile?['winTrades'] as num?)?.toInt() ?? p.winTrades;
    final publicVerified =
        publicProfile?['verifiedCreatorApproved'] == true || p.verified;
    final publicPhoto = (publicProfile?['profilePicUrl'] ?? p.authorPhotoUrl)
        .toString();
    return _CommunityPost(
        id: p.id,
        authorUid: p.authorUid,
        username: publicUsername,
        nickname: publicNickname,
        profilePicUrl: publicPhoto,
        badge: p.badge,
        referrals: publicReferrals,
        verified: publicVerified,
        isPremium: _publicPremiumByUid[p.authorUid] == true,
        hasMentorship: _publicMentorshipByUid[p.authorUid] == true,
        graduated: _publicGraduatedByUid[p.authorUid] == true,
        premiumBadgeType: _publicPremiumBadgeByUid[p.authorUid] ?? '',
        mentorshipBadgeType: _publicMentorshipBadgeByUid[p.authorUid] ?? '',
        text: p.text,
        imageBytes: p.imageBase64 == null ? null : base64Decode(p.imageBase64!),
        thumbnailBytes: null,
        profilePicBytes:
            p.authorPhotoBase64 == null || p.authorPhotoBase64!.isEmpty
            ? null
            : _tryDecodeBase64(p.authorPhotoBase64!),
        bullish: p.bullish,
        hashtags: p.hashtags,
        coins: p.coins,
        createdAt: p.createdAt,
        signalAsset: p.signalAsset,
        signalEntry: p.signalEntry,
        signalLongDirection: p.signalLongDirection,
        signalLeverage: p.signalLeverage,
        signalTp1: p.signalTp1,
        signalTp2: p.signalTp2,
        signalTp3: p.signalTp3,
        signalStopLoss: p.signalStopLoss,
        sourceType: p.sourceType ?? 'community',
        sourceId: p.sourceId,
        tp1Hit: p.tp1Hit,
        tp2Hit: p.tp2Hit,
        tp3Hit: p.tp3Hit,
        stopLossHit: p.stopLossHit,
        breakEven: p.breakEven,
        winTradeCounted: p.winTradeCounted,
        tp1Profit: p.tp1Profit ?? '',
        tp2Profit: p.tp2Profit ?? '',
        tp3Profit: p.tp3Profit ?? '',
        stopLossProfit: p.stopLossProfit ?? '',
        breakEvenProfit: p.breakEvenProfit ?? '',
        winResultImageBytes:
            p.winResultImageBase64 == null || p.winResultImageBase64!.isEmpty
            ? null
            : _tryDecodeBase64(p.winResultImageBase64!),
        winTrades: publicWinTrades,
      )
      ..likes = p.likesCount
      ..comments = p.commentsCount
      ..reposts = p.repostsCount
      ..followers = p.followersCount
      ..views = p.viewsCount
      ..shares = p.sharesCount;
  }

  List<_CommunityPost> _mergedPosts() {
    final merged = <String, _CommunityPost>{};
    final aliases = <String, String>{};

    String contentKey(_CommunityPost post) {
      // A post can reach the Feed through more than one path (local state,
      // the general feed query, or an Alpha Den fallback). Those copies can
      // have different document/source IDs and slightly different timestamps.
      // Normalize the content and only bucket the timestamp to the minute so
      // the duplicate copy collapses while genuinely separate later posts
      // with the same text can still remain separate.
      final normalizedText = post.text
          .replaceAll(RegExp(r'\s+'), ' ')
          .trim()
          .toLowerCase();
      final normalizedAuthor = post.authorUid.trim().toLowerCase();
      final minuteBucket = post.createdAt.millisecondsSinceEpoch ~/ 60000;
      final imageMarker = post.imageBytes == null
          ? ''
          : '${post.imageBytes!.length}';
      return 'content:$normalizedAuthor|$normalizedText|$minuteBucket|${post.signalAsset ?? ''}|${post.signalEntry ?? ''}|${post.signalLongDirection ?? ''}|${post.signalLeverage ?? ''}|${post.signalTp1 ?? ''}|${post.signalTp2 ?? ''}|${post.signalTp3 ?? ''}|${post.signalStopLoss ?? ''}|$imageMarker';
    }

    void addPost(_CommunityPost post) {
      if (post.id.isEmpty) return;
      final identity = contentKey(post);
      final key = aliases[identity] ?? post.id;
      final existing = merged[key];
      if (existing == null) {
        merged[key] = post;
      } else {
        // Keep the already-rendered object so local/backend copies of the
        // same post cannot produce two Feed cards. Preserve live comment
        // state from whichever copy already has it.
        for (final comment in post.commentItems) {
          if (!existing.commentItems.any((c) => c.id == comment.id)) {
            existing.commentItems.add(comment);
          }
        }
        existing.comments = existing.comments < post.comments
            ? post.comments
            : existing.comments;
      }
      aliases[identity] = key;
    }

    for (final post in _localPosts) {
      addPost(post);
    }
    for (final post in _backendPosts) {
      addPost(_toCommunity(post));
    }

    final posts = merged.values.toList()
      ..sort((a, b) => b.createdAt.compareTo(a.createdAt));
    return posts;
  }

  @override
  Widget build(BuildContext context) {
    final posts = _mergedPosts();

    return RefreshIndicator(
      onRefresh: _refresh,
      child: ListView(
        physics: const AlwaysScrollableScrollPhysics(
          parent: BouncingScrollPhysics(),
        ),
        padding: const EdgeInsets.fromLTRB(16, 12, 16, 100),
        children: [
          const Align(
            alignment: Alignment.centerLeft,
            child: _GalacticFeedHeading(),
          ),
          const SizedBox(height: 8),
          const LiveMarketPreview(),
          const SizedBox(height: 6),
          _FeedQuickActions(isAdmin: widget.isAdmin),
          const SizedBox(height: 18),
          if (_loading && posts.isEmpty)
            const Padding(
              padding: EdgeInsets.all(18),
              child: Center(child: CircularProgressIndicator()),
            ),
          if (_loadError != null)
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 8, 12, 12),
              child: Text(
                'Community posts could not be refreshed. Your Feed is still available.',
                textAlign: TextAlign.center,
                style: TextStyle(color: AppTheme.textMuted, fontSize: 11),
              ),
            ),
          for (final post in posts) _CommunityPostCard(post: post),
        ],
      ),
    );
  }
}

