class _MailPage extends StatelessWidget {
  const _MailPage();

  @override
  Widget build(BuildContext context) {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null)
      return const Scaffold(body: Center(child: Text('Please sign in again.')));
    return Scaffold(
      appBar: AppBar(title: const Text('MAIL')),
      body: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
        stream: BadgeService.watchMail(user.uid),
        builder: (context, snapshot) {
          if (snapshot.hasError)
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(24),
                child: Text(
                  'Mail is temporarily unavailable.\n\n${snapshot.error}',
                  textAlign: TextAlign.center,
                  style: TextStyle(color: AppTheme.textMuted),
                ),
              ),
            );
          if (!snapshot.hasData)
            return const Center(child: CircularProgressIndicator());
          final docs = snapshot.data!.docs;
          if (docs.isEmpty)
            return Center(
              child: Text(
                'No mail yet.',
                style: TextStyle(color: AppTheme.textMuted),
              ),
            );
          return ListView.builder(
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 30),
            itemCount: docs.length,
            itemBuilder: (context, index) {
              final doc = docs[index];
              final data = doc.data();
              final badgeIds = ((data['badgeIds'] as List?) ?? const [])
                  .map((e) => e.toString())
                  .toList();
              final isBadgeMail = (data['type'] ?? '').toString() == 'badge';
              final unread = data['readAt'] == null;
              return Padding(
                padding: const EdgeInsets.only(bottom: 10),
                child: GlassCard(
                  child: ListTile(
                    onTap: () async {
                      if (unread) {
                        try {
                          await BadgeService.markMailRead(user.uid, doc.id);
                        } catch (_) {}
                      }
                      if (isBadgeMail &&
                          badgeIds.isNotEmpty &&
                          context.mounted) {
                        await Navigator.push(
                          context,
                          MaterialPageRoute(
                            builder: (_) => _BadgeCollectionPage(
                              messageId: doc.id,
                              badgeIds: badgeIds,
                            ),
                          ),
                        );
                      }
                    },
                    leading: Icon(
                      isBadgeMail
                          ? Icons.workspace_premium_rounded
                          : Icons.mail_outline_rounded,
                      color: unread ? AppTheme.luxuryGold : AppTheme.textMuted,
                    ),
                    title: Text(
                      (data['title'] ?? 'Crypto Doctors Hub').toString(),
                      style: TextStyle(
                        fontWeight: unread ? FontWeight.w900 : FontWeight.w700,
                      ),
                    ),
                    subtitle: Padding(
                      padding: const EdgeInsets.only(top: 5),
                      child: Text(
                        (data['body'] ?? '').toString(),
                        style: TextStyle(
                          color: AppTheme.textSoft,
                          fontSize: 10,
                          height: 1.4,
                        ),
                      ),
                    ),
                    trailing: isBadgeMail
                        ? Icon(
                            Icons.card_giftcard_rounded,
                            color: AppTheme.luxuryGold,
                          )
                        : null,
                  ),
                ),
              );
            },
          );
        },
      ),
    );
  }
}

class _BadgeCollectionPage extends StatelessWidget {
  final String messageId;
  final List<String> badgeIds;
  const _BadgeCollectionPage({required this.messageId, required this.badgeIds});

  String _badgeTitle(Map<String, dynamic> data) {
    switch ((data['badgeType'] ?? '').toString()) {
      case 'premium_lifetime':
        return 'Lifetime';
      case 'mentorship_installment_1':
        return 'Student 1';
      case 'mentorship_installment_2':
        return 'Student 2';
      case 'mentorship_installment_3':
        return 'Student 3';
      case 'mentorship_installment_4':
        return 'Student 4';
      case 'mentorship_installment':
        return 'Student 1';
      case 'mentorship_one_time':
        return 'Student';
      case 'referral_crown_blue':
        return 'Blue Crown';
      case 'referral_crown_purple':
        return 'Purple Crown';
      case 'referral_crown_gold':
        return 'Golden Crown';
      case 'referral_crown_black_gold':
        return 'Black + Gold Crown';
      default:
        return 'Premium';
    }
  }

  IconData _badgeIcon(Map<String, dynamic> data) =>
      (data['badgeType'] ?? '').toString().startsWith('mentorship_')
      ? Icons.school_rounded
      : Icons.workspace_premium_rounded;

  Color _badgeColor(Map<String, dynamic> data) {
    switch ((data['badgeType'] ?? '').toString()) {
      case 'premium_lifetime':
        return const Color(0xFFB56CFF);
      case 'graduated_admin':
        return Colors.black;
      case 'mentorship_installment_1':
      case 'mentorship_installment_2':
      case 'mentorship_installment_3':
      case 'mentorship_installment_4':
      case 'mentorship_installment':
        return Colors.white;
      case 'mentorship_one_time':
        return const Color(0xFF8DB0FF);
      default:
        return AppTheme.luxuryGold;
    }
  }

  Future<void> _collect(
    BuildContext context,
    String badgeId,
    Map<String, dynamic> data,
  ) async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;
    try {
      final status = (data['status'] ?? '').toString();
      Map<String, dynamic> collected = data;
      if (status == 'available') {
        collected = await BadgeService.collectBadge(
          uid: user.uid,
          badgeId: badgeId,
        );
      } else if (status != 'collected') {
        return;
      }
      if (!context.mounted) return;
      if (status == 'available') {
        await showDialog<void>(
          context: context,
          barrierDismissible: false,
          builder: (_) => _BadgeRewardAnimation(data: {...data, ...collected}),
        );
      }
      if (!context.mounted) return;
      final confirmed = await showDialog<bool>(
        context: context,
        barrierDismissible: false,
        builder: (_) => _BadgeProfilePreview(data: data),
      );
      if (confirmed == true && context.mounted) {
        try {
          await BadgeService.confirmBadge(
            uid: user.uid,
            badgeId: badgeId,
            badgeType: (data['badgeType'] ?? '').toString(),
          );
          if (context.mounted) Navigator.pop(context);
        } catch (error) {
          if (context.mounted)
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text('The badge could not be confirmed yet: $error'),
              ),
            );
        }
      }
    } catch (error) {
      if (context.mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('This badge is not ready to collect: $error')),
        );
    }
  }

  @override
  Widget build(BuildContext context) {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null)
      return const Scaffold(body: Center(child: Text('Please sign in again.')));
    return Scaffold(
      appBar: AppBar(title: const Text('EARNED BADGES')),
      body: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
        stream: BadgeService.watchBadgeEntitlements(user.uid),
        builder: (context, snapshot) {
          if (!snapshot.hasData)
            return const Center(child: CircularProgressIndicator());
          final docs = snapshot.data!.docs
              .where((d) => badgeIds.contains(d.id))
              .toList();
          if (docs.isEmpty)
            return Center(
              child: Text(
                'No collectible badges are ready.',
                style: TextStyle(color: AppTheme.textMuted),
              ),
            );
          return ListView(
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 30),
            children: [
              const Text(
                'Congratulations! You have earned these badges.',
                style: TextStyle(fontSize: 17, fontWeight: FontWeight.w900),
              ),
              const SizedBox(height: 7),
              Text(
                'Collect each prepared badge, preview your Alpha Den profile, then confirm it.',
                style: TextStyle(
                  color: AppTheme.textMuted,
                  fontSize: 10,
                  height: 1.4,
                ),
              ),
              const SizedBox(height: 16),
              for (final doc in docs) ...[
                Builder(
                  builder: (context) {
                    final data = doc.data();
                    final status = (data['status'] ?? '').toString();
                    final color = _badgeColor(data);
                    return GlassCard(
                      child: ListTile(
                        leading: Icon(_badgeIcon(data), color: color, size: 27),
                        title: Text(
                          _badgeTitle(data),
                          style: TextStyle(
                            color: color,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        subtitle: Text(
                          status == 'confirmed'
                              ? 'Confirmed and applied to your profile.'
                              : status == 'collected'
                              ? 'Collected Ã¢â‚¬â€ ready for profile confirmation.'
                              : 'Ready to collect.',
                          style: TextStyle(
                            color: AppTheme.textMuted,
                            fontSize: 10,
                          ),
                        ),
                        trailing: status == 'available'
                            ? FilledButton(
                                onPressed: () =>
                                    _collect(context, doc.id, data),
                                child: const Text('COLLECT'),
                              )
                            : status == 'collected'
                            ? FilledButton(
                                onPressed: () =>
                                    _collect(context, doc.id, data),
                                child: const Text('CONTINUE'),
                              )
                            : Icon(
                                Icons.check_circle_rounded,
                                color: AppTheme.neonGreen,
                              ),
                      ),
                    );
                  },
                ),
                const SizedBox(height: 10),
              ],
            ],
          );
        },
      ),
    );
  }
}

