class _ContentReportSupportPage extends StatefulWidget {
  final String? postId;
  final String? commentId;
  final String? authorUid;
  const _ContentReportSupportPage({
    this.postId,
    this.commentId,
    this.authorUid,
  });
  @override
  State<_ContentReportSupportPage> createState() =>
      _ContentReportSupportPageState();
}

class _ContentReportSupportPageState extends State<_ContentReportSupportPage> {
  static const reasons = <String>[
    'Abusive language',
    'Explicit content',
    'Misinformation',
    'Misguiding',
    'Fraud',
  ];
  String? selectedReason;
  final details = TextEditingController();
  bool submitted = false;
  bool sending = false;

  @override
  void dispose() {
    details.dispose();
    super.dispose();
  }

  Future<void> _submit() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null || selectedReason == null || sending) return;
    setState(() => sending = true);
    try {
      String? reportId;
      if ((widget.commentId ?? '').isNotEmpty &&
          (widget.postId ?? '').isNotEmpty) {
        reportId = await FeedService.reportComment(
          postId: widget.postId!,
          commentId: widget.commentId!,
          reporterUid: user.uid,
          reason: selectedReason!,
          details: details.text.trim(),
        );
      } else if ((widget.postId ?? '').isNotEmpty) {
        reportId = await FeedService.reportPost(
          postId: widget.postId!,
          reporterUid: user.uid,
          reason: selectedReason!,
          details: details.text.trim(),
        );
      }
      if (reportId != null) {
        await CustomerSupportService.queueReportEmail(
          reportId: reportId,
          email: user.email ?? '',
          uid: user.uid,
        );
      }
      if (!mounted) return;
      setState(() {
        sending = false;
        submitted = true;
      });
    } catch (_) {
      if (!mounted) return;
      setState(() => sending = false);
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Could not submit the report. Please try again.'),
        ),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppTheme.adaptiveSurface(Color(0xFF070B10)),
      appBar: AppBar(
        title: const Text(
          'CONTENT REPORT',
          style: TextStyle(fontWeight: FontWeight.w900, letterSpacing: 1.1),
        ),
      ),
      body: RadioGroup<String>(
        groupValue: selectedReason,
        onChanged: (value) {
          if (!submitted) setState(() => selectedReason = value);
        },
        child: ListView(
          padding: const EdgeInsets.fromLTRB(18, 18, 18, 32),
          children: [
            const Text(
              'REPORT CONTENT / USER',
              style: TextStyle(fontSize: 18, fontWeight: FontWeight.w900),
            ),
            const SizedBox(height: 6),
            Text(
              'Choose the reason that best describes the issue. Your report will be sent to moderation.',
              style: TextStyle(
                color: AppTheme.textSoft,
                fontSize: 12,
                height: 1.45,
              ),
            ),
            const SizedBox(height: 16),
            for (final reason in reasons)
              Card(
                color: selectedReason == reason
                    ? const Color(0x1A59D7FF)
                    : AppTheme.adaptiveSurface(Color(0xFF15181E)),
                child: RadioListTile<String>(
                  value: reason,
                  enabled: !submitted,
                  title: Text(
                    reason,
                    style: const TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                  activeColor: AppTheme.luxuryGold,
                ),
