    );
  }
}

Future<void> showCustomerSupportSheet(BuildContext context) async {
  final options = <String>[
    'Account & Login',
    'Premium & Payments',
    'Alpha Den',
    'CD Feed & Posts',
    'Technical Issue',
    'Report Content / User',
    'Feature Request',
    'Submit a Ticket',
    'My Tickets',
  ];
  await showModalBottomSheet<void>(
    context: context,
    backgroundColor: AppTheme.adaptiveSurface(Color(0xFF070C12)),
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
    ),
    builder: (sheetContext) => SafeArea(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(18, 12, 18, 18),
        child: ConstrainedBox(
          constraints: BoxConstraints(
            maxHeight: MediaQuery.of(sheetContext).size.height * 0.78,
          ),
          child: Column(
            children: [
              Container(
                width: 42,
                height: 4,
                decoration: BoxDecoration(
                  color: AppTheme.borderSoft,
                  borderRadius: BorderRadius.circular(8),
                ),
              ),
              const SizedBox(height: 12),
              const Row(
                children: [
                  Icon(Icons.support_agent_rounded, color: Color(0xFF59D7FF)),
                  SizedBox(width: 9),
                  Text(
                    'CUSTOMER SUPPORT',
                    style: TextStyle(
                      fontWeight: FontWeight.w900,
                      letterSpacing: 1.0,
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 8),
              Expanded(
                child: ListView(
                  padding: EdgeInsets.zero,
                  children: [
                    ...options.map(
                      (label) => ListTile(
                        dense: true,
                        contentPadding: EdgeInsets.zero,
                        leading: Icon(
                          Icons.chevron_right_rounded,
                          color: AppTheme.textMuted,
                        ),
                        title: Text(
                          label,
                          style: const TextStyle(
                            fontSize: 13,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                        onTap: () async {
                          Navigator.of(sheetContext).pop();
                          // Let the Customer Support sheet finish closing before
                          // presenting another route/dialog. Opening the next
                          // route during the sheet's pop animation can leave a
                          // transient red Flutter error overlay on some devices.
                          await Future<void>.delayed(
                            const Duration(milliseconds: 220),
                          );
                          if (!context.mounted) return;
                          if (label == 'Report Content / User') {
                            await _openContentReportSupportPage(context);
                          } else if (label == 'Submit a Ticket') {
                            await Navigator.of(context).push(
                              MaterialPageRoute(
                                builder: (_) => const SubmitSupportTicketPage(),
                              ),
                            );
                          } else if (label == 'My Tickets') {
                            await Navigator.of(context).push(
                              MaterialPageRoute(
                                builder: (_) => const MySupportTicketsPage(),
                              ),
                            );
                          } else {
                            await showSupportRequestDialog(context, label);
                          }
                        },
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    ),
  );
}

Future<void> showSupportRequestDialog(
  BuildContext context,
  String category,
) async {
  final user = FirebaseAuth.instance.currentUser;
  if (user == null) {
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please sign in before contacting Customer Support.'),
        ),
      );
    }
    return;
  }

  final result = await showDialog<Map<String, String>?>(
    context: context,
    barrierDismissible: false,
    builder: (dialogContext) {
      String details = '';
      return AlertDialog(
        backgroundColor: AppTheme.adaptiveSurface(const Color(0xFF080D13)),
        title: Text(category.toUpperCase()),
        content: ConstrainedBox(
          constraints: BoxConstraints(
            maxHeight: MediaQuery.of(dialogContext).size.height * 0.32,
          ),
          child: SingleChildScrollView(
            child: TextField(
              autofocus: true,
              minLines: 4,
              maxLines: 7,
              onChanged: (value) => details = value,
              decoration: const InputDecoration(
                labelText: 'ENTER DETAILS',
                hintText: 'Describe what you need help withÃ¢â‚¬Â¦',
              ),
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext)
                .pop(<String, String>{'action': 'cancel', 'details': details}),
            child: const Text('CANCEL'),
          ),
          TextButton(
            onPressed: () => Navigator.of(dialogContext)
                .pop(<String, String>{'action': 'save', 'details': details}),
            child: const Text('SAVE'),
          ),
          TextButton(
            onPressed: () => Navigator.of(dialogContext)
                .pop(<String, String>{'action': 'send', 'details': details}),
            child: const Text('SEND'),
          ),
          FilledButton(
            onPressed: () => Navigator.of(dialogContext)
                .pop(<String, String>{'action': 'submit', 'details': details}),
            child: const Text('SUBMIT'),
          ),
        ],
      );
    },
  );

  final action = result?['action'];
  final details = (result?['details'] ?? '').trim();
  if (action == null || action == 'cancel') return;
  if (details.isEmpty) {
    if (!context.mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('Please enter your support details first.')),
    );
    return;
  }

  final status = action == 'save' ? 'draft' : 'submitted';
  final actionLabel = action == 'save' ? 'saved' : 'sent successfully';

  try {
    await CustomerSupportService.createRequest(
      uid: user.uid,
      email: user.email ?? '',
      category: category,
      details: details,
      status: status,
      action: action,
    );

    if (!context.mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          action == 'save'
              ? 'Customer Support details saved successfully.'
              : 'Customer Support request $actionLabel.',
        ),
      ),
    );
  } catch (_) {
    if (!context.mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text(
          'Customer Support could not process the request. Please try again.',
        ),
      ),
    );
  }
}

class SubmitSupportTicketPage extends StatefulWidget {
  const SubmitSupportTicketPage({super.key});
  @override
  State<SubmitSupportTicketPage> createState() =>
      _SubmitSupportTicketPageState();
}

class _SubmitSupportTicketPageState extends State<SubmitSupportTicketPage> {
  final controller = TextEditingController();
  bool sending = false;

  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  Future<void> _submit() async {
    final user = FirebaseAuth.instance.currentUser;
    final details = controller.text.trim();
    if (user == null) {
      ScaffoldMessenger.of(context)
          .showSnackBar(const SnackBar(content: Text('Please sign in first.')));
      return;
    }
    if (details.isEmpty || sending) return;
    setState(() => sending = true);
    try {
      final profile = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();
      final data = profile.data() ?? <String, dynamic>{};
      final name =
          (data['name'] ??
                  data['displayName'] ??
                  user.displayName ??
                  'CDH User')
              .toString();
      final ticketId = await CustomerSupportService.createTicket(
        uid: user.uid,
        userName: name,
        email: user.email ?? '',
        details: details,
      );
      if (!mounted) return;
      await showDialog<void>(
        context: context,
        builder: (ctx) => AlertDialog(
          backgroundColor: AppTheme.adaptiveSurface(const Color(0xFF080D13)),
          title: const Text('TICKET SUBMITTED'),
          content: Text(
            'Your ticket ID is:\n\n$ticketId\n\nPlease keep this ID for future support conversations.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text('OK'),
            ),
          ],
        ),
      );
      if (mounted) Navigator.pop(context);
    } catch (_) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not submit the ticket. Please try again.'),
          ),
        );
    } finally {
      if (mounted) setState(() => sending = false);
    }
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('SUBMIT A TICKET')),
    backgroundColor: AppTheme.adaptiveSurface(const Color(0xFF070B10)),
    body: ListView(
      padding: const EdgeInsets.fromLTRB(18, 18, 18, 32),
      children: [
        const Text(
          'NEW SUPPORT TICKET',
          style: TextStyle(fontSize: 19, fontWeight: FontWeight.w900),
        ),
        const SizedBox(height: 7),
        Text(
          'Use this when your issue does not fit an existing Customer Support category.',
          style: TextStyle(color: AppTheme.textSoft, fontSize: 12, height: 1.4),
        ),
        const SizedBox(height: 18),
        TextField(
          controller: controller,
          minLines: 8,
          maxLines: 14,
          textInputAction: TextInputAction.newline,
          decoration: const InputDecoration(
            labelText: 'DESCRIBE YOUR ISSUE',
            hintText: 'Enter your complete issue or questionÃ¢â‚¬Â¦',
            alignLabelWithHint: true,
          ),
        ),
        const SizedBox(height: 18),
        FilledButton.icon(
          onPressed: sending ? null : _submit,
          icon: const Icon(Icons.send_rounded),
          label: Text(sending ? 'SUBMITTINGÃ¢â‚¬Â¦' : 'SUBMIT TICKET'),
        ),
        const SizedBox(height: 8),
        OutlinedButton.icon(
          onPressed: () => Navigator.pop(context),
          icon: const Icon(Icons.close),
          label: const Text('CANCEL'),
        ),
      ],
    ),
  );
}

class MySupportTicketsPage extends StatelessWidget {
  const MySupportTicketsPage({super.key});
  @override
  Widget build(BuildContext context) {
    final user = FirebaseAuth.instance.currentUser;
    return Scaffold(
      appBar: AppBar(title: const Text('MY SUPPORT TICKETS')),
      backgroundColor: AppTheme.adaptiveSurface(const Color(0xFF070B10)),
      body: user == null
          ? const Center(child: Text('Please sign in.'))
          : StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream: CustomerSupportService.userTickets(user.uid),
              builder: (context, snapshot) {
                if (snapshot.connectionState == ConnectionState.waiting)
                  return const Center(child: CircularProgressIndicator());
                if (snapshot.hasError)
                  return Center(
                    child: Text('Unable to load tickets: ${snapshot.error}'),
                  );
                final docs =
                    snapshot.data?.docs ??
                    const <QueryDocumentSnapshot<Map<String, dynamic>>>[];
                if (docs.isEmpty)
                  return const Center(child: Text('No support tickets yet.'));
                return ListView.builder(
                  padding: const EdgeInsets.all(14),
                  itemCount: docs.length,
                  itemBuilder: (_, i) =>
                      _SupportTicketTile(doc: docs[i], isAdmin: false),
                );
              },
            ),
    );
  }
}

