class _SupportTicketConversationPageState
    extends State<SupportTicketConversationPage> {
  final controller = TextEditingController();
  bool sending = false;
  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  Future<void> _send() async {
    final u = FirebaseAuth.instance.currentUser;
    final text = controller.text.trim();
    if (u == null || text.isEmpty || sending) return;
    setState(() => sending = true);
    try {
      final profile = await FirebaseFirestore.instance
          .collection('users')
          .doc(u.uid)
          .get();
      final d = profile.data() ?? <String, dynamic>{};
      final name =
          (d['name'] ?? d['displayName'] ?? u.displayName ?? 'CDH User')
              .toString();
      await CustomerSupportService.sendTicketMessage(
        ticketDocId: widget.doc.id,
        senderUid: u.uid,
        senderName: name,
        senderRole: widget.isAdmin ? 'admin' : 'user',
        text: text,
      );
      controller.clear();
    } catch (_) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Could not send the response.')),
        );
    } finally {
      if (mounted) setState(() => sending = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final d = widget.doc.data();
    final ticket = (d['ticketId'] ?? widget.doc.id).toString();
    return Scaffold(
      appBar: AppBar(
        title: Text(ticket),
        actions: [
          if (widget.isAdmin)
            PopupMenuButton<String>(
              onSelected: (v) =>
                  CustomerSupportService.updateTicketStatus(widget.doc.id, v),
              itemBuilder: (_) => const [
                PopupMenuItem(value: 'open', child: Text('OPEN')),
                PopupMenuItem(
                  value: 'awaiting_user',
                  child: Text('AWAITING USER'),
                ),
                PopupMenuItem(value: 'closed', child: Text('CLOSED')),
              ],
            ),
        ],
      ),
      backgroundColor: AppTheme.adaptiveSurface(const Color(0xFF070B10)),
      body: Column(
        children: [
          Expanded(
            child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream: CustomerSupportService.ticketMessages(widget.doc.id)
                  .orderBy('createdAt')
                  .snapshots(),
              builder: (context, snapshot) {
                final messages =
                    snapshot.data?.docs ??
                    const <QueryDocumentSnapshot<Map<String, dynamic>>>[];
                return ListView.builder(
                  reverse: false,
                  padding: const EdgeInsets.all(14),
                  itemCount: messages.length + 1,
                  itemBuilder: (_, i) {
                    if (i == 0)
                      return Container(
                        margin: const EdgeInsets.only(bottom: 12),
                        padding: const EdgeInsets.all(14),
                        decoration: BoxDecoration(
                          borderRadius: BorderRadius.circular(16),
                          border: Border.all(color: AppTheme.fillFaint),
                        ),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              '${d['userName'] ?? 'User'} Ã¢â‚¬Â¢ ${d['email'] ?? ''}',
                              style: const TextStyle(
                                fontWeight: FontWeight.w800,
                              ),
                            ),
                            const SizedBox(height: 6),
                            Text((d['details'] ?? '').toString()),
                          ],
                        ),
                      );
                    final m = messages[i - 1].data();
                    final mine =
                        (m['senderRole'] ?? '') ==
                        (widget.isAdmin ? 'admin' : 'user');
                    final ts = m['createdAt'];
                    final when = ts is Timestamp
                        ? _supportTicketFormatAdminDateTime(ts.toDate())
                        : '';
                    return Align(
                      alignment: mine
                          ? Alignment.centerRight
                          : Alignment.centerLeft,
                      child: Container(
                        margin: const EdgeInsets.only(bottom: 8),
                        padding: const EdgeInsets.symmetric(
                          horizontal: 13,
                          vertical: 9,
                        ),
                        constraints: const BoxConstraints(maxWidth: 360),
                        decoration: BoxDecoration(
                          color: mine
                              ? const Color(0xFF174D3B)
                              : const Color(0xFF20272D),
                          borderRadius: BorderRadius.circular(14),
                        ),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              (m['senderName'] ?? '').toString(),
                              style: TextStyle(
                                color: AppTheme.luxuryGold,
                                fontSize: 10,
                                fontWeight: FontWeight.w800,
                              ),
                            ),
                            const SizedBox(height: 3),
                            Text((m['text'] ?? '').toString()),
                            if (when.isNotEmpty)
                              Align(
                                alignment: Alignment.centerRight,
                                child: Text(
                                  when,
                                  style: TextStyle(
                                    color: AppTheme.textFaint,
                                    fontSize: 9,
                                  ),
                                ),
                              ),
                          ],
                        ),
                      ),
                    );
                  },
                );
              },
            ),
          ),
          SafeArea(
            child: Padding(
              padding: const EdgeInsets.fromLTRB(10, 6, 10, 10),
              child: Row(
                children: [
                  Expanded(
                    child: TextField(
                      controller: controller,
                      minLines: 1,
                      maxLines: 4,
                      decoration: const InputDecoration(
                        hintText: 'Write a responseÃ¢â‚¬Â¦',
                      ),
                    ),
                  ),
                  const SizedBox(width: 8),
                  IconButton(
                    onPressed: sending ? null : _send,
                    icon: const Icon(Icons.send_rounded),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

