class _TradeExchangeCard extends StatelessWidget {
  final String exchangeId;
  final Map<String, dynamic> referral;
  final bool compact;
  const _TradeExchangeCard({
    required this.exchangeId,
    required this.referral,
    this.compact = false,
  });

  String get name => switch (exchangeId) {
    'binance' => 'Binance',
    'bitget' => 'Bitget',
    'mexc' => 'MEXC',
    _ => 'BingX',
  };
  String get logoUrl => switch (exchangeId) {
    'binance' => 'https://www.binance.com/favicon.ico',
    'bitget' => 'https://www.bitget.com/favicon.ico',
    'mexc' => 'https://www.mexc.com/favicon.ico',
    _ => 'https://bingx.com/favicon.ico',
  };

  Future<void> _open() async {
    final raw = (referral['link'] ?? '').toString().trim();
    final uri = Uri.tryParse(raw);
    if (uri == null || !uri.hasScheme || uri.host.isEmpty) return;
    await launchUrl(uri, mode: LaunchMode.externalApplication);
  }

  @override
  Widget build(BuildContext context) {
    final link = (referral['link'] ?? '').toString().trim();
    final code = (referral['code'] ?? '').toString().trim();
    return Container(
      padding: EdgeInsets.all(compact ? 9 : 12),
      decoration: BoxDecoration(
        color: AppTheme.adaptiveSurface(const Color(0xD00B1118)),
        borderRadius: BorderRadius.circular(17),
