class _PendingCommunityChat {
  final String id;
  final String type;
  final String text;
  final Uint8List? bytes;
  final String? replyText;
  String state;
  _PendingCommunityChat({
    required this.id,
    required this.type,
    required this.text,
    this.bytes,
    this.replyText,
    this.state = 'sending',
  });
}

bool _cdhChatLooksLikeLiveSignal(String text) {
  final x = text.toLowerCase().replaceAll(RegExp(r'\s+'), ' ');
  final patterns = <RegExp>[
    RegExp(r'\bentry\s*[:=@]?\s*[0-9]'),
    RegExp(r'\btp\s*[123]\s*[:=@]?\s*[0-9]'),
    RegExp(r'\bstop\s*loss\s*[:=@]?\s*[0-9]'),
    RegExp(r'\bstoploss\s*[:=@]?\s*[0-9]'),
    RegExp(r'\bleverage\s*[:=@]?\s*[0-9]+x?'),
    RegExp(r'\b(long|short)\b.{0,24}\b(usdt|usd|btc|eth|sol|xrp)\b'),
    RegExp(r'\b(usdt|usd)\b.{0,18}\b(tp1|tp2|tp3|stoploss|stop loss)\b'),
    RegExp(r'\b(tp1|tp2|tp3)\b.{0,18}\b(stoploss|stop loss)\b'),
  ];
  return patterns.any((p) => p.hasMatch(x));
}

String _cdhChatViolationCategory(String text) {
  if (_cdhChatLooksLikeLiveSignal(text)) return 'LIVE_SIGNAL_DATA';
  final x = text.toLowerCase();
  if (RegExp(r'https?://|www\\.|t\\.me/|wa\\.me/|discord\\.gg/').hasMatch(x))
    return 'EXTERNAL_PROMOTION';
  if (RegExp(
    r'\\b(sex|porn|xxx|nude|naked|fuck|dick|pussy|blowjob|onlyfans)\\b',
  ).hasMatch(x))
    return 'SEXUAL_CONTENT';
  return 'PROHIBITED_CONTENT';
}

