class _CommunityChatPage extends StatefulWidget {
  final bool isAdmin;
  const _CommunityChatPage({required this.isAdmin});
  @override
  State<_CommunityChatPage> createState() => _CommunityChatPageState();
}

class _CommunityChatPageState extends State<_CommunityChatPage> {
  final _controller = TextEditingController();
  final _scroll = ScrollController();
  final _picker = ImagePicker();
  final Map<String, Future<Map<String, dynamic>>> _profileFutures = {};
  final List<_PendingCommunityChat> _pending = [];
  bool _sending = false;
  DateTime? _cooldownUntil;
  Timer? _cooldownTimer;
  String? _reactionMessageId;
  Map<String, dynamic>? _replyingTo;

  @override
  void dispose() {
    _controller.dispose();
    _scroll.dispose();
    _cooldownTimer?.cancel();
    super.dispose();
  }

  Future<Map<String, dynamic>> _profile() async {
    final u = FirebaseAuth.instance.currentUser;
    if (u == null) return <String, dynamic>{};
    final d =
        (await FirebaseFirestore.instance.collection('users').doc(u.uid).get())
            .data() ??
        <String, dynamic>{};
    return {
      'uid': u.uid,
      'nickname':
          (d['nickname'] ??
                  d['handle'] ??
                  d['displayName'] ??
                  u.email?.split('@').first ??
                  'User')
              .toString(),
      'photoUrl': (d['photoUrl'] ?? d['photoURL'] ?? u.photoURL ?? '')
          .toString(),
    };
  }

  Future<Map<String, dynamic>> _senderProfile(String uid) {
    return _profileFutures.putIfAbsent(uid, () async {
      final d =
          (await FirebaseFirestore.instance.collection('users').doc(uid).get())
              .data() ??
          <String, dynamic>{};
      return {
        'nickname': (d['nickname'] ?? d['handle'] ?? d['displayName'] ?? 'User')
            .toString(),
        'photoUrl': (d['photoUrl'] ?? d['photoURL'] ?? '').toString(),
        'avatarBase64': (d['appAvatarBase64'] ?? '').toString(),
        'isPremium': d['isPremium'] == true,
        'graduated': d['graduated'] == true,
      };
    });
  }

  bool get _onCooldown =>
      _cooldownUntil != null && DateTime.now().isBefore(_cooldownUntil!);

  void _startCooldown() {
    _cooldownUntil = DateTime.now().add(const Duration(seconds: 3));
    _cooldownTimer?.cancel();
    _cooldownTimer = Timer.periodic(const Duration(milliseconds: 100), (timer) {
      if (!mounted || !_onCooldown) {
        timer.cancel();
        if (mounted) setState(() {});
      } else {
        setState(() {});
      }
    });
  }

  Future<void> _sendText([String? preset, String messageType = 'text']) async {
    final text = (preset ?? _controller.text).trim();
    if (text.isEmpty || _sending || _onCooldown) return;
    final u = FirebaseAuth.instance.currentUser;
    if (u == null) return;
    if (_cdhChatLooksLikeLiveSignal(text)) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'This message was removed because Live Call signal data cannot be posted in Chat.',
            ),
          ),
        );
      return;
    }
    final lowerText = text.toLowerCase();
    if (RegExp(r'https?://|www\.|t\.me/|wa\.me/|discord\.gg/')
            .hasMatch(lowerText) ||
        RegExp(
          r'\b(sex|porn|xxx|nude|naked|fuck|dick|pussy|blowjob|onlyfans)\b',
        ).hasMatch(lowerText)) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Warning: Your message was removed because it violated the CDH Chat Room rules.',
            ),
          ),
        );
      return;
    }
    final localId = 'local_${DateTime.now().microsecondsSinceEpoch}';
    final reply = _replyingTo == null
        ? null
        : Map<String, dynamic>.from(_replyingTo!);
    final replyText = reply == null ? null : (reply['text'] ?? '').toString();
    setState(() {
      _pending.add(
        _PendingCommunityChat(
          id: localId,
          type: messageType,
          text: text,
          replyText: replyText,
        ),
      );
      _replyingTo = null;
      if (preset == null) _controller.clear();
    });
    try {
      final profile = await _profile();
      await _commitMessage(
        text: text,
        type: messageType,
        profile: profile,
        replyTo: reply,
      );
      if (mounted) setState(() => _pending.removeWhere((x) => x.id == localId));
    } catch (e) {
      if (mounted)
        setState(() {
          final i = _pending.indexWhere((x) => x.id == localId);
          if (i >= 0) _pending[i].state = 'failed';
        });
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Message could not be sent: $e')),
        );
    }
  }

  Future<void> _pickImage({bool gif = false}) async {
    if (_sending || _onCooldown) return;
    if (gif) {
      final result = await FilePicker.pickFiles(
        type: FileType.custom,
        allowedExtensions: ['gif'],
      );
      if (result.isEmpty) return;
      final bytes = await result.first.readAsBytes();
      await _sendMedia(bytes, 'gif', 'image/gif');
      return;
    }
    final file = await _picker.pickImage(
      source: ImageSource.gallery,
      imageQuality: 84,
      maxWidth: 1800,
      maxHeight: 1800,
    );
    if (file == null) return;
    await _sendMedia(await file.readAsBytes(), 'image', 'image/jpeg');
  }

  Future<void> _sendMedia(
    Uint8List bytes,
    String type,
    String contentType,
  ) async {
    if (bytes.length > 4 * 1024 * 1024) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Media must be 4 MB or smaller.')),
        );
      return;
    }
    final u = FirebaseAuth.instance.currentUser;
    if (u == null) return;
    final localId = 'local_${DateTime.now().microsecondsSinceEpoch}';
    setState(
      () => _pending.add(
        _PendingCommunityChat(id: localId, type: type, text: '', bytes: bytes),
      ),
    );
    try {
      final ref = await DriveStorageService.uploadBytes(
        bytes: bytes,
        fileName:
            'chat_${u.uid}_${DateTime.now().millisecondsSinceEpoch}.${type == 'gif' ? 'gif' : 'jpg'}',
        contentType: contentType,
        scope: 'chat_media',
        ownerUid: u.uid,
      );
      final profile = await _profile();
      await _commitMessage(
        text: '',
        type: type,
        profile: profile,
        driveRef: ref,
      );
      if (mounted) setState(() => _pending.removeWhere((x) => x.id == localId));
    } catch (e) {
      if (mounted)
        setState(() {
          final i = _pending.indexWhere((x) => x.id == localId);
          if (i >= 0) _pending[i].state = 'failed';
        });
      if (mounted)
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Media could not be sent: $e')));
    }
  }

  Future<void> _commitMessage({
    required String text,
    required String type,
    required Map<String, dynamic> profile,
    String? driveRef,
    String? kind,
    Map<String, dynamic>? replyTo,
    String? forwardedFrom,
  }) async {
    final u = FirebaseAuth.instance.currentUser;
    if (u == null) return;
    final db = FirebaseFirestore.instance;
    final msg = db.collection('communityChatMessages').doc();
    final throttle = db.collection('communityChatThrottle').doc(u.uid);
    final batch = db.batch();
    final data = <String, dynamic>{
      'senderUid': u.uid,
      'type': type,
      'kind': kind ?? 'user',
      'text': text,
      'driveRef': driveRef ?? '',
      'nickname': profile['nickname'] ?? 'User',
      'photoUrl': profile['photoUrl'] ?? '',
      'createdAt': FieldValue.serverTimestamp(),
      'reactions': <String, String>{},
      'delivered': true,
      'readBy': <String>[],
    };
    if (replyTo != null && (replyTo['id'] ?? '').toString().isNotEmpty)
      data['replyTo'] = {
        'id': replyTo['id'],
        'senderUid': replyTo['senderUid'] ?? '',
        'text': replyTo['text'] ?? '',
        'type': replyTo['type'] ?? 'text',
      };
    if (forwardedFrom != null && forwardedFrom.isNotEmpty)
      data['forwardedFrom'] = forwardedFrom;
    batch.set(msg, data);
    batch.set(throttle, {
      'uid': u.uid,
      'nextAllowedAt': Timestamp.fromDate(
        DateTime.now().add(const Duration(seconds: 3)),
      ),
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
    await batch.commit();
    if (mounted) {
      _startCooldown();
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (_scroll.hasClients)
          _scroll.animateTo(
            _scroll.position.maxScrollExtent,
            duration: const Duration(milliseconds: 220),
            curve: Curves.easeOutCubic,
          );
      });
    }
  }

  Future<void> _react(String id, String reaction) async {
    final u = FirebaseAuth.instance.currentUser;
    if (u == null) return;
    await FirebaseFirestore.instance
        .collection('communityChatMessages')
        .doc(id)
        .update({'reactions.${u.uid}': reaction});
    if (mounted) setState(() => _reactionMessageId = null);
  }

  Future<void> _forwardCommunityMessage(Map<String, dynamic> d) async {
    if (_sending || _onCooldown) return;
    final text = (d['text'] ?? '').toString();
    final type = (d['type'] ?? 'text').toString();
    final me = FirebaseAuth.instance.currentUser;
    if (me == null) return;
    try {
      final profile = await _profile();
      await _commitMessage(
        text: text,
        type: type,
        profile: profile,
        driveRef: (d['driveRef'] ?? '').toString(),
        forwardedFrom: (d['id'] ?? '').toString(),
      );
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Message forwarded in Chat.')),
        );
      }
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context)
            .showSnackBar(SnackBar(content: Text('Forward failed: $e')));
    }
  }

  Future<void> _deleteMessage(String id) async {
    if (!widget.isAdmin) return;
    try {
      await FirebaseFirestore.instance
          .collection('communityChatMessages')
          .doc(id)
          .delete();
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context)
            .showSnackBar(SnackBar(content: Text('Delete failed: $e')));
    }
  }

  Future<void> _clearCommunityChat() async {
    if (!widget.isAdmin) return;
    final ok = await showDialog<bool>(
      context: context,
      builder: (c) => AlertDialog(
        title: const Text('CLEAR COMMUNITY CHAT'),
        content: const Text(
          'Permanently delete the entire Community Chat history for all users?',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(c, false),
            child: const Text('CANCEL'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(c, true),
            child: const Text('CLEAR ALL'),
          ),
        ],
      ),
    );
    if (ok != true) return;
    try {
      while (true) {
        final snap = await FirebaseFirestore.instance
            .collection('communityChatMessages')
            .limit(450)
            .get();
        if (snap.docs.isEmpty) break;
        final batch = FirebaseFirestore.instance.batch();
        for (final d in snap.docs) batch.delete(d.reference);
        await batch.commit();
        if (snap.docs.length < 450) break;
      }
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Community Chat cleared.')),
        );
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not clear Community Chat: $e')),
        );
    }
  }

  Future<void> _editOfficial(
    QueryDocumentSnapshot<Map<String, dynamic>> doc,
  ) async {
    if (!widget.isAdmin) return;
    final d = doc.data();
    final title = TextEditingController(text: (d['title'] ?? '').toString());
