        backgroundColor: AppTheme.adaptiveSurface(const Color(0xFF0A1017)),
        title: Text(
          (d['kind'] ?? '') == 'task'
              ? 'EDIT ADMIN TASK'
              : 'EDIT ADMIN ANNOUNCEMENT',
        ),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextField(
              controller: title,
              decoration: const InputDecoration(labelText: 'Title'),
            ),
            const SizedBox(height: 8),
            TextField(
              controller: text,
              minLines: 3,
              maxLines: 6,
              decoration: const InputDecoration(labelText: 'Message'),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(c),
            child: const Text('CANCEL'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(c, {
              'title': title.text.trim(),
              'text': text.text.trim(),
            }),
            child: const Text('SAVE'),
          ),
        ],
      ),
    );
    title.dispose();
    text.dispose();
    if (result == null || (result['text'] ?? '').isEmpty) return;
    await FirebaseFirestore.instance
        .collection('communityChatMessages')
        .doc(doc.id)
        .update({
          'title': result['title'] ?? '',
          'text': result['text'] ?? '',
          'updatedAt': FieldValue.serverTimestamp(),
        });
  }

  Future<void> _adminPost(String kind) async {
    if (!widget.isAdmin) return;
    final controller = TextEditingController();
    final title = TextEditingController();
    final result = await showDialog<Map<String, String>?>(
      context: context,
      builder: (c) => AlertDialog(
        backgroundColor: AppTheme.adaptiveSurface(const Color(0xFF0A1017)),
        title: Text(
          kind == 'announcement' ? 'ADMIN ANNOUNCEMENT' : 'ADMIN TASK',
        ),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextField(
              controller: title,
              decoration: const InputDecoration(labelText: 'Title'),
            ),
            const SizedBox(height: 8),
            TextField(
              controller: controller,
              minLines: 3,
              maxLines: 6,
              decoration: const InputDecoration(labelText: 'Message'),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(c),
            child: const Text('CANCEL'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(c, {
              'title': title.text.trim(),
              'text': controller.text.trim(),
            }),
            child: const Text('PUBLISH'),
          ),
        ],
      ),
    );
    controller.dispose();
    title.dispose();
    if (result == null || (result['text'] ?? '').isEmpty) return;
    final u = FirebaseAuth.instance.currentUser;
    if (u == null) return;
    await FirebaseFirestore.instance.collection('communityChatMessages').add({
      'senderUid': u.uid,
      'type': 'text',
      'kind': kind,
      'title': result['title'] ?? '',
      'text': result['text'],
      'driveRef': '',
      'createdAt': FieldValue.serverTimestamp(),
      'reactions': <String, String>{},
      'delivered': true,
      'readBy': <String>[],
    });
  }

