  @override
  Widget build(BuildContext context) {
    final remaining = _cooldownUntil == null
        ? 0
        : math.max(
            0,
            _cooldownUntil!.difference(DateTime.now()).inMilliseconds,
          );
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(14, 8, 8, 4),
          child: Row(
            children: [
              const Text(
                'Chat',
                style: TextStyle(
                  color: Colors.white,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const Spacer(),
              if (widget.isAdmin)
                PopupMenuButton<String>(
                  icon: const Icon(
                    Icons.admin_panel_settings_rounded,
                    color: Colors.white,
                  ),
                  onSelected: (v) {
                    if (v == 'announcement' || v == 'task') _adminPost(v);
                    if (v == 'users')
                      Navigator.push(
                        context,
                        MaterialPageRoute(
                          builder: (_) => const _AdminChatUsersPage(),
                        ),
                      );
                    if (v == 'clear') _clearCommunityChat();
                    if (v == 'moderation')
                      Navigator.push(
                        context,
                        MaterialPageRoute(
                          builder: (_) =>
                              const _AdminChatModerationSettingsPage(),
                        ),
                      );
                  },
                  itemBuilder: (_) => const [
                    PopupMenuItem(
                      value: 'announcement',
                      child: Text('Admin Announcement'),
                    ),
                    PopupMenuItem(value: 'task', child: Text('Admin Task')),
                    PopupMenuDivider(),
                    PopupMenuItem(value: 'users', child: Text('Manage Users')),
                    PopupMenuItem(
                      value: 'moderation',
                      child: Text('Moderation Settings'),
                    ),
                    PopupMenuItem(
                      value: 'clear',
                      child: Text('Clear Overall Chat'),
                    ),
                  ],
                ),
            ],
          ),
        ),
        Expanded(
          child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
            stream: FirebaseFirestore.instance
                .collection('communityChatMessages')
                .orderBy('createdAt', descending: false)
                .limit(300)
                .snapshots(),
            builder: (context, snapshot) {
              if (snapshot.hasError)
                return Center(
                  child: Text(
                    'Chat could not load. ${snapshot.error}',
                    style: TextStyle(color: AppTheme.textMuted),
                    textAlign: TextAlign.center,
                  ),
                );
              final docs =
                  snapshot.data?.docs ??
                  const <QueryDocumentSnapshot<Map<String, dynamic>>>[];
              if (docs.isEmpty && _pending.isEmpty)
                return Center(
                  child: Text(
                    'No messages yet. Start the conversation.',
                    style: TextStyle(color: AppTheme.textMuted),
                  ),
                );
              WidgetsBinding.instance.addPostFrameCallback((_) {
                if (!mounted || !_scroll.hasClients) return;
                _scroll.animateTo(
                  _scroll.position.maxScrollExtent,
                  duration: const Duration(milliseconds: 220),
                  curve: Curves.easeOutCubic,
                );
              });
              return ListView(
                controller: _scroll,
                padding: const EdgeInsets.fromLTRB(12, 8, 12, 12),
                children: [
                  for (final d in docs) _chatBubble(d),
                  for (final p in _pending) _pendingBubble(p),
                ],
              );
            },
          ),
        ),
        if (_replyingTo != null)
          Container(
            margin: const EdgeInsets.symmetric(horizontal: 10),
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
              color: AppTheme.adaptiveWhite(alpha: .055),
              borderRadius: BorderRadius.circular(10),
            ),
            child: Row(
              children: [
                const Icon(Icons.reply_rounded, size: 15, color: Colors.white),
                const SizedBox(width: 7),
                Expanded(
                  child: Text(
                    'Replying to ${_replyingTo!['nickname'] ?? 'User'}: ${_replyingTo!['text'] ?? ''}',
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(color: Colors.white70, fontSize: 10),
                  ),
                ),
                IconButton(
                  onPressed: () => setState(() => _replyingTo = null),
                  icon: const Icon(Icons.close, size: 15, color: Colors.white),
                ),
              ],
            ),
          ),
        if (remaining > 0)
          Padding(
            padding: const EdgeInsets.only(bottom: 3),
            child: Text(
              'You can send again in ${(remaining / 1000).ceil()}s',
              style: TextStyle(
                color: AppTheme.textMuted,
                fontSize: 9,
                fontWeight: FontWeight.w700,
              ),
            ),
          ),
        SafeArea(
          top: false,
          child: Container(
            padding: const EdgeInsets.fromLTRB(7, 7, 7, 8),
            decoration: BoxDecoration(
              color: AppTheme.adaptiveSurface(const Color(0xD90A1017)),
              border: Border(top: BorderSide(color: AppTheme.fillFaint)),
            ),
            child: Row(
              children: [
                IconButton(
                  tooltip: 'Media / GIF / Sticker',
                  onPressed: (_sending || remaining > 0)
                      ? null
                      : _showComposerMenu,
                  icon: const Icon(
                    Icons.add_circle_outline_rounded,
                    color: Colors.white,
                  ),
                ),
                Expanded(
                  child: TextField(
                    controller: _controller,
                    enabled: !_sending && remaining <= 0,
                    style: const TextStyle(color: Colors.white),
                    minLines: 1,
                    maxLines: 4,
                    decoration: InputDecoration(
                      hintText: 'Write a messageÃ¢â‚¬Â¦',
                      hintStyle: TextStyle(
                        color: AppTheme.textFaint,
                        fontSize: 11,
                      ),
                      filled: true,
                      fillColor: AppTheme.adaptiveWhite(alpha: .045),
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(17),
                        borderSide: BorderSide.none,
                      ),
                      prefixIcon: IconButton(
                        onPressed: _sending ? null : _showEmojiPicker,
                        icon: const Icon(
                          Icons.emoji_emotions_outlined,
                          color: Colors.white,
                        ),
                      ),
                    ),
                  ),
                ),
                const SizedBox(width: 5),
                IconButton(
                  tooltip: 'Send',
                  onPressed: (_sending || remaining > 0)
                      ? null
                      : () => _sendText(),
                  icon: Icon(
                    Icons.send_rounded,
                    color: (_sending || remaining > 0)
                        ? AppTheme.textFaint
                        : Colors.white,
                  ),
                ),
              ],
            ),
          ),
        ),
      ],
    );
  }

