  Widget _chatBubble(QueryDocumentSnapshot<Map<String, dynamic>> doc) {
    final d = doc.data();
    final kind = (d['kind'] ?? 'user').toString();
    final mine = d['senderUid'] == FirebaseAuth.instance.currentUser?.uid;
    final ts = d['createdAt'];
    final when = ts is Timestamp
        ? '${ts.toDate().hour.toString().padLeft(2, '0')}:${ts.toDate().minute.toString().padLeft(2, '0')}'
        : 'Ã¢â‚¬Â¦';
    final reactions =
        (d['reactions'] as Map?)?.cast<String, dynamic>() ??
        const <String, dynamic>{};
    final title = (d['title'] ?? '').toString();
    final text = (d['text'] ?? '').toString();
    final senderUid = (d['senderUid'] ?? '').toString();
    return FutureBuilder<Map<String, dynamic>>(
      future: senderUid.isEmpty
          ? Future.value(<String, dynamic>{})
          : _senderProfile(senderUid),
      builder: (context, profileSnap) {
        final p = profileSnap.data ?? const <String, dynamic>{};
        final nickname = (p['nickname'] ?? d['nickname'] ?? 'User').toString();
        final photo = (p['photoUrl'] ?? d['photoUrl'] ?? '').toString();
        final encoded = (p['avatarBase64'] ?? '').toString();
        Uint8List? avatarBytes;
        if (encoded.isNotEmpty) {
          try {
            avatarBytes = base64Decode(encoded);
          } catch (_) {}
        }
        return Align(
          alignment: mine ? Alignment.centerRight : Alignment.centerLeft,
          child: GestureDetector(
            onLongPress: () => _messageActions(doc),
            child: Container(
              constraints: const BoxConstraints(maxWidth: 360),
