                    children: [
                      CircleAvatar(
                        radius: 13,
                        backgroundColor: AppTheme.adaptiveSurface(
                          const Color(0xFF2B3138),
                        ),
                        backgroundImage: avatarBytes != null
                            ? MemoryImage(avatarBytes)
