  Future<void> _messageActions(
    QueryDocumentSnapshot<Map<String, dynamic>> doc,
  ) async {
    final d = doc.data();
    final choice = await showModalBottomSheet<String>(
      context: context,
      backgroundColor: AppTheme.adaptiveSurface(const Color(0xFF0A1017)),
      builder: (c) => SafeArea(
        child: Wrap(
          children: [
            ListTile(
              leading: const Icon(Icons.reply_rounded, color: Colors.white),
              title: const Text('Reply'),
              onTap: () => Navigator.pop(c, 'reply'),
            ),
            ListTile(
              leading: const Icon(Icons.forward_rounded, color: Colors.white),
              title: const Text('Forward'),
              onTap: () => Navigator.pop(c, 'forward'),
            ),
            ListTile(
              leading: const Icon(
                Icons.add_reaction_outlined,
                color: Colors.white,
              ),
              title: const Text('React'),
              onTap: () => Navigator.pop(c, 'react'),
            ),
            if (widget.isAdmin)
              ListTile(
                leading: const Icon(
                  Icons.delete_outline,
                  color: Colors.redAccent,
                ),
                title: const Text('Delete message'),
                onTap: () => Navigator.pop(c, 'delete'),
              ),
          ],
        ),
      ),
    );
    if (!mounted || choice == null) return;
    if (choice == 'reply')
      setState(
        () => _replyingTo = {
          'id': doc.id,
          'senderUid': d['senderUid'] ?? '',
          'nickname': d['nickname'] ?? 'User',
          'text': d['text'] ?? '',
          'type': d['type'] ?? 'text',
        },
      );
    if (choice == 'forward') _forwardCommunityMessage({...d, 'id': doc.id});
    if (choice == 'react') setState(() => _reactionMessageId = doc.id);
    if (choice == 'delete') _deleteMessage(doc.id);
  }
}

class _CommunityChatImage extends StatefulWidget {
  final String fileRef;
  const _CommunityChatImage({required this.fileRef});
  @override
  State<_CommunityChatImage> createState() => _CommunityChatImageState();
}

class _CommunityChatImageState extends State<_CommunityChatImage> {
  Uint8List? _bytes;
  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      final b = await DriveStorageService.downloadBytes(widget.fileRef);
      if (mounted) setState(() => _bytes = b);
    } catch (_) {}
  }

  @override
  Widget build(BuildContext context) => ClipRRect(
    borderRadius: BorderRadius.circular(12),
    child: _bytes == null
        ? Container(
            height: 150,
            width: 230,
            color: AppTheme.adaptiveWhite(alpha: .04),
            child: const Center(
              child: CircularProgressIndicator(strokeWidth: 2),
            ),
          )
        : Image.memory(_bytes!, width: 230, height: 180, fit: BoxFit.cover),
  );
}

class _AdminChatUsersPage extends StatefulWidget {
  const _AdminChatUsersPage();
  @override
  State<_AdminChatUsersPage> createState() => _AdminChatUsersPageState();
}

class _AdminChatUsersPageState extends State<_AdminChatUsersPage> {
  Future<List<String>> _uids() async {
    final snap = await FirebaseFirestore.instance
        .collection('communityChatMessages')
        .orderBy('createdAt', descending: true)
        .limit(500)
        .get();
    return snap.docs
        .map((d) => (d.data()['senderUid'] ?? '').toString())
        .where((x) => x.isNotEmpty)
        .toSet()
        .toList();
  }

  Future<void> _apply(String uid, String action) async {
    Timestamp? until;
    var banned = false;
    var kicked = false;
    final now = DateTime.now();
    if (action == '2h') {
      until = Timestamp.fromDate(now.add(const Duration(hours: 2)));
      banned = true;
    }
    if (action == '6h') {
      until = Timestamp.fromDate(now.add(const Duration(hours: 6)));
      banned = true;
    }
    if (action == '12h') {
      until = Timestamp.fromDate(now.add(const Duration(hours: 12)));
      banned = true;
    }
    if (action == '1d') {
      until = Timestamp.fromDate(now.add(const Duration(days: 1)));
      banned = true;
    }
    if (action == '1w') {
      until = Timestamp.fromDate(now.add(const Duration(days: 7)));
      banned = true;
    }
    if (action == '2w') {
      until = Timestamp.fromDate(now.add(const Duration(days: 14)));
      banned = true;
    }
    if (action == '3d') {
      until = Timestamp.fromDate(now.add(const Duration(days: 3)));
      banned = true;
    }
    if (action == '1m') {
      until = Timestamp.fromDate(now.add(const Duration(days: 30)));
      banned = true;
    }
    if (action == 'permanent') banned = true;
    if (action == 'kick') kicked = true;
    await FirebaseFirestore.instance
        .collection('communityChatModeration')
        .doc(uid)
        .set({
          'uid': uid,
          'banned': banned,
          'kicked': kicked,
          'bannedUntil': until,
          'updatedAt': FieldValue.serverTimestamp(),
          'updatedBy': FirebaseAuth.instance.currentUser?.uid,
        }, SetOptions(merge: true));
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            action == 'unban' ? 'User restored.' : 'User moderation updated.',
          ),
        ),
      );
      setState(() {});
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('CHAT USER MANAGEMENT')),
      body: FutureBuilder<List<String>>(
        future: _uids(),
        builder: (context, snap) {
          if (snap.connectionState == ConnectionState.waiting)
            return const Center(child: CircularProgressIndicator());
          final ids = snap.data ?? const <String>[];
          if (ids.isEmpty)
            return const Center(child: Text('No chat users found.'));
          return ListView.builder(
            padding: const EdgeInsets.all(12),
            itemCount: ids.length,
            itemBuilder: (_, i) {
              final uid = ids[i];
              return FutureBuilder<DocumentSnapshot<Map<String, dynamic>>>(
                future: FirebaseFirestore.instance
                    .collection('users')
                    .doc(uid)
                    .get(),
                builder: (context, p) {
                  final d = p.data?.data() ?? <String, dynamic>{};
                  final name =
                      (d['nickname'] ?? d['handle'] ?? d['displayName'] ?? uid)
                          .toString();
                  final photo = (d['photoUrl'] ?? d['photoURL'] ?? '')
                      .toString();
                  return Card(
                    color: AppTheme.adaptiveSurface(const Color(0xCC10151B)),
                    child: ListTile(
                      leading: CircleAvatar(
                        backgroundImage: photo.isNotEmpty
                            ? NetworkImage(photo)
                            : null,
                        child: photo.isEmpty ? const Icon(Icons.person) : null,
                      ),
                      title: Text(name),
                      subtitle: Text(uid, style: const TextStyle(fontSize: 8)),
                      trailing: PopupMenuButton<String>(
                        onSelected: (v) => _apply(uid, v),
                        itemBuilder: (_) => const [
                          PopupMenuItem(
                            value: 'kick',
                            child: Text('Kick from Chat'),
                          ),
                          PopupMenuItem(
                            value: '2h',
                            child: Text('Ban 2 hours'),
                          ),
                          PopupMenuItem(
                            value: '6h',
                            child: Text('Ban 6 hours'),
                          ),
                          PopupMenuItem(
                            value: '12h',
                            child: Text('Ban 12 hours'),
                          ),
                          PopupMenuItem(value: '1d', child: Text('Ban 1 day')),
                          PopupMenuItem(value: '1w', child: Text('Ban 1 week')),
                          PopupMenuItem(
                            value: '2w',
                            child: Text('Ban 2 weeks'),
                          ),
                          PopupMenuItem(value: '3d', child: Text('Ban 3 days')),
                          PopupMenuItem(
                            value: '1m',
                            child: Text('Ban 30 days'),
                          ),
                          PopupMenuItem(
                            value: 'permanent',
                            child: Text('Permanent ban'),
                          ),
                          PopupMenuItem(
                            value: 'unban',
                            child: Text('Restore user'),
                          ),
                        ],
                      ),
                    ),
                  );
                },
              );
            },
          );
        },
      ),
    );
  }
}

class _AdminTradeReferralSettingsPage extends StatefulWidget {
  const _AdminTradeReferralSettingsPage();
  @override
  State<_AdminTradeReferralSettingsPage> createState() =>
      _AdminTradeReferralSettingsPageState();
}

class _AdminTradeReferralSettingsPageState
    extends State<_AdminTradeReferralSettingsPage> {
  final _ids = const ['binance', 'bitget', 'mexc', 'bingx'];
  final Map<String, TextEditingController> _links = {};
  final Map<String, TextEditingController> _codes = {};
  bool _loading = true;
  bool _saving = false;
  @override
  void initState() {
    super.initState();
    for (final id in _ids) {
      _links[id] = TextEditingController();
      _codes[id] = TextEditingController();
    }
    _load();
  }

  @override
  void dispose() {
    for (final c in [..._links.values, ..._codes.values]) {
      c.dispose();
    }
    super.dispose();
  }

  Future<void> _load() async {
    try {
      final d =
          (await FirebaseFirestore.instance
                  .collection('tradeSettings')
                  .doc('config')
                  .get())
              .data() ??
          {};
      for (final id in _ids) {
        final x = (d[id] as Map?)?.cast<String, dynamic>() ?? {};
        _links[id]!.text = (x['link'] ?? '').toString();
        _codes[id]!.text = (x['code'] ?? '').toString();
      }
    } catch (_) {}
    if (mounted) setState(() => _loading = false);
  }

  Future<void> _save() async {
    setState(() => _saving = true);
    try {
      final data = <String, dynamic>{'updatedAt': FieldValue.serverTimestamp()};
      for (final id in _ids) {
        final link = _links[id]!.text.trim();
        final uri = Uri.tryParse(link);
        if (link.isNotEmpty &&
            (uri == null || uri.scheme != 'https' || uri.host.isEmpty))
          throw StateError(
            'Invalid HTTPS referral link for ${id.toUpperCase()}.',
          );
        data[id] = {'link': link, 'code': _codes[id]!.text.trim()};
      }
      await FirebaseFirestore.instance
          .collection('tradeSettings')
          .doc('config')
          .set(data, SetOptions(merge: true));
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Trade referral settings saved.')),
        );
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not save Trade settings: $e')),
        );
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('TRADE REFERRAL SETTINGS')),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : ListView(
              padding: const EdgeInsets.all(16),
              children: [
                for (final id in _ids)
                  Padding(
                    padding: const EdgeInsets.only(bottom: 10),
                    child: GlassCard(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            id.toUpperCase(),
                            style: const TextStyle(
                              fontWeight: FontWeight.w900,
                              color: AppTheme.luxuryGold,
                            ),
                          ),
                          const SizedBox(height: 7),
                          TextField(
                            controller: _links[id],
                            keyboardType: TextInputType.url,
                            decoration: const InputDecoration(
                              labelText: 'Referral link',
                            ),
                          ),
                          const SizedBox(height: 7),
                          TextField(
                            controller: _codes[id],
                            decoration: const InputDecoration(
                              labelText: 'Referral code (optional)',
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                SizedBox(
                  width: double.infinity,
                  child: FilledButton.icon(
                    onPressed: _saving ? null : _save,
                    icon: const Icon(Icons.save_outlined),
                    label: Text(_saving ? 'SAVING...' : 'SAVE ALL'),
                  ),
                ),
              ],
            ),
    );
  }
}

class _AdminChatModerationSettingsPage extends StatefulWidget {
  const _AdminChatModerationSettingsPage();
  @override
  State<_AdminChatModerationSettingsPage> createState() =>
      _AdminChatModerationSettingsPageState();
}

class _AdminChatModerationSettingsPageState
    extends State<_AdminChatModerationSettingsPage> {
  final _words = TextEditingController();
  bool _blockLinks = true;
  bool _loading = true;
  bool _saving = false;
  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _words.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    try {
      final d =
          (await FirebaseFirestore.instance
                  .collection('communityChatSettings')
                  .doc('moderation')
                  .get())
              .data() ??
          {};
      _words.text =
          ((d['blockedWords'] as List?)?.map((e) => e.toString()).join('\n') ??
          '');
      _blockLinks = d['blockLinks'] != false;
    } catch (_) {}
    if (mounted) setState(() => _loading = false);
  }

  Future<void> _save() async {
    setState(() => _saving = true);
    try {
      final words = _words.text
          .split(RegExp(r'[\n,]+'))
          .map((e) => e.trim())
          .where((e) => e.isNotEmpty)
          .take(100)
          .toList();
      final escaped = words.map(RegExp.escape).join('|');
      final pattern = escaped.isEmpty ? 'a^' : '(?i).*($escaped).*';
      await FirebaseFirestore.instance
          .collection('communityChatSettings')
          .doc('moderation')
          .set({
            'blockedWords': words,
            'blockedPattern': pattern,
            'blockLinks': _blockLinks,
            'updatedAt': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Chat moderation settings saved.')),
        );
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not save moderation settings: $e')),
        );
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('CHAT MODERATION')),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : ListView(
              padding: const EdgeInsets.all(16),
              children: [
                GlassCard(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text(
                        'BLOCKED WORDS',
                        style: TextStyle(
                          fontWeight: FontWeight.w900,
                          color: AppTheme.luxuryGold,
                        ),
                      ),
                      const SizedBox(height: 7),
                      TextField(
                        controller: _words,
                        minLines: 6,
                        maxLines: 12,
                        decoration: const InputDecoration(
                          hintText: 'One word or phrase per line',
                        ),
                      ),
                      SwitchListTile.adaptive(
                        contentPadding: EdgeInsets.zero,
                        title: const Text('Block external links'),
                        value: _blockLinks,
                        onChanged: (v) => setState(() => _blockLinks = v),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 12),
                SizedBox(
                  width: double.infinity,
                  child: FilledButton.icon(
                    onPressed: _saving ? null : _save,
                    icon: const Icon(Icons.save_outlined),
                    label: Text(_saving ? 'SAVING...' : 'SAVE MODERATION'),
                  ),
                ),
              ],
            ),
    );
  }
}

