  @override
  State<_HowToUseAppPage> createState() => _HowToUseAppPageState();
}

class _HowToUseAppPageState extends State<_HowToUseAppPage> {
  Future<void> _upload(String language) async {
    final picked = await FilePicker.pickFiles(type: FileType.video);
    if (picked.isEmpty) return;
    final file = picked.first;
    try {
      final bytes = await file.readAsBytes();
      if (bytes.isEmpty) throw StateError('The selected video is empty.');
      if (!mounted) return;
      await HowToUseAppService.uploadVideo(
        language: language,
        bytes: bytes,
        fileName: file.name,
        contentType: _howToVideoContentType(file.name),
      );
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${language == 'english' ? 'English' : 'Urdu'} tutorial updated successfully.',
          ),
        ),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text('Tutorial upload failed: $e')));
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFF030405),
      appBar: AppBar(title: const Text('HOW TO USE THE APP')),
      body: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
        stream: HowToUseAppService.watchConfig(),
        builder: (context, snapshot) {
          final data = snapshot.data?.data() ?? <String, dynamic>{};
          return ListView(
            padding: const EdgeInsets.fromLTRB(16, 10, 16, 30),
            children: [
              Text(
                'Learn how to use Crypto Doctors Hub, navigate the app, use its major features correctly, and understand the important rules and instructions.',
                style: TextStyle(
                  color: AppTheme.textSecondary,
                  fontSize: 11,
                  height: 1.45,
                ),
              ),
              const SizedBox(height: 14),
              _HowToUseVideoSection(
                title: 'English Version',
                icon: Icons.language_rounded,
                entry: HowToUseAppService.videoEntry(data, 'english'),
                onUpload: () => _upload('english'),
              ),
              const SizedBox(height: 12),
              _HowToUseVideoSection(
                title: 'Urdu Version',
                icon: Icons.translate_rounded,
                entry: HowToUseAppService.videoEntry(data, 'urdu'),
                onUpload: () => _upload('urdu'),
              ),
              const SizedBox(height: 12),
              FutureBuilder<bool>(
                future: _isCurrentUserAdmin(),
                builder: (context, adminSnapshot) {
                  if (adminSnapshot.data != true)
                    return const SizedBox.shrink();
                  return Container(
                    padding: const EdgeInsets.all(13),
                    decoration: BoxDecoration(
                      color: AppTheme.adaptiveSurface(const Color(0xFF101418)),
                      borderRadius: BorderRadius.circular(15),
                      border: Border.all(
                        color: AppTheme.luxuryGold.withValues(alpha: .24),
                      ),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(
                          children: [
                            Icon(
                              Icons.admin_panel_settings_rounded,
                              color: AppTheme.luxuryGold,
                              size: 18,
                            ),
                            const SizedBox(width: 7),
                            Text(
                              'ADMIN VIDEO MANAGEMENT',
                              style: TextStyle(
                                color: AppTheme.textPrimary,
                                fontSize: 10.5,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                          ],
                        ),
                        const SizedBox(height: 5),
                        Text(
                          'Only authorized Admins can upload or replace the active tutorial videos. Users can only watch them.',
                          style: TextStyle(
                            color: AppTheme.textMuted,
                            fontSize: 9.5,
                            height: 1.35,
                          ),
                        ),
                      ],
                    ),
                  );
                },
              ),
            ],
          );
        },
      ),
    );
  }

  Future<bool> _isCurrentUserAdmin() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return false;
    return _hasFirebaseAdminClaim(user);
  }
}

String _howToVideoContentType(String fileName) {
  final lower = fileName.toLowerCase();
  if (lower.endsWith('.webm')) return 'video/webm';
  if (lower.endsWith('.mov')) return 'video/quicktime';
  if (lower.endsWith('.m4v')) return 'video/x-m4v';
  return 'video/mp4';
}

Future<bool> _isHowToCurrentUserAdmin() async {
  final user = FirebaseAuth.instance.currentUser;
  if (user == null) return false;
  return _hasFirebaseAdminClaim(user);
}

