class _HowToUseVideoPlayer extends StatefulWidget {
  final String fileRef;
  final String fileName;
  const _HowToUseVideoPlayer({required this.fileRef, required this.fileName});
  @override
  State<_HowToUseVideoPlayer> createState() => _HowToUseVideoPlayerState();
}

class _HowToUseVideoPlayerState extends State<_HowToUseVideoPlayer> {
  VideoPlayerController? _controller;
  Future<void>? _initializeFuture;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      final url = await DriveStorageService.getPrivateFileUrl(widget.fileRef);
      final controller = VideoPlayerController.networkUrl(Uri.parse(url));
      _controller = controller;
      _initializeFuture = controller.initialize();
      if (mounted) setState(() {});
    } catch (e) {
      if (mounted) setState(() => _initializeFuture = Future<void>.error(e));
    }
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<void>(
      future: _initializeFuture,
      builder: (context, snapshot) {
        if (snapshot.hasError)
          return Padding(
            padding: const EdgeInsets.all(8),
            child: Text(
              'Video could not be loaded. Please try again later.',
              style: TextStyle(color: AppTheme.textMuted, fontSize: 9.5),
            ),
          );
        if (!snapshot.hasData &&
            snapshot.connectionState != ConnectionState.done)
          return const AspectRatio(
            aspectRatio: 16 / 9,
            child: Center(child: CircularProgressIndicator()),
          );
        final controller = _controller;
        if (controller == null || !controller.value.isInitialized)
          return const SizedBox.shrink();
        return ClipRRect(
          borderRadius: BorderRadius.circular(12),
          child: Stack(
            children: [
              AspectRatio(
                aspectRatio: controller.value.aspectRatio == 0
                    ? 16 / 9
                    : controller.value.aspectRatio,
                child: VideoPlayer(controller),
              ),
              Positioned.fill(
                child: Center(
                  child: IconButton(
                    onPressed: () => setState(
                      () => controller.value.isPlaying
                          ? controller.pause()
                          : controller.play(),
                    ),
                    icon: Icon(
                      controller.value.isPlaying
                          ? Icons.pause_circle_filled
                          : Icons.play_circle_fill,
                      color: Colors.white,
                      size: 54,
                    ),
                  ),
                ),
              ),
              Positioned(
                left: 8,
