      _QualifiedWinInfoDialogState();
}

class _QualifiedWinInfoDialogState extends State<_QualifiedWinInfoDialog> {
  Timer? _timer;
  double _progress = 1.0;

  @override
  void initState() {
    super.initState();
    const total = Duration(seconds: 4);
    final started = DateTime.now();
    _timer = Timer.periodic(const Duration(milliseconds: 80), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      final elapsed = DateTime.now().difference(started);
      final value = 1.0 - (elapsed.inMilliseconds / total.inMilliseconds);
      if (value <= 0) {
        timer.cancel();
        Navigator.of(context).pop();
      } else {
        setState(() => _progress = value);
      }
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Dialog(
      backgroundColor: AppTheme.adaptiveSurface(Color(0xFF0B0F11)),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
      child: Container(
        padding: const EdgeInsets.fromLTRB(20, 20, 20, 14),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(20),
          border: Border.all(color: AppTheme.luxuryGold.withValues(alpha: .34)),
          boxShadow: [
            BoxShadow(
              color: AppTheme.luxuryGold.withValues(alpha: .10),
              blurRadius: 28,
              spreadRadius: 1,
            ),
          ],
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Container(
              width: 48,
              height: 48,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: AppTheme.luxuryGold.withValues(alpha: .10),
                border: Border.all(
                  color: AppTheme.luxuryGold.withValues(alpha: .48),
                ),
              ),
              child: Icon(
                Icons.insights_rounded,
                color: AppTheme.luxuryGold,
                size: 25,
              ),
            ),
            const SizedBox(height: 12),
            Text(
              'QUALIFIED WIN TRADE',
              style: TextStyle(
                color: AppTheme.textPrimary,
