Future<void> _openFeedSearch(BuildContext context) async {
  final feedFuture = _loadSearchableFeedPosts();
  await Navigator.of(context).push(
    PageRouteBuilder<void>(
      opaque: false,
      barrierColor: const Color(0xB8000000),
      transitionDuration: const Duration(milliseconds: 280),
      pageBuilder: (_, animation, _) => _FeedSearchPage(feedFuture: feedFuture),
      transitionsBuilder: (_, animation, _, child) {
        final curved = CurvedAnimation(
          parent: animation,
          curve: Curves.easeOutCubic,
        );
        return FadeTransition(
          opacity: curved,
          child: SlideTransition(
            position: Tween<Offset>(
              begin: const Offset(0, 0.035),
              end: Offset.zero,
            ).animate(curved),
            child: child,
          ),
        );
      },
    ),
  );
}

Future<List<FeedPostModel>> _loadSearchableFeedPosts() async {
  try {
    return await FeedService.loadFeed(limit: 500);
  } catch (_) {
    return const <FeedPostModel>[];
  }
}

Future<void> _openPublicAlphaDenProfile(
  BuildContext context,
  String uid,
) async {
  final cleanUid = uid.trim();
  if (cleanUid.isEmpty) return;
  await Navigator.of(context).push(
    MaterialPageRoute(
      builder: (_) => _PublicAlphaDenProfilePage(uid: cleanUid),
    ),
  );
}

class _PublicAlphaDenProfilePage extends StatefulWidget {
  final String uid;
  const _PublicAlphaDenProfilePage({required this.uid});
  @override
  State<_PublicAlphaDenProfilePage> createState() =>
      _PublicAlphaDenProfilePageState();
}

class _PublicAlphaDenProfilePageState
    extends State<_PublicAlphaDenProfilePage> {
  Map<String, dynamic>? profile;
  List<Map<String, dynamic>> posts = const [];
  List<Map<String, dynamic>> reposts = const [];
  int currentTab = 0;
  bool loading = true;
  StreamSubscription<DocumentSnapshot<Map<String, dynamic>>>?
  _profileSubscription;
  StreamSubscription<QuerySnapshot<Map<String, dynamic>>>?
  _followersSubscription;
  StreamSubscription<QuerySnapshot<Map<String, dynamic>>>?
  _followingSubscription;
  StreamSubscription<QuerySnapshot<Map<String, dynamic>>>? _likesSubscription;
  int? _liveFollowers;
  int? _liveFollowing;

  @override
  void initState() {
    super.initState();
    _load();
    _subscribeRealtimeProfile();
  }

  void _subscribeRealtimeProfile() {
    _profileSubscription = FirebaseFirestore.instance
        .collection('users')
        .doc(widget.uid)
        .snapshots()
        .listen((snap) {
          final data = snap.data();
          if (data == null || !mounted) return;
          final raw = data['alphaDenProfile'];
          final next = <String, dynamic>{
            ...(profile ?? <String, dynamic>{}),
            if (raw is Map) ...Map<String, dynamic>.from(raw),
            if (_liveFollowers != null) 'followers': _liveFollowers,
            if (_liveFollowing != null) 'following': _liveFollowing,
            'isPremium': data['isPremium'] == true,
            'hasMentorship':
                data['mentorshipApproved'] == true ||
                data['isMentorship'] == true ||
                data['mentorship'] == true ||
                data['studentApproved'] == true ||
                data['isStudent'] == true,
            'premiumBadgeType': (data['confirmedPremiumBadgeType'] ?? '')
                .toString(),
            'mentorshipBadgeType': (data['confirmedMentorshipBadgeType'] ?? '')
                .toString(),
            'graduated': data['graduated'] == true,
            'referralCrownType': (data['confirmedReferralCrownType'] ?? '')
                .toString(),
          };
          setState(() => profile = next);
        });
    _followersSubscription = FirebaseFirestore.instance
        .collection('users')
        .doc(widget.uid)
        .collection('followers')
        .snapshots()
        .listen((snap) {
          _liveFollowers = snap.docs.length;
          if (!mounted) return;
          setState(
            () => profile = <String, dynamic>{
              ...(profile ?? <String, dynamic>{}),
              'followers': _liveFollowers,
            },
          );
        });
    _followingSubscription = FirebaseFirestore.instance
        .collection('users')
        .doc(widget.uid)
        .collection('following')
        .snapshots()
        .listen((snap) {
          _liveFollowing = snap.docs.length;
          if (!mounted) return;
          setState(
            () => profile = <String, dynamic>{
              ...(profile ?? <String, dynamic>{}),
              'following': _liveFollowing,
            },
          );
        });
    _likesSubscription = FirebaseFirestore.instance
        .collection('feed_posts')
        .where('authorUid', isEqualTo: widget.uid)
        .where('isPublished', isEqualTo: true)
        .snapshots()
        .listen((snap) {
          if (!mounted) return;
          final total = snap.docs.fold<int>(
            0,
            (sum, d) =>
                sum +
                ((d.data()['likesCount'] ?? d.data()['likes'] ?? 0) as num)
                    .toInt(),
          );
          setState(
            () => profile = <String, dynamic>{
              ...(profile ?? <String, dynamic>{}),
              'likes': total,
            },
          );
        });
  }

  @override
  void dispose() {
    _profileSubscription?.cancel();
    _followersSubscription?.cancel();
    _followingSubscription?.cancel();
    _likesSubscription?.cancel();
    super.dispose();
  }

  Future<void> _load() async {
    try {
      var loadedProfile = await AlphaDenService.loadProfile(widget.uid);
      final loadedUserDoc = await FirebaseFirestore.instance
          .collection('users')
          .doc(widget.uid)
          .get();
      final loadedUserData = loadedUserDoc.data() ?? <String, dynamic>{};
      // Admin Alpha Den profiles are public/searchable like any other Alpha Den
      // profile. If an admin has not opened Alpha Den yet, build a read-only
      // public profile from the account data so the profile can still be visited.
      if (loadedProfile == null) {
        final email = (loadedUserData['email'] ?? '')
            .toString()
            .trim()
            .toLowerCase();
        final isKnownAdmin =
            email == 'cryptodoctors73@gmail.com' ||
            email == 'teamcryptodoctors@gmail.com' ||
            email == 'sbroland11@gmail.com' ||
            email == 'sbroland@gmail.com';
        final fallbackName = (loadedUserData['displayName'] ?? '')
            .toString()
            .trim();
        loadedProfile = <String, dynamic>{
          'uid': widget.uid,
          'username': fallbackName.isEmpty
              ? (isKnownAdmin ? 'CRYPTO-DOCTORS-HUB ADMIN' : 'Community Member')
              : fallbackName,
          'name': fallbackName.isEmpty
              ? (isKnownAdmin ? 'CRYPTO-DOCTORS-HUB ADMIN' : 'Community Member')
              : fallbackName,
          'bio': isKnownAdmin ? 'Official Crypto Doctors Hub Admin' : '',
          'profilePicUrl': (loadedUserData['photoURL'] ?? '').toString(),
          'profilePicBase64': (loadedUserData['profilePicBase64'] ?? '')
              .toString(),
          'followers': 0,
          'posts': 0,
          'likes': 0,
          'views': 0,
          'reposts': 0,
          'referrals': 0,
          'winTrades': 0,
          'verifiedCreatorApproved':
              loadedUserData['verifiedCreatorApproved'] == true || isKnownAdmin,
          'isPremium': loadedUserData['isPremium'] == true,
          'mentorshipApproved':
              loadedUserData['mentorshipApproved'] == true ||
              loadedUserData['isMentorship'] == true ||
              loadedUserData['mentorship'] == true ||
              loadedUserData['studentApproved'] == true ||
              loadedUserData['isStudent'] == true,
          'isAdminProfile': isKnownAdmin,
        };
      }
      {
        loadedProfile['isPremium'] = loadedUserData['isPremium'] == true;
        loadedProfile['hasMentorship'] =
            loadedUserData['mentorshipApproved'] == true ||
            loadedUserData['isMentorship'] == true ||
            loadedUserData['mentorship'] == true ||
            loadedUserData['studentApproved'] == true ||
            loadedUserData['isStudent'] == true;
        loadedProfile['premiumBadgeType'] =
            (loadedUserData['confirmedPremiumBadgeType'] ?? '').toString();
        loadedProfile['mentorshipBadgeType'] =
            (loadedUserData['confirmedMentorshipBadgeType'] ?? '').toString();
        loadedProfile['graduated'] = loadedUserData['graduated'] == true;
        loadedProfile['referralCrownType'] =
            (loadedUserData['confirmedReferralCrownType'] ?? '').toString();
        final alphaPic = (loadedProfile['profilePicUrl'] ?? '')
            .toString()
            .trim();
        final alphaPicBase64 = (loadedProfile['profilePicBase64'] ?? '')
            .toString()
            .trim();
        if (alphaPic.isEmpty)
          loadedProfile['profilePicUrl'] = (loadedUserData['photoURL'] ?? '')
              .toString();
        if (alphaPicBase64.isEmpty)
          loadedProfile['profilePicBase64'] =
              (loadedUserData['profilePicBase64'] ?? '').toString();
      }
      List<Map<String, dynamic>> loadedPosts = const [];
      List<Map<String, dynamic>> loadedReposts = const [];
      try {
        loadedPosts = await AlphaDenService.loadPosts(widget.uid);
      } catch (_) {}
      try {
        loadedReposts = await AlphaDenService.loadPublicReposts(widget.uid);
      } catch (_) {}
      if (!mounted) return;
      setState(() {
        profile = loadedProfile;
        posts = loadedPosts;
        reposts = loadedReposts;
        loading = false;
      });
    } catch (_) {
      if (mounted) setState(() => loading = false);
    }
  }

  List<Map<String, dynamic>> _ideas() => posts.where((data) {
    final source = (data['sourceType'] ?? '').toString();
    return source != 'article' &&
        (data['signalAsset'] ?? '').toString().trim().isEmpty;
  }).toList();

  List<Map<String, dynamic>> _signals() => posts.where((data) {
    final source = (data['sourceType'] ?? '').toString();
    return source != 'article' &&
        (data['signalAsset'] ?? '').toString().trim().isNotEmpty;
  }).toList();

  List<Map<String, dynamic>> _articles() => posts
      .where((data) => (data['sourceType'] ?? '').toString() == 'article')
      .toList();

  @override
  Widget build(BuildContext context) {
    final p = profile ?? <String, dynamic>{};
