bool _matchesHowToUseAppSearch(String query) {
  final q = query.trim().toLowerCase();
  if (q.isEmpty) return false;
  const phrases = [
    'how to use the app',
    'how to use app',
    'how to use',
    'app tutorial',
    'app guide',
    'getting started',
    'tutorial',
    'guide',
  ];
  return phrases.any(q.contains);
}

