class _FeedSearchPage extends StatefulWidget {
  final Future<List<FeedPostModel>> feedFuture;

  const _FeedSearchPage({required this.feedFuture});

  @override
  State<_FeedSearchPage> createState() => _FeedSearchPageState();
}

class _FeedSearchPageState extends State<_FeedSearchPage> {
  final TextEditingController _controller = TextEditingController();
  int _tab = 0; // 0 all, 1 content, 2 users, 3 events
  String _query = '';
  late Future<List<FeedPostModel>> _future;
  late Future<List<Map<String, String>>> _userFuture;

  @override
  void initState() {
    super.initState();
    _future = widget.feedFuture;
    _userFuture = _loadSearchUsers();
    _controller.addListener(() {
      if (!mounted) return;
      setState(() => _query = _controller.text.trim().toLowerCase());
    });
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  Future<List<Map<String, String>>> _loadSearchUsers() async {
    try {
      final snap = await FirebaseFirestore.instance
          .collection('users')
          .limit(500)
          .get();
      final result = <Map<String, String>>[];
      for (final doc in snap.docs) {
        final data = doc.data();
        final raw = data['alphaDenProfile'];
        final email = (data['email'] ?? '').toString().trim().toLowerCase();
        final isKnownAdmin =
            email == 'cryptodoctors73@gmail.com' ||
            email == 'teamcryptodoctors@gmail.com' ||
            email == 'sbroland11@gmail.com' ||
            email == 'sbroland@gmail.com';
        final profile = raw is Map
            ? Map<String, dynamic>.from(raw)
            : <String, dynamic>{};
        final name =
            (profile['username'] ??
                    profile['name'] ??
                    data['displayName'] ??
                    (isKnownAdmin
                        ? 'CRYPTO-DOCTORS-HUB ADMIN'
                        : 'Community Member'))
                .toString()
                .trim();
        if (name.isEmpty) continue;
        result.add({
          'uid': doc.id,
          'name': name,
          'isAdmin': isKnownAdmin ? 'true' : 'false',
        });
      }
      result.sort(
        (a, b) => a['name']!.toLowerCase().compareTo(b['name']!.toLowerCase()),
      );
      return result;
    } catch (_) {
      return const <Map<String, String>>[];
    }
  }

  bool _matchesContent(FeedPostModel post) {
    if (_query.isEmpty) return true;
    final haystack = <String>[
      post.text,
      post.authorDisplayName,
      post.sourceType,
      post.sourceId ?? '',
      ...post.hashtags,
      ...post.coins,
    ].join(' ').toLowerCase();
    return haystack.contains(_query);
  }

  List<FeedPostModel> _filtered(List<FeedPostModel> posts) {
    if (_query.isEmpty) return posts.take(30).toList();
    return posts.where(_matchesContent).take(50).toList();
  }

  List<String> _uniqueUsers(List<FeedPostModel> posts) {
    final seen = <String>{};
    final users = <String>[];
    for (final post in posts) {
      final name = post.authorDisplayName.trim();
      if (name.isEmpty) continue;
      if (_query.isNotEmpty && !name.toLowerCase().contains(_query)) continue;
      if (seen.add(name.toLowerCase())) users.add(name);
    }
    return users.take(50).toList();
  }

  List<FeedPostModel> _events(List<FeedPostModel> posts) {
    return posts
        .where((post) {
          final isEvent = post.sourceType.toLowerCase() == 'event';
          final searchable =
              '${post.text} ${post.authorDisplayName} ${post.hashtags.join(' ')}'
                  .toLowerCase();
          return isEvent && (_query.isEmpty || searchable.contains(_query));
        })
        .take(50)
        .toList();
  }

  Widget _tabButton(String label, IconData icon, int index) {
    final selected = _tab == index;
    return Expanded(
      child: GestureDetector(
        onTap: () => setState(() => _tab = index),
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 180),
          padding: const EdgeInsets.symmetric(vertical: 9),
          decoration: BoxDecoration(
            color: selected
                ? AppTheme.neonGreen.withValues(alpha: 0.13)
                : Colors.transparent,
            borderRadius: BorderRadius.circular(12),
            border: Border.all(
              color: selected
                  ? AppTheme.neonGreen.withValues(alpha: 0.28)
                  : Colors.transparent,
            ),
          ),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(icon, size: 15, color: Colors.grey.shade500),
              const SizedBox(width: 5),
              Text(
                label,
                style: TextStyle(
                  color: Colors.grey.shade500,
                  fontSize: 11,
                  fontWeight: FontWeight.w800,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _resultPost(FeedPostModel post) {
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(13),
      decoration: BoxDecoration(
        color: const Color(0xFF111111),
        borderRadius: BorderRadius.circular(15),
        border: Border.all(color: Colors.white.withValues(alpha: 0.10)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              CircleAvatar(
                radius: 16,
