class _AnalysisPost {
  final String id;
  final String author;
  final String email;
  final String authorUid;
  final String profilePicUrl;
  final Uint8List? profilePicBytes;
  final int referrals;
  final bool verified;
  final int winTrades;
  String text;
  final Uint8List? imageBytes;
  final Uint8List? thumbnailBytes;
  final bool bullish;
  DateTime createdAt;
  int views = 0;
  String? feedPostId;
  final String period;
  final String category;
  final String imageDriveRef;
  final String thumbnailDriveRef;

  _AnalysisPost({
    required this.id,
    required this.author,
    required this.email,
    this.authorUid = '',
    this.profilePicUrl = '',
    this.profilePicBytes,
    this.referrals = 0,
    this.verified = false,
    this.winTrades = 0,
    required this.text,
    required this.imageBytes,
    required this.thumbnailBytes,
    required this.bullish,
    DateTime? createdAt,
    this.feedPostId,
    this.views = 0,
    this.period = 'legacy',
    this.category = 'general',
    this.imageDriveRef = '',
    this.thumbnailDriveRef = '',
  }) : createdAt = createdAt ?? DateTime.now();
}

final ValueNotifier<List<_AnalysisPost>> _analysisPosts =
    ValueNotifier<List<_AnalysisPost>>(<_AnalysisPost>[]);

String? _analysisImageBase64(Uint8List? bytes, {int maxBytes = 600000}) {
  if (bytes == null || bytes.isEmpty || bytes.length > maxBytes) return null;
  return base64Encode(bytes);
}

_AnalysisPost _analysisPostFromFirestore(
  DocumentSnapshot<Map<String, dynamic>> doc,
) {
  final data = doc.data() ?? <String, dynamic>{};
  Uint8List? decode(dynamic value) {
    final raw = (value ?? '').toString();
    if (raw.isEmpty) return null;
    try {
      return base64Decode(raw);
    } catch (_) {
      return null;
    }
  }

  final created = data['createdAt'];
  final createdAt = created is Timestamp
      ? created.toDate()
      : DateTime.tryParse((created ?? '').toString()) ?? DateTime.now();
  return _AnalysisPost(
    id: doc.id,
    author: (data['authorDisplayName'] ?? 'CRYPTO-DOCTORS-HUB ADMIN')
        .toString(),
    email: (data['authorEmail'] ?? '').toString(),
    authorUid: (data['authorUid'] ?? '').toString(),
    profilePicUrl: (data['authorProfilePicUrl'] ?? '').toString(),
    profilePicBytes: decode(data['authorProfilePicBase64']),
    referrals: (data['authorReferrals'] as num?)?.toInt() ?? 0,
    verified: data['authorVerified'] == true,
    winTrades: (data['authorWinTrades'] as num?)?.toInt() ?? 0,
    text: (data['text'] ?? '').toString(),
    imageBytes: decode(data['imageBase64']),
    thumbnailBytes: decode(data['thumbnailBase64']),
    bullish: data['bullish'] != false,
    createdAt: createdAt,
    feedPostId: (data['feedPostId'] ?? '').toString().trim().isEmpty
        ? null
        : (data['feedPostId'] ?? '').toString(),
    views: (data['viewsCount'] as num?)?.toInt() ?? 0,
    period: (data['period'] ?? 'legacy').toString(),
    category: (data['category'] ?? 'general').toString(),
    imageDriveRef: (data['imageDriveRef'] ?? '').toString(),
    thumbnailDriveRef: (data['thumbnailDriveRef'] ?? '').toString(),
  );
}

Future<void> _loadAnalysisPosts() async {
  try {
    final snapshot = await FirebaseFirestore.instance
        .collection('analysis_posts')
        .where('period', isEqualTo: 'legacy')
        .get();
    _analysisPosts.value =
        snapshot.docs
            .where(
              (doc) =>
                  doc.data()['isPublished'] == true &&
                  (doc.data()['period'] ?? 'legacy').toString() == 'legacy',
            )
            .map(_analysisPostFromFirestore)
            .toList()
          ..sort((a, b) => b.createdAt.compareTo(a.createdAt));
  } catch (_) {
    // Keep the existing local state if the backend is temporarily unavailable.
  }
}

Future<void> _publishAnalysisPost(_AnalysisPost post) async {
  final user = FirebaseAuth.instance.currentUser;
  if (user == null) return;

  final analysisRef = FirebaseFirestore.instance
      .collection('analysis_posts')
      .doc(post.id);
  final profile = await _feedAdminProfile();
  String imageDriveRef = post.imageDriveRef;
  String thumbnailDriveRef = post.thumbnailDriveRef;

  if (post.imageBytes != null && post.imageBytes!.isNotEmpty) {
    imageDriveRef = await DriveStorageService.uploadBytes(
      bytes: post.imageBytes!,
      fileName: 'analysis_${post.period}_${post.category}_${post.id}.jpg',
      contentType: 'image/jpeg',
      scope: 'analysis_media',
      ownerUid: user.uid,
    );
  }
  if (post.thumbnailBytes != null && post.thumbnailBytes!.isNotEmpty) {
    thumbnailDriveRef = await DriveStorageService.uploadBytes(
      bytes: post.thumbnailBytes!,
      fileName: 'analysis_${post.period}_${post.category}_${post.id}_thumb.jpg',
      contentType: 'image/jpeg',
      scope: 'analysis_media',
      ownerUid: user.uid,
    );
  }

  final analysisData = <String, dynamic>{
    'authorUid': user.uid,
    'authorDisplayName': 'CRYPTO-DOCTORS-HUB ADMIN',
    'authorEmail': (user.email ?? '').trim().toLowerCase(),
    'authorProfilePicUrl': (profile['photoUrl'] ?? '').toString(),
    'authorReferrals': (profile['referrals'] as num?)?.toInt() ?? 0,
    'authorVerified': profile['verified'] == true,
    'authorWinTrades': (profile['winTrades'] as num?)?.toInt() ?? 0,
    'text': post.text,
    'imageDriveRef': imageDriveRef,
    'thumbnailDriveRef': thumbnailDriveRef,
    'bullish': post.bullish,
    'period': post.period,
    'category': post.category,
    'createdAt': FieldValue.serverTimestamp(),
    'viewsCount': 0,
    'isPublished': true,
    'sourceType': 'analysis',
  };

  await analysisRef.set(analysisData);
  final publishedSnap = await analysisRef.get();
  final publishedData = publishedSnap.data() ?? analysisData;
  final publishedCreated = publishedData['createdAt'];
  if (publishedCreated is Timestamp) post.createdAt = publishedCreated.toDate();
  try {
    await DriveStorageService.archiveJsonRecord(
      scope: 'analysis',
      recordId: post.id,
      ownerUid: user.uid,
      data: publishedData,
    );
  } catch (_) {}

  // Preserve the existing CD Feed publication behavior for Analysis.
  final feedId = await _publishToCommunityFeed(
    _CommunityPost(
      id: 'analysis-${post.id}',
      authorUid: user.uid,
      username: 'CRYPTO-DOCTORS-HUB ADMIN',
      nickname: 'CRYPTO-DOCTORS-HUB ADMIN',
      profilePicUrl: (profile['photoUrl'] ?? '').toString(),
      profilePicBytes: profile['avatar'] as Uint8List?,
      badge: (profile['badge'] ?? 'ADMIN').toString(),
      verified: profile['verified'] == true,
      referrals: (profile['referrals'] as num?)?.toInt() ?? 0,
      winTrades: (profile['winTrades'] as num?)?.toInt() ?? 0,
      isPremium: profile['isPremium'] == true,
      text: post.text,
      imageBytes: post.imageBytes,
      thumbnailBytes: post.thumbnailBytes,
      bullish: post.bullish,
      hashtags: const <String>[],
      coins: const <String>[],
      createdAt: post.createdAt,
    ),
    sourceType: 'analysis',
    sourceId: post.id,
  );

  post.feedPostId = feedId;
  await analysisRef.update({'feedPostId': feedId});
  post.feedPostId = feedId;
  if (post.period == 'legacy') {
    _analysisPosts.value = <_AnalysisPost>[
      post,
      ..._analysisPosts.value.where((item) => item.id != post.id),
    ];
  }
}

Future<bool> _analysisPeriodHasUnread(String period) async {
  final uid = FirebaseAuth.instance.currentUser?.uid;
  if (uid == null || uid.isEmpty) return false;
  try {
    final readSnap = await FirebaseFirestore.instance
        .collection('users')
        .doc(uid)
        .collection('analysisReadState')
        .doc(period.toLowerCase())
        .get();
    final readData = readSnap.data();
    final readAt = readData?['lastSeenAt'];
    DateTime? lastSeen;
    if (readAt is Timestamp) lastSeen = readAt.toDate();
    if (readData == null || readAt == null) {
      await FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .collection('analysisReadState')
          .doc(period.toLowerCase())
          .set({
            'period': period,
            'lastSeenAt': FieldValue.serverTimestamp(),
            'updatedAt': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
      return false;
    }
    final snap = await FirebaseFirestore.instance
        .collection('analysis_posts')
        .where('period', isEqualTo: period)
        .get();
    for (final d in snap.docs) {
      if (d.data()['isPublished'] != true) continue;
      final v = d.data()['createdAt'];
      final created = v is Timestamp
          ? v.toDate()
          : DateTime.tryParse((v ?? '').toString());
      if (created != null && (lastSeen == null || created.isAfter(lastSeen)))
        return true;
    }
  } catch (_) {}
  return false;
}

Future<void> _markAnalysisPeriodSeen(String period) async {
  final uid = FirebaseAuth.instance.currentUser?.uid;
  if (uid == null || uid.isEmpty) return;
  try {
    await FirebaseFirestore.instance
        .collection('users')
        .doc(uid)
        .collection('analysisReadState')
        .doc(period.toLowerCase())
        .set({
          'period': period,
          'lastSeenAt': FieldValue.serverTimestamp(),
          'updatedAt': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
  } catch (_) {}
}

class _AnalysisPeriodTabs extends StatefulWidget {
  final bool isAdmin;
  const _AnalysisPeriodTabs({required this.isAdmin});
  @override
  State<_AnalysisPeriodTabs> createState() => _AnalysisPeriodTabsState();
}

class _AnalysisPeriodTabsState extends State<_AnalysisPeriodTabs> {
  final Map<String, bool> _unread = <String, bool>{};
  Timer? _timer;
  static const _periods = <String>['Daily', 'Weekly', 'Monthly'];
  @override
  void initState() {
    super.initState();
    _refresh();
    _timer = Timer.periodic(const Duration(seconds: 20), (_) => _refresh());
  }

  Future<void> _refresh() async {
    final values = <String, bool>{};
    for (final p in _periods) values[p] = await _analysisPeriodHasUnread(p);
    if (mounted) setState(() => _unread..addAll(values));
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Align(
    alignment: Alignment.centerLeft,
    child: SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      padding: const EdgeInsets.fromLTRB(16, 10, 0, 4),
      child: Row(
        children: [
          for (final period in _periods)
            Padding(
              padding: const EdgeInsets.only(right: 7),
              child: _CompactAnalysisTab(
                label: '$period Analysis',
                unread: _unread[period] == true,
                onTap: () async {
                  await _markAnalysisPeriodSeen(period);
                  if (mounted) setState(() => _unread[period] = false);
                  if (context.mounted)
                    await Navigator.push(
                      context,
                      MaterialPageRoute(
                        builder: (_) => _AnalysisPeriodPage(
                          period: period,
                          isAdmin: widget.isAdmin,
                        ),
                      ),
                    );
                  await _refresh();
                },
              ),
            ),
        ],
      ),
    ),
  );
}

