class _AnalysisCategoryPage extends StatefulWidget {
  final String period;
  final String category;
  final String title;
  final bool isAdmin;
  const _AnalysisCategoryPage({
    required this.period,
    required this.category,
    required this.title,
    required this.isAdmin,
  });
  @override
  State<_AnalysisCategoryPage> createState() => _AnalysisCategoryPageState();
}

class _AnalysisCategoryPageState extends State<_AnalysisCategoryPage> {
  List<_AnalysisPost> _posts = <_AnalysisPost>[];
  bool _loading = true;
  bool _isAdmin = false;

  @override
  void initState() {
    super.initState();
    _isAdmin = widget.isAdmin;
    _load();
  }

  Future<void> _load() async {
    try {
      final snap = await FirebaseFirestore.instance
          .collection('analysis_posts')
          .where('period', isEqualTo: widget.period)
          .get();
      final posts =
          snap.docs
              .where(
                (doc) =>
                    doc.data()['isPublished'] == true &&
                    (doc.data()['category'] ?? 'general').toString() ==
                        widget.category,
              )
              .map(_analysisPostFromFirestore)
              .toList()
            ..sort((a, b) => b.createdAt.compareTo(a.createdAt));
      if (mounted)
        setState(() {
          _posts = posts;
          _loading = false;
        });
    } catch (_) {
      if (mounted)
        setState(() {
          _loading = false;
        });
    }
  }

  Future<void> _create() async {
    final post = await Navigator.push<_AnalysisPost>(
      context,
      MaterialPageRoute(
        builder: (_) => _AnalysisComposerPage(
          period: widget.period,
          category: widget.category,
        ),
      ),
    );
    if (post != null && mounted) {
      try {
        await _publishAnalysisPost(post);
        await _load();
      } catch (e) {
        if (mounted)
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(content: Text('Analysis publish failed: $e')),
          );
      }
    }
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    backgroundColor: AppTheme.adaptiveSurface(const Color(0xFF070B10)),
    appBar: AppBar(
      title: Text(
        '${widget.period} Ã¢â‚¬Â¢ ${widget.title}',
        style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 14),
      ),
      actions: [
        if (_isAdmin)
          Padding(
            padding: const EdgeInsets.only(right: 10),
            child: _JellyPlusButton(
              tooltip: 'Create analysis',
              onPressed: _create,
            ),
          ),
      ],
    ),
    body: _loading
        ? const Center(child: CircularProgressIndicator())
        : RefreshIndicator(
            onRefresh: _load,
            child: _posts.isEmpty
                ? ListView(
                    physics: const AlwaysScrollableScrollPhysics(),
                    padding: const EdgeInsets.all(24),
                    children: [
                      const SizedBox(height: 110),
                      Center(child: Text('No analysis published yet.')),
                    ],
                  )
                : ListView.builder(
                    physics: const AlwaysScrollableScrollPhysics(),
                    padding: const EdgeInsets.fromLTRB(12, 12, 12, 30),
                    itemCount: _posts.length,
                    itemBuilder: (_, i) {
                      final postId = _posts[i].id;
                      return _AnalysisPostCard(
                        post: _posts[i],
                        isAdmin: _isAdmin,
                        onDeleted: () {
                          if (mounted)
                            setState(
                              () => _posts.removeWhere((x) => x.id == postId),
                            );
                        },
                      );
                    },
                  ),
          ),
  );
}

