String _formatAnalysisDateTime(DateTime dt) {
  final months = [
    'Jan',
    'Feb',
    'Mar',
    'Apr',
    'May',
    'Jun',
    'Jul',
    'Aug',
    'Sep',
    'Oct',
    'Nov',
    'Dec',
  ];
  final h = dt.hour % 12 == 0 ? 12 : dt.hour % 12;
  final ap = dt.hour >= 12 ? 'PM' : 'AM';
  return '${dt.day.toString().padLeft(2, '0')} ${months[dt.month - 1]} ${dt.year} Ã¢â‚¬Â¢ ${h.toString().padLeft(2, '0')}:${dt.minute.toString().padLeft(2, '0')} $ap';
}

class _LongContentPreview extends StatelessWidget {
  final String text;
  final VoidCallback onShowMore;
  const _LongContentPreview({required this.text, required this.onShowMore});
  @override
  Widget build(BuildContext context) {
    const limit = 360;
    final long = text.length > limit;
    final preview = long
        ? '${text.substring(0, limit).trimRight()}Ã¢â‚¬Â¦'
        : text;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(preview, style: const TextStyle(fontSize: 14, height: 1.35)),
        if (long) ...[
          const SizedBox(height: 5),
          TextButton(
            onPressed: onShowMore,
            style: TextButton.styleFrom(
              padding: EdgeInsets.zero,
              minimumSize: const Size(0, 30),
            ),
            child: const Text(
              'SHOW MORE',
              style: TextStyle(fontWeight: FontWeight.w900, letterSpacing: .4),
            ),
          ),
        ],
      ],
    );
  }
}

class _AnalysisPostCard extends StatefulWidget {
  final _AnalysisPost post;
  final bool isAdmin;
  final VoidCallback? onDeleted;
  const _AnalysisPostCard({
    required this.post,
    this.isAdmin = false,
    this.onDeleted,
  });

  @override
  State<_AnalysisPostCard> createState() => _AnalysisPostCardState();
}

class _AnalysisPostCardState extends State<_AnalysisPostCard> {
  Timer? _viewTimer;
  bool _liked = false;
  bool _reposted = false;
  Map<String, dynamic>? _alphaProfile;
  Uint8List? _alphaProfilePicBytes;
  Uint8List? _driveImageBytes;
  Uint8List? _driveThumbnailBytes;

  @override
  void initState() {
    super.initState();
    _loadAlphaDenProfile();
    _loadDriveImages();
    widget.post.views++;
    _viewTimer = Timer.periodic(const Duration(seconds: 4), (_) {
      if (!mounted) return;
      setState(() => widget.post.views++);
    });
  }

  Future<void> _loadDriveImages() async {
    try {
      Uint8List? image;
      Uint8List? thumb;
      if (widget.post.imageDriveRef.trim().isNotEmpty) {
        image = await DriveStorageService.downloadBytes(
          widget.post.imageDriveRef.trim(),
        );
      }
      if (widget.post.thumbnailDriveRef.trim().isNotEmpty) {
        thumb = await DriveStorageService.downloadBytes(
          widget.post.thumbnailDriveRef.trim(),
        );
      }
      if (!mounted) return;
      setState(() {
        _driveImageBytes = image;
        _driveThumbnailBytes = thumb;
      });
    } catch (_) {}
  }

  Future<void> _loadAlphaDenProfile() async {
    final uid = widget.post.authorUid.trim().isNotEmpty
        ? widget.post.authorUid.trim()
        : (FirebaseAuth.instance.currentUser?.uid ?? '').trim();
    if (uid.isEmpty) return;
    try {
      final loaded = await AlphaDenService.loadProfile(uid);
      if (!mounted || loaded == null) return;
      Uint8List? pic;
      final encoded = (loaded['profilePicBase64'] ?? '').toString().trim();
      if (encoded.isNotEmpty) {
        try {
          pic = base64Decode(encoded);
        } catch (_) {}
      }
      setState(() {
        _alphaProfile = loaded;
        _alphaProfilePicBytes = pic;
      });
    } catch (_) {
      // Keep the profile snapshot stored on the Analysis post as a safe fallback.
    }
  }

  Future<void> _editAnalysisPost() async {
    if (!widget.isAdmin) return;
    final edited = await Navigator.push<_AnalysisPost>(
      context,
      MaterialPageRoute(
        builder: (_) => _AnalysisComposerPage(
          existingPost: widget.post,
          initialImageBytes: _driveImageBytes ?? widget.post.imageBytes,
          initialThumbnailBytes:
              _driveThumbnailBytes ?? widget.post.thumbnailBytes,
        ),
      ),
    );
    if (edited == null || !mounted) return;
    try {
      final db = FirebaseFirestore.instance;
      final ref = db.collection('analysis_posts').doc(widget.post.id);
      final user = FirebaseAuth.instance.currentUser;
      if (user == null) throw StateError('You must be signed in.');
      String imageDriveRef = widget.post.imageDriveRef;
      String thumbnailDriveRef = widget.post.thumbnailDriveRef;
      if (edited.imageBytes != null && edited.imageBytes!.isNotEmpty) {
        imageDriveRef = await DriveStorageService.uploadBytes(
          bytes: edited.imageBytes!,
          fileName:
              'analysis_${widget.post.period}_${widget.post.category}_${widget.post.id}.jpg',
          contentType: 'image/jpeg',
          scope: 'analysis_media',
          ownerUid: user.uid,
        );
      }
      if (edited.thumbnailBytes != null && edited.thumbnailBytes!.isNotEmpty) {
        thumbnailDriveRef = await DriveStorageService.uploadBytes(
          bytes: edited.thumbnailBytes!,
          fileName:
              'analysis_${widget.post.period}_${widget.post.category}_${widget.post.id}_thumb.jpg',
          contentType: 'image/jpeg',
          scope: 'analysis_media',
          ownerUid: user.uid,
        );
      }
      await ref.update({
        'text': edited.text,
        'bullish': edited.bullish,
        'imageDriveRef': imageDriveRef,
        'thumbnailDriveRef': thumbnailDriveRef,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      final feedId = widget.post.feedPostId;
      if (feedId != null && feedId.isNotEmpty)
        await db.collection('feed_posts').doc(feedId).update({
          'text': edited.text,
          'bullish': edited.bullish,
          'updatedAt': FieldValue.serverTimestamp(),
        });
      widget.post.text = edited.text;
      if (mounted) setState(() {});
      await _loadAnalysisPosts();
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Could not edit Analysis: $e')));
    }
  }

  Future<void> _deleteAnalysisPost() async {
    if (!widget.isAdmin) return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dc) => AlertDialog(
        backgroundColor: AppTheme.adaptiveSurface(Color(0xFF0B0F11)),
        title: const Text(
          'DELETE ANALYSIS',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
        content: Text(
          'Delete this Analysis from its Analysis tab and CD Feed? Its long-term Drive history will also be removed.',
          style: TextStyle(color: AppTheme.textSecondary),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dc).pop(false),
            child: const Text('CANCEL'),
          ),
          FilledButton(
            onPressed: () => Navigator.of(dc).pop(true),
            child: const Text('DELETE'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    try {
      final db = FirebaseFirestore.instance;
      final batch = db.batch();
      batch.delete(db.collection('analysis_posts').doc(widget.post.id));
      final feedId = widget.post.feedPostId;
      if (feedId != null && feedId.isNotEmpty)
        batch.delete(db.collection('feed_posts').doc(feedId));
      else {
        final feedSnap = await db
            .collection('feed_posts')
            .where('sourceType', isEqualTo: 'analysis')
            .limit(200)
            .get();
        for (final d in feedSnap.docs) {
          if ((d.data()['sourceId'] ?? '').toString() == widget.post.id)
            batch.delete(d.reference);
        }
      }
      await batch.commit();
      try {
        await DriveStorageService.deleteArchivedRecord(
          scope: 'analysis',
          recordId: widget.post.id,
          ownerUid: FirebaseAuth.instance.currentUser?.uid ?? '',
        );
      } catch (_) {}
      _analysisPosts.value = _analysisPosts.value
          .where((x) => x.id != widget.post.id)
          .toList();
      widget.onDeleted?.call();
    } catch (e) {
      if (context.mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not delete Analysis: $e')),
        );
    }
  }

  @override
  void dispose() {
    _viewTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final accent = widget.post.bullish
        ? AppTheme.neonGreen
        : const Color(0xFFE05252);
    final profile = _alphaProfile;
    final profileName =
        (profile?['username'] ?? profile?['name'] ?? widget.post.author)
            .toString()
            .trim();
    final profilePicUrl =
        (profile?['profilePicUrl'] ?? widget.post.profilePicUrl)
            .toString()
            .trim();
    final profilePicBytes =
        _alphaProfilePicBytes ?? widget.post.profilePicBytes;
    final profileReferrals =
        (profile?['referrals'] as num?)?.toInt() ?? widget.post.referrals;
    final profileWinTrades =
        (profile?['winTrades'] as num?)?.toInt() ?? widget.post.winTrades;
    final profileVerified =
        profile?['verifiedCreatorApproved'] == true ||
        profile?['verified'] == true ||
        widget.post.verified;
    return Container(
      margin: const EdgeInsets.only(bottom: 14),
      decoration: _regularPostGlassDecoration(borderColor: accent, radius: 18),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 13, 14, 8),
            child: Row(
              children: [
                CircleAvatar(
                  radius: 18,
                  backgroundColor: AppTheme.adaptiveSurface(Color(0xFF111A24)),
                  backgroundImage: profilePicBytes != null
                      ? MemoryImage(profilePicBytes)
                      : (profilePicUrl.isNotEmpty
                            ? NetworkImage(profilePicUrl)
                            : null),
                  child: profilePicBytes == null && profilePicUrl.isEmpty
                      ? Icon(
                          Icons.person,
                          color: AppTheme.textPrimary,
                          size: 18,
                        )
                      : null,
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: Row(
                    children: [
                      Flexible(
                        child: Text(
                          profileName.isEmpty
                              ? widget.post.author
                              : profileName,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(fontWeight: FontWeight.w800),
                        ),
                      ),
                      if (profileVerified) ...[
                        const SizedBox(width: 5),
                        const Icon(
                          Icons.verified,
                          color: Color(0xFF4EA7FF),
                          size: 16,
                        ),
                      ],
                      const SizedBox(width: 5),
                      _ReferralCrownBadge(
                        referrals: profileReferrals,
                        flamingAura: profileWinTrades >= 10,
                      ),
                    ],
                  ),
                ),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 4,
                  ),
                  decoration: BoxDecoration(
                    color: accent.withValues(alpha: 0.14),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(color: accent.withValues(alpha: 0.55)),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(
                        widget.post.bullish
                            ? Icons.trending_up
                            : Icons.trending_down,
                        color: accent,
                        size: 15,
                      ),
                      const SizedBox(width: 4),
                      Text(
                        widget.post.bullish ? 'BULL' : 'BEAR',
                        style: TextStyle(
                          color: accent,
                          fontWeight: FontWeight.w900,
                          fontSize: 10,
                        ),
                      ),
                    ],
                  ),
                ),
                if (widget.isAdmin)
                  IconButton(
                    visualDensity: VisualDensity.compact,
                    padding: EdgeInsets.zero,
                    constraints: const BoxConstraints(
                      minWidth: 28,
                      minHeight: 28,
                    ),
                    onPressed: _editAnalysisPost,
                    icon: const Icon(Icons.edit_outlined, size: 17),
                  ),
                if (widget.isAdmin)
                  IconButton(
                    visualDensity: VisualDensity.compact,
                    padding: EdgeInsets.zero,
                    constraints: const BoxConstraints(
                      minWidth: 28,
                      minHeight: 28,
                    ),
                    onPressed: _deleteAnalysisPost,
                    icon: const Icon(
                      Icons.delete_outline_rounded,
                      size: 18,
                      color: Colors.redAccent,
                    ),
                  ),
              ],
            ),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 0, 14, 4),
