class _AnalysisComposerPageState extends State<_AnalysisComposerPage>
    with SingleTickerProviderStateMixin {
  @override
  void initState() {
    super.initState();
    final existing = widget.existingPost;
    if (existing != null) {
      _controller.text = existing.text;
      _bullish = existing.bullish;
      _imageBytes = widget.initialImageBytes;
      _thumbnailBytes = widget.initialThumbnailBytes;
    }
  }

  final TextEditingController _controller = TextEditingController();
  Uint8List? _imageBytes;
  Uint8List? _thumbnailBytes;
  bool _bullish = true;
  late final AnimationController _entry = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 650),
  )..forward();

  @override
  void dispose() {
    _entry.dispose();
    _controller.dispose();
    super.dispose();
  }

  final ImagePicker _analysisImagePicker = ImagePicker();
  bool get _editing => widget.existingPost != null;

  Future<Uint8List?> _pickImageBytes({required bool thumbnail}) async {
    try {
      // Use image_picker instead of a browser-only FileUploadInputElement so
      // Analysis images work on Android, iOS and Web. The old HTML picker was
      // the reason the buttons could appear to do nothing on the phone.
      final picked = await _analysisImagePicker.pickImage(
        source: ImageSource.gallery,
        imageQuality: thumbnail ? 72 : 82,
        maxWidth: thumbnail ? 720 : 1600,
        maxHeight: thumbnail ? 720 : 1600,
      );
      if (picked == null) return null;

      final bytes = await picked.readAsBytes();
      if (bytes.isEmpty) return null;

      final limit = thumbnail ? 180000 : 600000;
      if (bytes.length > limit) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                thumbnail
                    ? 'Thumbnail is too large. Please choose a smaller image.'
                    : 'Image is too large. Please choose a smaller image.',
              ),
            ),
          );
        }
        return null;
      }
      return bytes;
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Could not insert image: $e')));
      }
      return null;
    }
  }

  Future<void> _pickOriginal() async {
    final bytes = await _pickImageBytes(thumbnail: false);
    if (bytes != null && mounted) setState(() => _imageBytes = bytes);
  }

  Future<void> _pickThumbnail() async {
    final bytes = await _pickImageBytes(thumbnail: true);
    if (bytes != null && mounted) setState(() => _thumbnailBytes = bytes);
  }

  void _publish() {
    if (_controller.text.trim().isEmpty && _imageBytes == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Add analysis text or a chart/image before publishing.',
          ),
        ),
      );
      return;
    }
    Navigator.pop(
      context,
      _AnalysisPost(
        id:
            widget.existingPost?.id ??
            '${DateTime.now().microsecondsSinceEpoch}',
        author: 'CRYPTO-DOCTORS-HUB ADMIN',
        email: '',
        text: _controller.text.trim(),
        imageBytes: _imageBytes,
        thumbnailBytes: _thumbnailBytes,
        bullish: _bullish,
        period: widget.existingPost?.period ?? widget.period,
        category: widget.existingPost?.category ?? widget.category,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final accent = _bullish ? AppTheme.neonGreen : const Color(0xFFE05252);
    return Scaffold(
      appBar: AppBar(
        title: Text(_editing ? 'EDIT ANALYSIS' : 'CREATE ANALYSIS'),
        actions: [
          Padding(
            padding: const EdgeInsets.only(right: 12, top: 8, bottom: 8),
            child: FilledButton(
              onPressed: _publish,
              style: FilledButton.styleFrom(
                backgroundColor: AppTheme.luxuryGold,
                foregroundColor: Colors.black,
              ),
              child: Text(
                _editing ? 'SAVE' : 'PUBLISH',
                style: const TextStyle(fontWeight: FontWeight.w900),
              ),
            ),
          ),
        ],
      ),
      body: Stack(
        children: [
          const GalaxyBackground(
            animatePlanets: true,
            cinematicEntrance: false,
          ),
          SafeArea(
            child: FadeTransition(
              opacity: CurvedAnimation(parent: _entry, curve: Curves.easeOut),
              child: SlideTransition(
                position:
                    Tween<Offset>(
                      begin: const Offset(0, 0.04),
                      end: Offset.zero,
                    ).animate(
                      CurvedAnimation(
                        parent: _entry,
                        curve: Curves.easeOutCubic,
                      ),
                    ),
                child: Column(
                  children: [
                    Expanded(
                      child: Padding(
                        padding: const EdgeInsets.fromLTRB(16, 14, 16, 10),
                        child: TextField(
                          controller: _controller,
                          expands: true,
                          maxLines: null,
