class _LiveCallPost {
  final String id;
  final String asset;
  final String entry;
  final bool longDirection;
  final bool bullish;
  final String tp1;
  final String tp2;
  final String tp3;
  final String stopLoss;
  final int leverage;
  final Uint8List? imageBytes;
  final DateTime createdAt;
  int goodReactions;
  int badReactions;
  bool tp1Hit, tp2Hit, tp3Hit, stopLossHit, breakEven, winTradeCounted;
  String tp1Profit, tp2Profit, tp3Profit, stopLossProfit, breakEvenProfit;
  bool tradeClosed = false;
  bool closedGreen = false;
  double finalProfitPercentage = 0;
  String resultPercentage = '';
  int dailySequence = 0;
  String accessTier = '';

  _LiveCallPost({
    required this.id,
    required this.asset,
    required this.entry,
    required this.longDirection,
    required this.bullish,
    required this.tp1,
    required this.tp2,
    required this.tp3,
    required this.stopLoss,
    required this.leverage,
    required this.imageBytes,
    DateTime? createdAt,
    this.goodReactions = 0,
    this.badReactions = 0,
    this.tp1Hit = false,
    this.tp2Hit = false,
    this.tp3Hit = false,
    this.stopLossHit = false,
    this.breakEven = false,
    this.winTradeCounted = false,
    this.tp1Profit = '',
    this.tp2Profit = '',
    this.tp3Profit = '',
    this.stopLossProfit = '',
    this.breakEvenProfit = '',
    this.tradeClosed = false,
    this.closedGreen = false,
    this.finalProfitPercentage = 0,
    this.resultPercentage = '',
    this.dailySequence = 0,
    this.accessTier = '',
  }) : createdAt = createdAt ?? DateTime.now();
}

final ValueNotifier<List<_LiveCallPost>> _liveCallPosts =
    ValueNotifier<List<_LiveCallPost>>(<_LiveCallPost>[]);

// Protected Live Call details are cached at app level so recreating the Live
// Calls tab cannot make already-loaded Premium/Admin content disappear.
final Map<String, _LiveCallPost> _liveCallPremiumDetailsCache =
    <String, _LiveCallPost>{};

String? _liveCallImageBase64(Uint8List? bytes) =>
    bytes == null || bytes.isEmpty || bytes.length > 600000
    ? null
    : base64Encode(bytes);
DateTime _liveCallDate(dynamic v) => v is Timestamp
    ? v.toDate()
    : DateTime.tryParse((v ?? '').toString()) ?? DateTime.now();
Uint8List? _decodeLiveCallImage(dynamic v) {
  final raw = (v ?? '').toString();
  if (raw.isEmpty) return null;
  try {
    return base64Decode(raw);
  } catch (_) {
    return null;
  }
}

_LiveCallPost _liveCallFromFirestore(
  DocumentSnapshot<Map<String, dynamic>> doc,
) {
  final d = doc.data() ?? {};
  return _LiveCallPost(
    id: doc.id,
    asset: (d['asset'] ?? '').toString(),
    entry: (d['entry'] ?? '').toString(),
    longDirection: d['longDirection'] != false,
    bullish: d['bullish'] != false,
    tp1: (d['tp1'] ?? '').toString(),
    tp2: (d['tp2'] ?? '').toString(),
    tp3: (d['tp3'] ?? '').toString(),
    stopLoss: (d['stopLoss'] ?? '').toString(),
    leverage: (d['leverage'] as num?)?.toInt() ?? 10,
    imageBytes: _decodeLiveCallImage(d['imageBase64']),
    createdAt: _liveCallDate(d['createdAt']),
    goodReactions: (d['goodReactions'] as num?)?.toInt() ?? 0,
    badReactions: (d['badReactions'] as num?)?.toInt() ?? 0,
    tp1Hit: d['tp1Hit'] == true,
    tp2Hit: d['tp2Hit'] == true,
    tp3Hit: d['tp3Hit'] == true,
    stopLossHit: d['stopLossHit'] == true,
    breakEven: d['breakEven'] == true,
    winTradeCounted: d['winTradeCounted'] == true,
    tp1Profit: (d['tp1Profit'] ?? '').toString(),
    tp2Profit: (d['tp2Profit'] ?? '').toString(),
    tp3Profit: (d['tp3Profit'] ?? '').toString(),
    stopLossProfit: (d['stopLossProfit'] ?? '').toString(),
    breakEvenProfit: (d['breakEvenProfit'] ?? '').toString(),
    tradeClosed: d['tradeClosed'] == true,
    closedGreen: d['closedGreen'] == true,
    finalProfitPercentage:
        (d['finalProfitPercentage'] as num?)?.toDouble() ?? 0,
    resultPercentage: (d['resultPercentage'] ?? '').toString(),
    dailySequence: (d['dailySequence'] as num?)?.toInt() ?? 0,
    accessTier: (d['accessTier'] ?? '').toString(),
  );
}

Map<String, dynamic> _liveCallPublicData(_LiveCallPost p) {
  final tier = p.accessTier.isEmpty
      ? (p.dailySequence > 2 ? 'premium' : 'free')
      : p.accessTier;
  final d = <String, dynamic>{
    'createdAt': Timestamp.fromDate(p.createdAt),
    'goodReactions': p.goodReactions,
    'badReactions': p.badReactions,
    'tradeClosed': p.tradeClosed,
    'closedGreen': p.closedGreen,
    'finalProfitPercentage': p.finalProfitPercentage,
    'resultPercentage': p.resultPercentage,
    'dailySequence': p.dailySequence,
    'accessTier': tier,
    'isPublished': true,
  };
  // Public outcome fields are safe to expose. Protected Entry / target prices /
  // Stop Loss / Leverage / image data remain in premiumData/details.
  d.addAll({
    'asset': p.asset,
    'tp1Hit': p.tp1Hit,
    'tp2Hit': p.tp2Hit,
    'tp3Hit': p.tp3Hit,
    'stopLossHit': p.stopLossHit,
    'breakEven': p.breakEven,
    'tp1Profit': p.tp1Profit,
    'tp2Profit': p.tp2Profit,
    'tp3Profit': p.tp3Profit,
    'stopLossProfit': p.stopLossProfit,
    'breakEvenProfit': p.breakEvenProfit,
  });
  // Direction, coin name and public result metadata are always readable.
  // Premium pricing/details stay protected only while the signal is active.
  // Once any TP/SL is hit or Admin officially closes the trade, the complete
  // signal becomes public so Free users can see the original signal content
  // behind the light result blur/tick.
  d['longDirection'] = p.longDirection;
  d['tradeName'] = p.asset;
  final revealFullSignal =
      p.tp1Hit || p.tp2Hit || p.tp3Hit || p.stopLossHit || p.tradeClosed;
  if (tier != 'premium' || revealFullSignal) {
    d.addAll({
      'entry': p.entry,
      'bullish': p.bullish,
      'tp1': p.tp1,
      'tp2': p.tp2,
      'tp3': p.tp3,
      'stopLoss': p.stopLoss,
      'leverage': p.leverage,
      'imageBase64': _liveCallImageBase64(p.imageBytes),
      'winTradeCounted': p.winTradeCounted,
    });
  }
  return d;
}

Map<String, dynamic> _liveCallProtectedData(_LiveCallPost p) => {
  'asset': p.asset,
  'entry': p.entry,
  'longDirection': p.longDirection,
  'bullish': p.bullish,
  'tp1': p.tp1,
  'tp2': p.tp2,
  'tp3': p.tp3,
  'stopLoss': p.stopLoss,
  'leverage': p.leverage,
  'imageBase64': _liveCallImageBase64(p.imageBytes),
  'tp1Hit': p.tp1Hit,
  'tp2Hit': p.tp2Hit,
  'tp3Hit': p.tp3Hit,
  'stopLossHit': p.stopLossHit,
  'breakEven': p.breakEven,
  'winTradeCounted': p.winTradeCounted,
  'tp1Profit': p.tp1Profit,
  'tp2Profit': p.tp2Profit,
  'tp3Profit': p.tp3Profit,
  'stopLossProfit': p.stopLossProfit,
  'breakEvenProfit': p.breakEvenProfit,
};
Map<String, dynamic> _liveCallData(_LiveCallPost p) => _liveCallPublicData(p);
Map<String, dynamic> _liveCallArchiveData(_LiveCallPost p) => {
  ..._liveCallPublicData(p),
  ..._liveCallProtectedData(p),
  'id': p.id,
  'archivedAt': DateTime.now().toIso8601String(),
};
Future<void> _persistLiveCall(_LiveCallPost p) async {
  final db = FirebaseFirestore.instance;
  final ref = db.collection('live_calls').doc(p.id);
  await ref.set(_liveCallPublicData(p));
  // Keep the complete signal in the protected subdocument for every call.
  // Firestore rules still restrict this document to Admin/Premium users.
  // Free users get only the first-two-daily-call details from the public
  // document; Premium calls never expose protected fields publicly.
  await ref
      .collection('premiumData')
      .doc('details')
      .set(_liveCallProtectedData(p));
  try {
    await DriveStorageService.archiveJsonRecord(
      scope: 'live_call',
      recordId: p.id,
      ownerUid: FirebaseAuth.instance.currentUser?.uid ?? '',
      data: _liveCallArchiveData(p),
    );
  } catch (_) {}
}

Future<void> _updateLiveCallBackend(_LiveCallPost p) async {
  final db = FirebaseFirestore.instance;
  final ref = db.collection('live_calls').doc(p.id);
  await ref.update(_liveCallPublicData(p));
  // Keep the protected copy synchronized even for the first two free calls
  // so an authorized Admin/Premium read always has a complete signal source.
  await ref
      .collection('premiumData')
      .doc('details')
      .set(_liveCallProtectedData(p), SetOptions(merge: true));
  try {
    await DriveStorageService.archiveJsonRecord(
      scope: 'live_call',
      recordId: p.id,
      ownerUid: FirebaseAuth.instance.currentUser?.uid ?? '',
      data: _liveCallArchiveData(p),
    );
  } catch (_) {}
}

String _liveCallProfit(
  String entry,
  String target,
  bool longDir,
  int leverage,
) {
  final e = double.tryParse(entry.replaceAll(',', '').trim());
  final t = double.tryParse(target.replaceAll(',', '').trim());
  if (e == null || t == null || e == 0) return '';
  final move = longDir ? ((t - e) / e) * 100 : ((e - t) / e) * 100;
  final raw = move * leverage;
  return raw.roundToDouble() == raw
      ? raw.toStringAsFixed(0)
      : raw.toStringAsFixed(2);
}

bool _liveCallWin(_LiveCallPost p) => p.tp1Hit || p.tp2Hit || p.tp3Hit;
bool _liveCallLoss(_LiveCallPost p) => !_liveCallWin(p) && p.stopLossHit;
Future<void> _recordLiveParticipant(String id, bool like) async {
  final u = FirebaseAuth.instance.currentUser;
  if (u == null) return;
  final db = FirebaseFirestore.instance;
  final participantRef = db
      .collection('live_calls')
      .doc(id)
      .collection('participants')
      .doc(u.uid);
  final journalRef = db
      .collection('users')
      .doc(u.uid)
      .collection('tradingJournal')
      .doc(id);
  if (!like) {
    try {
      await participantRef.delete();
    } catch (_) {}
    try {
      await journalRef.delete();
    } catch (_) {}
    try {
      await DriveStorageService.deleteArchivedRecord(
        scope: 'journal_entry',
        recordId: '${u.uid}__$id',
        ownerUid: u.uid,
      );
    } catch (_) {}
    return;
  }
  try {
    final call = await db.collection('live_calls').doc(id).get();
    final data = call.data() ?? <String, dynamic>{};
    final publicAsset = (data['asset'] ?? '').toString();
    final longDirection = data['longDirection'] != false;
    await participantRef.set({
      'uid': u.uid,
      'tookTrade': true,
      'reaction': 'like',
      'likedAt': FieldValue.serverTimestamp(),
      'signalCreatedAt': data['createdAt'] ?? FieldValue.serverTimestamp(),
      'asset': publicAsset,
      'tradeName': publicAsset,
      'longDirection': longDirection,
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
    await journalRef.set({
      'liveCallId': id,
      'tookTrade': true,
      'interaction': 'like',
      'status': 'OPEN',
      'asset': publicAsset,
      'tradeName': publicAsset,
      'longDirection': longDirection,
      'signalCreatedAt': data['createdAt'] ?? FieldValue.serverTimestamp(),
      'likedAt': FieldValue.serverTimestamp(),
      'updatedAt': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
    final snap = await journalRef.get();
    await DriveStorageService.archiveJsonRecord(
      scope: 'journal_entry',
      recordId: '${u.uid}__$id',
      ownerUid: u.uid,
      data: snap.data() ?? <String, dynamic>{},
    );
  } catch (_) {}
}

Future<Map<String, dynamic>> _feedAdminProfile() async {
  final u = FirebaseAuth.instance.currentUser;
  if (u == null) return {};
  try {
    final d =
        (await FirebaseFirestore.instance.collection('users').doc(u.uid).get())
            .data() ??
        {};
    Uint8List? a;
    final x = (d['appAvatarBase64'] ?? '').toString();
    if (x.isNotEmpty) {
      try {
        a = base64Decode(x);
      } catch (_) {}
    }
    return {
      'uid': u.uid,
      'photoUrl': (d['profilePicUrl'] ?? d['photoURL'] ?? u.photoURL ?? '')
          .toString()
          .trim(),
      'avatar': a,
      'referrals': (d['referrals'] as num?)?.toInt() ?? 0,
      'verified': d['verifiedCreatorApproved'] == true || d['verified'] == true,
      'winTrades': (d['winTrades'] as num?)?.toInt() ?? 0,
      'isPremium': d['isPremium'] == true,
      'badge': _referralBadgeLabel((d['referrals'] as num?)?.toInt() ?? 0),
    };
  } catch (_) {
    return {'uid': u.uid, 'photoUrl': (u.photoURL ?? '').trim()};
  }
}

Future<void> _recordJournalAggregates(_LiveCallPost p, double finalPct) async {
  try {
    final db = FirebaseFirestore.instance;
    final closedAt = DateTime.now();
    final weekStart = closedAt.subtract(
      Duration(days: closedAt.weekday - DateTime.monday),
    );
    final keys = <String, String>{
      'daily':
          '${closedAt.year}-${closedAt.month.toString().padLeft(2, '0')}-${closedAt.day.toString().padLeft(2, '0')}',
      'weekly':
          '${weekStart.year}-${weekStart.month.toString().padLeft(2, '0')}-${weekStart.day.toString().padLeft(2, '0')}',
      'monthly':
          '${closedAt.year}-${closedAt.month.toString().padLeft(2, '0')}',
      'yearly': '${closedAt.year}',
    };
    final batch = db.batch();
    for (final e in keys.entries) {
      final ref = db
          .collection('journalCommunityAggregates')
          .doc('${e.key}_${e.value}');
      batch.set(ref, {
        'period': e.key,
        'periodKey': e.value,
        'sumProfitPercentage': FieldValue.increment(finalPct),
        'closedTradeCount': FieldValue.increment(1),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
    }
    final participants = await db
        .collection('live_calls')
        .doc(p.id)
        .collection('participants')
        .get();
    for (final d in participants.docs) {
      if (d.data()['reaction'] != 'like') continue;
      for (final e in keys.entries) {
        final ref = db
            .collection('users')
            .doc(d.id)
            .collection('journalAggregates')
            .doc('${e.key}_${e.value}');
        batch.set(ref, {
          'period': e.key,
          'periodKey': e.value,
          'sumProfitPercentage': FieldValue.increment(finalPct),
          'closedTradeCount': FieldValue.increment(1),
          'updatedAt': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      }
    }
    await batch.commit();
    for (final d in participants.docs) {
      if (d.data()['reaction'] != 'like') continue;
      for (final e in keys.entries) {
        try {
          final ref = db
              .collection('users')
              .doc(d.id)
              .collection('journalAggregates')
              .doc('${e.key}_${e.value}');
          final snap = await ref.get();
          await DriveStorageService.archiveJsonRecord(
            scope: 'journal_aggregate',
            recordId: '${d.id}__${e.key}_${e.value}',
            ownerUid: d.id,
            data: snap.data() ?? <String, dynamic>{},
          );
        } catch (_) {}
      }
    }
  } catch (_) {}
}

Future<void> _finalizeLiveJournal(_LiveCallPost p, double finalPct) async {
  try {
    final db = FirebaseFirestore.instance;
    final docs = await db
        .collection('live_calls')
        .doc(p.id)
        .collection('participants')
        .get();
    final batch = db.batch();
    final r = finalPct > 0
        ? 'WIN'
        : finalPct < 0
        ? 'LOSS'
        : p.breakEven
        ? 'BREAK EVEN'
        : 'CLOSED';
    final pct = '${finalPct >= 0 ? '+' : ''}${finalPct.toStringAsFixed(2)}%';
    for (final d in docs.docs) {
      if (d.data()['reaction'] != 'like') continue;
      final ref = db
          .collection('users')
          .doc(d.id)
          .collection('tradingJournal')
          .doc(p.id);
      batch.update(ref, {
        'officialResult': r,
        'resultPercentage': pct,
        'finalProfitPercentage': finalPct,
        'closedGreen': p.closedGreen,
        'status': 'CLOSED',
        'asset': p.asset,
        'tradeName': p.asset,
        'longDirection': p.longDirection,
        'signalCreatedAt': p.createdAt,
        'tp1Hit': p.tp1Hit,
        'tp2Hit': p.tp2Hit,
        'tp3Hit': p.tp3Hit,
        'tp1Profit': p.tp1Profit,
        'tp2Profit': p.tp2Profit,
        'tp3Profit': p.tp3Profit,
        'closedAt': FieldValue.serverTimestamp(),
      });
    }
    await batch.commit();
    for (final d in docs.docs) {
      if (d.data()['reaction'] != 'like') continue;
      try {
        final ref = db
            .collection('users')
            .doc(d.id)
            .collection('tradingJournal')
            .doc(p.id);
        final snap = await ref.get();
        await DriveStorageService.archiveJsonRecord(
          scope: 'journal_entry',
          recordId: '${d.id}__${p.id}',
          ownerUid: d.id,
          data: snap.data() ?? <String, dynamic>{},
        );
      } catch (_) {}
    }
  } catch (_) {}
}

Future<List<_LiveCallPost>> _liveCallsForDayFromBackend(DateTime day) async {
  try {
    // Query only published Live Calls first so Firestore security rules can
    // prove that every document returned by the query is readable. The date
    // filtering is then done locally. This also avoids making the publishing
    // sequence depend on an extra composite query.
    final snap = await FirebaseFirestore.instance
        .collection('live_calls')
        .where('isPublished', isEqualTo: true)
        .limit(200)
        .get();
    final start = DateTime(day.year, day.month, day.day);
    final end = start.add(const Duration(days: 1));
    final result = snap.docs
        .map(_liveCallFromFirestore)
        .where((p) => !p.createdAt.isBefore(start) && p.createdAt.isBefore(end))
        .toList();
    result.sort((a, b) {
      final c = a.createdAt.compareTo(b.createdAt);
      return c != 0 ? c : a.id.compareTo(b.id);
    });
    return result;
  } catch (_) {
    return <_LiveCallPost>[];
  }
}

Future<void> _publishLiveCall(_LiveCallPost post) async {
  final user = FirebaseAuth.instance.currentUser;
  if (user == null)
    throw StateError('You must be signed in to publish a Live Call.');
  await user.getIdToken(true);
  try {
    final todayCalls = await _liveCallsForDayFromBackend(post.createdAt);
    final sequence = todayCalls.length + 1;
    post.dailySequence = sequence;
    post.accessTier = sequence > 2 ? 'premium' : 'free';
    await _persistLiveCall(post);
    _liveCallPosts.value = <_LiveCallPost>[post, ..._liveCallPosts.value];

    if (sequence > 2) return;
    final profile = await _feedAdminProfile();
    await _publishToCommunityFeed(
      _CommunityPost(
        id: 'live-call-${post.id}',
        authorUid: user.uid,
        username: 'CRYPTO-DOCTORS-HUB ADMIN',
        nickname: 'CRYPTO-DOCTORS-HUB ADMIN',
        profilePicUrl: (profile['photoUrl'] ?? '').toString(),
        profilePicBytes: profile['avatar'] as Uint8List?,
        badge: 'ADMIN',
        referrals: 0,
        verified: true,
        text:
            '${post.asset} /USDT Ã¢â‚¬Â¢ ${post.longDirection ? 'LONG' : 'SHORT'} Ã¢â‚¬Â¢ ENTRY ${post.entry} Ã¢â‚¬Â¢ ${post.leverage}x Ã¢â‚¬Â¢ TP1 ${post.tp1} Ã¢â‚¬Â¢ TP2 ${post.tp2} Ã¢â‚¬Â¢ TP3 ${post.tp3} Ã¢â‚¬Â¢ STOPLOSS ${post.stopLoss}',
        imageBytes: post.imageBytes,
        thumbnailBytes: post.imageBytes,
        bullish: post.bullish,
        hashtags: const [],
        coins: [post.asset],
        signalAsset: post.asset,
        signalEntry: post.entry,
        signalLongDirection: post.longDirection,
        signalLeverage: post.leverage,
        signalTp1: post.tp1,
        signalTp2: post.tp2,
        signalTp3: post.tp3,
        signalStopLoss: post.stopLoss,
        createdAt: post.createdAt,
      ),
      sourceType: 'live_call',
      sourceId: post.id,
    );
  } catch (e) {
    rethrow;
  }
}

