class _PremiumRenewalWarning extends StatelessWidget {
  final DateTime expiry;
  const _PremiumRenewalWarning({required this.expiry});

  @override
  Widget build(BuildContext context) {
    final remaining = expiry.difference(DateTime.now());
    if (remaining.isNegative || remaining.inDays > 7)
      return const SizedBox.shrink();
    final days = remaining.inDays;
    final hours = remaining.inHours % 24;
    final text = days > 0
        ? 'Premium renews soon: about $days day${days == 1 ? '' : 's'} remaining. Renew before ${expiry.toLocal().toString().split('.').first} to keep Premium Live Calls unlocked.'
        : 'Premium expires soon: about $hours hour${hours == 1 ? '' : 's'} remaining. Renew now or Premium access will end and Premium Live Calls will lock again.';
    return GlassCard(
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Icon(
            Icons.workspace_premium_rounded,
            color: AppTheme.luxuryGold,
            size: 20,
          ),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              text,
              style: TextStyle(
                color: AppTheme.textPrimary,
                fontSize: 10.5,
                fontWeight: FontWeight.w800,
                height: 1.35,
              ),
            ),
          ),
        ],
      ),
    );
  }
}

