  Future<void> _close(BuildContext context, _LiveCallPost p, bool green) async {
    if (!widget.isAdmin || p.tradeClosed) return;
    final fallback = green
        ? _averageHitProfit(
            tp1Hit: p.tp1Hit,
            tp2Hit: p.tp2Hit,
            tp3Hit: p.tp3Hit,
            tp1Profit: p.tp1Profit,
            tp2Profit: p.tp2Profit,
            tp3Profit: p.tp3Profit,
          )
        : _parseSignalPercent(p.stopLossProfit).abs().toString();
    final controller = TextEditingController(
      text: fallback
          .replaceAll('%', '')
          .replaceFirst('+', '')
          .replaceFirst('-', ''),
    );
    double? entered;
    try {
      entered = await showDialog<double>(
        context: context,
        barrierDismissible: false,
        builder: (dc) => AlertDialog(
          backgroundColor: AppTheme.adaptiveSurface(Color(0xFF0B0F11)),
          title: Text(
            green ? 'TRADE CLOSED Ã¢â‚¬â€ GREEN' : 'TRADE CLOSED Ã¢â‚¬â€ RED',
            style: const TextStyle(fontWeight: FontWeight.w900),
          ),
          content: TextField(
            controller: controller,
            autofocus: true,
            keyboardType: const TextInputType.numberWithOptions(decimal: true),
            decoration: InputDecoration(
              labelText: green ? 'Final Profit %' : 'Final Loss %',
              prefixText: green ? '+' : '-',
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dc).pop(),
              child: const Text('CANCEL'),
            ),
            FilledButton(
              onPressed: () {
                final raw = controller.text
                    .trim()
                    .replaceAll('%', '')
                    .replaceFirst('+', '')
                    .replaceFirst('-', '')
                    .trim();
                final parsed = double.tryParse(raw);
                if (parsed == null || !parsed.isFinite) return;
                Navigator.of(dc).pop(parsed.abs());
              },
              child: const Text('SAVE'),
            ),
          ],
        ),
      );
    } catch (e) {
      if (context.mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not open/close the trade dialog: $e')),
        );
      controller.dispose();
      return;
    }
    // Wait for the dialog route's reverse animation before disposing the controller.
    // Disposing it immediately after showDialog returned was causing the red screen.
    await Future<void>.delayed(const Duration(milliseconds: 450));
    controller.dispose();
    if (!mounted || entered == null || !entered!.isFinite) return;
    final finalPct = green ? entered!.abs() : -entered!.abs();
    p.tradeClosed = true;
    p.closedGreen = green;
    p.finalProfitPercentage = finalPct;
    p.resultPercentage =
        '${finalPct >= 0 ? '+' : ''}${finalPct.toStringAsFixed(2)}%';
    try {
      await FirebaseFirestore.instance
          .collection('live_calls')
          .doc(p.id)
          .update({
            ..._liveCallData(p),
            'finalProfitPercentage': finalPct,
            'resultPercentage': p.resultPercentage,
            'officialResult': finalPct > 0
                ? 'WIN'
                : finalPct < 0
                ? 'LOSS'
                : 'CLOSED',
            'closedAt': FieldValue.serverTimestamp(),
          });
      await _finalizeLiveJournal(p, finalPct);
      await _recordJournalAggregates(p, finalPct);
      try {
        await DriveStorageService.archiveJsonRecord(
          scope: 'live_call',
          recordId: p.id,
          ownerUid: FirebaseAuth.instance.currentUser?.uid ?? '',
          data: _liveCallArchiveData(p),
        );
      } catch (_) {}
      _liveCallPosts.value = List<_LiveCallPost>.from(_liveCallPosts.value);
    } catch (e) {
      p.tradeClosed = false;
      p.closedGreen = false;
      p.finalProfitPercentage = 0;
      p.resultPercentage = '';
      if (context.mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not close this trade. Please try again.'),
          ),
        );
    }
  }

