        ),
        content: Text(
          'Delete this Live Call from Live Calls and CD Feed? Its long-term Drive history will also be removed.',
          style: TextStyle(color: AppTheme.textSecondary),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dc).pop(false),
            child: const Text('CANCEL'),
          ),
          FilledButton(
            onPressed: () => Navigator.of(dc).pop(true),
            child: const Text('DELETE'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    try {
      final db = FirebaseFirestore.instance;
      final liveRef = db.collection('live_calls').doc(p.id);
      final feedSnap = await db
          .collection('feed_posts')
          .where('sourceId', isEqualTo: p.id)
          .get();
      for (int start = 0; start < feedSnap.docs.length; start += 450) {
        final end = (start + 450 > feedSnap.docs.length
            ? feedSnap.docs.length
            : start + 450);
        final batch = db.batch();
        for (final d in feedSnap.docs.sublist(start, end)) {
          if ((d.data()['sourceType'] ?? '').toString() == 'live_call')
            batch.delete(d.reference);
        }
        await batch.commit();
      }
      while (true) {
        final snap = await liveRef.collection('participants').limit(450).get();
        if (snap.docs.isEmpty) break;
        final batch = db.batch();
        for (final d in snap.docs) batch.delete(d.reference);
        await batch.commit();
        if (snap.docs.length < 450) break;
      }
      final detailRef = liveRef.collection('premiumData').doc('details');
      final batch = db.batch();
      batch.delete(detailRef);
      batch.delete(liveRef);
      await batch.commit();
      try {
        await DriveStorageService.deleteArchivedRecord(
          scope: 'live_call',
          recordId: p.id,
          ownerUid: FirebaseAuth.instance.currentUser?.uid ?? '',
        );
      } catch (_) {}
      _liveCallPosts.value = _liveCallPosts.value
          .where((x) => x.id != p.id)
          .toList();
      if (mounted) setState(() {});
    } catch (e) {
      if (context.mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not delete Live Call: $e')),
        );
    }
  }

  Future<void> _edit(BuildContext context, _LiveCallPost p) async {
    if (p.tradeClosed) return;
    final u = await Navigator.push<_LiveCallPost>(
      context,
      MaterialPageRoute(builder: (_) => _LiveCallComposerPage(existingPost: p)),
    );
    if (u == null) return;
    try {
      await _updateLiveCallBackend(u);
    } catch (_) {}
    _liveCallPosts.value = _liveCallPosts.value
        .map((x) => x.id == p.id ? u : x)
        .toList();
  }

