  late final Stream<DocumentSnapshot<Map<String, dynamic>>> _userStream;
  late final Stream<QuerySnapshot<Map<String, dynamic>>> _allStream;

  // Keep Premium/Admin Live Call details across tab switches. The page widget
  // can be recreated when the user changes tabs, so the per-page Future alone
  // is not enough; the shared _liveCallPosts cache is used as the instant
  // source while protected details are refreshed in the background.
  String _premiumFutureKey = '';
  Future<List<_LiveCallPost>>? _premiumFuture;

  @override
  void initState() {
    super.initState();
    final uid = FirebaseAuth.instance.currentUser?.uid;
    _userStream = uid == null
        ? const Stream<DocumentSnapshot<Map<String, dynamic>>>.empty()
        : FirebaseFirestore.instance.collection('users').doc(uid).snapshots();
    // Keep the listener dependent only on the published flag. Ordering is
    // performed locally below, so a missing/still-building composite index
    // can never make the Live Calls list disappear. The existing index is
    // still valid and can remain in Firestore.
    _allStream = FirebaseFirestore.instance
        .collection('live_calls')
        .where('isPublished', isEqualTo: true)
        .limit(200)
        .snapshots();
  }

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: _userStream,
      builder: (context, userSnap) {
        final userData = userSnap.data?.data();
        final premium = _isActivePremiumUserData(userData);
        final premiumExpiry = _premiumExpiryFromUserData(userData);
        final canReadAll = widget.isAdmin || widget.isPremium || premium;
        if (canReadAll) {
          return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
            stream: _allStream,
            builder: (context, snap) => _renderLiveCallSnapshot(
              context,
              snap,
              premiumOverride: canReadAll,
              premiumExpiry: premiumExpiry,
            ),
          );
        }
        // Free users can read the public Live Call metadata for every
        // published signal. Premium signal details are not stored in this
        // document, so the card remains locked/blurred until Premium access.
        return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
          stream: _allStream,
          builder: (context, snap) {
            // During a listener reconnect/error, keep the last successful
            // Live Calls list instead of replacing it with an empty list.
            if (snap.hasError || !snap.hasData) {
              return _renderLiveCallPosts(
                context,
                _liveCallPosts.value,
                premiumOverride: false,
                premiumExpiry: premiumExpiry,
              );
            }
            final docs = snap.data!.docs;
            final posts =
                docs
                    .where((d) => d.data()['isPublished'] == true)
                    .map(_liveCallFromFirestore)
                    .toList()
                  ..sort((a, b) {
                    final c = b.createdAt.compareTo(a.createdAt);
                    return c != 0 ? c : b.id.compareTo(a.id);
                  });
            return _renderLiveCallPosts(
              context,
              posts,
              premiumOverride: false,
              premiumExpiry: premiumExpiry,
            );
          },
        );
      },
    );
  }

  Widget _renderLiveCallSnapshot(
    BuildContext context,
    AsyncSnapshot<QuerySnapshot<Map<String, dynamic>>> snap, {
    required bool premiumOverride,
    DateTime? premiumExpiry,
  }) {
    final docs = snap.hasData
        ? snap.data!.docs.where((d) => d.data()['isPublished'] == true).toList()
        : <QueryDocumentSnapshot<Map<String, dynamic>>>[];
    docs.sort((a, b) {
      final ad = _liveCallDate(a.data()['createdAt']);
      final bd = _liveCallDate(b.data()['createdAt']);
      final c = bd.compareTo(ad);
      return c != 0 ? c : b.id.compareTo(a.id);
    });
    if (!snap.hasData) {
      return _renderLiveCallPosts(
        context,
        _liveCallPosts.value,
        premiumOverride: premiumOverride,
        premiumExpiry: premiumExpiry,
      );
    }
    if (!premiumOverride) {
      return _renderLiveCallPosts(
        context,
        docs.map(_liveCallFromFirestore).toList(),
        premiumOverride: false,
        premiumExpiry: premiumExpiry,
      );
    }

    // If the stream is still reconnecting or temporarily returns no docs,
    // keep the last successful protected list visible instead of flashing an
    // empty Live Calls page.
    if (docs.isEmpty && _liveCallPosts.value.isNotEmpty) {
      return _renderLiveCallPosts(
        context,
        _liveCallPosts.value,
        premiumOverride: true,
        premiumExpiry: premiumExpiry,
      );
    }

    final publicPosts = docs.map(_liveCallFromFirestore).toList();
    final cachedPosts = <_LiveCallPost>[];
    for (final publicPost in publicPosts) {
      cachedPosts.add(
        _liveCallPremiumDetailsCache[publicPost.id] ??
            _findCachedLiveCall(publicPost.id) ??
            publicPost,
      );
    }

    // Reuse the same Future for the same snapshot instead of starting a new
    // serial protected-data read on every StreamBuilder rebuild. This was the
    // reason the card disappeared whenever the user switched tabs.
    final key = docs.map((d) => d.id).join('|');
    if (key != _premiumFutureKey) {
      _premiumFutureKey = key;
      _premiumFuture = _loadLiveCallPostsWithPremiumDetails(docs);
    }

    return FutureBuilder<List<_LiveCallPost>>(
      future: _premiumFuture,
      builder: (context, detailsSnap) {
        final posts = detailsSnap.hasData ? detailsSnap.data! : cachedPosts;
        return _renderLiveCallPosts(
          context,
          posts,
          premiumOverride: true,
          premiumExpiry: premiumExpiry,
        );
      },
    );
  }

  _LiveCallPost? _findCachedLiveCall(String id) {
    for (final post in _liveCallPosts.value) {
      if (post.id == id) return post;
    }
    return null;
  }

  Future<List<_LiveCallPost>> _loadLiveCallPostsWithPremiumDetails(
    List<QueryDocumentSnapshot<Map<String, dynamic>>> docs,
  ) async {
    // Read all protected detail documents concurrently. The previous version
    // awaited them one-by-one, so opening/switching to Live Calls could leave
    // the page showing the public/empty version for several seconds.
    final results = await Future.wait(
      docs.map((doc) async {
        final publicPost = _liveCallFromFirestore(doc);
        final cached = _liveCallPremiumDetailsCache[doc.id];
        if (cached != null) return cached;
        try {
          final detail = await doc.reference
              .collection('premiumData')
              .doc('details')
              .get(const GetOptions(source: Source.server));
          final d = detail.data();
          if (d != null &&
              d.isNotEmpty &&
              (d['entry'] ?? '').toString().trim().isNotEmpty) {
            final merged = _liveCallFromMap(doc.id, <String, dynamic>{
              ...doc.data(),
              ...d,
            });
            _liveCallPremiumDetailsCache[doc.id] = merged;
            return merged;
          }
        } catch (_) {
          // Keep the public snapshot as the safe fallback. Do not cache a failed
          // protected read, so a temporary auth/claim race can recover later.
        }
        return publicPost;
      }),
    );
    if (results.isNotEmpty) {
      _liveCallPosts.value = List<_LiveCallPost>.from(results);
    }
    return results;
  }

  _LiveCallPost _liveCallFromMap(String id, Map<String, dynamic> d) =>
      _LiveCallPost(
        id: id,
        asset: (d['asset'] ?? '').toString(),
        entry: (d['entry'] ?? '').toString(),
        longDirection: d['longDirection'] != false,
        bullish: d['bullish'] != false,
        tp1: (d['tp1'] ?? '').toString(),
        tp2: (d['tp2'] ?? '').toString(),
        tp3: (d['tp3'] ?? '').toString(),
        stopLoss: (d['stopLoss'] ?? '').toString(),
        leverage: (d['leverage'] as num?)?.toInt() ?? 10,
        imageBytes: _decodeLiveCallImage(d['imageBase64']),
        createdAt: _liveCallDate(d['createdAt']),
        goodReactions: (d['goodReactions'] as num?)?.toInt() ?? 0,
        badReactions: (d['badReactions'] as num?)?.toInt() ?? 0,
        tp1Hit: d['tp1Hit'] == true,
        tp2Hit: d['tp2Hit'] == true,
        tp3Hit: d['tp3Hit'] == true,
        stopLossHit: d['stopLossHit'] == true,
        breakEven: d['breakEven'] == true,
        winTradeCounted: d['winTradeCounted'] == true,
        tp1Profit: (d['tp1Profit'] ?? '').toString(),
        tp2Profit: (d['tp2Profit'] ?? '').toString(),
        tp3Profit: (d['tp3Profit'] ?? '').toString(),
        stopLossProfit: (d['stopLossProfit'] ?? '').toString(),
        breakEvenProfit: (d['breakEvenProfit'] ?? '').toString(),
        tradeClosed: d['tradeClosed'] == true,
        closedGreen: d['closedGreen'] == true,
        finalProfitPercentage:
            (d['finalProfitPercentage'] as num?)?.toDouble() ?? 0,
        resultPercentage: (d['resultPercentage'] ?? '').toString(),
        dailySequence: (d['dailySequence'] as num?)?.toInt() ?? 0,
        accessTier: (d['accessTier'] ?? '').toString(),
      );
  Widget _renderLiveCallPosts(
    BuildContext context,
    List<_LiveCallPost> posts, {
    required bool premiumOverride,
    DateTime? premiumExpiry,
  }) {
    if (posts.isNotEmpty) _liveCallPosts.value = posts;
    final now = DateTime.now();
    final today = posts.where((p) => _sameDay(p.createdAt, now)).toList();
    return _body(
      context,
      posts,
      today,
      widget.isAdmin || premiumOverride,
      premiumExpiry: premiumExpiry,
    );
  }

  Widget _body(
    BuildContext context,
    List<_LiveCallPost> posts,
    List<_LiveCallPost> today,
    bool premium, {
    DateTime? premiumExpiry,
  }) {
    final sequenceById = <String, int>{};
    final groups = <String, List<_LiveCallPost>>{};
    for (final p in posts) {
      final key = '${p.createdAt.year}-${p.createdAt.month}-${p.createdAt.day}';
      (groups[key] ??= <_LiveCallPost>[]).add(p);
    }
    for (final group in groups.values) {
      group.sort((a, b) {
        final c = a.createdAt.compareTo(b.createdAt);
        return c != 0 ? c : a.id.compareTo(b.id);
      });
      for (var i = 0; i < group.length; i++) {
        final p = group[i];
        final seq = p.dailySequence > 0 ? p.dailySequence : i + 1;
        sequenceById[p.id] = seq;
        if (p.dailySequence != seq) {
          p.dailySequence = seq;
          p.accessTier = seq > 2 ? 'premium' : 'free';
        }
      }
    }
    return RefreshIndicator(
      onRefresh: refresh,
      child: ListView(
        physics: const AlwaysScrollableScrollPhysics(),
        padding: const EdgeInsets.fromLTRB(16, 10, 16, 110),
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(
                child: Text(
                  'LIVE CALLS',
                  style: TextStyle(
                    color: AppTheme.textPrimary,
                    fontSize: 16,
                    fontWeight: FontWeight.w900,
                    letterSpacing: 1,
                  ),
                ),
              ),
              _LiveCallsStats(
                total: today.length,
                wins: today.where(_liveCallWin).length,
                losses: today.where(_liveCallLoss).length,
              ),
              const SizedBox(width: 6),
              if (widget.isAdmin && widget.onCreate != null)
                _JellyPlusButton(
                  tooltip: 'Create live call',
                  onPressed: widget.onCreate!,
                ),
            ],
          ),
          const SizedBox(height: 8),
          if (posts.isEmpty)
            Padding(
              padding: EdgeInsets.only(top: 230),
              child: Center(
                child: Text(
                  'No live calls published yet.',
                  style: TextStyle(color: AppTheme.textMuted),
                ),
              ),
            ),
          if (premium &&
              premiumExpiry != null &&
              premiumExpiry.isAfter(DateTime.now()))
            Padding(
              padding: const EdgeInsets.only(bottom: 10),
              child: _PremiumRenewalWarning(expiry: premiumExpiry),
            ),
          ...posts.map((p) {
            final sequence = sequenceById[p.id] ?? 0;
            final premiumOnly =
                !widget.isAdmin &&
                !premium &&
                ((p.accessTier == 'premium') ||
                    (p.accessTier.isEmpty && sequence > 2) ||
                    sequence > 2);
            final hasTpHit = p.tp1Hit || p.tp2Hit || p.tp3Hit;
            final locked = premiumOnly && !hasTpHit && !p.tradeClosed;
            return _LiveCallCard(
              post: p,
              locked: locked,
              resultRevealed: premiumOnly && (hasTpHit || p.tradeClosed),
              canEdit: widget.isAdmin,
              onOpenPremium: () => _premium(context),
              onEdit: widget.isAdmin ? () => _edit(context, p) : null,
              onEnterWinRatio: widget.isAdmin
                  ? () => _outcome(context, p)
                  : null,
              onCloseGreen: widget.isAdmin
                  ? () => _close(context, p, true)
                  : null,
              onCloseRed: widget.isAdmin
                  ? () => _close(context, p, false)
                  : null,
              onDelete: widget.isAdmin
                  ? () => _deleteLiveCall(context, p)
                  : null,
              onReaction: (good) async {
                try {
                  await _recordLiveParticipant(p.id, good);
                } catch (_) {}
              },
            );
          }),
        ],
      ),
    );
  }
}

