class _LiveCallCard extends StatefulWidget {
  final _LiveCallPost post;
  final bool locked;
  final bool resultRevealed;
  final bool canEdit;
  final VoidCallback onOpenPremium;
  final VoidCallback? onEdit;
  final VoidCallback? onEnterWinRatio;
  final VoidCallback? onCloseGreen;
  final VoidCallback? onCloseRed;
  final VoidCallback? onDelete;
  final Future<void> Function(bool good)? onReaction;

  const _LiveCallCard({
    required this.post,
    required this.locked,
    this.resultRevealed = false,
    required this.canEdit,
    required this.onOpenPremium,
    this.onEdit,
    this.onEnterWinRatio,
    this.onCloseGreen,
    this.onCloseRed,
    this.onDelete,
    this.onReaction,
  });

  @override
  State<_LiveCallCard> createState() => _LiveCallCardState();
}

class _LiveCallCardState extends State<_LiveCallCard> {
  bool good = false, bad = false;

  void react(bool g) {
    setState(() {
      if (g) {
        good = !good;
        if (good) {
          widget.post.goodReactions++;
        } else if (widget.post.goodReactions > 0) {
          widget.post.goodReactions--;
        }
      } else {
        bad = !bad;
        if (bad) {
          widget.post.badReactions++;
        } else if (widget.post.badReactions > 0) {
          widget.post.badReactions--;
        }
      }
    });
    widget.onReaction?.call(g);
  }

