  Widget build(BuildContext context) {
    final dir = widget.post.longDirection
        ? AppTheme.neonGreen
        : const Color(0xFFE05252);
    final closed = widget.post.closedGreen
        ? const Color(0xFF39E75F)
        : const Color(0xFFE05252);
    final avg = _averageHitProfit(
      tp1Hit: widget.post.tp1Hit,
      tp2Hit: widget.post.tp2Hit,
      tp3Hit: widget.post.tp3Hit,
      tp1Profit: widget.post.tp1Profit,
      tp2Profit: widget.post.tp2Profit,
      tp3Profit: widget.post.tp3Profit,
    );
    final overall =
        widget.post.tradeClosed &&
            widget.post.resultPercentage.trim().isNotEmpty
        ? widget.post.resultPercentage
        : avg;
    final overallColor = overall.trim().startsWith('-')
