              ),
            const SizedBox(height: 11),
            // Never manufacture dotted/placeholder signal values. Authorized users
            // render the real protected fields. Free users who are not authorized
            // receive no protected values at all; the existing lock/blur layer is
            // the only visual restriction.
            _LiveCallValueRow(
              label: 'ENTRY',
              value: detailsAvailable && !widget.locked
                  ? widget.post.entry
                  : '',
            ),
            Row(
              children: [
                Text(
                  'LEVERAGE',
                  style: TextStyle(
                    color: AppTheme.textMuted,
                    fontSize: 10,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(width: 8),
                Text(
                  detailsAvailable && !widget.locked
                      ? '${widget.post.leverage}x'
                      : '',
                  style: TextStyle(
                    color: _leverageColor(widget.post.leverage),
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ],
            ),
            _signalTargetRow(
              label: 'TP1',
              value: detailsAvailable && !widget.locked ? widget.post.tp1 : '',
              hit: widget.post.tp1Hit,
              profit: detailsAvailable && !widget.locked
                  ? widget.post.tp1Profit
                  : '',
            ),
            _signalTargetRow(
              label: 'TP2',
              value: detailsAvailable && !widget.locked ? widget.post.tp2 : '',
              hit: widget.post.tp2Hit,
              profit: detailsAvailable && !widget.locked
                  ? widget.post.tp2Profit
                  : '',
            ),
            _signalTargetRow(
              label: 'TP3',
              value: detailsAvailable && !widget.locked ? widget.post.tp3 : '',
              hit: widget.post.tp3Hit,
              profit: detailsAvailable && !widget.locked
                  ? widget.post.tp3Profit
                  : '',
            ),
            _signalTargetRow(
              label: 'STOPLOSS',
              value: detailsAvailable && !widget.locked
                  ? widget.post.stopLoss
                  : '',
