            const SizedBox(height: 10),
            Row(
              mainAxisAlignment: MainAxisAlignment.end,
              children: [
                _LiveCallReactionButton(
                  icon: Icons.thumb_up_alt_rounded,
                  label: 'LIKE',
                  count: widget.post.goodReactions,
                  active: good,
                  activeColor: const Color(0xFF39E75F),
                  onTap: widget.post.tradeClosed ? () {} : () => react(true),
                ),
                const SizedBox(width: 8),
                _LiveCallReactionButton(
                  icon: Icons.thumb_down_alt_rounded,
                  label: 'DISLIKE',
                  count: widget.post.badReactions,
                  active: bad,
                  activeColor: const Color(0xFFE05252),
                  onTap: widget.post.tradeClosed ? () {} : () => react(false),
                ),
              ],
            ),
          ],
        ),
      ),
    );

    final visibleCard = widget.locked
        ? ImageFiltered(
            imageFilter: ui.ImageFilter.blur(sigmaX: 5.5, sigmaY: 5.5),
            child: card,
          )
        : widget.resultRevealed
        ? ImageFiltered(
            imageFilter: ui.ImageFilter.blur(sigmaX: 1.15, sigmaY: 1.15),
            child: card,
          )
        : card;

    return Stack(
