            child: IgnorePointer(
              child: Center(
                child: _LiveCallResultTick(
                  color: closed,
                  icon: Icons.check_rounded,
                ),
              ),
            ),
          )
        else if (widget.resultRevealed && hasPublicTp)
          Positioned.fill(
            child: IgnorePointer(
              child: Center(
                child: _LiveCallResultTick(
                  color: const Color(0xFF39E75F),
                  icon: Icons.check_rounded,
                ),
              ),
            ),
          ),
        if (widget.locked && showPublicResult)
          Positioned(
            top: 66,
            left: 14,
            right: 14,
            child: IgnorePointer(
              child: Wrap(
                spacing: 6,
                runSpacing: 6,
                children: [
                  if (widget.post.tp1Hit)
                    _LiveCallPublicResultChip(
                      label: 'TP1 HIT',
                      profit: widget.post.tp1Profit,
                      icon: Icons.check_rounded,
                      color: const Color(0xFF39E75F),
                    ),
                  if (widget.post.tp2Hit)
                    _LiveCallPublicResultChip(
                      label: 'TP2 HIT',
                      profit: widget.post.tp2Profit,
                      icon: Icons.check_rounded,
                      color: const Color(0xFF39E75F),
                    ),
                  if (widget.post.tp3Hit)
                    _LiveCallPublicResultChip(
                      label: 'TP3 HIT',
                      profit: widget.post.tp3Profit,
                      icon: Icons.check_rounded,
                      color: const Color(0xFF39E75F),
                    ),
                  if (widget.post.stopLossHit)
                    _LiveCallPublicResultChip(
                      label: 'STOP LOSS',
                      profit: widget.post.stopLossProfit,
                      icon: Icons.priority_high_rounded,
                      color: const Color(0xFFE05252),
                    ),
                ],
              ),
            ),
          ),
        if (widget.locked)
          Positioned.fill(
            child: Material(
              color: Colors.transparent,
              child: InkWell(
                borderRadius: BorderRadius.circular(18),
                onTap: widget.onOpenPremium,
                child: const Center(child: _LiveCall3DLock()),
              ),
            ),
          ),
      ],
    );
  }
}

