class _LiveCallResultTickState extends State<_LiveCallResultTick>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;
  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 850),
    )..forward();
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _controller,
      builder: (context, _) {
        final pulse = 0.75 + (_controller.value * 0.25);
        final scale = Curves.elasticOut.transform(
          _controller.value.clamp(0.0, 1.0).toDouble(),
        );
        return Transform.scale(
          scale: scale,
          child: Container(
            width: 72,
            height: 72,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              color: const Color(0xCC090D12),
              border: Border.all(color: widget.color, width: 2.2),
              boxShadow: [
                BoxShadow(
                  color: widget.color.withValues(alpha: .30 * pulse),
                  blurRadius: 22,
                  spreadRadius: 4,
                ),
              ],
            ),
            child: Icon(widget.icon, color: widget.color, size: 42),
          ),
        );
      },
    );
  }
}

