    setState(() => _bounce = true);
    widget.onTap();
    Future<void>.delayed(const Duration(milliseconds: 180), () {
      if (mounted) setState(() => _bounce = false);
    });
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: _tap,
      child: AnimatedScale(
        scale: _bounce ? 1.16 : 1,
        duration: const Duration(milliseconds: 180),
        curve: Curves.easeOutBack,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 220),
          padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 6),
          decoration: BoxDecoration(
            color: widget.active
                ? widget.activeColor.withValues(alpha: 0.16)
                : AppTheme.adaptiveWhite(alpha: 0.04),
            borderRadius: BorderRadius.circular(12),
            border: Border.all(
              color: widget.active
                  ? widget.activeColor.withValues(alpha: 0.6)
                  : AppTheme.borderFaint,
            ),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                widget.icon,
                size: 17,
                color: widget.active ? widget.activeColor : AppTheme.textSoft,
              ),
              const SizedBox(width: 4),
              Text(
                '${widget.label} ${widget.count}',
                style: TextStyle(
                  color: widget.active ? widget.activeColor : AppTheme.textSoft,
                  fontSize: 9,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

