class _LiveCallLockOrbitPainter extends CustomPainter {
  final double progress;

  _LiveCallLockOrbitPainter({required this.progress});

  @override
  void paint(Canvas canvas, Size size) {
    final center = size.center(Offset.zero);
    final rings = <({double w, double h, double rotation, Color color})>[
      (w: 102, h: 34, rotation: -0.32, color: AppTheme.luxuryGold),
      (w: 88, h: 44, rotation: 0.72, color: AppTheme.neonGreen),
      (w: 74, h: 54, rotation: -1.08, color: const Color(0xFF7C83D8)),
    ];

    for (var i = 0; i < rings.length; i++) {
      final ring = rings[i];
      final rect = Rect.fromCenter(
        center: center,
        width: ring.w,
        height: ring.h,
      );
      final paint = Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.1
        ..color = ring.color.withValues(alpha: 0.55);
      canvas.save();
      canvas.translate(center.dx, center.dy);
      canvas.rotate(ring.rotation + progress * (i.isEven ? 1.0 : -1.0));
      canvas.translate(-center.dx, -center.dy);
      canvas.drawOval(rect, paint);

      final angle = progress * math.pi * 2 * (i.isEven ? 1 : -1) + i * 1.7;
      final x = center.dx + math.cos(angle) * ring.w / 2;
      final y = center.dy + math.sin(angle) * ring.h / 2;
      final dot = Paint()..color = ring.color;
      canvas.drawCircle(Offset(x, y), 3.1, dot);
      canvas.restore();
    }
  }

  @override
  bool shouldRepaint(covariant _LiveCallLockOrbitPainter oldDelegate) =>
      oldDelegate.progress != progress;
}

