class _LiveCallComposerPage extends StatefulWidget {
  final _LiveCallPost? existingPost;
  const _LiveCallComposerPage({this.existingPost});
  @override
  State<_LiveCallComposerPage> createState() => _LiveCallComposerPageState();
}

class _LiveCallComposerPageState extends State<_LiveCallComposerPage>
    with SingleTickerProviderStateMixin {
  final a = TextEditingController(),
      e = TextEditingController(),
      t1 = TextEditingController(),
      t2 = TextEditingController(),
      t3 = TextEditingController(),
      sl = TextEditingController();
  Uint8List? img;
  bool longDir = true;
  int lev = 10;
  late final AnimationController anim = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 650),
  )..forward();
  @override
  void initState() {
    super.initState();
    final p = widget.existingPost;
    if (p != null) {
      a.text = p.asset;
      e.text = p.entry;
      t1.text = p.tp1;
      t2.text = p.tp2;
      t3.text = p.tp3;
      sl.text = p.stopLoss;
      longDir = p.longDirection;
      lev = p.leverage;
      img = p.imageBytes;
    }
  }

  @override
  void dispose() {
    anim.dispose();
    a.dispose();
    e.dispose();
    t1.dispose();
    t2.dispose();
    t3.dispose();
    sl.dispose();
    super.dispose();
  }

  Future<Uint8List?> pick() async {
    final input = html.FileUploadInputElement()..accept = 'image/*';
    input.click();
    await input.onChange.first;
    final f = input.files?.isNotEmpty == true ? input.files!.first : null;
    if (f == null) return null;
    final r = html.FileReader();
    r.readAsArrayBuffer(f);
    await r.onLoad.first;
    return r.result is ByteBuffer
        ? (r.result as ByteBuffer).asUint8List()
        : null;
  }

  void publish() {
    final asset = a.text.trim().toUpperCase();
    if (asset.isEmpty ||
        e.text.trim().isEmpty ||
        t1.text.trim().isEmpty ||
        t2.text.trim().isEmpty ||
        t3.text.trim().isEmpty ||
        sl.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Fill Asset, Entry, TP1, TP2, TP3 and Stoploss before publishing.',
          ),
        ),
      );
      return;
    }
    Navigator.pop(
      context,
      _LiveCallPost(
        id:
            widget.existingPost?.id ??
            '${DateTime.now().microsecondsSinceEpoch}',
        asset: asset,
        entry: e.text.trim(),
        longDirection: longDir,
        bullish: true,
        tp1: t1.text.trim(),
        tp2: t2.text.trim(),
        tp3: t3.text.trim(),
        stopLoss: sl.text.trim(),
        leverage: lev,
        imageBytes: img,
        createdAt: widget.existingPost?.createdAt,
        goodReactions: widget.existingPost?.goodReactions ?? 0,
        badReactions: widget.existingPost?.badReactions ?? 0,
        tp1Hit: widget.existingPost?.tp1Hit ?? false,
        tp2Hit: widget.existingPost?.tp2Hit ?? false,
        tp3Hit: widget.existingPost?.tp3Hit ?? false,
        stopLossHit: widget.existingPost?.stopLossHit ?? false,
        breakEven: widget.existingPost?.breakEven ?? false,
        winTradeCounted: widget.existingPost?.winTradeCounted ?? false,
        tp1Profit: widget.existingPost?.tp1Profit ?? '',
        tp2Profit: widget.existingPost?.tp2Profit ?? '',
        tp3Profit: widget.existingPost?.tp3Profit ?? '',
        stopLossProfit: widget.existingPost?.stopLossProfit ?? '',
        breakEvenProfit: widget.existingPost?.breakEvenProfit ?? '',
        tradeClosed: widget.existingPost?.tradeClosed ?? false,
        closedGreen: widget.existingPost?.closedGreen ?? false,
        finalProfitPercentage: widget.existingPost?.finalProfitPercentage ?? 0,
        resultPercentage: widget.existingPost?.resultPercentage ?? '',
        dailySequence: widget.existingPost?.dailySequence ?? 0,
        accessTier: widget.existingPost?.accessTier ?? '',
      ),
    );
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(
      title: Text(
        widget.existingPost == null ? 'CREATE LIVE CALL' : 'EDIT LIVE CALL',
      ),
      actions: [
        Padding(
          padding: const EdgeInsets.only(right: 12, top: 8, bottom: 8),
          child: FilledButton(
            onPressed: publish,
            style: FilledButton.styleFrom(
              backgroundColor: AppTheme.luxuryGold,
              foregroundColor: Colors.black,
            ),
            child: const Text('PUBLISH'),
          ),
        ),
      ],
    ),
    body: ListView(
      padding: const EdgeInsets.fromLTRB(16, 14, 16, 30),
      children: [
        TextField(
          controller: a,
          decoration: const InputDecoration(labelText: 'ASSET'),
        ),
        const SizedBox(height: 10),
        TextField(
          controller: e,
          decoration: const InputDecoration(labelText: 'ENTRY'),
        ),
        const SizedBox(height: 10),
        Text(
          'DIRECTION',
          style: TextStyle(
            color: AppTheme.textMuted,
            fontSize: 10,
            fontWeight: FontWeight.w900,
          ),
        ),
        RadioGroup<bool>(
          groupValue: longDir,
          onChanged: (v) => setState(() => longDir = v ?? true),
          child: Row(
            children: [
              Expanded(
                child: RadioListTile<bool>(
                  value: true,
                  title: const Text('LONG'),
                ),
              ),
              Expanded(
                child: RadioListTile<bool>(
                  value: false,
                  title: const Text('SHORT'),
                ),
              ),
            ],
          ),
        ),
        Text(
          'LEVERAGE ${lev}x',
          style: TextStyle(
            color: _leverageColor(lev),
            fontWeight: FontWeight.w900,
          ),
        ),
        Slider(
          min: 10,
          max: 100,
          divisions: 9,
          value: lev.toDouble(),
          onChanged: (v) => setState(() => lev = (v.round() ~/ 10) * 10),
        ),
        TextField(
          controller: t1,
          decoration: const InputDecoration(labelText: 'TP1'),
        ),
        TextField(
