Future<void> _repairClosedLiveCallPublicNames() async {
  final user = FirebaseAuth.instance.currentUser;
  if (user == null || !await _hasFirebaseAdminClaim(user)) return;
  try {
    final snap = await FirebaseFirestore.instance
        .collection('live_calls')
        .where('isPublished', isEqualTo: true)
        .limit(500)
        .get();
    for (final doc in snap.docs) {
      final data = doc.data();
      final revealed =
          data['tradeClosed'] == true ||
          data['tp1Hit'] == true ||
          data['tp2Hit'] == true ||
          data['tp3Hit'] == true ||
          data['stopLossHit'] == true;
      if (!revealed) continue;
      final current = (data['asset'] ?? data['tradeName'] ?? '')
          .toString()
          .trim();
      final hasFullSignal =
          (data['entry'] ?? '').toString().trim().isNotEmpty &&
          (data['tp1'] ?? '').toString().trim().isNotEmpty &&
          (data['stopLoss'] ?? '').toString().trim().isNotEmpty;
      if (current.isNotEmpty &&
          current.toUpperCase() != 'UNKNOWN' &&
          hasFullSignal)
        continue;
      try {
        final detail = await doc.reference
            .collection('premiumData')
            .doc('details')
            .get();
        final d = detail.data();
        final asset = (d?['asset'] ?? d?['tradeName'] ?? '').toString().trim();
        if (asset.isEmpty || asset.toUpperCase() == 'UNKNOWN') continue;
        await doc.reference.update({
          'asset': asset,
          'tradeName': asset,
          'entry': d?['entry'],
          'longDirection': d?['longDirection'],
          'bullish': d?['bullish'],
          'tp1': d?['tp1'],
          'tp2': d?['tp2'],
          'tp3': d?['tp3'],
          'stopLoss': d?['stopLoss'],
          'leverage': d?['leverage'],
          'imageBase64': d?['imageBase64'],
          'winTradeCounted': d?['winTradeCounted'],
        });
      } catch (_) {}
    }
  } catch (_) {}
}

