}

class _JournalPageState extends State<JournalPage> {
  Map<String, double> _community = {'daily': 0, 'monthly': 0, 'yearly': 0};
  Map<String, double> _personal = {'daily': 0, 'monthly': 0, 'yearly': 0};
  bool _loading = true;
  final _helpTitle = 'TRADING JOURNAL INFORMATION & GUIDE';

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    unawaited(_repairClosedLiveCallPublicNames());
    final u = FirebaseAuth.instance.currentUser;
    if (u == null) return;
    try {
      final c = await TradingJournalService.loadCommunityPerformance();
      final p = await TradingJournalService.loadPersonalPerformance(u.uid);
      if (mounted)
        setState(() {
          _community = c;
          _personal = p;
          _loading = false;
        });
    } catch (_) {
      if (mounted) setState(() => _loading = false);
    }
  }

  Future<void> _communityOpen(String period, String title) async {
    final enter = await showDialog<bool>(
      context: context,
