  @override
  Widget build(BuildContext context) {
    final communityTiles = [
      ('DAILY COMMUNITY PROFIT', 'daily'),
      ('WEEKLY COMMUNITY PROFIT', 'weekly'),
      ('MONTHLY COMMUNITY PROFIT', 'monthly'),
      ('YEARLY COMMUNITY PROFIT', 'yearly'),
    ];
    final personalTiles = [
      ('YOUR DAILY PROFIT', 'daily'),
      ('YOUR WEEKLY PROFIT', 'weekly'),
      ('YOUR MONTHLY PROFIT', 'monthly'),
      ('YOUR YEARLY PROFIT', 'yearly'),
    ];
    return RefreshIndicator(
      onRefresh: _load,
      child: ListView(
        physics: const AlwaysScrollableScrollPhysics(),
        padding: const EdgeInsets.fromLTRB(16, 10, 16, 110),
        children: [
          Row(
            children: [
              Expanded(
                child: Text(
                  'TRADING JOURNAL',
                  style: TextStyle(
                    color: AppTheme.textPrimary,
                    fontSize: 16,
                    fontWeight: FontWeight.w900,
                    letterSpacing: 1,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 4),
          _JournalActionTile(
            title: 'PERSONAL',
            subtitle: 'Private Trading Journal & Trading Task',
            icon: Icons.person_outline_rounded,
            onTap: () => Navigator.push(
              context,
              MaterialPageRoute(
                builder: (_) => const _PersonalTradingJournalPage(),
              ),
            ),
          ),
          const SizedBox(height: 14),
          Text(
            'COMMUNITY',
            style: TextStyle(
              color: AppTheme.luxuryGold,
              fontSize: 10,
              fontWeight: FontWeight.w900,
              letterSpacing: 1,
            ),
          ),
          const SizedBox(height: 8),
          StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
            stream: FirebaseFirestore.instance
                .collection('journalCommunityAggregates')
                .where(
                  'period',
                  whereIn: const ['daily', 'weekly', 'monthly', 'yearly'],
                )
                .snapshots(),
            builder: (context, snap) {
              final now = DateTime.now();
              final weekStart = DateTime(
                now.year,
                now.month,
                now.day,
              ).subtract(Duration(days: now.weekday - DateTime.monday));
              final keys = {
                'daily':
                    '${now.year}-${now.month.toString().padLeft(2, '0')}-${now.day.toString().padLeft(2, '0')}',
                'weekly':
                    '${weekStart.year}-${weekStart.month.toString().padLeft(2, '0')}-${weekStart.day.toString().padLeft(2, '0')}',
                'monthly':
                    '${now.year}-${now.month.toString().padLeft(2, '0')}',
                'yearly': '${now.year}',
              };
              final live = <String, double>{};
              for (final d
                  in snap.data?.docs ??
                      const <QueryDocumentSnapshot<Map<String, dynamic>>>[]) {
                final x = d.data();
                final period = (x['period'] ?? '').toString();
                if (keys[period] == x['periodKey']) {
                  final count =
                      (x['closedTradeCount'] as num?)?.toDouble() ?? 0;
                  live[period] = count == 0
                      ? 0
                      : ((x['sumProfitPercentage'] as num?)?.toDouble() ?? 0) /
                            count;
                }
              }
              return Column(
                children: [
                  for (final item in communityTiles) ...[
                    _JournalStatTile(
                      title: item.$1,
                      value: _formatJournalPercent(
                        live[item.$2] ?? _community[item.$2] ?? 0,
                      ),
                      onTap: () => _communityOpen(item.$2, item.$1),
                    ),
                    const SizedBox(height: 10),
                  ],
                ],
              );
            },
          ),
          const SizedBox(height: 7),
          Text(
            'PERSONAL',
            style: TextStyle(
              color: AppTheme.luxuryGold,
              fontSize: 10,
              fontWeight: FontWeight.w900,
              letterSpacing: 1,
            ),
          ),
          const SizedBox(height: 8),
          for (final item in personalTiles) ...[
            _JournalStatTile(
              title: item.$1,
              value: _loading
                  ? '...'
                  : _formatJournalPercent(_personal[item.$2] ?? 0),
              onTap: () => _personalOpen(item.$2, item.$1),
            ),
            const SizedBox(height: 10),
          ],
        ],
      ),
    );
  }
}

String _formatJournalPercent(double value) {
  final sign = value > 0 ? '+' : '';
  return '$sign${value.toStringAsFixed(2)}%';
}

