class _CommunityJournalResultsPage extends StatelessWidget {
  final String period, title;
  const _CommunityJournalResultsPage({
    required this.period,
    required this.title,
  });

  @override
  Widget build(BuildContext context) => Scaffold(
    backgroundColor: AppTheme.adaptiveSurface(Color(0xFF070B10)),
    appBar: AppBar(
      title: Text(
        title,
        style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 14),
      ),
      actions: [
        IconButton(
          tooltip: 'Refresh',
          onPressed: () => Navigator.of(context).pushReplacement(
            MaterialPageRoute(
              builder: (_) =>
                  _CommunityJournalResultsPage(period: period, title: title),
            ),
          ),
          icon: const Icon(Icons.refresh_rounded),
        ),
      ],
    ),
    body: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: TradingJournalService.closedLiveCallsStream(period),
      builder: (context, snapshot) {
        if (snapshot.connectionState == ConnectionState.waiting)
          return const Center(child: CircularProgressIndicator());
        if (snapshot.hasError)
          return Center(
            child: Padding(
              padding: EdgeInsets.all(24),
              child: Text(
                'Journal history could not be loaded. Pull to refresh or use the refresh button.',
                textAlign: TextAlign.center,
                style: TextStyle(color: AppTheme.textMuted),
              ),
            ),
          );
        final now = DateTime.now();
        final today = DateTime(now.year, now.month, now.day);
        final start = period == 'daily'
            ? today
            : period == 'weekly'
            ? today.subtract(Duration(days: today.weekday - DateTime.monday))
            : period == 'monthly'
            ? DateTime(now.year, now.month)
            : DateTime(now.year);
        final end = period == 'daily'
            ? start.add(const Duration(days: 1))
            : period == 'weekly'
            ? start.add(const Duration(days: 7))
            : period == 'monthly'
            ? DateTime(start.year, start.month + 1)
            : DateTime(start.year + 1);
        DateTime? readDate(dynamic raw) => raw is Timestamp
            ? raw.toDate()
            : DateTime.tryParse((raw ?? '').toString());
        final docs =
            (snapshot.data?.docs ?? []).where((d) {
              final data = d.data();
              if (data['tradeClosed'] != true) return false;
              final closedAt = readDate(data['closedAt']);
              return closedAt != null &&
                  !closedAt.isBefore(start) &&
                  closedAt.isBefore(end);
            }).toList()..sort(
              (a, b) => (readDate(b.data()['closedAt']) ?? DateTime(0))
                  .compareTo(readDate(a.data()['closedAt']) ?? DateTime(0)),
            );
        if (docs.isEmpty)
          return RefreshIndicator(
            onRefresh: () async =>
                Future<void>.delayed(const Duration(milliseconds: 250)),
            child: ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              children: [
                SizedBox(height: 220),
                Center(
                  child: Text(
                    'No officially closed Live Call results for this period.',
                    style: TextStyle(color: AppTheme.textMuted),
                  ),
                ),
              ],
            ),
          );
        return RefreshIndicator(
          onRefresh: () async =>
              Future<void>.delayed(const Duration(milliseconds: 250)),
          child: ListView(
            physics: const AlwaysScrollableScrollPhysics(),
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 30),
            children: [
              for (final d in docs) _CommunityResultCard(data: d.data()),
            ],
          ),
        );
      },
    ),
  );
}

String _journalTradeName(Map<String, dynamic> data) {
  const keys = <String>[
    'tradeName',
    'asset',
    'signalAsset',
    'coin',
    'symbol',
    'assetName',
  ];
  for (final key in keys) {
    final value = (data[key] ?? '').toString().trim();
    if (value.isNotEmpty && value.toUpperCase() != 'UNKNOWN') {
      return value
          .replaceAll(RegExp(r'/USDT$', caseSensitive: false), '')
          .trim();
    }
  }
  return 'LIVE CALL';
}

class _CommunityResultCard extends StatelessWidget {
  final Map<String, dynamic> data;
  const _CommunityResultCard({required this.data});
  DateTime? _date(dynamic v) =>
      v is Timestamp ? v.toDate() : DateTime.tryParse((v ?? '').toString());
  String _stamp(dynamic v) {
    final d = _date(v);
    if (d == null) return 'Ã¢â‚¬â€';
    return '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')} ${d.hour.toString().padLeft(2, '0')}:${d.minute.toString().padLeft(2, '0')}';
  }

  @override
  Widget build(BuildContext context) {
    final green = data['closedGreen'] == true;
    final c = green ? const Color(0xFF39E75F) : const Color(0xFFE05252);
    final raw =
        (data['finalProfitPercentage'] ?? data['resultPercentage'] ?? '0')
            .toString()
            .replaceAll('%', '');
    final value = double.tryParse(raw.replaceAll('+', '')) ?? 0;
    final p = '${value >= 0 ? '+' : ''}${value.toStringAsFixed(2)}%';
    final hits = <String>[];
    if (data['tp1Hit'] == true)
      hits.add(
        'TP1 +${(data['tp1Profit'] ?? '').toString().replaceFirst(RegExp(r'^\+'), '')}%',
      );
    if (data['tp2Hit'] == true)
      hits.add(
        'TP2 +${(data['tp2Profit'] ?? '').toString().replaceFirst(RegExp(r'^\+'), '')}%',
      );
    if (data['tp3Hit'] == true)
      hits.add(
        'TP3 +${(data['tp3Profit'] ?? '').toString().replaceFirst(RegExp(r'^\+'), '')}%',
      );
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.fromLTRB(12, 11, 12, 11),
      decoration: BoxDecoration(
        color: AppTheme.adaptiveSurface(Color(0xFF303238)),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: c.withValues(alpha: .20)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
