class _PersonalLiveCallResultsPage extends StatelessWidget {
  final String period, title;
  const _PersonalLiveCallResultsPage({
    required this.period,
    required this.title,
  });
  DateTime? _date(dynamic v) =>
      v is Timestamp ? v.toDate() : DateTime.tryParse((v ?? '').toString());
  bool _inPeriod(DateTime d, DateTime now) {
    if (period == 'daily')
      return d.year == now.year && d.month == now.month && d.day == now.day;
    if (period == 'weekly') {
      final today = DateTime(now.year, now.month, now.day);
      final start = today.subtract(
        Duration(days: today.weekday - DateTime.monday),
      );
      final end = start.add(const Duration(days: 7));
      return !d.isBefore(start) && d.isBefore(end);
    }
    if (period == 'monthly') return d.year == now.year && d.month == now.month;
    return d.year == now.year;
  }

  @override
  Widget build(BuildContext context) {
    final u = FirebaseAuth.instance.currentUser;
    if (u == null)
      return Scaffold(
        backgroundColor: AppTheme.adaptiveSurface(Color(0xFF070B10)),
        body: Center(child: Text('Sign in to view your personal history.')),
      );
    return Scaffold(
      backgroundColor: AppTheme.adaptiveSurface(Color(0xFF070B10)),
      appBar: AppBar(
        title: Text(
          title,
          style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 14),
        ),
      ),
      body: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
        stream: FirebaseFirestore.instance
            .collection('users')
            .doc(u.uid)
            .collection('tradingJournal')
            .where('status', isEqualTo: 'CLOSED')
            .snapshots(),
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting)
            return const Center(child: CircularProgressIndicator());
          final now = DateTime.now();
          final docs =
              (snapshot.data?.docs ?? []).where((d) {
                final x = d.data();
                if (x['interaction'] != 'like') return false;
                final date = _date(x['closedAt']);
                return date != null && _inPeriod(date, now);
              }).toList()..sort((a, b) {
                final da = _date(a.data()['closedAt']) ?? DateTime(0);
                final db = _date(b.data()['closedAt']) ?? DateTime(0);
                return db.compareTo(da);
              });
          if (docs.isEmpty)
            return Center(
              child: Text(
                'No liked Live Call results for this period.',
                style: TextStyle(color: AppTheme.textMuted),
              ),
            );
          return ListView(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 30),
            children: [
              for (final d in docs) _PersonalLiveCallResultCard(data: d.data()),
            ],
          );
        },
      ),
    );
  }
}

class _PersonalLiveCallResultCard extends StatelessWidget {
