class _PersonalTradingJournalPage extends StatefulWidget {
  const _PersonalTradingJournalPage();
  @override
  State<_PersonalTradingJournalPage> createState() =>
      _PersonalTradingJournalPageState();
}

class _PersonalTradingJournalPageState
    extends State<_PersonalTradingJournalPage> {
  Map<String, dynamic> settings = {};
  Map<String, dynamic> today = {};
  List<Map<String, dynamic>> history = [];
  final actual = TextEditingController();
  final manual = TextEditingController();

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    actual.dispose();
    manual.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    final u = FirebaseAuth.instance.currentUser;
    if (u == null) return;
    try {
      var s = await TradingJournalService.loadTaskSettings(u.uid);
      if (s.isNotEmpty) {
        final portfolio = (s['portfolio'] as num?)?.toDouble() ?? 0;
        final monthlyTarget = (s['monthlyTargetPct'] as num?)?.toDouble() ?? 0;
        if (portfolio > 0 && monthlyTarget > 0) {
          final normalized = TradingJournalService.calculatePlan({
            'portfolio': portfolio,
            'monthlyTargetPct': monthlyTarget,
          });
          s = <String, dynamic>{
            'portfolio': portfolio,
            'monthlyTargetPct': monthlyTarget,
            ...normalized,
          };
          await TradingJournalService.saveTaskSettings(u.uid, s);
          await TradingJournalService.syncTodayTask(u.uid, s);
        }
        final generated = await TradingJournalService.ensureTodayTask(u.uid, s);
        if (generated && mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('You have a new Trading Task')),
          );
        }
      }
      final h = await TradingJournalService.loadPersonalDays(u.uid);
      final d = await TradingJournalService.loadToday(u.uid);
      if (mounted)
        setState(() {
          settings = s;
          history = h;
          today = d;
        });
    } catch (_) {}
  }

  void _showDailyTaskCompletedPopup() {
    showDialog<void>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: const Color(0xFF5A5D63),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(18),
          side: BorderSide(color: AppTheme.adaptiveWhite(alpha: .28)),
        ),
        title: Center(
          child: Text(
            'DAILY TASK COMPLETED Ã°Å¸Å½â€°',
            textAlign: TextAlign.center,
            style: TextStyle(
              color: AppTheme.textPrimary,
              fontWeight: FontWeight.w900,
              fontSize: 16,
            ),
          ),
        ),
        content: Text(
          'Enjoy and come back tomorrow. Ã¢Å“Â¨\n\nDo not overtrade. Ã°Å¸â€ºÂ¡Ã¯Â¸ÂÃ°Å¸â€œË†\nYou completed today\'s task Ã¢â‚¬â€ protect your progress and let tomorrow be tomorrow.',
          textAlign: TextAlign.center,
          style: TextStyle(
            color: AppTheme.textPrimary,
            fontSize: 13,
            height: 1.5,
            fontWeight: FontWeight.w700,
          ),
        ),
        actionsAlignment: MainAxisAlignment.center,
        actions: [
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('ENJOY THE WIN Ã¢Å“Â¨'),
          ),
        ],
      ),
    );
  }

  Future<void> _setup() async {
    if ((today['status'] ?? '') == 'TASK COMPLETED') {
      _showDailyTaskCompletedPopup();
      return;
    }
    final result = await showDialog<Map<String, double>>(
      context: context,
      builder: (_) => const _TaskSetupDialog(),
    );
    if (result == null) return;
    final u = FirebaseAuth.instance.currentUser;
    if (u == null) return;
    final plan = TradingJournalService.calculatePlan(result);
    final all = <String, dynamic>{...result, ...plan};
    await TradingJournalService.saveTaskSettings(u.uid, all);
    await TradingJournalService.syncTodayTask(u.uid, all);
    await _load();
  }

  Future<void> _saveActual() async {
    final u = FirebaseAuth.instance.currentUser;
    if (u == null) return;
    final v = double.tryParse(actual.text.trim());
    if (v == null) return;
    try {
      await TradingJournalService.saveTodayProfit(u.uid, v);
      if (!mounted) return;
      actual.clear();
      await _load();
    } catch (_) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text("Could not save today's result. Please try again."),
          ),
        );
    }
  }

  Future<void> _saveManual() async {
    final u = FirebaseAuth.instance.currentUser;
    if (u == null) return;
    final v = double.tryParse(manual.text.trim());
    if (v == null || !v.isFinite) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Enter a valid profit or loss amount.')),
        );
      return;
    }
    try {
      await TradingJournalService.saveManualProfit(u.uid, v);
      if (!mounted) return;
      manual.clear();
      await _load();
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Could not save Manual Entry Profit. Please try again.',
            ),
          ),
        );
    }
  }

  Future<void> _editManualProfit(double currentValue) async {
    final controller = TextEditingController(
      text: currentValue.toStringAsFixed(2),
    );
    final value = await showDialog<double>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: AppTheme.adaptiveSurface(Color(0xFF101419)),
        title: const Text(
          'EDIT PERSONAL PROFIT',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
        content: TextField(
          controller: controller,
          autofocus: true,
          keyboardType: const TextInputType.numberWithOptions(
            decimal: true,
            signed: true,
          ),
          decoration: const InputDecoration(labelText: 'Profit / Loss (USDT)'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('CANCEL'),
          ),
          FilledButton(
            onPressed: () {
              final v = double.tryParse(controller.text.trim());
              if (v != null) Navigator.pop(dialogContext, v);
            },
            child: const Text('SAVE'),
          ),
        ],
      ),
    );
    controller.dispose();
    if (value == null || !mounted) return;
    final u = FirebaseAuth.instance.currentUser;
    if (u == null || !value.isFinite) return;
    try {
      await TradingJournalService.saveManualProfit(u.uid, value);
      if (mounted) await _load();
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Could not save Manual Entry Profit. Please try again.',
            ),
          ),
        );
    }
  }

  @override
  Widget build(BuildContext context) {
    final dailyTarget =
        (today['dailyTargetPct'] as num?)?.toDouble() ??
        (settings['dailyTargetPct'] as num?)?.toDouble() ??
        0;
    final targetUsd =
        (today['dailyTargetUsd'] as num?)?.toDouble() ??
        (settings['dailyTargetUsd'] as num?)?.toDouble() ??
        0;
    final actualValue = (today['actualProfitUsd'] as num?)?.toDouble();
    final done =
        actualValue != null &&
        actualValue
                .toStringAsFixed(2)
                .compareTo(targetUsd.toStringAsFixed(2)) >=
            0;
    double dayValue(Map<String, dynamic> d) =>
        ((d['actualProfitUsd'] ?? d['manualProfitUsd']) as num?)?.toDouble() ??
        0;
    final now = DateTime.now();
    final calendarTradingDays = DateTime(now.year, now.month + 1, 0).day;
    final tradedDays =
        history.where((d) {
          final x = DateTime.tryParse((d['date'] ?? '').toString());
          return x != null &&
              x.year == now.year &&
              x.month == now.month &&
              (d['actualProfitUsd'] != null || d['manualProfitUsd'] != null);
        }).length +
        ((today['actualProfitUsd'] != null ||
                    today['manualProfitUsd'] != null) &&
