class _PersonalCalendar extends StatelessWidget {
  final List<Map<String, dynamic>> history;
  const _PersonalCalendar({required this.history});

  @override
  Widget build(BuildContext context) {
    final by = <String, Map<String, dynamic>>{};
    for (final d in history) {
      by[(d['date'] ?? '').toString()] = d;
    }
    final now = DateTime.now();
    final days = DateTime(now.year, now.month + 1, 0).day;
    return GridView.builder(
      shrinkWrap: true,
      physics: const NeverScrollableScrollPhysics(),
      itemCount: days,
      gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: 7,
        crossAxisSpacing: 5,
        mainAxisSpacing: 5,
        childAspectRatio: .86,
      ),
      itemBuilder: (_, i) {
        final day = i + 1;
        final key =
            '${now.year}-${now.month.toString().padLeft(2, '0')}-${day.toString().padLeft(2, '0')}';
        final d = by[key];
        final profit = d == null
            ? null
            : ((d['actualProfitUsd'] ?? d['manualProfitUsd']) as num?)
                  ?.toDouble();
        final active = d != null;
        final profitColor = profit == null
            ? AppTheme.textMuted
            : profit >= 0
            ? const Color(0xFF39E75F)
            : const Color(0xFFE05252);
        return InkWell(
          onTap: active
              ? () => showDialog<void>(
                  context: context,
                  builder: (_) => AlertDialog(
                    backgroundColor: AppTheme.adaptiveSurface(
                      Color(0xFF101419),
                    ),
                    title: Text(key),
                    content: Text(
                      'Daily Target: ${(d['dailyTargetUsd'] ?? 0)} USDT\nActual Profit: ${(d['actualProfitUsd'] ?? d['manualProfitUsd'] ?? 0)} USDT\nStatus: ${(d['status'] ?? 'No result')}',
                    ),
                    actions: [
                      TextButton(
                        onPressed: () => Navigator.pop(context),
                        child: const Text('CLOSE'),
                      ),
                    ],
                  ),
                )
              : null,
          borderRadius: BorderRadius.circular(7),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 2, vertical: 4),
            decoration: BoxDecoration(
              color: active
                  ? profitColor.withValues(alpha: .08)
                  : AppTheme.adaptiveSurface(Color(0xFF202228)),
              borderRadius: BorderRadius.circular(7),
              border: Border.all(
                color: active
                    ? profitColor.withValues(alpha: .40)
                    : AppTheme.fillFaint,
              ),
            ),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Text(
                  '$day',
                  style: TextStyle(
                    color: active ? profitColor : AppTheme.textMuted,
                    fontWeight: FontWeight.w800,
                    fontSize: 9,
                  ),
                ),
                if (profit != null) ...[
                  const SizedBox(height: 3),
                  FittedBox(
                    child: Text(
                      '${profit >= 0 ? '+' : ''}${profit.toStringAsFixed(2)}',
                      style: TextStyle(
                        color: profitColor,
                        fontWeight: FontWeight.w900,
                        fontSize: 8,
                      ),
                    ),
                  ),
                  const SizedBox(height: 1),
                  Text(
                    'USDT',
                    style: TextStyle(
                      color: AppTheme.textFaint,
                      fontSize: 6,
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                ],
              ],
            ),
          ),
        );
      },
    );
  }
}

