class MentorshipPage extends StatefulWidget {
  final bool isAdmin;
  const MentorshipPage({super.key, this.isAdmin = false});

  @override
  State<MentorshipPage> createState() => _MentorshipPageState();
}

class _MentorshipPageState extends State<MentorshipPage> {
  bool _loading = true;
  bool _student = false;
  String _selectedPlan = '';
  String _paymentStatus = '';
  int _paidWeeks = 0;
  DateTime? _nextInstallmentDueAt;
  DateTime? _installmentGraceEndsAt;
  bool _mentorshipPaymentLocked = false;
  String _installmentNotice = '';
  List<QueryDocumentSnapshot<Map<String, dynamic>>> _lessons = [];
  List<QueryDocumentSnapshot<Map<String, dynamic>>> _schedules = [];
  List<QueryDocumentSnapshot<Map<String, dynamic>>> _students = [];

  static const _oneTime = 'one_time';
  static const _installment = 'installment';

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final uid = AuthService.currentUser?.uid;
    if (uid == null) {
      if (mounted) setState(() => _loading = false);
      return;
    }
    try {
      final data = await MentorshipService.loadMyMentorship(uid) ?? {};
      _student =
          data['mentorshipApproved'] == true ||
          data['studentApproved'] == true ||
          data['isStudent'] == true;
      _selectedPlan = (data['mentorshipPaymentPlan'] ?? '').toString();
      _paymentStatus = (data['mentorshipPaymentStatus'] ?? '').toString();
      _paidWeeks = (data['installmentPaidWeeks'] as num?)?.toInt() ?? 0;
      _nextInstallmentDueAt = data['installmentNextDueAt'] is Timestamp
          ? (data['installmentNextDueAt'] as Timestamp).toDate()
          : null;
      _installmentGraceEndsAt = data['installmentGraceEndsAt'] is Timestamp
          ? (data['installmentGraceEndsAt'] as Timestamp).toDate()
          : null;
      _mentorshipPaymentLocked = false;
      _installmentNotice = '';
      if (_student && !_mentorshipPaymentLocked && !widget.isAdmin) {
        try {
          final name =
              (data['displayName'] ??
                      data['name'] ??
                      AuthService.currentUser?.displayName ??
                      'Mentorship Student')
                  .toString();
          await MentorshipService.ensureChatMember(uid: uid, name: name);
        } catch (_) {}
      }
      if (_student && _selectedPlan == _installment) {
        final now = DateTime.now();
        if (_paidWeeks >= 4) {
          _paymentStatus = 'completed';
        } else if (_installmentGraceEndsAt == null) {
          _mentorshipPaymentLocked = true;
          _installmentNotice = 'Your first installment payment is required to unlock Mentorship.';
        } else if (now.isAfter(_installmentGraceEndsAt!)) {
          _mentorshipPaymentLocked = true;
          _paymentStatus = 'overdue';
          _installmentNotice = 'Your 24-hour payment grace period has expired. Mentorship is locked until the next installment is paid.';
        } else if (_nextInstallmentDueAt != null &&
            now.isAfter(_nextInstallmentDueAt!)) {
          final remaining = _installmentGraceEndsAt!.difference(now);
          _paymentStatus = 'warning';
          _installmentNotice =
              'Your next \$20 installment is due. You have ${remaining.inHours.clamp(0, 24)} hours remaining before Mentorship locks.';
        }
      }
      _lessons = widget.isAdmin ? await MentorshipService.loadLessons() : [];
      if (widget.isAdmin) {
        _students = await MentorshipService.loadStudents();
        _schedules = await MentorshipService.loadSchedules();
      } else if (_student) {
        _schedules = await MentorshipService.loadSchedules(studentUid: uid);
      }
    } catch (_) {}
    if (mounted) {
      setState(() => _loading = false);
      if (_paymentStatus == 'warning' && _installmentNotice.isNotEmpty) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted) return;
          showDialog<void>(
            context: context,
            builder: (_) => AlertDialog(
              backgroundColor: AppTheme.adaptiveSurface(Color(0xFF101419)),
              title: const Text(
                'INSTALLMENT PAYMENT WARNING',
                style: TextStyle(fontWeight: FontWeight.w900),
              ),
              content: Text(_installmentNotice),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(context),
                  child: const Text('OK'),
                ),
              ],
            ),
          );
        });
      }
    }
  }

  Future<void> _choosePlan(String plan) async {
    final uid = AuthService.currentUser?.uid;
    if (uid == null) return;
    try {
      await MentorshipService.choosePaymentPlan(uid: uid, plan: plan);
      if (mounted) {
        setState(() {
          _selectedPlan = plan;
          _paymentStatus = 'selected';
        });
        if (mounted) {
          final paymentPlanId = plan == _oneTime
              ? 'mentorship_one_time'
              : 'mentorship_installment';
          await Navigator.push(
            context,
            MaterialPageRoute(
              builder: (_) => CentralPaymentPage(
                product: 'mentorship',
                planId: paymentPlanId,
              ),
            ),
          );
        }
      }
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not save payment plan: $e')),
        );
    }
  }

  Future<void> _lessonEditor({int? number}) async {
    final n = number ?? ((_lessons.length + 1).clamp(1, 99));
    final existing = _lessons
        .where((d) => (d.data()['sessionNumber'] as num?)?.toInt() == n)
        .firstOrNull;
    final data = existing?.data() ?? <String, dynamic>{};
    final title = TextEditingController(
      text: (data['title'] ?? 'Session $n').toString(),
    );
    final content = TextEditingController();
    final video = TextEditingController();
    bool published = data['isPublished'] != false;
    if (existing != null) {
      try {
        final details = await MentorshipService.loadLessonContent(existing.id);
        content.text = (details?['content'] ?? '').toString();
        video.text = (details?['videoUrl'] ?? '').toString();
      } catch (_) {}
    }
    if (!mounted) return;
    final save = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          backgroundColor: AppTheme.adaptiveSurface(Color(0xFF101419)),
          title: Text(
