  Future<void> _scheduleEditor({
    QueryDocumentSnapshot<Map<String, dynamic>>? existing,
  }) async {
    final d = existing?.data() ?? <String, dynamic>{};
    final students = _students
        .where((x) => x.data()['status'] == 'approved')
        .toList();
    if (students.isEmpty) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Approve a Mentorship student first.')),
        );
      return;
    }
    String studentUid = (d['studentUid'] ?? students.first.id).toString();
    String studentName = (d['studentName'] ?? '').toString();
    String country = (d['country'] ?? '').toString();
    String timezone = (d['timezone'] ?? '').toString();
    String details = (d['details'] ?? '').toString();
    String meet = (d['meetUrl'] ?? '').toString();
    DateTime when = (d['scheduledAt'] is Timestamp)
        ? (d['scheduledAt'] as Timestamp).toDate()
        : DateTime.now().add(const Duration(hours: 1));
    final name = TextEditingController(text: studentName);
    final countryC = TextEditingController(text: country);
    final zone = TextEditingController(text: timezone);
    final info = TextEditingController(text: details);
    final meetC = TextEditingController(text: meet);
    String selectedUid = studentUid;
    final ok = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          backgroundColor: AppTheme.adaptiveSurface(Color(0xFF101419)),
          title: const Text(
            'PRIVATE STUDENT CLASS',
            style: TextStyle(fontWeight: FontWeight.w900),
          ),
          content: SingleChildScrollView(
            child: Column(
              children: [
                DropdownButtonFormField<String>(
                  initialValue: selectedUid,
                  items: [
                    for (final s in students)
                      DropdownMenuItem(
                        value: s.id,
                        child: Text((s.data()['name'] ?? s.id).toString()),
                      ),
                  ],
                  onChanged: (v) {
                    if (v != null) {
                      setDialogState(() {
                        selectedUid = v;
                        name.text =
                            (students
                                        .firstWhere((s) => s.id == v)
                                        .data()['name'] ??
                                    '')
                                .toString();
                      });
                    }
                  },
                  decoration: const InputDecoration(labelText: 'Student'),
                ),
                TextField(
                  controller: name,
                  decoration: const InputDecoration(labelText: 'Student name'),
                ),
                TextField(
                  controller: countryC,
                  decoration: const InputDecoration(labelText: 'Country'),
                ),
                TextField(
                  controller: zone,
                  decoration: const InputDecoration(labelText: 'Timezone'),
                ),
                const SizedBox(height: 8),
                ListTile(
                  contentPadding: EdgeInsets.zero,
                  title: Text('Class time: ${when.toLocal()}'),
                  trailing: const Icon(Icons.schedule_rounded),
                  onTap: () async {
                    final date = await showDatePicker(
                      context: context,
                      initialDate: when,
                      firstDate: DateTime.now().subtract(
                        const Duration(days: 1),
                      ),
                      lastDate: DateTime.now().add(const Duration(days: 365)),
                    );
                    if (date == null || !context.mounted) return;
                    final time = await showTimePicker(
                      context: context,
                      initialTime: TimeOfDay.fromDateTime(when),
                    );
                    if (time != null)
                      setDialogState(
                        () => when = DateTime(
                          date.year,
                          date.month,
                          date.day,
                          time.hour,
                          time.minute,
                        ),
                      );
                  },
                ),
                TextField(
                  controller: info,
                  minLines: 2,
                  maxLines: 5,
                  decoration: const InputDecoration(
                    labelText: 'Live class details',
                  ),
                ),
                TextField(
                  controller: meetC,
                  decoration: const InputDecoration(
                    labelText: 'Google Meet link',
                  ),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('CANCEL'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('SAVE SCHEDULE'),
            ),
          ],
        ),
      ),
    );
    if (ok != true) return;
    try {
      await MentorshipService.saveSchedule(
        id: existing?.id ?? '',
        studentUid: selectedUid,
        studentName: name.text,
        country: countryC.text,
        timezone: zone.text,
        classDateTime: when,
        details: info.text,
        meetUrl: meetC.text,
      );
      await _load();
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Could not save schedule: $e')));
    }
  }

