  void _showAdminPayments() {
    showModalBottomSheet<void>(
      context: context,
      backgroundColor: AppTheme.adaptiveSurface(Color(0xFF0B0F11)),
      isScrollControlled: true,
      builder: (_) =>
          FutureBuilder<List<QueryDocumentSnapshot<Map<String, dynamic>>>>(
            future: FirebaseFirestore.instance
                .collection('mentorshipPayments')
                .get()
                .then((s) => s.docs),
            builder: (context, snap) {
              final docs = snap.data ?? [];
              return ListView(
                padding: const EdgeInsets.all(16),
                children: [
                  const Text(
                    'MENTORSHIP PAYMENTS',
                    style: TextStyle(fontSize: 18, fontWeight: FontWeight.w900),
                  ),
                  const SizedBox(height: 10),
                  for (final d in docs) _adminPaymentTile(d),
                ],
              );
            },
          ),
    );
  }

  Widget _adminPaymentTile(QueryDocumentSnapshot<Map<String, dynamic>> d) {
    final data = d.data();
    final plan = (data['plan'] ?? '').toString();
    final paidWeeks = (data['paidWeeks'] as num?)?.toInt() ?? 0;
    final status = (data['paymentStatus'] ?? '').toString();
    return Card(
      color: AppTheme.adaptiveSurface(Color(0xFF12171A)),
      child: ListTile(
        title: Text(d.id, style: const TextStyle(fontWeight: FontWeight.w800)),
        subtitle: Text(
          '$plan Ã¢â‚¬Â¢ $status${plan == _installment ? ' Ã¢â‚¬Â¢ $paidWeeks/4 paid' : ''}',
        ),
        trailing: plan == _installment && paidWeeks < 4
            ? FilledButton(
                onPressed: () async {
                  try {
                    await MentorshipService.adminRecordInstallmentPayment(d.id);
                    if (mounted) {
                      Navigator.pop(context);
                      await _load();
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(
                          content: Text(
                            'Installment marked as paid. The next 7-day period has started.',
                          ),
                        ),
                      );
                    }
                  } catch (e) {
                    if (mounted)
                      ScaffoldMessenger.of(context).showSnackBar(
                        SnackBar(content: Text('Could not record payment: $e')),
                      );
                  }
                },
                child: const Text('MARK PAID'),
              )
            : Text('\$${data['totalAmount'] ?? ''}'),
      ),
    );
  }

