  Future<void> _openMentorshipArea(
    String category,
    String title, {
    bool openEditor = false,
  }) async {
    try {
      final items = await MentorshipService.loadCategoryContent(category);
      if (!mounted) return;
      await Navigator.push(
        context,
        MaterialPageRoute(
          builder: (_) => _MentorshipAreaPage(
            category: category,
            title: title,
            items: items,
            isAdmin: widget.isAdmin,
            isStudent: _student,
            paymentLocked: _mentorshipPaymentLocked,
            openEditor: openEditor,
          ),
        ),
      );
      await _load();
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text('Could not open $title: $e')));
    }
  }

