class _MentorshipAreaPage extends StatefulWidget {
  final String category;
  final String title;
  final List<QueryDocumentSnapshot<Map<String, dynamic>>> items;
  final bool isAdmin;
  final bool isStudent;
  final bool paymentLocked;
  final bool openEditor;
  const _MentorshipAreaPage({
    required this.category,
    required this.title,
    required this.items,
    required this.isAdmin,
    required this.isStudent,
    this.paymentLocked = false,
    this.openEditor = false,
  });
  @override
  State<_MentorshipAreaPage> createState() => _MentorshipAreaPageState();
}

class _MentorshipAreaPageState extends State<_MentorshipAreaPage> {
  late List<QueryDocumentSnapshot<Map<String, dynamic>>> _items;

  @override
  void initState() {
    super.initState();
    _items = [...widget.items];
    if (widget.openEditor && widget.isAdmin) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _editor();
      });
    }
  }

  Future<void> _refresh() async {
    final items = await MentorshipService.loadCategoryContent(widget.category);
    if (mounted) setState(() => _items = items);
  }

  Future<void> _editor({int? number}) async {
    final n = number ?? ((_items.length + 1).clamp(1, 25));
    final existing = _items
        .where((d) => (d.data()['contentNumber'] as num?)?.toInt() == n)
        .firstOrNull;
    final data = existing?.data() ?? <String, dynamic>{};
    final title = TextEditingController(
      text: (data['title'] ?? '${widget.title} $n').toString(),
    );
    final notes = TextEditingController();
    final video = TextEditingController();
    List<Map<String, dynamic>> pdfFiles = [];
    List<Map<String, dynamic>> imageFiles = [];
    final imagePreviewBytes = <String, Uint8List>{};
    bool published = data['isPublished'] != false;
    if (existing != null) {
      final details =
          await MentorshipService.loadLessonContent(existing.id) ?? {};
      notes.text = (details['notes'] ?? details['content'] ?? '').toString();
      video.text = (details['videoUrl'] ?? '').toString();
      pdfFiles = ((details['pdfFiles'] as List?) ?? [])
          .whereType<Map>()
          .map((e) => Map<String, dynamic>.from(e))
          .toList();
      imageFiles = ((details['imageFiles'] as List?) ?? [])
          .whereType<Map>()
          .map((e) => Map<String, dynamic>.from(e))
          .toList();
    }
    if (!mounted) return;
    final save = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          backgroundColor: AppTheme.adaptiveSurface(Color(0xFF101419)),
          title: Text(
            'MANAGE ${widget.title} $n',
            style: const TextStyle(fontWeight: FontWeight.w900),
          ),
          content: SingleChildScrollView(
            child: Column(
              children: [
                TextField(
                  controller: title,
                  decoration: const InputDecoration(
                    labelText: 'Title / heading',
                  ),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: notes,
                  minLines: 5,
                  maxLines: 12,
                  decoration: InputDecoration(
                    labelText: widget.category == 'lectures'
                        ? 'Notes / video summary'
                        : 'Written task / class notes',
                  ),
                ),
                if (widget.category != 'assignments') ...[
                  const SizedBox(height: 10),
                  TextField(
                    controller: video,
                    decoration: const InputDecoration(
                      labelText: 'External video URL (optional)',
                    ),
                  ),
                ],
                const SizedBox(height: 12),
                if (widget.category != 'lectures')
                  FilledButton.icon(
                    onPressed: () async {
                      try {
                        final picked = await FilePicker.pickFiles(
                          type: FileType.custom,
                          allowedExtensions: ['pdf'],
                        );
                        if (picked.isEmpty) return;
                        final f = picked.first;
                        final bytes = await f.readAsBytes();
                        final path =
                            await MentorshipService.uploadMentorshipFile(
                              category: widget.category,
                              contentId: MentorshipService.contentDocId(
                                widget.category,
                                n,
                              ),
                              fileName: f.name,
                              bytes: bytes,
                              contentType: 'application/pdf',
                            );
                        setDialogState(
                          () => pdfFiles.add({'name': f.name, 'path': path}),
                        );
                      } catch (e) {
                        if (context.mounted)
                          ScaffoldMessenger.of(context).showSnackBar(
                            SnackBar(content: Text('PDF upload failed: $e')),
                          );
                      }
                    },
                    icon: const Icon(Icons.picture_as_pdf_rounded),
                    label: const Text('ADD PDF'),
                  ),
                if (widget.category != 'lectures' && pdfFiles.isNotEmpty) ...[
                  const SizedBox(height: 6),
                  for (final f in pdfFiles)
                    ListTile(
                      contentPadding: EdgeInsets.zero,
                      dense: true,
                      leading: Icon(
                        Icons.picture_as_pdf,
                        color: AppTheme.textPrimary,
                      ),
                      title: Text((f['name'] ?? 'PDF').toString()),
                      trailing: IconButton(
                        onPressed: () =>
                            setDialogState(() => pdfFiles.remove(f)),
                        icon: Icon(Icons.close, color: AppTheme.textMuted),
                      ),
                    ),
                ],
                FilledButton.icon(
                  onPressed: () async {
                    try {
                      final picked = await FilePicker.pickFiles(
                        type: FileType.image,
                      );
                      if (picked.isEmpty) return;
                      final f = picked.first;
                      final bytes = await f.readAsBytes();
                      if (bytes.isEmpty)
                        throw StateError(
                          'The selected picture could not be read.',
                        );
                      final ext = (f.extension ?? 'jpeg').toLowerCase();
                      final mime = ext == 'png'
                          ? 'image/png'
                          : ext == 'webp'
                          ? 'image/webp'
                          : ext == 'gif'
                          ? 'image/gif'
                          : 'image/jpeg';
                      final path = await MentorshipService.uploadMentorshipFile(
                        category: widget.category,
                        contentId: MentorshipService.contentDocId(
                          widget.category,
                          n,
                        ),
                        fileName: f.name,
                        bytes: bytes,
                        contentType: mime,
                      );
                      setDialogState(() {
                        imageFiles.add({'name': f.name, 'path': path});
                        imagePreviewBytes[path] = Uint8List.fromList(bytes);
                      });
                    } catch (e) {
                      if (context.mounted)
                        ScaffoldMessenger.of(context).showSnackBar(
                          SnackBar(content: Text('Picture upload failed: $e')),
                        );
                    }
                  },
                  icon: const Icon(Icons.image_rounded),
                  label: const Text('ADD PICTURE'),
                ),
                if (imageFiles.isNotEmpty) ...[
                  const SizedBox(height: 6),
                  for (final f in imageFiles) ...[
                    if (imagePreviewBytes[(f['path'] ?? '').toString()] != null)
                      Padding(
                        padding: const EdgeInsets.only(bottom: 6),
                        child: ClipRRect(
                          borderRadius: BorderRadius.circular(10),
                          child: Image.memory(
                            imagePreviewBytes[(f['path'] ?? '').toString()]!,
                            height: 120,
                            width: double.infinity,
                            fit: BoxFit.cover,
                          ),
                        ),
                      ),
                    ListTile(
                      contentPadding: EdgeInsets.zero,
                      dense: true,
                      leading: Icon(Icons.image, color: AppTheme.textPrimary),
                      title: Text((f['name'] ?? 'Picture').toString()),
                      trailing: IconButton(
                        onPressed: () => setDialogState(() {
                          imagePreviewBytes.remove(
                            (f['path'] ?? '').toString(),
                          );
                          imageFiles.remove(f);
                        }),
                        icon: Icon(Icons.close, color: AppTheme.textMuted),
                      ),
                    ),
                  ],
                ],
                const SizedBox(height: 8),
                SwitchListTile(
                  value: published,
                  onChanged: (v) => setDialogState(() => published = v),
                  title: const Text('Published'),
                  contentPadding: EdgeInsets.zero,
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('CANCEL'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('SAVE'),
            ),
          ],
        ),
      ),
    );
    if (save != true) return;
    try {
      await MentorshipService.saveCategoryContent(
        category: widget.category,
        number: n,
        title: title.text,
        notes: notes.text,
        videoUrl: video.text,
        published: published,
        pdfFiles: pdfFiles,
        imageFiles: imageFiles,
      );
      await _refresh();
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Could not save content: $e')));
    }
  }

  Future<void> _openItem(
    QueryDocumentSnapshot<Map<String, dynamic>> item,
  ) async {
    final details = await MentorshipService.loadLessonContent(item.id) ?? {};
    if (!mounted) return;
    final video = (details['videoUrl'] ?? '').toString().trim();
    final notes =
        (details['notes'] ?? details['content'] ?? 'No notes uploaded yet.')
            .toString();
    final pdfFiles = ((details['pdfFiles'] as List?) ?? [])
        .whereType<Map>()
        .map((e) => Map<String, dynamic>.from(e))
        .toList();
    final imageFiles = ((details['imageFiles'] as List?) ?? [])
        .whereType<Map>()
        .map((e) => Map<String, dynamic>.from(e))
        .toList();
    showDialog<void>(
      context: context,
      builder: (_) => AlertDialog(
        backgroundColor: AppTheme.adaptiveSurface(Color(0xFF101419)),
        title: Text((item.data()['title'] ?? 'Content').toString()),
        content: SingleChildScrollView(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                notes,
                style: TextStyle(color: AppTheme.textPrimary, height: 1.4),
              ),
              if (video.isNotEmpty) ...[
                const SizedBox(height: 16),
                Text(
                  'VIDEO',
                  style: TextStyle(
                    color: AppTheme.textSecondary,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 6),
                FilledButton.icon(
                  onPressed: () async {
                    final uri = Uri.tryParse(video);
                    if (uri == null) {
                      if (!context.mounted) return;
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(
                          content: Text('Could not open video URL.'),
                        ),
                      );
                      return;
                    }
                    final opened = await launchUrl(
                      uri,
                      mode: LaunchMode.externalApplication,
                    );
                    if (!context.mounted) return;
                    if (!opened)
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(
                          content: Text('Could not open video URL.'),
                        ),
                      );
                  },
                  icon: const Icon(Icons.play_circle_fill_rounded),
                  label: const Text('OPEN VIDEO'),
                ),
              ],
              if (pdfFiles.isNotEmpty) ...[
                const SizedBox(height: 16),
                Text(
                  'PDF FILES',
                  style: TextStyle(
                    color: AppTheme.textSecondary,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                for (final f in pdfFiles)
                  ListTile(
                    contentPadding: EdgeInsets.zero,
                    leading: Icon(
                      Icons.picture_as_pdf,
                      color: AppTheme.textPrimary,
                    ),
                    title: Text((f['name'] ?? 'PDF').toString()),
                    onTap: () => _openPdf(
                      (f['path'] ?? '').toString(),
                      (f['name'] ?? 'PDF').toString(),
                    ),
                  ),
              ],
              if (imageFiles.isNotEmpty) ...[
                const SizedBox(height: 16),
                Text(
                  'PICTURES',
                  style: TextStyle(
                    color: AppTheme.textSecondary,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 8),
                for (final f in imageFiles)
                  _MentorshipImageThumb(
                    path: (f['path'] ?? '').toString(),
                    name: (f['name'] ?? 'Picture').toString(),
                  ),
              ],
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('CLOSE'),
          ),
        ],
      ),
    );
  }

  Future<void> _openPdf(String path, String name) async {
    if (path.trim().isEmpty) return;
    try {
      final bytes = await MentorshipService.downloadMentorshipFile(path);
      if (!mounted) return;
      await Navigator.push(
        context,
        MaterialPageRoute(
          builder: (_) => Scaffold(
            appBar: AppBar(title: Text(name)),
            body: SfPdfViewer.memory(bytes),
          ),
        ),
      );
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context)
            .showSnackBar(SnackBar(content: Text('Could not open PDF: $e')));
    }
  }

  @override
  Widget build(BuildContext context) {
    final unlocked =
        widget.isAdmin || (widget.isStudent && !widget.paymentLocked);
    return Scaffold(
      appBar: AppBar(
        title: Text(widget.title),
        actions: [
          if (widget.isAdmin)
            IconButton(
              tooltip: 'Add content',
              onPressed: () => _editor(),
              icon: Icon(Icons.add_rounded, color: AppTheme.textPrimary),
            ),
        ],
      ),
      body: RefreshIndicator(
        onRefresh: _refresh,
        child: GridView.builder(
          padding: const EdgeInsets.all(16),
          physics: const AlwaysScrollableScrollPhysics(),
          gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
            crossAxisCount: 2,
            crossAxisSpacing: 10,
            mainAxisSpacing: 10,
            childAspectRatio: 0.88,
          ),
          itemCount: 25,
          itemBuilder: (context, index) {
            final n = index + 1;
            final doc = _items
                .where((d) => (d.data()['contentNumber'] as num?)?.toInt() == n)
                .firstOrNull;
            final title = (doc?.data()['title'] ?? '${widget.title} $n')
                .toString();
            final published = doc?.data()['isPublished'] != false;
            final canOpen = unlocked && published;
            final Widget adminButton = widget.isAdmin
                ? Positioned(
                    top: 6,
                    right: 6,
                    child: _JellyPlusButton(
                      color: AppTheme.textPrimary,
                      tooltip: 'Upload content',
                      onPressed: () => _editor(number: n),
                    ),
                  )
                : const SizedBox.shrink();

            return InkWell(
              onTap: canOpen && doc != null ? () => _openItem(doc) : null,
              borderRadius: BorderRadius.circular(16),
              child: ClipRRect(
                borderRadius: BorderRadius.circular(16),
                child: Stack(
                  children: [
                    ImageFiltered(
                      imageFilter: ui.ImageFilter.blur(
                        sigmaX: canOpen ? 0 : 0.65,
                        sigmaY: canOpen ? 0 : 0.65,
                      ),
                      child: GlassCard(
                        child: Padding(
                          padding: const EdgeInsets.all(13),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Icon(
                                widget.category == 'lectures'
                                    ? Icons.play_circle_fill_rounded
                                    : Icons.menu_book_rounded,
                                color: AppTheme.textPrimary,
                                size: 28,
                              ),
                              const Spacer(),
                              Text(
                                title,
                                style: TextStyle(
                                  color: AppTheme.textPrimary,
                                  fontWeight: FontWeight.w900,
                                  fontSize: 12,
                                ),
                              ),
                              const SizedBox(height: 4),
                              Text(
                                doc == null
                                    ? 'Coming soon'
                                    : (published
                                          ? (unlocked
                                                ? 'Open content'
                                                : 'Locked')
                                          : 'Coming soon'),
                                style: TextStyle(
                                  color: AppTheme.textMuted,
                                  fontSize: 9,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                    // The four category cards are the only lock surface. Admins and approved students never see a lock inside the content page.
                    adminButton,
                  ],
                ),
              ),
            );
          },
        ),
      ),
    );
  }
}

