class _MentorshipPaymentPlansPage extends StatelessWidget {
  const _MentorshipPaymentPlansPage();

  Future<void> _selectPlan(BuildContext context, String plan) async {
    final uid = AuthService.currentUser?.uid;
    if (uid == null) return;
    try {
      await MentorshipService.choosePaymentPlan(uid: uid, plan: plan);
      if (!context.mounted) return;
      final paymentPlanId = plan == 'one_time'
          ? 'mentorship_one_time'
          : 'mentorship_installment';
      await Navigator.push(
        context,
        MaterialPageRoute(
          builder: (_) =>
              CentralPaymentPage(product: 'mentorship', planId: paymentPlanId),
        ),
      );
    } catch (e) {
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not save payment plan: $e')),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('MENTORSHIP PAYMENT')),
      body: ListView(
        padding: const EdgeInsets.fromLTRB(16, 14, 16, 28),
        children: [
          GlassCard(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'CHOOSE YOUR MENTORSHIP PLAN',
                  style: TextStyle(
