class ProfilePage extends StatefulWidget {
  const ProfilePage({super.key});

  @override
  State<ProfilePage> createState() => _ProfilePageState();
}

class _ProfilePageState extends State<ProfilePage> {
  String _displayName = '';
  Uint8List? _appAvatarBytes;
  bool _loading = true;
  bool _isPremium = false;
  bool _hasMentorship = false;
  String _premiumBadgeType = '';
  String _mentorshipBadgeType = '';
  bool _graduated = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final user = AuthService.currentUser;
    if (user == null) {
      if (mounted) setState(() => _loading = false);
      return;
    }
    try {
      final data = await ProfileService.loadUserProfile(user.uid);
      _displayName = (data?['displayName'] ?? '').toString().trim();
      _isPremium = _isActivePremiumUserData(data);
      _hasMentorship =
          data?['mentorshipApproved'] == true ||
          data?['isMentorship'] == true ||
          data?['mentorship'] == true ||
          data?['studentApproved'] == true ||
          data?['isStudent'] == true;
      _premiumBadgeType = (data?['confirmedPremiumBadgeType'] ?? '').toString();
      _mentorshipBadgeType = (data?['confirmedMentorshipBadgeType'] ?? '')
          .toString();
      _graduated = data?['graduated'] == true;
      final appAvatar = ((data?['appAvatarBase64'] ?? '').toString().isNotEmpty)
          ? (data?['appAvatarBase64'] ?? '').toString()
          : await ProfileService.loadAppAvatar(uid: user.uid);
      if (appAvatar.isNotEmpty) {
        try {
          _appAvatarBytes = base64Decode(appAvatar);
        } catch (_) {}
      }
    } catch (_) {}
    if (mounted) setState(() => _loading = false);
  }

  Future<void> _openEditProfile() async {
    await Navigator.of(context)
        .push(MaterialPageRoute(builder: (_) => const _EditProfilePage()));
    if (mounted) await _load();
  }

  Future<void> _openReferral() async {
    await Navigator.of(context)
        .push(MaterialPageRoute(builder: (_) => const _ReferralCenterPage()));
  }

  Future<void> _openPaymentDetails() async {
    await Navigator.of(context).push(
      MaterialPageRoute(builder: (_) => const _UserPayoutPaymentDetailsPage()),
    );
  }

  Future<void> _logoutProfile() async {
    final shouldLogout = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: Theme.of(context).cardColor,
        title: const Text('LOG OUT'),
        content: const Text(
          'Are you sure you want to log out of CRYPTO-DOCTORS-HUB?',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('CANCEL'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFFB83A3A),
              foregroundColor: AppTheme.textPrimary,
              minimumSize: const Size(110, 44),
            ),
            child: const Text('LOG OUT'),
          ),
        ],
      ),
    );
    if (shouldLogout != true) return;
    try {
      await AuthService.signOut();
    } catch (_) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'We could not log you out right now. Please try again.',
            ),
          ),
        );
      return;
    }
    if (!mounted) return;
    Navigator.pushAndRemoveUntil(
      context,
      MaterialPageRoute(builder: (_) => const LoginScreen()),
      (route) => false,
    );
  }

  Widget _option({
    required IconData icon,
    required String title,
    required String subtitle,
    required VoidCallback onTap,
  }) {
    final isLight = Theme.of(context).brightness == Brightness.light;
