class _EditProfilePage extends StatefulWidget {
  const _EditProfilePage();
  @override
  State<_EditProfilePage> createState() => _EditProfilePageState();
}

class _EditProfilePageState extends State<_EditProfilePage> {
  final _nameController = TextEditingController();
  final _nicknameController = TextEditingController();
  Uint8List? _appAvatarBytes;
  Uint8List? _profileImageBytes;
  DateTime? _nicknameChangedAt;
  DateTime? _profilePicChangedAt;
  bool _loading = true;
  bool _saving = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _nameController.dispose();
    _nicknameController.dispose();
    super.dispose();
  }

  DateTime? _timestamp(dynamic value) =>
      value is Timestamp ? value.toDate() : null;

  Future<void> _load() async {
    final user = AuthService.currentUser;
    if (user == null) {
      if (mounted) setState(() => _loading = false);
      return;
    }
    try {
      final data = await ProfileService.loadUserProfile(user.uid);
      final alpha = data?['alphaDenProfile'];
      final profile = alpha is Map
          ? Map<String, dynamic>.from(alpha)
          : <String, dynamic>{};
      _nameController.text = (data?['displayName'] ?? profile['name'] ?? '')
          .toString();
      _nicknameController.text =
          (profile['nickname'] ?? profile['handle'] ?? '')
              .toString()
              .replaceFirst(RegExp(r'^@'), '');
      _nicknameChangedAt = _timestamp(profile['nicknameChangedAt']);
      _profilePicChangedAt = _timestamp(profile['profilePicChangedAt']);
      final avatar = ((data?['appAvatarBase64'] ?? '').toString().isNotEmpty)
          ? (data?['appAvatarBase64'] ?? '').toString()
          : await ProfileService.loadAppAvatar(uid: user.uid);
      final pic =
          (data?['profilePicBase64'] ?? profile['profilePicBase64'] ?? '')
              .toString();
      if (avatar.isNotEmpty) {
        try {
          _appAvatarBytes = base64Decode(avatar);
        } catch (_) {}
      }
      if (pic.isNotEmpty) {
        try {
          _profileImageBytes = base64Decode(pic);
        } catch (_) {}
      }
    } catch (_) {}
    if (mounted) setState(() => _loading = false);
  }

  bool _locked(DateTime? changedAt) =>
      changedAt != null &&
      DateTime.now().difference(changedAt).inHours < 24 * 7;

  String _lockMessage(String label, DateTime changedAt) {
    final remaining =
        const Duration(days: 7) - DateTime.now().difference(changedAt);
    final days = remaining.inHours <= 0 ? 0 : (remaining.inHours / 24).ceil();
    return '$label can be changed again in about $days day${days == 1 ? '' : 's'}.';
  }

  Future<void> _pickAppAvatar() async {
    try {
      final picked = await ImagePicker().pickImage(
        source: ImageSource.gallery,
        imageQuality: 68,
        maxWidth: 768,
        maxHeight: 768,
      );
      if (picked == null) return;
      final bytes = await picked.readAsBytes();
      if (bytes.isEmpty || bytes.length > 600000) {
        if (mounted)
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('Please choose a smaller avatar (under 600 KB).'),
            ),
          );
        return;
      }
      final user = AuthService.currentUser;
      if (user == null) return;
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
        'appAvatarBase64': base64Encode(bytes),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      if (mounted) setState(() => _appAvatarBytes = bytes);
    } catch (_) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not save the avatar. Please try again.'),
          ),
        );
    }
  }

  Future<void> _pickProfilePicture() async {
    final changedAt = _profilePicChangedAt;
    if (changedAt != null && _locked(changedAt)) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(_lockMessage('Profile picture', changedAt))),
        );
      return;
    }
    try {
      final picked = await ImagePicker().pickImage(
        source: ImageSource.gallery,
        imageQuality: 68,
        maxWidth: 1280,
        maxHeight: 1280,
      );
      if (picked == null) return;
      final bytes = await picked.readAsBytes();
      if (bytes.isEmpty || bytes.length > 700000) {
        if (mounted)
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text(
                'Please choose a smaller profile image (under 700 KB).',
              ),
            ),
          );
        return;
      }
      final user = AuthService.currentUser;
      if (user == null) return;
      final now = DateTime.now();
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
        'profilePicBase64': base64Encode(bytes),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
        'alphaDenProfile': {
          'profilePicBase64': base64Encode(bytes),
          'profilePicChangedAt': Timestamp.fromDate(now),
        },
      }, SetOptions(merge: true));
      _profilePicChangedAt = now;
      if (mounted) setState(() => _profileImageBytes = bytes);
      // The profile write above is the authoritative save. Public-post sync is
      // secondary and must never turn a successful profile update into a false
      // error message.
      try {
        final data = await ProfileService.loadUserProfile(user.uid);
        final alpha = data?['alphaDenProfile'];
        if (alpha is Map) {
          await AlphaDenService.syncPublicProfileToPosts(
            uid: user.uid,
            username: (alpha['username'] ?? _nicknameController.text.trim())
                .toString(),
            profilePicUrl: (alpha['profilePicUrl'] ?? '').toString(),
            profilePicBase64: base64Encode(bytes),
            referrals: (alpha['referrals'] as num?)?.toInt() ?? 0,
            winTrades: (alpha['winTrades'] as num?)?.toInt() ?? 0,
            verified: alpha['verifiedCreatorApproved'] == true,
          );
        }
      } catch (_) {}
    } catch (_) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Could not save the profile picture. Please try again.',
            ),
          ),
        );
    }
  }

  Future<void> _save() async {
    final user = AuthService.currentUser;
    if (user == null || _saving) return;
    final name = _nameController.text.trim();
    var nickname = _nicknameController.text.trim();
    if (name.length > 40) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Name must be 40 characters or less.')),
      );
      return;
    }
    if (nickname.isNotEmpty && nickname.length > 30) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Nickname must be 30 characters or less.'),
        ),
      );
      return;
    }
    final oldNickname = _nicknameController.text.trim();
    if (nickname != oldNickname &&
        _nicknameChangedAt != null &&
        _locked(_nicknameChangedAt)) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(_lockMessage('Nickname', _nicknameChangedAt!))),
      );
      return;
    }
    setState(() => _saving = true);
    try {
      final existing =
          await ProfileService.loadUserProfile(user.uid) ?? <String, dynamic>{};
      final rawAlpha = existing['alphaDenProfile'];
      final alpha = rawAlpha is Map
          ? Map<String, dynamic>.from(rawAlpha)
          : <String, dynamic>{};
      final now = DateTime.now();
      alpha['uid'] = user.uid;
      alpha['name'] = name;
      final existingUsername = (alpha['username'] ?? 'userxxxx')
          .toString()
          .trim();
      alpha['username'] = existingUsername.startsWith('@')
          ? existingUsername
          : '@$existingUsername';
      alpha['usernameNormalized'] = alpha['username']
          .toString()
          .replaceFirst(RegExp(r'^@'), '')
          .toLowerCase();
      alpha['nickname'] = nickname;
      alpha['handle'] = nickname;
      alpha['updatedAt'] = FieldValue.serverTimestamp();
      if (nickname != oldNickname)
        alpha['nicknameChangedAt'] = Timestamp.fromDate(now);
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
        'uid': user.uid,
        'displayName': name,
        'alphaDenProfile': alpha,
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      // Public-feed synchronization is secondary. A failure there must not
      // overwrite the successful profile-save result with a false error.
      try {
        final finalData = await ProfileService.loadUserProfile(user.uid);
        final finalAlphaRaw = finalData?['alphaDenProfile'];
        final finalAlpha = finalAlphaRaw is Map
            ? Map<String, dynamic>.from(finalAlphaRaw)
            : alpha;
        await AlphaDenService.syncPublicProfileToPosts(
          uid: user.uid,
          username: (finalAlpha['username'] ?? 'userxxxx').toString(),
          profilePicUrl: (finalAlpha['profilePicUrl'] ?? '').toString(),
          profilePicBase64:
              (finalData?['profilePicBase64'] ??
                      finalAlpha['profilePicBase64'] ??
                      '')
                  .toString(),
          referrals: (finalAlpha['referrals'] as num?)?.toInt() ?? 0,
          winTrades: (finalAlpha['winTrades'] as num?)?.toInt() ?? 0,
          verified: finalAlpha['verifiedCreatorApproved'] == true,
        );
      } catch (_) {}
      if (mounted) {
        _nicknameChangedAt = nickname != oldNickname ? now : _nicknameChangedAt;
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Profile saved successfully.')),
        );
      }
    } catch (_) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'We could not save your profile right now. Please try again.',
            ),
          ),
        );
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  Widget _photoCard({
    required String title,
    required String subtitle,
    required Uint8List? bytes,
    required VoidCallback onTap,
