  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('EDIT PROFILE')),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : ListView(
              padding: const EdgeInsets.fromLTRB(16, 14, 16, 30),
              children: [
                _photoCard(
                  title: 'APP AVATAR',
                  subtitle: 'Your separate in-app avatar',
                  bytes: _appAvatarBytes,
                  onTap: _pickAppAvatar,
                  fallback: Icons.person_rounded,
                ),
                const SizedBox(height: 10),
                _photoCard(
                  title: 'PROFILE PICTURE',
                  subtitle: 'Shown on your Alpha Den profile and posts',
                  bytes: _profileImageBytes,
                  onTap: _pickProfilePicture,
                  fallback: Icons.account_circle_rounded,
                ),
                const SizedBox(height: 12),
                GlassCard(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text(
                        'NAME',
                        style: TextStyle(
                          fontWeight: FontWeight.w900,
                          letterSpacing: 1.0,
                        ),
                      ),
                      const SizedBox(height: 7),
                      TextField(
                        controller: _nameController,
                        maxLength: 40,
                        decoration: const InputDecoration(
                          hintText: 'Your name / display name',
                          counterText: '',
                        ),
                      ),
                      const SizedBox(height: 12),
                      const Text(
                        'ALPHA DEN NICKNAME',
                        style: TextStyle(
                          fontWeight: FontWeight.w900,
                          letterSpacing: 1.0,
                        ),
                      ),
                      const SizedBox(height: 7),
                      TextField(
                        controller: _nicknameController,
                        maxLength: 30,
                        decoration: const InputDecoration(
                          hintText: 'Your nickname',
                          counterText: '',
                        ),
                      ),
                      const SizedBox(height: 6),
                      Text(
                        'Nickname changes remain subject to the existing 7-day profile rule.',
                        style: TextStyle(
                          color: Theme.of(context).colorScheme.onSurface
                              .withValues(alpha: .50),
                          fontSize: 9.5,
                        ),
                      ),
                      const SizedBox(height: 14),
                      SizedBox(
                        width: double.infinity,
                        child: ElevatedButton.icon(
                          onPressed: _saving ? null : _save,
                          icon: const Icon(Icons.save_outlined),
                          label: Text(_saving ? 'SAVING...' : 'SAVE PROFILE'),
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
    );
  }
}

