class _ThemePage extends StatelessWidget {
  const _ThemePage();

  Future<void> _select(BuildContext context, String value) async {
    appThemePreference.value = value;
    final user = AuthService.currentUser;
    if (user != null)
      await ProfileService.saveThemePreference(
        uid: user.uid,
        preference: value,
      );
  }

  Widget _choice(
    BuildContext context,
    String value,
    String title,
    String subtitle,
    IconData icon,
  ) {
    return ValueListenableBuilder<String>(
      valueListenable: appThemePreference,
      builder: (context, current, _) {
        final active = current == value;
        return Padding(
          padding: const EdgeInsets.only(bottom: 10),
          child: GlassCard(
            child: ListTile(
              leading: Icon(icon, color: active ? AppTheme.luxuryGold : null),
              title: Text(
                title,
