class _AdminReferralSettingsPage extends StatefulWidget {
  const _AdminReferralSettingsPage();
  @override
  State<_AdminReferralSettingsPage> createState() =>
      _AdminReferralSettingsPageState();
}

class _AdminReferralSettingsPageState
    extends State<_AdminReferralSettingsPage> {
  final _url = TextEditingController();
  final _monthly = TextEditingController();
  bool _loading = true;
  bool _saving = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _url.dispose();
    _monthly.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    try {
      final data = await ReferralService.loadSettings();
      _url.text = (data['publicReferralUrl'] ?? '').toString();
      _monthly.text = (data['monthlyRecurringRewardUsd'] ?? '').toString();
    } catch (_) {}
    if (mounted) setState(() => _loading = false);
  }

  Future<void> _save() async {
    if (_saving) return;
    final base = _url.text.trim();
    final monthly = double.tryParse(_monthly.text.trim()) ?? 0;
    final uri = Uri.tryParse(base);
    if (base.isNotEmpty &&
        (uri == null || !uri.hasScheme || uri.host.isEmpty)) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Enter a valid HTTPS referral URL.')),
      );
      return;
    }
    if (monthly < 0) return;
    setState(() => _saving = true);
    try {
      await FirebaseFirestore.instance
          .collection('referralSettings')
          .doc('config')
          .set({
            'publicReferralUrl': base,
            'monthlyRecurringRewardUsd': monthly,
            'updatedAt': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Referral settings saved and synced.')),
        );
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not save referral settings: $e')),
        );
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('REFERRAL SETTINGS')),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : ListView(
              padding: const EdgeInsets.all(16),
              children: [
                GlassCard(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'PERSONAL REFERRAL LINK',
                        style: TextStyle(
                          color: AppTheme.luxuryGold,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(height: 6),
                      Text(
                        'Set the production HTTPS URL that carries ?ref=USERCODE. This URL must be configured as the Android App Link / iOS Universal Link and store fallback before publishing.',
                        style: TextStyle(
                          color: AppTheme.textMuted,
                          fontSize: 10,
                          height: 1.4,
                        ),
                      ),
                      const SizedBox(height: 10),
                      TextField(
                        controller: _url,
                        decoration: const InputDecoration(
                          labelText: 'Production referral URL',
                          hintText: 'https://your-official-domain.example/',
                        ),
                      ),
                      const SizedBox(height: 16),
                      Text(
                        'MONTHLY RECURRING REFERRAL INCENTIVE',
                        style: TextStyle(
                          color: AppTheme.luxuryGold,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(height: 6),
                      Text(
                        'This amount is intentionally configurable because the requirements specify an applicable monthly incentive but do not specify its dollar amount. The secure backend reads this value when issuing each monthly cycle.',
                        style: TextStyle(
                          color: AppTheme.textMuted,
                          fontSize: 10,
                          height: 1.4,
                        ),
                      ),
                      const SizedBox(height: 10),
                      TextField(
                        controller: _monthly,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: const InputDecoration(
                          labelText: 'Monthly reward (USD)',
                          hintText: '0.00',
                        ),
                      ),
                      const SizedBox(height: 14),
                      SizedBox(
                        width: double.infinity,
                        child: FilledButton.icon(
                          onPressed: _saving ? null : _save,
                          icon: const Icon(Icons.save_outlined),
                          label: Text(
                            _saving ? 'SAVING...' : 'SAVE REFERRAL SETTINGS',
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
    );
  }
}

class _AdminPaymentSettingsPage extends StatefulWidget {
  const _AdminPaymentSettingsPage();
  @override
  State<_AdminPaymentSettingsPage> createState() =>
      _AdminPaymentSettingsPageState();
}

class _AdminPaymentSettingsPageState extends State<_AdminPaymentSettingsPage> {
  final List<Map<String, dynamic>> _methods = [];
  final Map<String, Map<String, dynamic>> _plans = {};
  bool _loading = true;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      await PaymentService.ensureDefaultPaymentMethods();
      final data = await PaymentService.loadConfig();
      final methods = ((data['paymentMethods'] as List?) ?? const [])
          .whereType<Map>()
          .map((e) => Map<String, dynamic>.from(e))
          .toList();
      if (methods.isEmpty) {
        methods.addAll(PaymentService.defaultPaymentMethods());
      } else {
        final existingIds = methods
            .map((m) => (m['id'] ?? '').toString())
            .toSet();
        for (final fallback in PaymentService.defaultPaymentMethods()) {
          if (!existingIds.contains((fallback['id'] ?? '').toString()))
            methods.add(Map<String, dynamic>.from(fallback));
        }
      }
      final plans = Map<String, dynamic>.from((data['plans'] as Map?) ?? {});
      if (plans.isEmpty) {
        plans.addAll({
          'premium_monthly': {
            'name': 'Premium Monthly',
            'amount': 15,
            'currency': 'USD',
            'description': 'Premium access for one month.',
            'enabled': true,
          },
          'premium_one_time': {
            'name': 'Premium Lifetime',
            'amount': 50,
            'currency': 'USD',
            'description': 'One-time lifetime Premium access.',
            'enabled': true,
          },
          'mentorship_one_time': {
            'name': 'Mentorship One-Time',
            'amount': 80,
            'currency': 'USD',
            'description': 'One-time Mentorship payment.',
            'enabled': true,
          },
          'mentorship_installment': {
            'name': 'Mentorship Installment',
            'amount': 80,
            'currency': 'USD',
            'description': '4 weekly payments of \$20.',
            'enabled': true,
          },
          'verified_creator_monthly': {
            'name': 'Verified Creator',
            'amount': 5,
            'currency': 'USD',
            'description':
                'Verified Creator application payment Ã¢â‚¬Â¢ monthly.',
            'enabled': true,
          },
        });
      }
      if (!mounted) return;
      setState(() {
        _methods
          ..clear()
          ..addAll(methods);
        _plans
          ..clear()
          ..addAll(
            plans.map(
              (k, v) =>
                  MapEntry(k, Map<String, dynamic>.from((v as Map?) ?? {})),
            ),
          );
        _loading = false;
      });
    } catch (_) {
      if (mounted) setState(() => _loading = false);
    }
  }

  Future<void> _editMethod([Map<String, dynamic>? existing]) async {
    final id = TextEditingController(
      text:
          (existing?['id'] ?? 'method_${DateTime.now().millisecondsSinceEpoch}')
              .toString(),
    );
    final name = TextEditingController(
      text: (existing?['name'] ?? '').toString(),
    );
    final type = TextEditingController(
      text: (existing?['type'] ?? 'wallet').toString(),
    );
    final details = TextEditingController(
      text: (existing?['details'] ?? '').toString(),
    );
    bool enabled = existing?['enabled'] != false;
    final result = await showDialog<bool>(
      context: context,
      builder: (dc) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          backgroundColor: AppTheme.adaptiveSurface(Color(0xFF101419)),
          title: Text(
            existing == null ? 'ADD PAYMENT METHOD' : 'EDIT PAYMENT METHOD',
          ),
          content: SingleChildScrollView(
            child: Column(
              children: [
                TextField(
                  controller: id,
                  decoration: const InputDecoration(labelText: 'Internal ID'),
                ),
                TextField(
                  controller: name,
                  decoration: const InputDecoration(labelText: 'Display name'),
                ),
                TextField(
                  controller: type,
                  decoration: const InputDecoration(
                    labelText: 'Type / network',
                  ),
                ),
                TextField(
                  controller: details,
                  maxLines: 3,
                  decoration: const InputDecoration(
                    labelText: 'Account number / wallet / payment details',
                  ),
                ),
                SwitchListTile(
                  value: enabled,
                  onChanged: (v) => setDialogState(() => enabled = v),
                  title: const Text('Enabled'),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dc, false),
              child: const Text('CANCEL'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(dc, true),
              child: const Text('SAVE'),
            ),
          ],
        ),
      ),
    );
    if (result != true) return;
    final value = {
      'id': id.text.trim(),
      'name': name.text.trim(),
      'type': type.text.trim(),
      'details': details.text.trim(),
      'enabled': enabled,
    };
    if (value['id'].toString().isEmpty ||
        value['name'].toString().isEmpty ||
        value['details'].toString().isEmpty)
      return;
    await PaymentService.saveMethod(
      id: value['id'] as String,
      name: value['name'] as String,
      type: value['type'] as String,
      details: value['details'] as String,
      enabled: enabled,
    );
    await _load();
  }

  Future<void> _editPlan(String id) async {
    final old = _plans[id] ?? <String, dynamic>{};
    final name = TextEditingController(text: (old['name'] ?? id).toString());
    final amount = TextEditingController(
      text:
          (old['amount'] ??
                  (id == 'premium_monthly'
                      ? 15
                      : id == 'mentorship_one_time'
                      ? 80
                      : id == 'mentorship_installment'
                      ? 80
                      : id == 'verified_creator_monthly'
                      ? 5
                      : ''))
              .toString(),
    );
    final currency = TextEditingController(
      text: (old['currency'] ?? 'USD').toString(),
    );
    final description = TextEditingController(
      text: (old['description'] ?? '').toString(),
    );
    bool enabled = old['enabled'] != false;
    final result = await showDialog<bool>(
      context: context,
      builder: (dc) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          backgroundColor: AppTheme.adaptiveSurface(Color(0xFF101419)),
          title: Text('EDIT $id'),
          content: SingleChildScrollView(
            child: Column(
              children: [
                TextField(
                  controller: name,
                  decoration: const InputDecoration(labelText: 'Plan name'),
                ),
                TextField(
                  controller: amount,
                  keyboardType: const TextInputType.numberWithOptions(
                    decimal: true,
                  ),
                  decoration: const InputDecoration(labelText: 'Amount'),
                ),
                TextField(
                  controller: currency,
                  decoration: const InputDecoration(labelText: 'Currency'),
                ),
                TextField(
                  controller: description,
                  maxLines: 2,
                  decoration: const InputDecoration(labelText: 'Description'),
                ),
                SwitchListTile(
                  value: enabled,
                  onChanged: (v) => setDialogState(() => enabled = v),
                  title: const Text('Enabled'),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dc, false),
              child: const Text('CANCEL'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(dc, true),
              child: const Text('SAVE'),
            ),
          ],
        ),
      ),
    );
    if (result != true) return;
    final parsed = double.tryParse(amount.text.trim());
    if (parsed == null) return;
    await PaymentService.savePlan(
      id: id,
      name: name.text,
      amount: parsed,
      currency: currency.text,
      description: description.text,
      enabled: enabled,
    );
    await _load();
  }

  @override
  Widget build(BuildContext context) {
    final planIds = [
      'premium_monthly',
      'premium_one_time',
      'mentorship_one_time',
      'mentorship_installment',
      'verified_creator_monthly',
    ];
    return Scaffold(
      appBar: AppBar(title: const Text('PAYMENT SETTINGS')),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : ListView(
              padding: const EdgeInsets.all(16),
              children: [
                const Text(
                  'PAYMENT METHODS',
                  style: TextStyle(fontSize: 17, fontWeight: FontWeight.w900),
                ),
                const SizedBox(height: 6),
                Text(
                  'These values are stored in Firebase. Enabled users see the current values immediately; changing them later updates the same central payment page for everyone.',
                  style: TextStyle(
                    color: AppTheme.textMuted,
                    fontSize: 11,
                    height: 1.4,
                  ),
                ),
                const SizedBox(height: 12),
                for (final m in _methods)
                  Card(
                    color: AppTheme.adaptiveSurface(Color(0xFF11171B)),
                    child: ListTile(
                      leading: Icon(
                        Icons.account_balance_wallet_outlined,
                        color: AppTheme.luxuryGold,
                      ),
                      title: Text((m['name'] ?? 'Payment method').toString()),
                      subtitle: Text(
                        '${m['type'] ?? ''}\n${m['details'] ?? ''}',
                        style: TextStyle(color: AppTheme.textMuted),
                      ),
                      isThreeLine: true,
                      trailing: IconButton(
                        icon: const Icon(Icons.edit_outlined),
                        onPressed: () => _editMethod(m),
                      ),
                    ),
                  ),
                OutlinedButton.icon(
                  onPressed: () => _editMethod(),
                  icon: const Icon(Icons.add),
                  label: const Text('ADD PAYMENT METHOD'),
                ),
                const SizedBox(height: 24),
                const Text(
                  'PAYMENT PLANS',
                  style: TextStyle(fontSize: 17, fontWeight: FontWeight.w900),
                ),
                const SizedBox(height: 8),
                for (final id in planIds)
                  Card(
                    color: AppTheme.adaptiveSurface(Color(0xFF11171B)),
                    child: ListTile(
                      title: Text((_plans[id]?['name'] ?? id).toString()),
                      subtitle: Text(
                        '${_plans[id]?['amount'] ?? 'Not configured'} ${_plans[id]?['currency'] ?? 'USD'} Ã¢â‚¬Â¢ ${_plans[id]?['description'] ?? ''}',
                        style: TextStyle(color: AppTheme.textMuted),
                      ),
                      trailing: IconButton(
                        icon: const Icon(Icons.edit_outlined),
                        onPressed: () => _editPlan(id),
                      ),
                    ),
                  ),
              ],
            ),
    );
  }
}

class CentralPaymentPage extends StatefulWidget {
  final String product;
  final String? planId;
  const CentralPaymentPage({super.key, required this.product, this.planId});

  @override
  State<CentralPaymentPage> createState() => _CentralPaymentPageState();
}

class _CentralPaymentPageState extends State<CentralPaymentPage> {
  final ImagePicker _imagePicker = ImagePicker();
  final TextEditingController _referenceController = TextEditingController();
  Map<String, dynamic>? _selectedMethod;
  XFile? _proofFile;
  Uint8List? _proofBytes;
  bool _submitting = false;
  bool _notifyingAdmin = false;
  String? _statusMessage;
  String? _requestId;
  String? _automaticOrderId;
  Map<String, dynamic>? _automaticOrder;
  bool _creatingAutomaticOrder = false;
  bool _verifyingAutomaticPayment = false;
  bool _automaticVerificationSuccess = false;
  Timer? _automaticPollTimer;
  Timer? _automaticExpiryTimer;
  Duration? _automaticRemaining;
  bool _automaticExpiryCheckInProgress = false;
  bool _restoringActivePaymentSession = true;
  String _selectedPremiumPlanId = 'premium_monthly';

  @override
  void initState() {
    super.initState();
    _selectedPremiumPlanId =
        widget.product == 'premium' && widget.planId == 'premium_one_time'
        ? 'premium_one_time'
        : (widget.planId ?? 'premium_monthly');
    _restoreActiveAutomaticPaymentSession();
  }

  @override
  void dispose() {
    _automaticPollTimer?.cancel();
    _automaticExpiryTimer?.cancel();
    _referenceController.dispose();
    super.dispose();
  }

  bool _isAutomaticCryptoMethod(Map<String, dynamic>? method) {
    final id = (method?['id'] ?? '').toString().trim().toLowerCase();
    final type = (method?['type'] ?? '').toString().trim().toLowerCase();
    return id == 'trc20' ||
        id == 'bep20' ||
        id == 'erc20' ||
        id.contains('trc20') ||
        id.contains('bep20') ||
        id.contains('erc20') ||
        type.contains('trc20') ||
        type.contains('bep20') ||
        type.contains('erc20');
  }

  bool _isEasypaisaMethod(Map<String, dynamic>? method) {
    final id = (method?['id'] ?? '').toString().trim().toLowerCase();
    final name = (method?['name'] ?? '').toString().trim().toLowerCase();
    final type = (method?['type'] ?? '').toString().trim().toLowerCase();
    return id == 'easypaisa' ||
        id.contains('easypaisa') ||
        name.contains('easypaisa') ||
        type.contains('easypaisa');
  }

  bool _isSelectedPaymentMethod(Map<String, dynamic> method) {
    final selectedId = (_selectedMethod?['id'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    final selectedType = (_selectedMethod?['type'] ?? '')
        .toString()
        .trim()
        .toLowerCase();
    final methodId = (method['id'] ?? '').toString().trim().toLowerCase();
    final methodType = (method['type'] ?? '').toString().trim().toLowerCase();
    return selectedId.isNotEmpty &&
            methodId.isNotEmpty &&
            selectedId == methodId ||
        selectedType.isNotEmpty &&
            methodType.isNotEmpty &&
            selectedType == methodType;
  }

  String get _effectivePlanId => widget.product == 'premium'
      ? _selectedPremiumPlanId
      : (widget.planId ??
            (widget.product == 'mentorship'
                ? 'mentorship_one_time'
                : widget.product == 'verified_creator'
                ? 'verified_creator_monthly'
                : ''));

  String _displayPlanName(String planId, Map<String, dynamic> plan) {
    if (planId == 'premium_monthly') return 'Monthly Subscription';
    if (planId == 'premium_one_time') return 'One-Time Fee';
    return (plan['name'] ?? planId).toString();
  }

  double _displayPlanAmount(String planId, Map<String, dynamic> plan) {
    if (planId == 'premium_monthly') return 15;
    if (planId == 'premium_one_time') return 50;
    return planId == 'mentorship_installment'
        ? 20
        : ((plan['amount'] as num?)?.toDouble() ?? 0);
  }

  String _displayPlanDescription(String planId, Map<String, dynamic> plan) {
    if (planId == 'premium_monthly')
      return 'Pay \$15 monthly for 30 days of Premium access. Renew before expiry to keep Premium privileges and unlocked Live Calls.';
    if (planId == 'premium_one_time')
      return 'Pay \$50 one time. This is a one-time Premium fee; no monthly renewal is required.';
    return (plan['description'] ?? '').toString();
  }

  Future<void> _restoreActiveAutomaticPaymentSession() async {
    final user = FirebaseAuth.instance.currentUser;
    final planId = _effectivePlanId.trim();
    if (user == null || planId == null || planId.isEmpty) {
      if (mounted) setState(() => _restoringActivePaymentSession = false);
      return;
    }

    try {
      final result = await AutomaticPaymentService.getActiveOrder(
        product: widget.product,
        planId: planId,
      );
      final active = result['active'] == true;
      final rawOrder = result['order'];
      if (!active || rawOrder is! Map) {
        if (mounted) setState(() => _restoringActivePaymentSession = false);
        return;
      }

      final order = Map<String, dynamic>.from(rawOrder);
      final orderId = (order['orderId'] ?? result['orderId'] ?? '')
          .toString()
          .trim();
      if (orderId.isEmpty || !mounted) {
        if (mounted) setState(() => _restoringActivePaymentSession = false);
        return;
      }

      final backendMethod = (order['paymentMethod'] ?? order['network'] ?? '')
          .toString()
          .trim();
      final backendDetails = (order['receivingDetails'] ?? '').toString();
      final restoredMethod = <String, dynamic>{
        'id': backendMethod,
        'type': (order['network'] ?? backendMethod).toString(),
        'name': backendMethod.toUpperCase(),
        'details': backendDetails,
        'enabled': true,
      };

      setState(() {
        _selectedMethod = restoredMethod;
        _automaticOrder = order;
        _automaticOrderId = orderId;
        _automaticVerificationSuccess = false;
        _verifyingAutomaticPayment = true;
        _creatingAutomaticOrder = false;
        _restoringActivePaymentSession = false;
        _statusMessage = 'You already have an active payment. Payment verification will continue for the existing order.';
      });

      _startAutomaticExpiryCountdown();
      _startAutomaticVerificationPolling();
    } catch (_) {
      // A restore failure must never manufacture a local payment session.
      // Unlock the selector only after the authoritative restore attempt has finished.
      if (mounted) setState(() => _restoringActivePaymentSession = false);
    }
  }

  void _startAutomaticExpiryCountdown() {
    _automaticExpiryTimer?.cancel();
    _updateAutomaticExpiryCountdown();
    _automaticExpiryTimer = Timer.periodic(
      const Duration(seconds: 1),
      (_) => _updateAutomaticExpiryCountdown(),
    );
  }

  void _updateAutomaticExpiryCountdown() {
    final rawExpiresAt = (_automaticOrder?['expiresAt'] ?? '')
        .toString()
        .trim();
    final expiresAt = DateTime.tryParse(rawExpiresAt);
    if (expiresAt == null) {
      if (mounted) setState(() => _automaticRemaining = null);
      return;
    }

    final remaining = expiresAt.difference(DateTime.now());
    final clamped = remaining.isNegative ? Duration.zero : remaining;
    if (!mounted) return;
    setState(() => _automaticRemaining = clamped);

    if (clamped == Duration.zero && !_automaticExpiryCheckInProgress) {
      _automaticExpiryTimer?.cancel();
      _automaticExpiryCheckInProgress = true;
      _pollAutomaticPaymentStatus().whenComplete(() {
        _automaticExpiryCheckInProgress = false;
      });
    }
  }

  String _automaticCountdownText() {
    final remaining = _automaticRemaining;
    if (remaining == null) return '--:--';
    final totalSeconds = remaining.inSeconds;
    final minutes = totalSeconds ~/ 60;
    final seconds = totalSeconds % 60;
    return '${minutes.toString().padLeft(2, '0')}:${seconds.toString().padLeft(2, '0')}';
  }

  Future<void> _copyAutomaticDestination() async {
    final address = (_automaticOrder?['receivingDetails'] ?? '')
        .toString()
        .trim();
    if (address.isEmpty) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Destination address is not available yet.'),
          ),
        );
      return;
    }
    await Clipboard.setData(ClipboardData(text: address));
    if (mounted)
      ScaffoldMessenger.of(context)
          .showSnackBar(const SnackBar(content: Text('Address copied')));
  }

  Future<void> _createAutomaticOrder(Map<String, dynamic> plan) async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null ||
        _selectedMethod == null ||
        plan.isEmpty ||
        _creatingAutomaticOrder ||
        _verifyingAutomaticPayment)
      return;
    final rawNetwork =
        (_selectedMethod!['id'] ??
                _selectedMethod!['type'] ??
                _selectedMethod!['name'] ??
                '')
            .toString()
            .toLowerCase();
    final network = rawNetwork.contains('trc20')
        ? 'trc20'
        : rawNetwork.contains('bep20')
        ? 'bep20'
        : rawNetwork.contains('erc20')
        ? 'erc20'
        : rawNetwork.trim();
    setState(() {
      _creatingAutomaticOrder = true;
      _statusMessage = null;
      _automaticVerificationSuccess = false;
    });
    try {
      final result = await AutomaticPaymentService.createOrder(
        product: widget.product,
        planId: _effectivePlanId.trim(),
        network: network,
      );
      if (!mounted) return;
      final order = Map<String, dynamic>.from(
        (result['order'] as Map?) ?? result,
      );
      final orderId = (result['orderId'] ?? order['orderId'] ?? '').toString();
      if (orderId.isEmpty)
        throw StateError('The backend did not return a payment order ID.');
      final backendMethod = (order['paymentMethod'] ?? order['network'] ?? '')
          .toString()
          .trim();
      if (backendMethod.isNotEmpty && _selectedMethod != null) {
        _selectedMethod = <String, dynamic>{
          ..._selectedMethod!,
          'id': backendMethod,
          'type': (order['network'] ?? backendMethod).toString(),
          'details':
              (order['receivingDetails'] ?? _selectedMethod!['details'] ?? '')
                  .toString(),
        };
      }
      setState(() {
        _automaticOrder = order;
        _automaticOrderId = orderId;
        _statusMessage = result['reused'] == true
            ? 'You already have an active payment. Continuing with the existing order.'
            : 'Payment order created. Pay the exact amount shown above. Verification is handled by the secure backend.';
        _verifyingAutomaticPayment = true;
      });
      _startAutomaticExpiryCountdown();
      _startAutomaticVerificationPolling();
    } catch (e) {
      if (mounted)
        setState(
          () => _statusMessage = 'Could not create automatic payment order: $e',
        );
    } finally {
      if (mounted) setState(() => _creatingAutomaticOrder = false);
    }
  }

  void _startAutomaticVerificationPolling() {
    _automaticPollTimer?.cancel();
    _automaticPollTimer = Timer.periodic(const Duration(seconds: 5), (_) async {
      await _pollAutomaticPaymentStatus();
    });
    _pollAutomaticPaymentStatus();
  }

  Future<void> _pollAutomaticPaymentStatus() async {
    final orderId = (_automaticOrderId ?? '').trim();
    if (orderId.isEmpty || !_verifyingAutomaticPayment || !mounted) return;
    try {
      final result = await AutomaticPaymentService.getOrder(orderId);
      final order = Map<String, dynamic>.from(
        (result['order'] as Map?) ?? result,
      );
      final status = (order['status'] ?? '').toString().toLowerCase();
      if (status.isEmpty) return;
      if (status == 'paid' ||
          status == 'completed' ||
          status == 'entitlement_granted' ||
          order['entitlementGranted'] == true) {
        _automaticPollTimer?.cancel();
        _automaticExpiryTimer?.cancel();
        if (!mounted) return;
        setState(() {
          _automaticOrder = order;
          _automaticRemaining = null;
          _automaticVerificationSuccess = true;
          _statusMessage = 'Successfully Verified';
        });
        await Future<void>.delayed(const Duration(milliseconds: 1500));
        if (!mounted) return;
        setState(() {
          _verifyingAutomaticPayment = false;
          _automaticVerificationSuccess = false;
          _statusMessage = 'Payment verified successfully. Your purchased access has been updated.';
        });
        return;
      }
      if (status == 'expired' ||
          status == 'failed' ||
          status == 'rejected' ||
          status == 'cancelled') {
        _automaticPollTimer?.cancel();
        _automaticExpiryTimer?.cancel();
        if (mounted)
          setState(() {
            _verifyingAutomaticPayment = false;
            _automaticOrder = null;
            _automaticOrderId = null;
            _automaticRemaining = null;
            _automaticVerificationSuccess = false;
            _selectedMethod = null;
            _statusMessage = status == 'expired'
                ? 'Payment window expired. Please select a payment method to create a new payment order.'
                : 'Automatic payment status: ${status.toUpperCase()}';
          });
        return;
      }
      if (mounted)
        setState(() {
          _automaticOrder = order;
          _statusMessage = 'Verify your payment';
        });
    } catch (e) {
      // Keep the verification overlay active. A transient polling/network
      // failure must never be interpreted as payment success.
      if (mounted) setState(() => _statusMessage = 'Verify your payment');
    }
  }

  Future<void> _verifyAutomaticPayment() async {
    await _pollAutomaticPaymentStatus();
  }

  Future<void> _pickProofFromGallery() async {
    try {
      final file = await _imagePicker.pickImage(
        source: ImageSource.gallery,
        imageQuality: 88,
        maxWidth: 2200,
        maxHeight: 2200,
      );
      if (file == null) return;
      final bytes = await file.readAsBytes();
      if (bytes.length > 5 * 1024 * 1024) {
        if (mounted)
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text(
                'Screenshot is too large. Please choose an image under 5 MB.',
              ),
            ),
          );
        return;
      }
      setState(() {
        _proofFile = file;
        _proofBytes = bytes;
      });
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not import screenshot: $e')),
        );
    }
  }

  Future<void> _notifyAdmin(Map<String, dynamic> plan) async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      ScaffoldMessenger.of(context)
          .showSnackBar(const SnackBar(content: Text('Please sign in first.')));
      return;
    }
    if (_selectedMethod == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Select the payment method you plan to use.'),
        ),
      );
      return;
    }
    if (!_isEasypaisaMethod(_selectedMethod)) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Manual payment proof is available only for Easypaisa. USDT TRC20, BEP20 and ERC20 use automatic payment verification.',
          ),
        ),
      );
      return;
    }
    setState(() {
      _notifyingAdmin = true;
      _statusMessage = null;
    });
    try {
      final userSnap = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();
      final userData = userSnap.data() ?? <String, dynamic>{};
      final username =
          (userData['username'] ??
                  userData['alphaUsername'] ??
                  userData['nickname'] ??
                  userData['displayName'] ??
                  user.email?.split('@').first ??
                  'User')
              .toString();
      final planId = _effectivePlanId.trim();
      final requestId = await PaymentService.notifyAdminIntent(
        uid: user.uid,
        username: username,
        email: user.email ?? '',
        product: widget.product,
        planId: planId,
        planName: _displayPlanName(planId, plan),
        amount: _displayPlanAmount(planId, plan),
        currency: (plan['currency'] ?? 'USD').toString(),
        methodId: (_selectedMethod!['id'] ?? '').toString(),
        methodName: (_selectedMethod!['name'] ?? '').toString(),
        methodType: (_selectedMethod!['type'] ?? '').toString(),
      );
      if (mounted)
        setState(() {
          _requestId = requestId;
          _statusMessage = 'Admin has been notified. You can now make the payment and upload the screenshot below.';
        });
    } catch (e) {
      if (mounted)
        setState(() => _statusMessage = 'Could not notify Admin: $e');
    } finally {
      if (mounted) setState(() => _notifyingAdmin = false);
    }
  }

  Future<void> _submit(
    Map<String, dynamic> plan,
    List<Map<String, dynamic>> methods,
  ) async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please sign in before submitting payment proof.'),
        ),
      );
      return;
    }
    if (_selectedMethod == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Select the payment method you used.')),
      );
      return;
    }
    if (!_isEasypaisaMethod(_selectedMethod)) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Manual payment proof is available only for Easypaisa. USDT TRC20, BEP20 and ERC20 use automatic payment verification.',
          ),
        ),
      );
      return;
    }
    if (_proofBytes == null || _proofFile == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Please import your payment screenshot from the gallery.',
          ),
        ),
      );
      return;
    }

    setState(() {
      _submitting = true;
      _statusMessage = null;
    });
    try {
      final userSnap = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();
      final userData = userSnap.data() ?? <String, dynamic>{};
      final username =
          (userData['username'] ??
                  userData['alphaUsername'] ??
                  userData['nickname'] ??
                  userData['displayName'] ??
                  user.email?.split('@').first ??
                  'User')
              .toString();
      final planId = _effectivePlanId.trim();
      int installmentNumber = 0;
      if (widget.product == 'mentorship' &&
          planId == 'mentorship_installment') {
        final paymentSnap = await FirebaseFirestore.instance
            .collection('mentorshipPayments')
            .doc(user.uid)
            .get();
        final paidWeeks =
            (paymentSnap.data()?['paidWeeks'] as num?)?.toInt() ?? 0;
        installmentNumber = paidWeeks + 1;
      }

      final ext = _proofFile!.name.contains('.')
          ? _proofFile!.name.split('.').last
          : 'jpg';
      final proofUrl = await PaymentService.uploadPaymentProof(
        uid: user.uid,
        bytes: _proofBytes!,
        extension: ext,
      );
      final requestId = await PaymentService.submitPaymentProof(
        uid: user.uid,
        username: username,
        email: user.email ?? '',
        product: widget.product,
        planId: planId,
        planName: _displayPlanName(planId, plan),
        amount: _displayPlanAmount(planId, plan),
        currency: (plan['currency'] ?? 'USD').toString(),
        methodId: (_selectedMethod!['id'] ?? '').toString(),
        methodName: (_selectedMethod!['name'] ?? '').toString(),
        methodType: (_selectedMethod!['type'] ?? '').toString(),
        paymentDetails: (_selectedMethod!['details'] ?? '').toString(),
        transactionReference: _referenceController.text,
        proofUrl: proofUrl,
        installmentNumber: installmentNumber,
      );
      if (!mounted) return;
      setState(() {
        _statusMessage =
            'Payment proof submitted successfully. Request ID: $requestId.\nStatus: AWAITING ADMIN VERIFICATION.';
        _proofFile = null;
        _proofBytes = null;
        _referenceController.clear();
        _requestId = requestId;
      });
    } catch (e) {
      if (mounted)
        setState(() => _statusMessage = 'Payment submission failed: $e');
    } finally {
      if (mounted) setState(() => _submitting = false);
    }
  }

  Widget _buildPremiumPlanSwitcher() {
    final monthly = _selectedPremiumPlanId == 'premium_monthly';
    final disabled = _verifyingAutomaticPayment || _creatingAutomaticOrder;
    Widget option(String id, String label, Color accent) {
      final selected = _selectedPremiumPlanId == id;
      return Expanded(
        child: GestureDetector(
          onTap: disabled
              ? null
              : () {
                  setState(() {
                    _selectedPremiumPlanId = id;
                    _automaticOrder = null;
                    _automaticOrderId = null;
                    _statusMessage = null;
                  });
                },
          child: AnimatedContainer(
            duration: const Duration(milliseconds: 180),
            padding: const EdgeInsets.symmetric(vertical: 9),
            decoration: BoxDecoration(
              color: selected
                  ? accent.withValues(alpha: .16)
                  : AppTheme.adaptiveSurface(const Color(0xFF11171B)),
              borderRadius: BorderRadius.circular(10),
              border: Border.all(
                color: selected ? accent : AppTheme.borderFaint,
              ),
            ),
            child: Center(
              child: Text(
                label,
                style: const TextStyle(
                  fontWeight: FontWeight.w900,
                  fontSize: 10,
                ),
              ),
            ),
          ),
        ),
      );
    }

    return Column(
      children: [
        const SizedBox(height: 12),
        Row(
          children: [
            option('premium_monthly', '\$15 MONTHLY', AppTheme.luxuryGold),
            const SizedBox(width: 8),
            option(
              'premium_one_time',
              '\$50 ONE-TIME',
              const Color(0xFFB56CFF),
            ),
          ],
        ),
        const SizedBox(height: 5),
        Text(
          monthly
              ? 'Monthly Subscription Ã¢â‚¬Â¢ Pay \$15 for 30 days. Renew before expiry to keep Premium access.'
              : 'One-Time Fee Ã¢â‚¬Â¢ Pay \$50 once. Premium remains active without monthly renewal.',
          textAlign: TextAlign.center,
          style: TextStyle(
            color: AppTheme.textMuted,
            fontSize: 9.5,
            fontWeight: FontWeight.w700,
          ),
        ),
      ],
    );
  }

