class _DriveAwareImage extends StatefulWidget {
  final String source;
  final double? width;
  final double? height;
  final BoxFit fit;
  final String errorText;
  const _DriveAwareImage({
    required this.source,
    this.width,
    this.height,
    this.fit = BoxFit.contain,
    required this.errorText,
  });
  @override
  State<_DriveAwareImage> createState() => _DriveAwareImageState();
}

class _DriveAwareImageState extends State<_DriveAwareImage> {
  Uint8List? _bytes;
  String? _url;
  bool _loading = true;
  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    final source = widget.source.trim();
    try {
      if (source.toLowerCase().startsWith('drive://')) {
        // Prefer the authenticated backend byte path. A Drive download URL can
        // be valid but still fail inside Flutter Web because the final Drive
        // response may redirect or omit browser CORS headers. The backend byte
        // path avoids that browser-side failure and works after app restart.
        try {
          final bytes = await DriveStorageService.downloadBytes(source);
          if (bytes.isNotEmpty && mounted) {
            setState(() {
              _bytes = bytes;
              _loading = false;
            });
            return;
          }
        } catch (_) {}

        // Keep the existing signed-URL fallback for environments where the
        // authenticated byte response is temporarily unavailable.
        try {
          final url = await DriveStorageService.getPrivateFileUrl(source);
          if (url.trim().isNotEmpty && mounted) {
            setState(() {
              _url = url;
              _loading = false;
            });
            return;
          }
        } catch (_) {}
      } else if (source.isNotEmpty) {
        if (mounted)
          setState(() {
            _url = source;
            _loading = false;
          });
        return;
      }
    } catch (_) {}
    if (mounted) setState(() => _loading = false);
  }

  @override
  Widget build(BuildContext context) {
    if (_loading)
      return SizedBox(
        width: widget.width,
        height: widget.height ?? 80,
        child: const Center(child: CircularProgressIndicator(strokeWidth: 2)),
      );
    if (_bytes != null)
      return Image.memory(
        _bytes!,
        width: widget.width,
        height: widget.height,
        fit: widget.fit,
        errorBuilder: (_, __, ___) => Text(widget.errorText),
      );
    if (_url != null)
      return Image.network(
        _url!,
        width: widget.width,
        height: widget.height,
        fit: widget.fit,
        errorBuilder: (_, __, ___) => Text(widget.errorText),
      );
    return SizedBox(
      width: widget.width,
      height: widget.height ?? 80,
      child: Center(child: Text(widget.errorText)),
    );
  }
}

