class PersonalPage extends StatefulWidget {
  const PersonalPage({super.key});

  @override
  State<PersonalPage> createState() => _PersonalPageState();
}

class _PersonalPageState extends State<PersonalPage> {
  String _displayName = '';
  Uint8List? _profileImageBytes;
  Uint8List? _appAvatarBytes;

  @override
  void initState() {
    super.initState();
    _loadDisplayName();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // Refresh after returning to this page so the latest Firestore display
    // name is always reflected without changing the locked Personal UI.
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _loadDisplayName();
    });
  }

  Future<void> _loadDisplayName() async {
    final user = AuthService.currentUser;
    if (user == null) return;

    try {
      final data = await ProfileService.loadUserProfile(user.uid);
      final displayName = (data?['displayName'] as String?)?.trim() ?? '';
      Uint8List? imageBytes;
      Uint8List? appAvatarBytes;
      final savedImage = (data?['profilePicBase64'] ?? '').toString();
      final savedAppAvatar =
          ((data?['appAvatarBase64'] ?? '').toString().isNotEmpty)
          ? (data?['appAvatarBase64'] ?? '').toString()
          : await ProfileService.loadAppAvatar(uid: user.uid);
      if (savedImage.isNotEmpty) {
        try {
          imageBytes = base64Decode(savedImage);
        } catch (_) {}
      }
      if (savedAppAvatar.isNotEmpty) {
        try {
          appAvatarBytes = base64Decode(savedAppAvatar);
        } catch (_) {}
      }
      if (!mounted) return;
      setState(() {
        _displayName = displayName;
        _profileImageBytes = imageBytes;
        _appAvatarBytes = appAvatarBytes;
      });
    } catch (_) {
      // Keep the Personal page usable if the profile read is temporarily unavailable.
    }
  }

  Future<void> _pickAppAvatar() async {
    try {
      final picked = await ImagePicker().pickImage(
        source: ImageSource.gallery,
        imageQuality: 72,
        maxWidth: 1024,
        maxHeight: 1024,
      );
      if (picked == null) return;
      final bytes = await picked.readAsBytes();
      if (bytes.isEmpty || bytes.length > 600000) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Please choose a smaller avatar (under 600 KB).'),
          ),
        );
        return;
      }
      final user = AuthService.currentUser;
      if (user == null) return;
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
        'appAvatarBase64': base64Encode(bytes),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      if (!mounted) return;
      setState(() => _appAvatarBytes = bytes);
      ScaffoldMessenger.of(context)
          .showSnackBar(const SnackBar(content: Text('App avatar saved.')));
    } catch (_) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not save the app avatar. Please try again.'),
          ),
        );
    }
  }

  Future<void> _openProfile() async {
    await Navigator.push(
      context,
      MaterialPageRoute(builder: (_) => const ProfilePage()),
    );
    if (mounted) {
      await _loadDisplayName();
    }
  }

  Future<void> _logout(BuildContext context) async {
    final shouldLogout = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: AppTheme.adaptiveSurface(Color(0xFF0B0F11)),
        title: const Text('LOG OUT'),
        content: const Text(
