class AlphaDenPage extends StatefulWidget {
  final bool isAdmin;

  const AlphaDenPage({super.key, this.isAdmin = false});

  @override
  State<AlphaDenPage> createState() => _AlphaDenPageState();
}

class _AlphaDenPageState extends State<AlphaDenPage> {
  static final Set<String> _usedAlphaDenHandles = <String>{'@userxxxx'};
  String username = '@userxxxx';
  String handle = '';
  String name = 'Hassan';
  String age = '';
  String sex = '';
  String bio = 'Building my edge in the Alpha Den.';
  String profilePicUrl = '';
  Uint8List? profilePicBytes;
  int followers = 0;
  int following = 0;
  int posts = 0;
  int likes = 0;
  int views = 0;
  int reposts = 0;
  int referrals = 0;
  int winTrades = 0;
  bool verificationPaymentSubmitted = false;
  bool verifiedCreatorApproved = false;
  bool isPremium = false;
  String premiumBadgeType = '';
  String mentorshipBadgeType = '';
  String referralCrownType = '';
  bool graduated = false;
  bool hasMentorship = false;
  DateTime? _profilePicChangedAt;
  DateTime? _usernameChangedAt;
  DateTime? _nicknameChangedAt;
  DateTime? _bioChangedAt;
  DateTime? _sexChangedAt;
  DateTime? _ageSetAt;
  final List<_AlphaDenPost> _ideas = [];
  final List<_AlphaDenArticle> _articles = [];
  final List<_AlphaDenRepost> _repostItems = [];
  final Set<int> _likedIdeas = <int>{};
  final Set<String> _likedArticles = <String>{};
  late final PageController _alphaDenPageController;
  int _alphaDenPage = 0;
  bool _alphaDenMenuOpen = false;
  OverlayEntry? _alphaDenMenuEntry;

  @override
  void initState() {
    super.initState();
    _alphaDenPageController = PageController();
    _loadAlphaDenData();
  }

  String? _legacySignalField(String text, String label) {
    final match = RegExp(
      r'(?:^|Ã¢â‚¬Â¢|\n)\s*' + RegExp.escape(label) + r'\s+([^Ã¢â‚¬Â¢\n]+)',
      caseSensitive: false,
    ).firstMatch(text);
    return match?.group(1)?.trim();
  }

  Map<String, dynamic> _recoverLegacySignal(Map<String, dynamic> data) {
    final raw = (data['text'] ?? '').toString();
    final hasStructured =
        data['signalAsset'] != null ||
        data['signalEntry'] != null ||
        data['signalTp1'] != null;
    if (hasStructured || raw.trim().isEmpty) return data;
    final assetMatch = RegExp(
      r'^\s*([A-Za-z0-9._-]+)\s*/\s*USDT',
      caseSensitive: false,
    ).firstMatch(raw);
    final direction = RegExp(
      r'\b(LONG|SHORT)\b',
      caseSensitive: false,
    ).firstMatch(raw)?.group(1)?.toUpperCase();
    final leverageRaw = _legacySignalField(raw, 'LEVERAGE');
    final leverage = leverageRaw == null
        ? null
        : int.tryParse(leverageRaw.replaceAll(RegExp(r'[^0-9]'), ''));
    return <String, dynamic>{
      ...data,
      'signalAsset': assetMatch?.group(1)?.toUpperCase(),
      'signalEntry': _legacySignalField(raw, 'ENTRY'),
      'signalLongDirection': direction == null ? null : direction == 'LONG',
      'signalLeverage': leverage,
      'signalTp1': _legacySignalField(raw, 'TP1'),
      'signalTp2': _legacySignalField(raw, 'TP2'),
      'signalTp3': _legacySignalField(raw, 'TP3'),
      'signalStopLoss': _legacySignalField(raw, 'STOPLOSS'),
    };
  }

  Future<void> _loadAlphaDenData() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;
    try {
      final profile = await AlphaDenService.loadProfile(user.uid);
      final userDoc = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();
      final userData = userDoc.data() ?? <String, dynamic>{};
      isPremium = _isActivePremiumUserData(userData);
      hasMentorship =
          userData['mentorshipApproved'] == true ||
          userData['isMentorship'] == true ||
          userData['mentorship'] == true ||
          userData['studentApproved'] == true ||
          userData['isStudent'] == true;
      premiumBadgeType = (userData['confirmedPremiumBadgeType'] ?? '')
          .toString();
      mentorshipBadgeType = (userData['confirmedMentorshipBadgeType'] ?? '')
          .toString();
      graduated = userData['graduated'] == true;
      referralCrownType = (userData['confirmedReferralCrownType'] ?? '')
          .toString();
      final savedPosts = await AlphaDenService.loadPosts(user.uid);
      final savedReposts = await AlphaDenService.loadMyReposts(user.uid);
      final followingSnapshot = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .collection('following')
          .get();
      if (!mounted) return;
      if (profile != null) {
        final savedUsername = (profile['username'] ?? '').toString().trim();
        if (savedUsername.isNotEmpty) {
          username = savedUsername.startsWith('@')
              ? savedUsername
              : '@$savedUsername';
        }
        final savedNickname = (profile['nickname'] ?? profile['handle'] ?? '')
            .toString()
            .trim();
        handle = savedNickname.replaceFirst(RegExp(r'^@'), '');
        name = (profile['name'] as String?) ?? name;
        age = (profile['age'] as String?) ?? age;
        sex = (profile['sex'] as String?) ?? sex;
        bio = (profile['bio'] as String?) ?? bio;
        profilePicUrl = (profile['profilePicUrl'] as String?) ?? profilePicUrl;
        final savedProfilePic = (profile['profilePicBase64'] ?? '').toString();
        if (savedProfilePic.isNotEmpty) {
          try {
            profilePicBytes = base64Decode(savedProfilePic);
          } catch (_) {
            profilePicBytes = null;
          }
        }
        final followersSnapshot = await FirebaseFirestore.instance
            .collection('users')
            .doc(user.uid)
            .collection('followers')
            .get();
        followers = followersSnapshot.docs.length;
        following = followingSnapshot.docs.length;
        final alphaPosts = await AlphaDenService.loadPosts(user.uid);
        posts = alphaPosts.length;
        likes = alphaPosts.fold<int>(
          0,
          (sum, post) =>
              sum + ((post['likesCount'] ?? post['likes'] ?? 0) as num).toInt(),
        );
        views = (profile['views'] as num?)?.toInt() ?? views;
        reposts = savedReposts.length;
        referrals = (profile['referrals'] as num?)?.toInt() ?? referrals;
        winTrades = (profile['winTrades'] as num?)?.toInt() ?? winTrades;
        verifiedCreatorApproved =
            (profile['verifiedCreatorApproved'] as bool?) ??
            verifiedCreatorApproved;
        DateTime? readTimestamp(dynamic value) =>
            value is Timestamp ? value.toDate() : null;
        _profilePicChangedAt = readTimestamp(profile['profilePicChangedAt']);
        _usernameChangedAt = readTimestamp(profile['usernameChangedAt']);
        _nicknameChangedAt = readTimestamp(profile['nicknameChangedAt']);
        _bioChangedAt = readTimestamp(profile['bioChangedAt']);
        _sexChangedAt = readTimestamp(profile['sexChangedAt']);
        _ageSetAt = readTimestamp(profile['ageSetAt']);
        if (widget.isAdmin) {
          verifiedCreatorApproved = true;
          winTrades = winTrades < 10 ? 10 : winTrades;
        }
        _usedAlphaDenHandles.add(handle);
      } else {
        if (widget.isAdmin) {
          verifiedCreatorApproved = true;
          winTrades = 10;
        }
        await _persistAlphaProfile();
      }
      if (widget.isAdmin) {
        try {
          await _persistAlphaProfile();
        } catch (_) {}
      }
      _ideas.clear();
      _articles.clear();
      _repostItems.clear();
      for (final rawRepost in savedReposts) {
        _repostItems.add(_AlphaDenRepost.fromMap(rawRepost));
      }
      for (final rawData in savedPosts) {
        final data = _recoverLegacySignal(rawData);
        final sourceType = (data['sourceType'] ?? 'alpha_den').toString();
        if (sourceType == 'article') {
          final rawArticle = (data['text'] ?? '').toString();
          final parts = rawArticle.split('\n\n');
          _articles.add(
            _AlphaDenArticle(
              id: (data['sourceId'] ?? data['id'] ?? '').toString(),
              title:
                  (data['articleTitle'] ??
                          (parts.isNotEmpty
                              ? parts.first
                              : 'Alpha Den Article'))
                      .toString(),
              body:
                  (data['articleBody'] ??
                          (parts.length > 1
                              ? parts.sublist(1).join('\n\n')
                              : rawArticle))
                      .toString(),
              imageBytes:
                  (data['imageBase64'] is String &&
                      (data['imageBase64'] as String).isNotEmpty)
                  ? base64Decode(data['imageBase64'] as String)
                  : null,
              hashtags: List<String>.from(
                (data['hashtags'] as List?) ?? const [],
              ),
              coins: List<String>.from((data['coins'] as List?) ?? const []),
              bullish: data['bullish'] != false,
              likes: (data['likesCount'] as num?)?.toInt() ?? 0,
              comments: (data['commentsCount'] as num?)?.toInt() ?? 0,
              reposts: (data['repostsCount'] as num?)?.toInt() ?? 0,
            ),
          );
          continue;
        }
        _ideas.add(
          _AlphaDenPost(
            id: (data['id'] ?? data['sourceId'] ?? '').toString(),
            authorUid: (data['authorUid'] ?? '').toString(),
            text: (data['text'] as String?) ?? '',
            imageBytes:
                (data['imageBase64'] is String &&
                    (data['imageBase64'] as String).isNotEmpty)
                ? base64Decode(data['imageBase64'] as String)
                : null,
            bullish: (data['bullish'] as bool?) ?? true,
            hashtags: List<String>.from(
              (data['hashtags'] as List?) ?? const [],
            ),
            coins: List<String>.from((data['coins'] as List?) ?? const []),
            signalAsset: data['signalAsset'] as String?,
            signalEntry: data['signalEntry'] as String?,
            signalLongDirection: data['signalLongDirection'] as bool?,
            signalLeverage: (data['signalLeverage'] as num?)?.toInt(),
            signalTp1: data['signalTp1'] as String?,
            signalTp2: data['signalTp2'] as String?,
            signalTp3: data['signalTp3'] as String?,
            signalStopLoss: data['signalStopLoss'] as String?,
            tp1Hit: data['tp1Hit'] == true,
            tp2Hit: data['tp2Hit'] == true,
            tp3Hit: data['tp3Hit'] == true,
            stopLossHit: data['stopLossHit'] == true,
            breakEven: data['breakEven'] == true,
            winTradeCounted: data['winTradeCounted'] == true,
            tp1Profit: (data['tp1Profit'] ?? '').toString(),
            tp2Profit: (data['tp2Profit'] ?? '').toString(),
            tp3Profit: (data['tp3Profit'] ?? '').toString(),
            stopLossProfit: (data['stopLossProfit'] ?? '').toString(),
            breakEvenProfit: (data['breakEvenProfit'] ?? '').toString(),
            winResultImageBytes:
                data['winResultImageBase64'] is String &&
                    (data['winResultImageBase64'] as String).isNotEmpty
                ? _tryDecodeBase64(data['winResultImageBase64'] as String)
                : null,
          ),
        );
      }
      final currentUser = FirebaseAuth.instance.currentUser;
      if (currentUser != null) {
        for (var i = 0; i < _ideas.length; i++) {
          try {
            if (await FeedService.hasPostLikeBySourceId(
              sourceId: _ideas[i].id,
              uid: currentUser.uid,
            ))
              _likedIdeas.add(i);
          } catch (_) {}
        }
        for (final article in _articles) {
          try {
            if (await FeedService.hasPostLikeBySourceId(
              sourceId: article.id,
              uid: currentUser.uid,
            ))
              _likedArticles.add(article.id);
          } catch (_) {}
        }
      }
      posts = _ideas.length + _articles.length;
      setState(() {});
    } catch (_) {
      // Keep the existing UI usable if the backend is temporarily unavailable.
    }
  }

  Future<Uint8List?> _pickWinProofImageBytes() async {
    try {
      final picker = ImagePicker();
      final picked = await picker.pickImage(
        source: ImageSource.gallery,
        imageQuality: 50,
        maxWidth: 900,
        maxHeight: 900,
      );
      if (picked == null) return null;
      final bytes = await picked.readAsBytes();
      if (bytes.isEmpty || bytes.length > 100000) return null;
      return bytes;
    } catch (_) {
      return null;
    }
  }

