  Future<void> _showAlphaPostActions(_AlphaDenPost post) async {
    final currentUid = FirebaseAuth.instance.currentUser?.uid ?? '';
    final isOwner = currentUid.isNotEmpty && currentUid == post.authorUid;
    final canAdminDelete = widget.isAdmin && !isOwner;
    if (!isOwner && !canAdminDelete) {
      await _openContentReportSupportPage(
        context,
        postId: post.id,
        authorUid: post.authorUid,
      );
      return;
    }
    final action = await showModalBottomSheet<String>(
      context: context,
      backgroundColor: AppTheme.adaptiveSurface(Color(0xFF080D13)),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(22)),
      ),
      builder: (sheetContext) => SafeArea(
        child: Padding(
          padding: const EdgeInsets.fromLTRB(10, 6, 10, 8),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              if (isOwner) ...[
                _compactAlphaAction(
                  sheetContext,
                  'edit',
                  Icons.edit_outlined,
                  'Edit post',
                ),
                const SizedBox(height: 4),
                if (post.isSignal) ...[
                  _compactAlphaAction(
                    sheetContext,
                    'win_ratio',
                    Icons.insights_outlined,
                    'Enter Win Ratio',
                    color: AppTheme.neonGreen,
                  ),
                  const SizedBox(height: 4),
                ],
                _compactAlphaAction(
                  sheetContext,
                  'report',
                  Icons.flag_outlined,
                  'Report post',
                ),
                const SizedBox(height: 4),
                _compactAlphaAction(
                  sheetContext,
                  'delete',
                  Icons.delete_outline,
                  'Delete post',
                  color: const Color(0xFFE05252),
                ),
              ] else if (canAdminDelete) ...[
                _compactAlphaAction(
                  sheetContext,
                  'admin_delete',
                  Icons.delete_forever_outlined,
                  'Admin delete Alpha Den post',
                  color: const Color(0xFFE05252),
                ),
              ],
            ],
          ),
        ),
      ),
    );
    if (!mounted || action == null) return;
    // Let the bottom-sheet reverse animation fully deactivate before opening
    // another route/dialog. This prevents Navigator dependent-tree assertions
    // when SAVE/DELETE is tapped immediately after the sheet closes.
    await Future<void>.delayed(const Duration(milliseconds: 360));
    if (!mounted) return;

    if (action == 'win_ratio') {
      await _enterSignalOutcome(post);
      return;
    }

    if (action == 'report') {
      await _openContentReportSupportPage(
        context,
        postId: post.id,
        authorUid: post.authorUid,
      );
      return;
    }

    if (action == 'admin_delete' || action == 'delete') {
      final confirmed = await showDialog<bool>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          title: const Text('DELETE POST'),
          content: Text(
            action == 'admin_delete'
                ? 'Delete this Alpha Den post as an administrator? This will also remove its CD Feed copy.'
                : 'Delete this Alpha Den post? This will also remove its CD Feed copy.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('CANCEL'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('DELETE'),
            ),
          ],
        ),
      );
      if (confirmed != true || !mounted) return;
      final user = FirebaseAuth.instance.currentUser;
      if (user == null || post.id.isEmpty) return;
      try {
        await FeedService.deletePost(
          post.id,
          authorUid: post.authorUid,
          requesterUid: user.uid,
          adminDelete: action == 'admin_delete' && widget.isAdmin,
        );
        setState(() {
          _ideas.removeWhere((item) => item.id == post.id);
          posts = _ideas.length + _articles.length;
        });
        await _persistAlphaProfile();
      } catch (_) {
        if (mounted)
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('Could not delete this post.')),
          );
      }
      return;
    }

    final controller = TextEditingController(text: post.text);
    String? updatedText;
    try {
      updatedText = await showDialog<String>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          title: const Text('EDIT POST'),
          content: TextField(
            controller: controller,
            autofocus: true,
            maxLines: 5,
            decoration: const InputDecoration(hintText: 'Post text'),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('CANCEL'),
            ),
            FilledButton(
              onPressed: () =>
                  Navigator.pop(dialogContext, controller.text.trim()),
              child: const Text('SAVE'),
            ),
          ],
        ),
      );
    } finally {
      controller.dispose();
    }
    if (!mounted ||
        updatedText == null ||
        updatedText.isEmpty ||
        post.id.isEmpty)
      return;
    final editedText = updatedText;
    await Future<void>.delayed(Duration.zero);
    if (!mounted) return;
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;
    try {
      await FeedService.updatePost(
        post.id,
        authorUid: user.uid,
        text: updatedText,
      );
      final index = _ideas.indexOf(post);
      if (index >= 0) {
        setState(() {
          _ideas[index] = _AlphaDenPost(
            id: post.id,
            authorUid: post.authorUid,
            text: editedText,
            imageBytes: post.imageBytes,
            thumbnailBytes: post.thumbnailBytes,
            bullish: post.bullish,
            hashtags: List<String>.from(post.hashtags),
            coins: List<String>.from(post.coins),
            signalAsset: post.signalAsset,
            signalEntry: post.signalEntry,
            signalLongDirection: post.signalLongDirection,
            signalLeverage: post.signalLeverage,
            signalTp1: post.signalTp1,
            signalTp2: post.signalTp2,
            signalTp3: post.signalTp3,
            signalStopLoss: post.signalStopLoss,
          );
        });
      }
    } catch (_) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Could not update this post.')),
        );
    }
  }

  Future<void> _persistAlphaProfile() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;
    try {
      final profileImage = _safeImageBase64(profilePicBytes);
      await AlphaDenService.saveProfile(
        uid: user.uid,
        username: username,
        handle: handle,
        name: name,
        age: age,
        sex: sex,
        bio: bio,
        profilePicUrl: profilePicUrl,
        followers: followers,
        posts: posts,
        likes: likes,
        views: views,
        reposts: reposts,
        referrals: referrals,
        verified: verifiedCreatorApproved,
        winTrades: winTrades,
        profilePicBase64: profileImage,
        profilePicChangedAt: _profilePicChangedAt,
        nicknameChangedAt: _nicknameChangedAt,
        bioChangedAt: _bioChangedAt,
        sexChangedAt: _sexChangedAt,
        ageSetAt: _ageSetAt,
      );
      try {
        await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
          'alphaDenProfile': {
            'username': username.startsWith('@') ? username : '@$username',
            'usernameNormalized': username
                .replaceFirst(RegExp(r'^@'), '')
                .trim()
                .toLowerCase(),
            'nickname': handle.replaceFirst(RegExp(r'^@'), ''),
            'handle': handle.replaceFirst(RegExp(r'^@'), ''),
            if (_usernameChangedAt != null)
              'usernameChangedAt': Timestamp.fromDate(_usernameChangedAt!),
            if (_nicknameChangedAt != null)
              'nicknameChangedAt': Timestamp.fromDate(_nicknameChangedAt!),
            'flamingAuraCrown': widget.isAdmin,
          },
        }, SetOptions(merge: true));
      } catch (_) {}
      try {
        await AlphaDenService.syncPublicProfileToPosts(
          uid: user.uid,
          username: username,
          profilePicUrl: profilePicUrl,
          profilePicBase64: profileImage,
          referrals: referrals,
          verified: verifiedCreatorApproved,
          winTrades: winTrades,
        );
      } catch (_) {}
    } catch (_) {}
  }

  Future<void> _toggleAlphaDenRepost({
    required String postId,
    required Map<String, dynamic> snapshot,
    _AlphaDenRepost? existing,
  }) async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null || postId.trim().isEmpty) return;
    try {
      if (existing != null) {
        await AlphaDenService.deleteRepost(uid: user.uid, postId: postId);
        await FeedService.togglePostRepostBySourceId(
          sourceId: postId,
          uid: user.uid,
          reposted: false,
        );
        reposts = reposts > 0 ? reposts - 1 : 0;
        await _persistAlphaProfile();
        if (!mounted) return;
        setState(
          () =>
              _repostItems.removeWhere((item) => item.originalPostId == postId),
        );
        ScaffoldMessenger.of(context)
            .showSnackBar(const SnackBar(content: Text('Repost removed.')));
      } else {
        await AlphaDenService.createRepost(
          uid: user.uid,
          postId: postId,
          snapshot: snapshot,
        );
        await FeedService.togglePostRepostBySourceId(
          sourceId: postId,
          uid: user.uid,
          reposted: true,
        );
        reposts += 1;
        await _persistAlphaProfile();
        if (!mounted) return;
        setState(
          () => _repostItems.insert(
            0,
            _AlphaDenRepost.fromMap({
              ...snapshot,
              'originalPostId': postId,
              'reposterUid': user.uid,
              'createdAt': Timestamp.now(),
            }),
          ),
        );
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Reposted to your Alpha Den.')),
        );
      }
    } catch (_) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not update the repost. Please try again.'),
          ),
        );
    }
  }

