  bool _withinSevenDays(DateTime? changedAt) =>
      changedAt != null &&
      DateTime.now().difference(changedAt).inHours < 24 * 7;

  Future<bool> _checkSevenDayLock(DateTime? changedAt, String label) async {
    if (!_withinSevenDays(changedAt)) return true;
    final remaining = const Duration(days: 7);
    final elapsed = DateTime.now().difference(changedAt!);
    final left = remaining - elapsed;
    final days = left.inHours ~/ 24;
    final hours = left.inHours % 24;
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('$label can be changed again in ${days}d ${hours}h.'),
        ),
      );
    }
    return false;
  }

