    if (!mounted) return;
    final controller = TextEditingController(
      text: username.startsWith('@') ? username : '@$username',
    );
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: AppTheme.adaptiveSurface(Color(0xFF080D13)),
        title: const Text('EDIT USERNAME'),
        content: TextField(
          controller: controller,
          autofocus: true,
          maxLength: 20,
          decoration: const InputDecoration(hintText: 'unique username'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('CANCEL'),
          ),
          ElevatedButton(
            onPressed: () async {
              var value = controller.text.trim().toLowerCase();
              if (!value.startsWith('@')) value = '@$value';
              if (!RegExp(r'^@[a-z0-9_]{1,20}$').hasMatch(value)) {
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(
                    content: Text(
                      'Username: start with @ and use lowercase letters, numbers, and _ only.',
                    ),
                  ),
                );
                return;
              }
              if (value ==
                  (username.startsWith('@') ? username : '@$username')
                      .trim()
                      .toLowerCase()) {
                if (dialogContext.mounted) Navigator.pop(dialogContext);
                return;
              }
              final user = FirebaseAuth.instance.currentUser;
              if (user == null) return;
              try {
                final taken = await FirebaseFirestore.instance
                    .collection('users')
                    .where(
                      'alphaDenProfile.usernameNormalized',
                      isEqualTo: value.replaceFirst(RegExp(r'^@'), ''),
                    )
                    .limit(2)
                    .get();
                final takenByOther = taken.docs.any(
                  (doc) => doc.id != user.uid,
                );
                if (takenByOther) {
                  if (mounted)
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(
                        content: Text('That username is already taken.'),
                      ),
                    );
                  return;
                }
                final now = DateTime.now();
                setState(() {
                  username = value;
                  _usernameChangedAt = now;
                });
                await FirebaseFirestore.instance
                    .collection('users')
                    .doc(user.uid)
                    .set({
                      'alphaDenProfile': {
                        'username': value,
                        'usernameNormalized': value.replaceFirst(
                          RegExp(r'^@'),
                          '',
                        ),
                        'nickname': handle.replaceFirst(RegExp(r'^@'), ''),
                        'handle': handle.replaceFirst(RegExp(r'^@'), ''),
                        'usernameChangedAt': Timestamp.fromDate(now),
                      },
                    }, SetOptions(merge: true));
                if (dialogContext.mounted) Navigator.pop(dialogContext);
              } catch (_) {
                if (mounted)
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(
                      content: Text(
                        'Could not update the username right now. Please try again.',
                      ),
                    ),
                  );
              }
            },
            child: const Text('SAVE'),
          ),
        ],
      ),
    );
    await WidgetsBinding.instance.endOfFrame;
    await WidgetsBinding.instance.endOfFrame;
    controller.dispose();
    await _persistAlphaProfile();
  }

  Future<void> _editNickname() async {
