  Future<void> _createPostSignal() async {
    final post = await Navigator.push<_AlphaDenPost>(
      context,
      PageRouteBuilder(
        transitionDuration: const Duration(milliseconds: 420),
        pageBuilder: (_, animation, _) => const _AlphaDenSignalComposerPage(),
        transitionsBuilder: (_, animation, _, child) => FadeTransition(
          opacity: CurvedAnimation(
            parent: animation,
            curve: Curves.easeOutCubic,
          ),
          child: ScaleTransition(
            scale: Tween<double>(begin: 0.94, end: 1.0).animate(
              CurvedAnimation(parent: animation, curve: Curves.easeOutBack),
            ),
            child: child,
          ),
        ),
      ),
    );
    if (post == null || !mounted) return;
    setState(() {
      _ideas.insert(0, post);
      posts = _ideas.length + _articles.length;
    });
    final user = FirebaseAuth.instance.currentUser;
    if (user != null) {
      await AlphaDenService.createPost(
        uid: user.uid,
        text: _alphaDenSignalSummary(post),
        bullish: post.bullish,
        isSignal: true,
        signalAsset: post.signalAsset,
        signalEntry: post.signalEntry,
        signalLongDirection: post.signalLongDirection,
        signalLeverage: post.signalLeverage,
        signalTp1: post.signalTp1,
        signalTp2: post.signalTp2,
        signalTp3: post.signalTp3,
        signalStopLoss: post.signalStopLoss,
        hashtags: post.hashtags,
        coins: post.coins,
      );
    }
    await _persistAlphaProfile();
    final publishedId = await _publishToCommunityFeed(
      _CommunityPost(
        id: 'alpha-signal-${DateTime.now().microsecondsSinceEpoch}',
        username: username,
        nickname: handle,
        profilePicUrl: profilePicUrl,
        profilePicBytes: profilePicBytes,
        badge: _referralBadgeLabel(referrals),
        referrals: referrals,
        verified: verifiedCreatorApproved,
        isPremium: isPremium,
        winTrades: winTrades,
        text: _alphaDenSignalSummary(post),
        imageBytes: post.imageBytes,
        thumbnailBytes: null,
        bullish: post.bullish,
        hashtags: List<String>.from(post.hashtags),
        coins: post.signalAsset == null
            ? const <String>[]
            : <String>[post.signalAsset!],
        signalAsset: post.signalAsset,
        signalEntry: post.signalEntry,
        signalLongDirection: post.signalLongDirection,
        signalLeverage: post.signalLeverage,
        signalTp1: post.signalTp1,
        signalTp2: post.signalTp2,
        signalTp3: post.signalTp3,
        signalStopLoss: post.signalStopLoss,
        createdAt: DateTime.now(),
        tp1Hit: post.tp1Hit,
        tp2Hit: post.tp2Hit,
        tp3Hit: post.tp3Hit,
        stopLossHit: post.stopLossHit,
        breakEven: post.breakEven,
        winTradeCounted: post.winTradeCounted,
        tp1Profit: post.tp1Profit,
        tp2Profit: post.tp2Profit,
        tp3Profit: post.tp3Profit,
      ),
      sourceType: 'alpha_den',
    );
    final signalIndex = _ideas.indexOf(post);
    if (signalIndex >= 0 && mounted) {
      setState(() => _ideas[signalIndex] = post.copyWith(id: publishedId));
    }
  }

