  Future<void> _resetAlphaDenProfile() async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: AppTheme.adaptiveSurface(Color(0xFF080D13)),
        title: const Text('RESET ALPHA DEN PROFILE'),
        content: const Text(
          'This will clear your Alpha Den username, nickname, bio, profile picture, age, sex, verification state, referral display and Win Trade profile progress. Your account itself will not be deleted.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('CANCEL'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('RESET'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;
    try {
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
        'alphaDenProfile': FieldValue.delete(),
      }, SetOptions(merge: true));
      if (!mounted) return;
      setState(() {
        username = '@userxxxx';
        handle = '';
        name = '';
        age = '';
        sex = '';
        bio = '';
        profilePicUrl = '';
        profilePicBytes = null;
        followers = 0;
        posts = 0;
        likes = 0;
        views = 0;
        reposts = 0;
        referrals = 0;
        winTrades = 0;
        verifiedCreatorApproved = false;
        verificationPaymentSubmitted = false;
        _profilePicChangedAt = null;
        _usernameChangedAt = null;
        _nicknameChangedAt = null;
        _bioChangedAt = null;
        _sexChangedAt = null;
        _ageSetAt = null;
        if (widget.isAdmin) {
          verifiedCreatorApproved = true;
          winTrades = 10;
        }
        _ideas.clear();
        _articles.clear();
        _repostItems.clear();
      });
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Alpha Den profile reset. You can create it again from scratch.',
          ),
        ),
      );
    } catch (_) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not reset the Alpha Den profile right now.'),
          ),
        );
    }
  }

  Future<void> _showVerifiedCreatorDialog() async {
    if (verifiedCreatorApproved) {
      await showDialog<void>(
        context: context,
        builder: (_) => AlertDialog(
          backgroundColor: AppTheme.adaptiveSurface(Color(0xFF080D13)),
          title: const Text('VERIFIED CREATOR'),
          content: const Text(
            'Your payment has been accepted and the verified creator status is active. The blue tick is displayed on your profile and posts.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context),
              child: const Text('CLOSE'),
            ),
          ],
        ),
      );
      return;
    }
    // The application page is intentionally open so creators can read the full
    // requirements and payment/security terms before submitting. Eligibility
    // is still stated as 3+ qualified Win Trades and approval is not automatic.
    await Navigator.of(context).push<void>(
      PageRouteBuilder(
        transitionDuration: const Duration(milliseconds: 420),
        pageBuilder: (_, animation, _) => _VerifiedCreatorPaymentPage(
          paymentSubmitted: verificationPaymentSubmitted,
          onPaymentSubmitted: () {
            if (mounted) setState(() => verificationPaymentSubmitted = true);
          },
        ),
        transitionsBuilder: (_, animation, _, child) => FadeTransition(
          opacity: CurvedAnimation(
            parent: animation,
            curve: Curves.easeOutCubic,
          ),
          child: child,
        ),
      ),
    );
  }

  Future<void> _openAlphaDenArticleComposer() async {
    final article = await Navigator.of(context).push<_AlphaDenArticle>(
      PageRouteBuilder(
        transitionDuration: const Duration(milliseconds: 420),
        pageBuilder: (_, animation, _) => const _AlphaDenArticleComposerPage(),
        transitionsBuilder: (_, animation, _, child) => FadeTransition(
          opacity: CurvedAnimation(
            parent: animation,
            curve: Curves.easeOutCubic,
          ),
          child: SlideTransition(
            position:
                Tween<Offset>(
                  begin: const Offset(0.05, 0),
                  end: Offset.zero,
                ).animate(
                  CurvedAnimation(
                    parent: animation,
                    curve: Curves.easeOutCubic,
                  ),
                ),
            child: child,
          ),
        ),
      ),
    );
    if (article == null || !mounted) return;
    setState(() {
      _articles.insert(0, article);
      posts = _ideas.length + _articles.length;
    });
    await _persistAlphaProfile();
    final publishedId = await _publishToCommunityFeed(
      _CommunityPost(
        id: 'alpha-article-${article.id}',
        username: username,
        nickname: handle,
        profilePicUrl: profilePicUrl,
        profilePicBytes: profilePicBytes,
        badge: _referralBadgeLabel(referrals),
        referrals: referrals,
        verified: verifiedCreatorApproved,
        winTrades: winTrades,
        text: '${article.title}\n\n${article.body}',
        imageBytes: article.imageBytes,
        thumbnailBytes: null,
        bullish: article.bullish,
        hashtags: List<String>.from(article.hashtags),
        coins: List<String>.from(article.coins),
        createdAt: DateTime.now(),
      ),
      sourceType: 'article',
      sourceId: article.id,
    );
    if (publishedId.isNotEmpty && mounted) {
      setState(() {});
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.transparent,
      appBar: AppBar(
        backgroundColor: AppTheme.adaptiveSurface(Color(0xFF080D13)),
        surfaceTintColor: Colors.transparent,
        elevation: 0,
        leading: IconButton(
          icon: const Icon(Icons.arrow_back_ios_new),
