              },
              child: ListView(
                physics: const AlwaysScrollableScrollPhysics(),
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 40),
                children: [
                  _WinRateProfileAura(
                    winTrades: winTrades,
                    child: Padding(
                      padding: const EdgeInsets.all(1.5),
                      child: Column(
                        children: [
                          _AlphaDenProfileHeader(
                            username: username,
                            handle: handle,
                            name: name,
                            age: age,
                            sex: sex,
                            profilePicUrl: profilePicUrl,
                            profilePicBytes: profilePicBytes,
                            verified: verifiedCreatorApproved,
                            followers: followers,
                            following: following,
                            posts: posts,
                            likes: likes,
                            views: views,
                            reposts: reposts,
                            referrals: referrals,
                            winTrades: winTrades,
                            bio: bio,
                            flamingAuraCrown: winTrades >= 10,
                            isPremium: isPremium,
                            hasMentorship: hasMentorship,
                            premiumBadgeType: premiumBadgeType,
                            mentorshipBadgeType: mentorshipBadgeType,
                            graduated: graduated,
                            referralCrownType: referralCrownType,
                          ),
                          const SizedBox(height: 14),
                          _AlphaDenSectionTabs(
                            currentIndex: _alphaDenPage,
                            onTap: (index) =>
                                _alphaDenPageController.animateToPage(
                                  index,
                                  duration: const Duration(milliseconds: 420),
                                  curve: Curves.easeOutCubic,
                                ),
                          ),
                          const SizedBox(height: 12),
                          SizedBox(
                            height: 500,
                            child: PageView(
                              controller: _alphaDenPageController,
                              physics: const BouncingScrollPhysics(),
                              onPageChanged: (index) =>
