                              children: [
                                _AlphaDenIdeasPage(
                                  ideas: _ideas,
                                  likedIdeas: _likedIdeas,
                                  onLike: (index) async {
                                    final user =
                                        FirebaseAuth.instance.currentUser;
                                    if (user == null) return;
                                    final post = _ideas[index];
                                    final next = !_likedIdeas.contains(index);
                                    setState(() {
                                      if (next)
                                        _likedIdeas.add(index);
                                      else
                                        _likedIdeas.remove(index);
                                    });
                                    try {
                                      await FeedService.togglePostLikeBySourceId(
                                        sourceId: post.id,
                                        uid: user.uid,
                                        liked: next,
                                      );
                                      await _persistAlphaProfile();
                                    } catch (_) {}
                                  },
                                  onRepost: (index) {
                                    final post = _ideas[index];
                                    _toggleAlphaDenRepost(
                                      postId: post.id,
                                      snapshot: _repostSnapshotForPost(post),
                                    );
                                  },
                                  onShare: (index) {
                                    final post = _ideas[index];
                                    final user =
                                        FirebaseAuth.instance.currentUser;
                                    if (user != null)
                                      FeedService.findPostIdBySourceId(post.id)
                                          .then((id) {
                                            if (id != null)
                                              FeedService.recordShare(
                                                postId: id,
                                                uid: user.uid,
                                              );
                                          });
                                  },
                                ),
                                _AlphaDenSignalsPage(
                                  signals: _ideas
                                      .where((post) => post.isSignal)
                                      .toList(),
                                  onRepost: (index) {
                                    final signals = _ideas
                                        .where((post) => post.isSignal)
                                        .toList();
                                    final post = signals[index];
                                    _toggleAlphaDenRepost(
                                      postId: post.id,
                                      snapshot: _repostSnapshotForPost(post),
                                    );
                                  },
                                  onShare: (index) {
                                    final signals = _ideas
                                        .where((post) => post.isSignal)
                                        .toList();
                                    final post = signals[index];
                                    final user =
                                        FirebaseAuth.instance.currentUser;
                                    if (user != null)
                                      FeedService.findPostIdBySourceId(post.id)
                                          .then((id) {
                                            if (id != null)
                                              FeedService.recordShare(
                                                postId: id,
                                                uid: user.uid,
                                              );
                                          });
                                  },
                                ),
                                _AlphaDenArticlesPage(
                                  articles: _articles,
                                  likedArticles: _likedArticles,
                                  onLike: (id) async {
                                    final article = _articles.firstWhere(
                                      (a) => a.id == id,
                                    );
                                    final user =
                                        FirebaseAuth.instance.currentUser;
                                    if (user == null) return;
                                    final next = !_likedArticles.contains(id);
                                    setState(() {
                                      if (next)
                                        _likedArticles.add(id);
                                      else
                                        _likedArticles.remove(id);
                                      article.likes =
                                          (article.likes + (next ? 1 : -1))
                                              .clamp(0, 1000000)
                                              .toInt();
                                    });
                                    try {
                                      await FeedService.togglePostLikeBySourceId(
                                        sourceId: id,
                                        uid: user.uid,
                                        liked: next,
                                      );
                                      await _persistAlphaProfile();
                                    } catch (_) {}
                                  },
                                  onRepost: (id) {
                                    final article = _articles.firstWhere(
                                      (a) => a.id == id,
                                    );
                                    _toggleAlphaDenRepost(
                                      postId: 'article_${article.id}',
                                      snapshot: _repostSnapshotForArticle(
                                        article,
                                      ),
                                    );
                                  },
                                ),
                                _AlphaDenRepostsPage(
                                  items: _repostItems,
                                  onDelete: (item) => _toggleAlphaDenRepost(
                                    postId: item.originalPostId,
                                    snapshot: item.toMap(),
                                    existing: item,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
          Positioned(
            right: 0,
            top: MediaQuery.sizeOf(context).height * 0.70 - 29,
            child: _AlphaDenPlusButton(onPressed: _openAlphaDenCreateMenu),
          ),
        ],
      ),
    );
  }
}

class _WinRateProfileAura extends StatefulWidget {
  final int winTrades;
  final Widget child;
  const _WinRateProfileAura({required this.winTrades, required this.child});

  @override
  State<_WinRateProfileAura> createState() => _WinRateProfileAuraState();
}

class _WinRateProfileAuraState extends State<_WinRateProfileAura>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 2200),
  )..repeat();

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final wins = widget.winTrades;
    if (wins < 5) return widget.child;
    final tier8 = wins >= 8;
    final tier10 = wins >= 10;

    return AnimatedBuilder(
      animation: _controller,
      child: widget.child,
      builder: (context, child) {
        final pulse =
            0.72 + (math.sin(_controller.value * math.pi * 2) + 1) * 0.14;
        final gold = AppTheme.luxuryGold.withValues(alpha: pulse);
        final cyan = const Color(0xFF59D7FF)
            .withValues(alpha: tier8 ? pulse * 0.62 : 0.0);
        final red = const Color(0xFFFF4D5E)
            .withValues(alpha: tier8 ? pulse * (tier10 ? 0.90 : 0.62) : 0.0);
        final orange = const Color(0xFFFF8A3D)
            .withValues(alpha: tier10 ? pulse * 0.82 : 0.0);
        return Container(
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(29),
            gradient: LinearGradient(
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
              colors: tier10
                  ? [
                      const Color(0x22FFD54A),
                      const Color(0x12000000),
                      const Color(0x22FF4D5E),
                    ]
                  : tier8
                  ? [
                      const Color(0x1459D7FF),
                      const Color(0x10000000),
                      const Color(0x14FF4D5E),
                    ]
                  : [
                      const Color(0x18FFD54A),
                      const Color(0x0A000000),
                      const Color(0x10FFD54A),
                    ],
            ),
            boxShadow: [
              BoxShadow(
                color: gold,
                blurRadius: tier10 ? 30 : 20,
                spreadRadius: tier10 ? 2 : 1,
              ),
              if (tier8)
                BoxShadow(color: cyan, blurRadius: 28, spreadRadius: 1),
              if (tier8)
                BoxShadow(
                  color: red,
                  blurRadius: tier10 ? 38 : 22,
                  spreadRadius: tier10 ? 4 : 1,
                ),
              if (tier10)
                BoxShadow(color: orange, blurRadius: 48, spreadRadius: 5),
              BoxShadow(
                color: Colors.black.withValues(alpha: .55),
                blurRadius: 10,
                offset: const Offset(0, 7),
              ),
            ],
          ),
          child: DecoratedBox(
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(26),
              border: Border.all(
                color: tier10
                    ? red
                    : tier8
                    ? cyan
                    : gold,
                width: tier10 ? 1.35 : 1.05,
              ),
            ),
            child: Stack(
              children: [
                Positioned.fill(
                  child: IgnorePointer(
                    child: CustomPaint(
                      painter: _WinRateDepthPainter(
                        progress: _controller.value,
                        tier8: tier8,
                        tier10: tier10,
                      ),
                    ),
                  ),
                ),
                if (tier10)
                  Positioned.fill(
                    child: IgnorePointer(
                      child: CustomPaint(
                        painter: _WinRateFlameAuraPainter(
                          progress: _controller.value,
                        ),
                      ),
                    ),
                  ),
                child!,
              ],
            ),
          ),
        );
      },
    );
  }
}

class _WinRateDepthPainter extends CustomPainter {
  final double progress;
  final bool tier8;
  final bool tier10;
  const _WinRateDepthPainter({
    required this.progress,
    required this.tier8,
    required this.tier10,
  });
  @override
  void paint(Canvas canvas, Size size) {
    final pulse = .5 + .5 * math.sin(progress * math.pi * 2);
    final p = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = tier10 ? 1.4 : 1.0
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3.5);
    p.color =
        (tier10
                ? const Color(0xFFFF8A3D)
                : tier8
                ? const Color(0xFF59D7FF)
                : AppTheme.luxuryGold)
            .withValues(alpha: .20 + pulse * .14);
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        Rect.fromLTWH(2, 2, size.width - 4, size.height - 4),
        const Radius.circular(25),
      ),
      p,
    );
    final hi = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = .8
      ..color = AppTheme.adaptiveWhite(alpha: .10 + pulse * .08);
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        Rect.fromLTWH(4, 4, size.width - 8, size.height - 8),
        const Radius.circular(23),
      ),
      hi,
    );
  }

  @override
  bool shouldRepaint(covariant _WinRateDepthPainter oldDelegate) =>
      oldDelegate.progress != progress ||
      oldDelegate.tier8 != tier8 ||
      oldDelegate.tier10 != tier10;
}

class _WinRateFlameAuraPainter extends CustomPainter {
  final double progress;
  const _WinRateFlameAuraPainter({required this.progress});
  @override
  void paint(Canvas canvas, Size size) {
    final t = progress * math.pi * 2;
    void flame(Offset base, double w, double h, double phase, bool up) {
      final sway = math.sin(t + phase) * w * .18;
      final dir = up ? -1.0 : 1.0;
      final tip = Offset(base.dx + sway, base.dy + dir * h);
      final path = Path()
        ..moveTo(base.dx - w * .5, base.dy)
        ..quadraticBezierTo(
          base.dx - w * .18,
          base.dy + dir * h * .42,
          tip.dx,
          tip.dy,
        )
        ..quadraticBezierTo(
          base.dx + w * .18,
          base.dy + dir * h * .42,
          base.dx + w * .5,
          base.dy,
        )
        ..close();
      canvas.drawPath(
        path,
        Paint()
          ..color = const Color(0xFFFF3B24).withValues(alpha: .30)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3.5),
      );
      final mid = Path()
        ..moveTo(base.dx - w * .34, base.dy)
        ..quadraticBezierTo(
          base.dx - w * .10,
          base.dy + dir * h * .30,
          tip.dx,
          tip.dy + dir * 2,
        )
        ..quadraticBezierTo(
          base.dx + w * .10,
          base.dy + dir * h * .30,
          base.dx + w * .34,
          base.dy,
        )
        ..close();
      canvas.drawPath(
        mid,
        Paint()
          ..color = const Color(0xFFFF8A21).withValues(alpha: .55)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 2),
      );
      final inner = Path()
        ..moveTo(base.dx - w * .18, base.dy)
        ..quadraticBezierTo(
          base.dx,
          base.dy + dir * h * .26,
          tip.dx,
          tip.dy + dir * 4,
        )
        ..quadraticBezierTo(
          base.dx,
          base.dy + dir * h * .26,
          base.dx + w * .18,
          base.dy,
        )
        ..close();
      canvas.drawPath(
        inner,
        Paint()..color = const Color(0xFFFFD54A).withValues(alpha: .76),
      );
    }

    for (var i = 0; i < 11; i++) {
      final x = size.width * (i + .5) / 11;
      flame(Offset(x, 2), 12, 12 + 6 * ((i + 1) % 3), t + i, true);
      flame(
        Offset(x, size.height - 2),
        12,
        10 + 5 * ((i + 2) % 3),
        t + i * 1.7,
        false,
      );
    }
    for (var i = 0; i < 7; i++) {
      final y = size.height * (i + .5) / 7;
      flame(Offset(2, y), 10, 11 + 5 * (i % 3), t + i * 1.3, false);
      flame(
        Offset(size.width - 2, y),
        10,
        11 + 5 * ((i + 1) % 3),
        t + i * 1.8,
        false,
      );
    }
  }

  @override
  bool shouldRepaint(covariant _WinRateFlameAuraPainter oldDelegate) =>
      oldDelegate.progress != progress;
}

