String _officialCrownName(int referrals) {
  if (referrals >= 10) return 'BLACK + GOLD CROWN';
  if (referrals >= 5 && referrals <= 9) return 'GOLDEN CROWN';
  if (referrals >= 3 && referrals <= 4) return 'PURPLE CROWN';
  if (referrals >= 1 && referrals <= 2) return 'BLUE CROWN';
  return 'BROWN CROWN';
}

String _crownRequirement(int referrals) {
  if (referrals >= 10) return '10+ qualified referrals.';
  if (referrals >= 8)
    return '8Ã¢â‚¬â€œ9 qualified referrals; this is the enhanced GOLDEN CROWN glow tier.';
  if (referrals >= 5) return '5Ã¢â‚¬â€œ7 qualified referrals.';
  if (referrals >= 3) return '3Ã¢â‚¬â€œ4 qualified referrals.';
  if (referrals >= 1) return '1Ã¢â‚¬â€œ2 qualified referrals.';
  return '0 qualified referrals.';
}

Future<void> _showCrownInfo(BuildContext context, int referrals) =>
    _showProfileBadgeInfo(
      context,
      name: _officialCrownName(referrals),
      meaning: 'Referral-based Alpha Den crown tier.',
      requirement: _crownRequirement(referrals),
      earned: 'The crown reflects the accountÃ¢â‚¬â„¢s current qualified referral count. At 10+ qualified referrals the BLACK + GOLD CROWN includes the existing corner flame aura.',
    );

Future<void> _showPremiumInfo(BuildContext context, String badgeType) =>
    _showProfileBadgeInfo(
      context,
      name: badgeType == 'premium_lifetime' ? 'LIFETIME PREMIUM' : 'PREMIUM',
      meaning: badgeType == 'premium_lifetime'
          ? 'Purple Lifetime Star badge.'
          : 'Normal Premium Star badge.',
      requirement: badgeType == 'premium_lifetime'
          ? 'Lifetime Premium access must be confirmed for the account.'
          : 'Monthly Premium access must be confirmed for the account.',
      earned: badgeType == 'premium_lifetime'
          ? 'Granted after the Lifetime Premium entitlement is confirmed.'
          : 'Granted after the Monthly Premium entitlement is confirmed.',
    );

Future<void> _showStudentInfo(BuildContext context, String badgeType) =>
    _showProfileBadgeInfo(
      context,
      name: _studentBadgeLabel(badgeType),
      meaning: _studentBadgeMeaning(badgeType),
      requirement: _studentBadgeRequirement(badgeType),
      earned: _studentBadgeEarned(badgeType),
    );

String _studentBadgeLabel(String badgeType) {
  switch (badgeType) {
    case 'mentorship_installment_1':
      return 'STUDENT 1';
    case 'mentorship_installment_2':
      return 'STUDENT 2';
    case 'mentorship_installment_3':
      return 'STUDENT 3';
    case 'mentorship_installment_4':
      return 'STUDENT 4';
    case 'mentorship_installment':
      return 'STUDENT 1';
    default:
      return 'STUDENT';
  }
}

String _studentBadgeMeaning(String badgeType) {
  if (badgeType == 'mentorship_installment_4')
    return 'Fourth installment progress badge with the white Student 4 cap. The separate Graduated badge is awarded by Admin.';
  if (badgeType.startsWith('mentorship_installment_'))
    return 'Mentorship installment progress badge for the completed payment stage.';
  if (badgeType == 'mentorship_installment')
    return 'Mentorship installment Student 1 badge.';
  return 'Mentorship One-Time Student badge.';
}

String _studentBadgeRequirement(String badgeType) {
  switch (badgeType) {
    case 'mentorship_installment_1':
      return 'First \$20 installment must be verified.';
    case 'mentorship_installment_2':
      return 'Second \$20 installment must be verified.';
    case 'mentorship_installment_3':
      return 'Third \$20 installment must be verified.';
    case 'mentorship_installment_4':
      return 'Fourth and final \$20 installment must be verified.';
    case 'mentorship_installment':
      return 'Mentorship Installment entitlement must be confirmed.';
    default:
      return 'Mentorship One-Time entitlement must be confirmed.';
  }
}

String _studentBadgeEarned(String badgeType) {
  if (badgeType == 'mentorship_installment_4')
    return 'After the fourth installment is confirmed, the white Student 4 cap is shown. Graduation is a separate Admin-awarded badge.';
  final match = RegExp(r'mentorship_installment_([1-3])').firstMatch(badgeType);
  if (match != null)
    return 'After installment ${match.group(1)} is confirmed from Mail, the corresponding Student ${match.group(1)} cap is shown on the Alpha Den profile.';
  if (badgeType == 'mentorship_installment')
    return 'Granted after the installment mentorship entitlement is confirmed.';
  return 'Granted after the one-time mentorship entitlement is confirmed.';
}

Future<void> _showVerifiedCreatorInfo(BuildContext context) =>
    _showProfileBadgeInfo(
      context,
      name: 'VERIFIED CREATOR',
      meaning: 'Approved Verified Creator account identified by the blue tick.',
      requirement: 'At least 3 qualified Win Trades are required to submit an application; approval is reviewed by the platform.',
      earned: 'Granted after Verified Creator review and approval. Approval is not automatic.',
    );

int _referralsForConfirmedCrown(String type) {
  switch (type) {
    case 'referral_crown_blue':
      return 1;
    case 'referral_crown_purple':
      return 3;
    case 'referral_crown_gold':
      return 5;
    case 'referral_crown_black_gold':
      return 10;
    default:
      return 0;
  }
}

