class _PostNewIdeaTwinkle extends StatefulWidget {
  const _PostNewIdeaTwinkle();

  @override
  State<_PostNewIdeaTwinkle> createState() => _PostNewIdeaTwinkleState();
}

class _PostNewIdeaTwinkleState extends State<_PostNewIdeaTwinkle>
    with SingleTickerProviderStateMixin {
  late final AnimationController _twinkleController;

  @override
  void initState() {
    super.initState();
    _twinkleController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1800),
    )..repeat(reverse: true);
  }

  @override
  void dispose() {
    _twinkleController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Center(
      child: AnimatedBuilder(
        animation: _twinkleController,
        builder: (context, child) {
          final glow = 0.35 + (_twinkleController.value * 0.45);
          return Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                Icons.auto_awesome,
                size: 13,
                color: AppTheme.adaptiveWhite(alpha: glow),
              ),
              const SizedBox(width: 8),
              Text(
                'Post new idea',
                style: TextStyle(
                  color: AppTheme.adaptiveWhite(
                    alpha: 0.42 + _twinkleController.value * 0.18,
                  ),
                  fontSize: 13,
                  fontWeight: FontWeight.w700,
                  letterSpacing: 0.5,
                ),
              ),
              const SizedBox(width: 8),
              Icon(
                Icons.auto_awesome,
                size: 10,
                color: AppTheme.adaptiveWhite(alpha: glow * 0.8),
              ),
            ],
          );
        },
      ),
    );
  }
}

class _AlphaDenPost {
  final String id;
  final String authorUid;
  final String text;
  final Uint8List? imageBytes;
  final Uint8List? thumbnailBytes;
  final bool bullish;
  final List<String> hashtags;
  final List<String> coins;
  final String? signalAsset;
  final String? signalEntry;
  final bool? signalLongDirection;
  final int? signalLeverage;
  final String? signalTp1;
  final String? signalTp2;
  final String? signalTp3;
  final String? signalStopLoss;
  bool tp1Hit, tp2Hit, tp3Hit, stopLossHit, breakEven, winTradeCounted;
  String tp1Profit, tp2Profit, tp3Profit, stopLossProfit, breakEvenProfit;
  Uint8List? winResultImageBytes;

  _AlphaDenPost({
    this.id = '',
    this.authorUid = '',
    required this.text,
    this.imageBytes,
    this.thumbnailBytes,
    required this.bullish,
    required this.hashtags,
    required this.coins,
    this.signalAsset,
    this.signalEntry,
    this.signalLongDirection,
    this.signalLeverage,
    this.signalTp1,
    this.signalTp2,
    this.signalTp3,
    this.signalStopLoss,
    this.tp1Hit = false,
    this.tp2Hit = false,
    this.tp3Hit = false,
    this.stopLossHit = false,
    this.breakEven = false,
    this.winTradeCounted = false,
    this.tp1Profit = '',
    this.tp2Profit = '',
    this.tp3Profit = '',
    this.stopLossProfit = '',
    this.breakEvenProfit = '',
    this.winResultImageBytes,
  });

  _AlphaDenPost copyWith({String? id}) => _AlphaDenPost(
    id: id ?? this.id,
    authorUid: authorUid,
    text: text,
    imageBytes: imageBytes,
    thumbnailBytes: thumbnailBytes,
    bullish: bullish,
    hashtags: List<String>.from(hashtags),
    coins: List<String>.from(coins),
    signalAsset: signalAsset,
    signalEntry: signalEntry,
    signalLongDirection: signalLongDirection,
    signalLeverage: signalLeverage,
    signalTp1: signalTp1,
    signalTp2: signalTp2,
    signalTp3: signalTp3,
    signalStopLoss: signalStopLoss,
    tp1Hit: tp1Hit,
    tp2Hit: tp2Hit,
    tp3Hit: tp3Hit,
    stopLossHit: stopLossHit,
    breakEven: breakEven,
    winTradeCounted: winTradeCounted,
    tp1Profit: tp1Profit,
    tp2Profit: tp2Profit,
    tp3Profit: tp3Profit,
    stopLossProfit: stopLossProfit,
    breakEvenProfit: breakEvenProfit,
    winResultImageBytes: winResultImageBytes,
  );

  bool get isSignal => signalAsset != null;
}

String _alphaDenSignalSummary(_AlphaDenPost post) {
  final asset = post.signalAsset ?? '';
  final direction = post.signalLongDirection == true ? 'LONG' : 'SHORT';
  final leverage = post.signalLeverage == null ? '' : '${post.signalLeverage}x';
  return '$asset /USDT Ã¢â‚¬Â¢ $direction Ã¢â‚¬Â¢ ENTRY ${post.signalEntry ?? ''} Ã¢â‚¬Â¢ LEVERAGE $leverage Ã¢â‚¬Â¢ TP1 ${post.signalTp1 ?? ''} Ã¢â‚¬Â¢ TP2 ${post.signalTp2 ?? ''} Ã¢â‚¬Â¢ TP3 ${post.signalTp3 ?? ''} Ã¢â‚¬Â¢ STOPLOSS ${post.signalStopLoss ?? ''}';
}

