  final TextEditingController _tp2Controller = TextEditingController();
  final TextEditingController _tp3Controller = TextEditingController();
  final TextEditingController _stopController = TextEditingController();

  Uint8List? _imageBytes;
  bool _longDirection = true;
  bool _bullish = true;
  int _leverage = 10;
  late final AnimationController _entry = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 650),
  )..forward();

  @override
  void dispose() {
    _entry.dispose();
    _assetController.dispose();
    _entryController.dispose();
    _tp1Controller.dispose();
    _tp2Controller.dispose();
    _tp3Controller.dispose();
    _stopController.dispose();
    super.dispose();
  }

  Future<Uint8List?> _pickImageBytes() async {
    final input = html.FileUploadInputElement()..accept = 'image/*';
    input.click();
    await input.onChange.first;
    final file = input.files?.isNotEmpty == true ? input.files!.first : null;
    if (file == null) return null;
    final reader = html.FileReader();
    reader.readAsArrayBuffer(file);
    await reader.onLoad.first;
    final result = reader.result;
    return result is ByteBuffer ? result.asUint8List() : null;
  }

  Future<void> _pickOriginal() async {
    final bytes = await _pickImageBytes();
    if (bytes != null && mounted) setState(() => _imageBytes = bytes);
  }

  Future<void> _pickLeverage() async {
    final selected = await showDialog<int>(
      context: context,
