                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: List.generate(10, (index) {
                        final value = (index + 1) * 10;
                        final dotColor = _leverageColor(value);
                        final selectedDot = value == currentInt;
                        return Column(
                          children: [
                            AnimatedContainer(
                              duration: const Duration(milliseconds: 160),
                              width: selectedDot ? 8 : 5,
                              height: selectedDot ? 8 : 5,
