class _JellyPlusButton extends StatefulWidget {
  final String tooltip;
  final VoidCallback onPressed;
  final Color color;

  const _JellyPlusButton({
    required this.tooltip,
    required this.onPressed,
    this.color = AppTheme.luxuryGold,
  });

  @override
  State<_JellyPlusButton> createState() => _JellyPlusButtonState();
}

class _JellyPlusButtonState extends State<_JellyPlusButton>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 420),
  );

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  Future<void> _tap() async {
    await _controller.forward(from: 0);
    if (mounted) widget.onPressed();
  }

  @override
  Widget build(BuildContext context) {
    return Tooltip(
      message: widget.tooltip,
      child: AnimatedBuilder(
        animation: _controller,
        builder: (context, child) {
          final jelly = TweenSequence<double>([
            TweenSequenceItem(
              tween: Tween(
                begin: 1.0,
                end: 1.28,
              ).chain(CurveTween(curve: Curves.easeOut)),
              weight: 28,
            ),
            TweenSequenceItem(
              tween: Tween(
                begin: 1.28,
                end: 0.88,
              ).chain(CurveTween(curve: Curves.easeInOut)),
              weight: 30,
            ),
            TweenSequenceItem(
              tween: Tween(
                begin: 0.88,
                end: 1.08,
              ).chain(CurveTween(curve: Curves.elasticOut)),
              weight: 42,
            ),
          ]).evaluate(_controller);
          return Transform.scale(
            scale: jelly,
            child: IconButton(
              onPressed: _tap,
              tooltip: widget.tooltip,
              icon: Icon(
                Icons.add_circle_outline,
                color: widget.color,
                size: 27,
              ),
            ),
          );
        },
      ),
    );
  }
}

class _AlphaDenArticleComposerPage extends StatefulWidget {
  const _AlphaDenArticleComposerPage();
  @override
  State<_AlphaDenArticleComposerPage> createState() =>
      _AlphaDenArticleComposerPageState();
}

class _AlphaDenArticleComposerPageState
    extends State<_AlphaDenArticleComposerPage> {
  final _title = TextEditingController();
  final _body = TextEditingController();
  final _hashtagController = TextEditingController();
  final _coinController = TextEditingController();
  final List<String> _hashtags = [];
  final List<String> _coins = [];
  Uint8List? _imageBytes;
  bool _bullish = true;

  @override
  void dispose() {
    _title.dispose();
    _body.dispose();
    _hashtagController.dispose();
    _coinController.dispose();
    super.dispose();
  }

  Future<void> _pickImage() async {
    final bytes = await _pickImageBytes();
    if (!mounted) return;
    if (bytes == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please choose an image under 600 KB.')),
      );
      return;
    }
    setState(() => _imageBytes = bytes);
  }

  void _addHashtag() {
    final raw = _hashtagController.text.trim().replaceAll('#', '');
    if (raw.isEmpty || _hashtags.contains(raw)) return;
    setState(() => _hashtags.add(raw));
    _hashtagController.clear();
  }

  void _addCoin() {
    final raw = _coinController.text.trim().replaceAll('\$', '').toUpperCase();
    if (raw.isEmpty || _coins.contains(raw)) return;
    setState(() => _coins.add(raw));
    _coinController.clear();
  }

  void _publish() {
    final title = _title.text.trim();
    final body = _body.text.trim();
    if (title.isEmpty || body.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Add an article title and content before publishing.'),
        ),
      );
      return;
    }
    Navigator.pop(
      context,
      _AlphaDenArticle(
        id: DateTime.now().microsecondsSinceEpoch.toString(),
        title: title,
        body: body,
        imageBytes: _imageBytes,
        hashtags: List<String>.from(_hashtags),
        coins: List<String>.from(_coins),
        bullish: _bullish,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppTheme.adaptiveSurface(Color(0xFF070B10)),
      appBar: AppBar(
        backgroundColor: AppTheme.adaptiveSurface(Color(0xFF080D13)),
        surfaceTintColor: Colors.transparent,
        elevation: 0,
        leading: IconButton(
          icon: const Icon(Icons.arrow_back_ios_new),
          onPressed: () => Navigator.pop(context),
        ),
        title: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              'ALPHA DEN EDITOR',
              style: TextStyle(
                fontWeight: FontWeight.w900,
                letterSpacing: 1.5,
                fontSize: 14,
              ),
            ),
            Text(
              'PREMIUM ARTICLE',
              style: TextStyle(
                color: AppTheme.textMuted,
                fontSize: 9,
                letterSpacing: 1.0,
              ),
            ),
          ],
        ),
        actions: [
          Padding(
            padding: const EdgeInsets.only(right: 10),
            child: FilledButton(
              onPressed: _publish,
              child: const Text('PUBLISH'),
