}

class _AlphaDenPlusButtonState extends State<_AlphaDenPlusButton>
    with TickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1800),
  )..repeat(reverse: true);
  late final AnimationController _pressController = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 420),
  );

  @override
  void dispose() {
    _controller.dispose();
    _pressController.dispose();
    super.dispose();
  }

  Future<void> _tap() async {
    await _pressController.forward(from: 0);
    if (mounted) widget.onPressed();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: Listenable.merge([_controller, _pressController]),
      builder: (_, _) {
        final pulse = 0.97 + (_controller.value * 0.035);
        final jelly = TweenSequence<double>([
          TweenSequenceItem(
            tween: Tween(
              begin: 1.0,
              end: 1.24,
            ).chain(CurveTween(curve: Curves.easeOut)),
            weight: 28,
          ),
          TweenSequenceItem(
            tween: Tween(
              begin: 1.24,
              end: 0.88,
            ).chain(CurveTween(curve: Curves.easeInOut)),
            weight: 30,
          ),
          TweenSequenceItem(
            tween: Tween(
              begin: 0.88,
              end: 1.0,
            ).chain(CurveTween(curve: Curves.elasticOut)),
            weight: 42,
          ),
        ]).evaluate(_pressController);
        return Transform.scale(
          scale: pulse * jelly,
          child: Material(
            color: Colors.transparent,
            child: InkWell(
              onTap: _tap,
              customBorder: const CircleBorder(),
              child: Container(
                width: 58,
                height: 58,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: AppTheme.luxuryGold.withValues(alpha: 0.68),
                  boxShadow: [
                    BoxShadow(
                      color: AppTheme.luxuryGold.withValues(alpha: 0.32),
                      blurRadius: 24,
                      spreadRadius: 2,
                    ),
                  ],
                ),
                child: Icon(
                  Icons.add,
                  color: AppTheme.adaptiveSurface(Color(0xFF11151A)),
                  size: 31,
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}

