class _AlphaDenPostComposerPageState extends State<_AlphaDenPostComposerPage>
    with SingleTickerProviderStateMixin {
  final TextEditingController _ideaController = TextEditingController();
  final TextEditingController _hashtagController = TextEditingController();
  final TextEditingController _coinController = TextEditingController();
  final List<String> _hashtags = [];
  final List<String> _coins = [];
  Uint8List? _imageBytes;
  Uint8List? _thumbnailBytes;
  bool _bullish = true;
  late final AnimationController _entryController = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 700),
  )..forward();

  @override
  void dispose() {
    _entryController.dispose();
    _ideaController.dispose();
    _hashtagController.dispose();
    _coinController.dispose();
    super.dispose();
  }

  Future<void> _pickImage() async {
    final bytes = await _pickImageBytes();
    if (!mounted) return;
    if (bytes == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please choose an image under 600 KB.')),
      );
      return;
    }
    setState(() => _imageBytes = bytes);
  }

  void _addHashtag() {
    final raw = _hashtagController.text.trim().replaceAll('#', '');
    if (raw.isEmpty || _hashtags.contains(raw)) return;
    setState(() => _hashtags.add(raw));
    _hashtagController.clear();
  }

  void _addCoin() {
    final raw = _coinController.text.trim().replaceAll('\$', '').toUpperCase();
    if (raw.isEmpty || _coins.contains(raw)) return;
    setState(() => _coins.add(raw));
    _coinController.clear();
  }

  void _publish() {
    if (_ideaController.text.trim().isEmpty && _imageBytes == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Add an idea or an image before posting.'),
        ),
      );
      return;
    }
    Navigator.pop(
      context,
      _AlphaDenPost(
        text: _ideaController.text.trim(),
        imageBytes: _imageBytes,
        thumbnailBytes: _thumbnailBytes,
        bullish: _bullish,
        hashtags: List<String>.from(_hashtags),
        coins: List<String>.from(_coins),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return PopScope(
      canPop: true,
      child: Scaffold(
        backgroundColor: AppTheme.adaptiveSurface(Color(0xFF140A25)),
        appBar: AppBar(
          backgroundColor: AppTheme.adaptiveSurface(Color(0xFF140A25)),
          elevation: 0,
          surfaceTintColor: Colors.transparent,
          title: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
