          child: _ComposerBottomBar(
            bullish: _bullish,
            hasImage: _imageBytes != null,
            onImage: _pickImage,
            onBullishChanged: (value) => setState(() => _bullish = value),
            onHashtags: _showHashtagDialog,
            onCoins: _showCoinDialog,
          ),
        ),
      ),
    );
  }

  Future<void> _showHashtagDialog() async {
    _hashtagController.clear();
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: AppTheme.adaptiveSurface(Color(0xFF1A102B)),
        title: const Text('ADD HASHTAG'),
        content: TextField(
          controller: _hashtagController,
          autofocus: true,
          onSubmitted: (_) {
            _addHashtag();
            Navigator.pop(dialogContext);
          },
          decoration: const InputDecoration(hintText: '#marketview'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('CANCEL'),
          ),
          ElevatedButton(
            onPressed: () {
              _addHashtag();
              Navigator.pop(dialogContext);
