  const _PurpleGalaxyComposerBackground();
  @override
  State<_PurpleGalaxyComposerBackground> createState() =>
      _PurpleGalaxyComposerBackgroundState();
}

class _PurpleGalaxyComposerBackgroundState
    extends State<_PurpleGalaxyComposerBackground>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 7),
  )..repeat();
  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => AnimatedBuilder(
    animation: _controller,
    builder: (_, _) => Container(
      decoration: const BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [Color(0xFF12091F), Color(0xFF24104A), Color(0xFF0B0615)],
        ),
      ),
      child: CustomPaint(
        painter: _ComposerStarsPainter(_controller.value),
        child: const SizedBox.expand(),
      ),
    ),
  );
}

class _ComposerStarsPainter extends CustomPainter {
  final double progress;
  _ComposerStarsPainter(this.progress);
  @override
  void paint(Canvas canvas, Size size) {
    final random = math.Random(77);
    final paint = Paint()..style = PaintingStyle.fill;
    for (int i = 0; i < 95; i++) {
      final x = random.nextDouble() * size.width;
      final baseY = random.nextDouble() * size.height;
      final y = (baseY + progress * 20 * ((i % 3) + 1)) % size.height;
      final twinkle =
          0.35 +
          0.65 *
              (0.5 +
                  0.5 * math.sin(progress * math.pi * 2 * ((i % 4) + 1) + i));
      paint.color = AppTheme.adaptiveWhite(
        alpha: twinkle * (i % 5 == 0 ? 0.9 : 0.45),
      );
      canvas.drawCircle(Offset(x, y), i % 7 == 0 ? 1.5 : 0.8, paint);
    }
    final glow = Paint()
      ..shader =
          RadialGradient(
            colors: [const Color(0x665F3AA8), const Color(0x00120A20)],
          ).createShader(
            Rect.fromCircle(
              center: Offset(size.width * 0.62, size.height * 0.38),
              radius: size.width * 0.55,
            ),
          );
    canvas.drawCircle(
      Offset(size.width * 0.62, size.height * 0.38),
      size.width * 0.55,
      glow,
    );
  }

  @override
  bool shouldRepaint(covariant _ComposerStarsPainter oldDelegate) =>
      oldDelegate.progress != progress;
}

String _alphaArticleFeedPostId(String sourceId) {
  final safeId = sourceId.replaceAll(RegExp(r'[^a-zA-Z0-9_-]'), '_');
  return 'article_$safeId';
}

