  final String? articleBody;
  final String? signalAsset;
  final String? signalEntry;
  final bool? signalLongDirection;
  final int? signalLeverage;
  final String? signalTp1;
  final String? signalTp2;
  final String? signalTp3;
  final String? signalStopLoss;
  final bool tp1Hit, tp2Hit, tp3Hit, stopLossHit, breakEven, winTradeCounted;
  final String tp1Profit, tp2Profit, tp3Profit, stopLossProfit, breakEvenProfit;
  final Uint8List? winResultImageBytes;
  final int winTrades;
  final DateTime createdAt;

  const _AlphaDenRepost({
    this.id = '',
    required this.originalPostId,
    this.originalAuthorUid = '',
    this.sourceType = '',
    this.sourceId = '',
    required this.text,
    this.imageBytes,
    this.bullish = true,
    this.hashtags = const [],
    this.coins = const [],
    this.articleTitle,
    this.articleBody,
    this.signalAsset,
    this.signalEntry,
    this.signalLongDirection,
    this.signalLeverage,
    this.signalTp1,
    this.signalTp2,
    this.signalTp3,
    this.signalStopLoss,
    this.tp1Hit = false,
    this.tp2Hit = false,
    this.tp3Hit = false,
    this.stopLossHit = false,
    this.breakEven = false,
    this.winTradeCounted = false,
    this.tp1Profit = '',
    this.tp2Profit = '',
    this.tp3Profit = '',
    this.stopLossProfit = '',
    this.breakEvenProfit = '',
    this.winResultImageBytes,
    this.winTrades = 0,
    required this.createdAt,
  });

  factory _AlphaDenRepost.fromMap(Map<String, dynamic> data) {
    Uint8List? bytes;
    final encoded = (data['imageBase64'] ?? '').toString();
    if (encoded.isNotEmpty) {
      try {
        bytes = base64Decode(encoded);
      } catch (_) {}
    }
    final ts = data['createdAt'];
    return _AlphaDenRepost(
      id: (data['id'] ?? '').toString(),
      originalPostId: (data['originalPostId'] ?? '').toString(),
      originalAuthorUid: (data['originalAuthorUid'] ?? '').toString(),
      sourceType: (data['sourceType'] ?? '').toString(),
      sourceId: (data['sourceId'] ?? '').toString(),
      text: (data['text'] ?? '').toString(),
      imageBytes: bytes,
      bullish: data['bullish'] != false,
      hashtags: List<String>.from((data['hashtags'] as List?) ?? const []),
      coins: List<String>.from((data['coins'] as List?) ?? const []),
      articleTitle: data['articleTitle']?.toString(),
      articleBody: data['articleBody']?.toString(),
      signalAsset: data['signalAsset']?.toString(),
      signalEntry: data['signalEntry']?.toString(),
      signalLongDirection: data['signalLongDirection'] is bool
          ? data['signalLongDirection'] as bool
          : null,
      signalLeverage: data['signalLeverage'] is num
          ? (data['signalLeverage'] as num).toInt()
          : null,
      signalTp1: data['signalTp1']?.toString(),
      signalTp2: data['signalTp2']?.toString(),
      signalTp3: data['signalTp3']?.toString(),
      signalStopLoss: data['signalStopLoss']?.toString(),
      tp1Hit: data['tp1Hit'] == true,
      tp2Hit: data['tp2Hit'] == true,
      tp3Hit: data['tp3Hit'] == true,
      stopLossHit: data['stopLossHit'] == true,
      breakEven: data['breakEven'] == true,
      winTradeCounted: data['winTradeCounted'] == true,
      tp1Profit: (data['tp1Profit'] ?? '').toString(),
      tp2Profit: (data['tp2Profit'] ?? '').toString(),
      tp3Profit: (data['tp3Profit'] ?? '').toString(),
      stopLossProfit: (data['stopLossProfit'] ?? '').toString(),
      breakEvenProfit: (data['breakEvenProfit'] ?? '').toString(),
      winResultImageBytes:
          (data['winResultImageBase64'] is String &&
              (data['winResultImageBase64'] as String).isNotEmpty)
          ? _tryDecodeBase64(data['winResultImageBase64'] as String)
          : null,
      winTrades: (data['winTrades'] ?? 0) is num
          ? (data['winTrades'] as num).toInt()
          : 0,
      createdAt: ts is Timestamp ? ts.toDate() : DateTime.now(),
    );
  }

  Map<String, dynamic> toMap() => <String, dynamic>{
    'originalAuthorUid': originalAuthorUid,
    'sourceType': sourceType,
    'sourceId': sourceId,
    'text': text,
    'bullish': bullish,
    'hashtags': hashtags,
    'coins': coins,
    'articleTitle': articleTitle,
    'articleBody': articleBody,
    'signalAsset': signalAsset,
    'signalEntry': signalEntry,
    'signalLongDirection': signalLongDirection,
    'signalLeverage': signalLeverage,
    'signalTp1': signalTp1,
    'signalTp2': signalTp2,
    'signalTp3': signalTp3,
    'signalStopLoss': signalStopLoss,
    'tp1Hit': tp1Hit,
    'tp2Hit': tp2Hit,
    'tp3Hit': tp3Hit,
    'stopLossHit': stopLossHit,
    'breakEven': breakEven,
    'winTradeCounted': winTradeCounted,
    'tp1Profit': tp1Profit,
    'tp2Profit': tp2Profit,
    'tp3Profit': tp3Profit,
    'stopLossProfit': stopLossProfit,
    'breakEvenProfit': breakEvenProfit,
    if (winResultImageBytes != null)
      'winResultImageBase64': base64Encode(winResultImageBytes!),
    'winTrades': winTrades,
    if (imageBytes != null) 'imageBase64': base64Encode(imageBytes!),
  };
}

