class _AlphaDenIdeasPage extends StatelessWidget {
  final List<_AlphaDenPost> ideas;
  final Set<int> likedIdeas;
  final Future<void> Function(int) onLike;
  final ValueChanged<int> onRepost;
  final ValueChanged<int> onShare;
  const _AlphaDenIdeasPage({
    required this.ideas,
    required this.likedIdeas,
    required this.onLike,
    required this.onRepost,
    required this.onShare,
  });
  @override
  Widget build(BuildContext context) {
    final items = <_AlphaDenPost>[];
    for (final post in ideas) {
      if (!post.isSignal) items.add(post);
    }
    if (items.isEmpty)
      return const _AlphaDenEmptyState(
        icon: Icons.lightbulb_outline,
        title: 'NO IDEAS YET',
        subtitle: 'Your published ideas will appear here.',
      );
    return ListView.builder(
      physics: const BouncingScrollPhysics(),
      padding: const EdgeInsets.only(bottom: 20),
      itemCount: items.length,
      itemBuilder: (_, i) {
        final post = items[i];
        final originalIndex = ideas.indexOf(post);
        return _AlphaDenSinglePostCard(
          key: ValueKey<String>(
            'alpha-idea-${post.id.isEmpty ? originalIndex : post.id}',
          ),
          post: post,
          liked: likedIdeas.contains(originalIndex),
          onLike: () => onLike(originalIndex),
          onRepost: () => onRepost(originalIndex),
          onShare: () => onShare(originalIndex),
          onComment: () async {
            await _showFeedCommentsSheet(
              context,
              postId: post.id,
              authorUid: post.authorUid,
            );
          },
          onOptions: () =>
              (context.findAncestorStateOfType<_AlphaDenPageState>())
                  ?._showAlphaPostActions(post),
          label: 'IDEA',
          winTrades:
              (context.findAncestorStateOfType<_AlphaDenPageState>())
                  ?.winTrades ??
              0,
        );
      },
    );
  }
}

class _AlphaDenSignalsPage extends StatelessWidget {
  final List<_AlphaDenPost> signals;
  final ValueChanged<int> onRepost;
  final ValueChanged<int> onShare;
  const _AlphaDenSignalsPage({
    required this.signals,
    required this.onRepost,
    required this.onShare,
  });
  @override
  Widget build(BuildContext context) {
    if (signals.isEmpty)
      return const _AlphaDenEmptyState(
        icon: Icons.candlestick_chart_outlined,
        title: 'NO SIGNALS YET',
        subtitle: 'Your published signals will appear here.',
      );
    return ListView.builder(
      physics: const BouncingScrollPhysics(),
      padding: const EdgeInsets.only(bottom: 20),
      itemCount: signals.length,
      itemBuilder: (_, i) => _AlphaDenSinglePostCard(
        key: ValueKey<String>(
          'alpha-signal-${signals[i].id.isEmpty ? i : signals[i].id}',
        ),
        post: signals[i],
        liked: false,
        onLike: () async {
          final state = context.findAncestorStateOfType<_AlphaDenPageState>();
          if (state == null) return;
          final post = signals[i];
          final user = FirebaseAuth.instance.currentUser;
          if (user == null) return;
          final liked = await FeedService.hasPostLikeBySourceId(
            sourceId: post.id,
            uid: user.uid,
          );
          final next = !liked;
          try {
            await FeedService.togglePostLikeBySourceId(
              sourceId: post.id,
              uid: user.uid,
              liked: next,
            );
          } catch (_) {}
          if (context.mounted) state.setState(() {});
        },
        onRepost: () => onRepost(i),
        onShare: () => onShare(i),
        onComment: () async {
          await _showFeedCommentsSheet(
            context,
            postId: signals[i].id,
            authorUid: signals[i].authorUid,
          );
        },
        onOptions: () => (context.findAncestorStateOfType<_AlphaDenPageState>())
            ?._showAlphaPostActions(signals[i]),
        label: 'SIGNAL',
        winTrades:
            (context.findAncestorStateOfType<_AlphaDenPageState>())
                ?.winTrades ??
            0,
      ),
    );
  }
}

