double _parseSignalPercent(String value) {
  final cleaned = value.replaceAll('%', '').replaceAll('+', '').trim();
  return double.tryParse(cleaned) ?? 0;
}

String _averageHitProfit({
  required bool tp1Hit,
  required bool tp2Hit,
  required bool tp3Hit,
  required String tp1Profit,
  required String tp2Profit,
  required String tp3Profit,
}) {
  final values = <double>[];
  if (tp1Hit) values.add(_parseSignalPercent(tp1Profit));
  if (tp2Hit) values.add(_parseSignalPercent(tp2Profit));
  if (tp3Hit) values.add(_parseSignalPercent(tp3Profit));
  if (values.isEmpty) return '';
  final avg = values.reduce((a, b) => a + b) / values.length;
  final rounded = avg.roundToDouble() == avg
      ? avg.toStringAsFixed(0)
      : avg.toStringAsFixed(1);
  return '+$rounded%';
}

Widget _signalTargetRow({
  required String label,
  required String value,
  bool warning = false,
  bool hit = false,
  String profit = '',
}) => Padding(
  padding: const EdgeInsets.symmetric(vertical: 4),
  child: Row(
    children: [
      SizedBox(
        width: 76,
        child: Text(
          label,
          style: TextStyle(
            color: warning ? const Color(0xFFE05252) : AppTheme.textMuted,
            fontSize: 10,
            fontWeight: FontWeight.w900,
          ),
        ),
      ),
      Expanded(
        child: Text(
          value,
          style: TextStyle(
            color: AppTheme.textPrimary,
            fontSize: 14,
            fontWeight: FontWeight.w800,
          ),
        ),
      ),
      if (hit)
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
          decoration: BoxDecoration(
            color: (warning ? const Color(0xFFE05252) : const Color(0xFF39E75F))
                .withValues(alpha: .14),
            borderRadius: BorderRadius.circular(6),
            border: Border.all(
              color: warning
                  ? const Color(0xFFE05252)
                  : const Color(0xFF39E75F),
            ),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                warning ? Icons.close_rounded : Icons.check_rounded,
                size: 11,
                color: warning
                    ? const Color(0xFFE05252)
                    : const Color(0xFF39E75F),
              ),
              const SizedBox(width: 3),
              Text(
                warning ? '$label HIT' : '$label HIT',
                style: TextStyle(
                  color: warning
                      ? const Color(0xFFE05252)
                      : const Color(0xFF39E75F),
                  fontSize: 8,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ],
          ),
        ),
      if (hit && profit.trim().isNotEmpty) ...[
        const SizedBox(width: 5),
        Text(
          '${warning ? '-' : '+'}${profit.replaceFirst(RegExp(r'^[+-]'), '')}%',
          style: TextStyle(
            color: warning ? const Color(0xFFE05252) : const Color(0xFF39E75F),
            fontSize: 9,
            fontWeight: FontWeight.w900,
          ),
        ),
      ],
    ],
  ),
);

Widget _signalWinBadge({
  required bool tp1Hit,
  required bool tp2Hit,
  required bool tp3Hit,
  required String tp1Profit,
  required String tp2Profit,
  required String tp3Profit,
  required bool stopLossHit,
  required String stopLossProfit,
  required bool breakEven,
  required String breakEvenProfit,
}) {
  final avg = _averageHitProfit(
    tp1Hit: tp1Hit,
    tp2Hit: tp2Hit,
    tp3Hit: tp3Hit,
    tp1Profit: tp1Profit,
    tp2Profit: tp2Profit,
    tp3Profit: tp3Profit,
  );
  final isWin = avg.isNotEmpty;
  final isLoss = !isWin && stopLossHit;
  final isBreakEven = !isWin && !isLoss && breakEven;
  if (!isWin && !isLoss && !isBreakEven) return const SizedBox.shrink();
  final label = isWin
      ? 'WIN'
      : isLoss
      ? 'LOSS'
      : 'BREAK EVEN';
  final value = isWin
      ? avg
      : isLoss
      ? '-${stopLossProfit.replaceFirst(RegExp(r'^[+-]'), '')}%'
      : '0%';
  final color = isWin ? const Color(0xFF39E75F) : const Color(0xFFE05252);
  return Container(
    width: isBreakEven ? 64 : 54,
    padding: const EdgeInsets.symmetric(vertical: 3, horizontal: 4),
    decoration: BoxDecoration(
      color: color.withValues(alpha: .10),
      borderRadius: BorderRadius.circular(7),
      border: Border.all(color: color.withValues(alpha: .5)),
    ),
    child: Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(
          label,
          style: TextStyle(
            color: color,
            fontSize: 5.5,
            fontWeight: FontWeight.w900,
            letterSpacing: .3,
          ),
        ),
        const SizedBox(height: 1),
        Text(
          value,
          style: TextStyle(
            color: color,
            fontSize: 11,
            fontWeight: FontWeight.w900,
          ),
        ),
      ],
    ),
  );
}

