  });

  @override
  State<_AlphaDenSinglePostCard> createState() =>
      _AlphaDenSinglePostCardState();
}

class _AlphaDenSinglePostCardState extends State<_AlphaDenSinglePostCard> {
  StreamSubscription<DocumentSnapshot<Map<String, dynamic>>>? _postSubscription;
  StreamSubscription<DocumentSnapshot<Map<String, dynamic>>>? _likeSubscription;
  bool _likedLocal = false;
  int _likes = 0, _comments = 0, _reposts = 0, _shares = 0;

  @override
  void initState() {
    super.initState();
    _likedLocal = widget.liked;
    _resolveAndSubscribe();
  }

  Future<void> _resolveAndSubscribe() async {
    final sourceOrPostId = widget.post.id.trim();
    if (sourceOrPostId.isEmpty) return;

    String? postId;
    try {
      final direct = await FirebaseFirestore.instance
          .collection('feed_posts')
          .doc(sourceOrPostId)
          .get();
      postId = direct.exists
          ? sourceOrPostId
          : await FeedService.findPostIdBySourceId(sourceOrPostId);
    } catch (_) {
      return;
    }
    if (!mounted || postId == null || postId.isEmpty) return;

    final postRef = FirebaseFirestore.instance
        .collection('feed_posts')
        .doc(postId);
    _postSubscription = postRef.snapshots().listen((snap) {
      final d = snap.data();
      if (!snap.exists || d == null || !mounted) return;
      setState(() {
        _likes =
            (d['likesCount'] as num?)?.toInt() ??
            (d['likes'] as num?)?.toInt() ??
            0;
        _comments =
            (d['commentsCount'] as num?)?.toInt() ??
            (d['comments'] as num?)?.toInt() ??
            0;
        _reposts =
            (d['repostsCount'] as num?)?.toInt() ??
            (d['reposts'] as num?)?.toInt() ??
            0;
        _shares =
            (d['sharesCount'] as num?)?.toInt() ??
            (d['shareCount'] as num?)?.toInt() ??
            (d['shares'] as num?)?.toInt() ??
            0;
      });
    });

    final user = FirebaseAuth.instance.currentUser;
    if (user != null) {
      _likeSubscription = postRef
          .collection('likes')
          .doc(user.uid)
          .snapshots()
          .listen((snap) {
            if (mounted) setState(() => _likedLocal = snap.exists);
          });
    }
  }

  @override
  void dispose() {
    _postSubscription?.cancel();
    _likeSubscription?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final post = widget.post;
    final liked = _likedLocal;
    final onLike = widget.onLike;
    final onRepost = widget.onRepost;
    final onComment = widget.onComment;
    final onOptions = widget.onOptions;
    final label = widget.label;
    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: AppTheme.adaptiveSurface(Color(0xFF303238)),
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: const Color(0x334E9FC1)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(
                post.isSignal
                    ? Icons.candlestick_chart_outlined
                    : Icons.lightbulb_outline,
                color: post.isSignal ? AppTheme.neonGreen : AppTheme.luxuryGold,
                size: 16,
              ),
              const SizedBox(width: 7),
              Text(
                label,
                style: const TextStyle(
                  fontWeight: FontWeight.w900,
                  letterSpacing: .9,
                ),
              ),
              const Spacer(),
              if (!post.isSignal)
                Text(
                  post.bullish ? 'BULL' : 'BEAR',
                  style: TextStyle(
                    color: post.bullish
                        ? AppTheme.neonGreen
                        : const Color(0xFFE05252),
                    fontSize: 10,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              if (!post.isSignal) const SizedBox(width: 5),
              _signalWinBadge(
                tp1Hit: post.tp1Hit,
                tp2Hit: post.tp2Hit,
                tp3Hit: post.tp3Hit,
                tp1Profit: post.tp1Profit,
                tp2Profit: post.tp2Profit,
                tp3Profit: post.tp3Profit,
                stopLossHit: post.stopLossHit,
                stopLossProfit: post.stopLossProfit,
                breakEven: post.breakEven,
                breakEvenProfit: post.breakEvenProfit,
              ),
              const SizedBox(width: 4),
              IconButton(
                tooltip: 'Post options',
                visualDensity: VisualDensity.compact,
                padding: EdgeInsets.zero,
                onPressed: onOptions,
                icon: Icon(
                  Icons.more_vert_rounded,
                  color: AppTheme.textSecondary,
