Future<int> _showFeedCommentsSheet(
  BuildContext context, {
  required String postId,
  required String authorUid,
}) async {
  final currentUser = FirebaseAuth.instance.currentUser;
  if (currentUser == null || postId.trim().isEmpty) return 0;
  final controller = TextEditingController();
  final focusNode = FocusNode();
  final local = <_CommunityComment>[];
  var addedCount = 0;
  var sheetOpen = false;
  var commentsLoadStarted = false;
  var commentsLoading = true;
  try {
    if (!context.mounted) return 0;
    String? replyTo;
    sheetOpen = true;
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) => StatefulBuilder(
        builder: (sheetContext, setModalState) {
          final inset = MediaQuery.of(sheetContext).viewInsets.bottom;
          if (!commentsLoadStarted) {
            commentsLoadStarted = true;
            Future<void>(() async {
              try {
                final rows = await FeedService.loadComments(postId);
                if (!sheetOpen) return;
                local
                  ..clear()
                  ..addAll(
                    rows.map(
                      (data) => _CommunityComment(
                        id: (data['id'] ?? '').toString(),
                        authorUid: (data['authorUid'] ?? '').toString(),
                        author: (data['author'] ?? 'User').toString(),
                        text: (data['text'] ?? '').toString(),
                        creatorReply: data['creatorReply'] == true,
                        parentId:
                            (data['parentId'] as String?)?.trim().isEmpty ==
                                true
                            ? null
                            : data['parentId']?.toString(),
                        likes: (data['likes'] as num?)?.toInt() ?? 0,
                      ),
                    ),
                  );
              } catch (_) {
                // The sheet remains usable even when the initial read fails.
              } finally {
                if (sheetOpen && sheetContext.mounted) {
                  commentsLoading = false;
                  setModalState(() {});
                }
              }
            });
          }
          final roots = local.where((c) => c.parentId == null).toList();
          List<_CommunityComment> replies(String id) =>
              local.where((c) => c.parentId == id).toList();
          Future<void> submit() async {
            final text = controller.text.trim();
            if (text.isEmpty) return;
            try {
              final id = FeedService.newCommentId(postId);
              final author = currentUser.displayName?.trim().isNotEmpty == true
                  ? currentUser.displayName!.trim()
                  : 'You';
              final optimistic = _CommunityComment(
                id: id,
                authorUid: currentUser.uid,
                author: author,
                text: text,
                parentId: replyTo,
              );
              local.add(optimistic);
              addedCount++;
              controller.clear();
              replyTo = null;
              setModalState(() {});
              try {
                await FeedService.addComment(
                  postId: postId,
                  authorUid: currentUser.uid,
                  author: author,
                  text: text,
                  parentId: optimistic.parentId,
                  creatorReply:
                      currentUser.uid == authorUid && authorUid.isNotEmpty,
                  commentId: id,
                );
              } catch (_) {
                local.removeWhere((c) => c.id == id);
                addedCount--;
                if (sheetContext.mounted) setModalState(() {});
                if (sheetContext.mounted)
                  ScaffoldMessenger.of(sheetContext).showSnackBar(
                    const SnackBar(
                      content: Text(
                        'Comment could not be posted. Please check your connection and try again.',
                      ),
                    ),
                  );
              }
            } catch (_) {
              if (sheetContext.mounted)
                ScaffoldMessenger.of(sheetContext).showSnackBar(
                  const SnackBar(
                    content: Text(
                      'Comment could not be posted. Please check your connection and try again.',
                    ),
                  ),
                );
            }
          }

          Widget tile(_CommunityComment c, {bool reply = false}) => Container(
            margin: EdgeInsets.only(left: reply ? 30 : 0, bottom: 8),
            padding: const EdgeInsets.all(10),
            decoration: BoxDecoration(
              color: AppTheme.adaptiveWhite(alpha: .035),
              borderRadius: BorderRadius.circular(13),
              border: Border.all(color: AppTheme.fillFaint),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  c.author,
                  style: TextStyle(
                    color: AppTheme.textPrimary,
                    fontSize: 10,
                    fontWeight: FontWeight.w800,
                  ),
                ),
                const SizedBox(height: 3),
                Text(
                  c.text,
                  style: TextStyle(
                    color: AppTheme.textSecondary,
                    fontSize: 12,
                    height: 1.3,
                  ),
                ),
                const SizedBox(height: 5),
                Row(
                  children: [
                    InkWell(
                      onTap: () async {
                        final next = !c.likedByMe;
                        c.likedByMe = next;
                        c.likes = (c.likes + (next ? 1 : -1)).clamp(0, 1000000);
                        setModalState(() {});
                        try {
                          await FeedService.toggleCommentLike(
                            postId: postId,
                            commentId: c.id,
                            uid: currentUser.uid,
                            liked: next,
                          );
                        } catch (_) {}
                      },
                      child: Row(
                        children: [
                          Icon(
                            c.likedByMe
                                ? Icons.favorite
                                : Icons.favorite_border,
                            size: 13,
                            color: c.likedByMe
                                ? const Color(0xFFFF3B4D)
                                : AppTheme.textFaint,
                          ),
                          const SizedBox(width: 3),
                          Text(
                            '${c.likes}',
                            style: TextStyle(
                              color: AppTheme.textFaint,
                              fontSize: 8,
                            ),
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(width: 12),
                    InkWell(
                      onTap: () {
                        replyTo = c.id;
                        focusNode.requestFocus();
                        setModalState(() {});
                      },
                      child: const Text(
                        'REPLY',
                        style: TextStyle(
                          color: Color(0xFF59D7FF),
                          fontSize: 8,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                    const SizedBox(width: 12),
                    InkWell(
                      onTap: () {
                        Navigator.pop(sheetContext);
                        Future<void>.delayed(
                          const Duration(milliseconds: 180),
                          () {
                            if (!sheetContext.mounted) return;
                            _openContentReportSupportPage(
                              sheetContext,
                              postId: postId,
                              commentId: c.id,
                              authorUid: authorUid,
                            );
                          },
                        );
                      },
                      child: Text(
                        'REPORT',
                        style: TextStyle(
                          color: AppTheme.textFaint,
                          fontSize: 8,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                  ],
                ),
              ],
            ),
          );
          return SafeArea(
            child: Padding(
              padding: EdgeInsets.only(bottom: inset),
              child: Container(
                height: MediaQuery.of(sheetContext).size.height * .68,
                decoration: BoxDecoration(
                  color: AppTheme.adaptiveSurface(Color(0xFF080D13)),
                  borderRadius: BorderRadius.vertical(top: Radius.circular(22)),
                ),
                child: Column(
                  children: [
                    Padding(
                      padding: const EdgeInsets.fromLTRB(16, 10, 12, 8),
                      child: Row(
                        children: [
                          Text(
                            'COMMENTS',
                            style: TextStyle(
                              fontSize: 10,
                              fontWeight: FontWeight.w900,
                              color: AppTheme.textSecondary,
                            ),
                          ),
                          const Spacer(),
                          IconButton(
                            onPressed: () => Navigator.pop(sheetContext),
                            icon: Icon(Icons.close, color: AppTheme.textMuted),
                          ),
                        ],
                      ),
                    ),
                    Divider(height: 1, color: AppTheme.fillFaint),
                    Expanded(
                      child: commentsLoading
                          ? const Center(child: CircularProgressIndicator())
                          : local.isEmpty
                          ? Center(
                              child: Text(
                                'No comments yet. Start the conversation.',
                                style: TextStyle(
                                  color: AppTheme.textFaint,
                                  fontSize: 12,
                                ),
                              ),
                            )
                          : ListView(
                              padding: const EdgeInsets.all(14),
                              children: [
                                for (final c in roots) ...[
                                  tile(c),
                                  for (final r in replies(c.id))
                                    tile(r, reply: true),
                                ],
                              ],
                            ),
                    ),
                    if (replyTo != null)
                      Padding(
                        padding: const EdgeInsets.fromLTRB(14, 0, 14, 4),
                        child: Row(
                          children: [
                            Text(
                              'Replying',
                              style: TextStyle(
                                color: AppTheme.textFaint,
                                fontSize: 9,
                              ),
                            ),
                            const Spacer(),
                            TextButton(
                              onPressed: () {
                                replyTo = null;
                                setModalState(() {});
                              },
                              child: const Text('CANCEL'),
                            ),
                          ],
                        ),
                      ),
                    Padding(
                      padding: const EdgeInsets.fromLTRB(12, 6, 12, 12),
                      child: Row(
                        children: [
                          Expanded(
                            child: TextField(
                              controller: controller,
                              focusNode: focusNode,
                              minLines: 1,
                              maxLines: 4,
                              textInputAction: TextInputAction.newline,
                              decoration: const InputDecoration(
                                hintText: 'Write a comment...',
                              ),
                            ),
                          ),
                          const SizedBox(width: 7),
                          IconButton(
                            onPressed: commentsLoading ? null : submit,
                            icon: Icon(
                              Icons.send_rounded,
                              color: AppTheme.luxuryGold,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
            ),
          );
        },
      ),
    );
  } finally {
    sheetOpen = false;
    controller.dispose();
    focusNode.dispose();
  }
  return addedCount;
}

class _CommunityPostCard extends StatefulWidget {
  final _CommunityPost post;
  const _CommunityPostCard({required this.post});

  @override
  State<_CommunityPostCard> createState() => _CommunityPostCardState();
}

class _CommunityPostCardState extends State<_CommunityPostCard> {
  bool liked = false;
  bool following = false;
  bool reposted = false;
  bool _countedView = false;
  bool _isAdmin = false;
  StreamSubscription<DocumentSnapshot<Map<String, dynamic>>>? _postSubscription;

  @override
  void initState() {
    super.initState();
    if (!_countedView) {
      _countedView = true;
      widget.post.views += 1;
    }
    _loadAdminAccess();
    _loadLikeState();
    _loadRepostState();
    _loadFollowState();
    _subscribeToPost();
  }

  Future<void> _loadLikeState() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null || widget.post.id.isEmpty) return;
    try {
      final value = await FeedService.hasPostLike(
        postId: widget.post.id,
        uid: user.uid,
      );
      if (mounted) setState(() => liked = value);
    } catch (_) {}
  }

  Future<void> _loadFollowState() async {
    final user = FirebaseAuth.instance.currentUser;
    final target = widget.post.authorUid.trim();
    if (user == null || target.isEmpty || target == user.uid) return;
    try {
      final snap = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .collection('following')
          .doc(target)
          .get();
      if (mounted) setState(() => following = snap.exists);
    } catch (_) {}
  }

  Future<void> _loadRepostState() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null || widget.post.id.isEmpty) return;
    try {
      final value = await FeedService.hasPostRepost(
        postId: widget.post.id,
        uid: user.uid,
      );
      if (mounted) setState(() => reposted = value);
    } catch (_) {}
  }

  void _subscribeToPost() {
    if (widget.post.id.isEmpty) return;
    _postSubscription = FirebaseFirestore.instance
        .collection('feed_posts')
        .doc(widget.post.id)
        .snapshots()
        .listen((snap) {
          final data = snap.data();
          if (!snap.exists || data == null || !mounted) return;
          setState(() {
            widget.post.likes =
                (data['likesCount'] as num?)?.toInt() ??
                (data['likes'] as num?)?.toInt() ??
                widget.post.likes;
            widget.post.comments =
                (data['commentsCount'] as num?)?.toInt() ??
                widget.post.comments;
            widget.post.reposts =
                (data['repostsCount'] as num?)?.toInt() ?? widget.post.reposts;
            widget.post.shares =
                (data['sharesCount'] as num?)?.toInt() ??
                (data['shareCount'] as num?)?.toInt() ??
                widget.post.shares;
          });
        });
  }

  @override
  void dispose() {
    _postSubscription?.cancel();
    super.dispose();
  }

  Future<void> _loadAdminAccess() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;
    try {
      final allowed = await _hasFirebaseAdminClaim(user);
      if (mounted && allowed != _isAdmin) setState(() => _isAdmin = allowed);
    } catch (_) {}
  }

  void _sortFeed() {
    final next = List<_CommunityPost>.from(_communityFeed.value);
    next.sort((a, b) => b.createdAt.compareTo(a.createdAt));
    _communityFeed.value = next;
  }

  Future<void> _openComments() async {
    final controller = TextEditingController();
    final focusNode = FocusNode();
    final emojis = <String>[
      'Ã¢ÂÂ¤Ã¯Â¸Â',
      'Ã°Å¸â€Â¥',
      'Ã°Å¸Ëœâ€š',
      'Ã°Å¸Å¡â‚¬',
      'Ã°Å¸â€˜Â',
      'Ã°Å¸ËœÂ',
    ];
    final coins = <String>['BTC', 'ETH', 'SOL', 'XRP'];
    final currentUser = FirebaseAuth.instance.currentUser;
    if (currentUser == null) return;
    StreamSubscription<QuerySnapshot<Map<String, dynamic>>>?
    commentsSubscription;
    StateSetter? refreshComments;
    var sheetOpen = false;

    try {
      final rows = await FeedService.loadComments(widget.post.id);
      // Merge the server snapshot into the existing in-memory list instead
      // of clearing it first. This prevents a temporarily stale read from
      // removing a comment that was just posted successfully.
      final mergedComments = <String, _CommunityComment>{
        for (final comment in widget.post.commentItems) comment.id: comment,
      };
      for (final data in rows) {
        final comment = _CommunityComment(
          id: (data['id'] ?? '').toString(),
          authorUid: (data['authorUid'] ?? '').toString(),
          author: (data['author'] ?? 'User').toString(),
          text: (data['text'] ?? '').toString(),
          creatorReply: data['creatorReply'] == true,
          parentId: (data['parentId'] as String?)?.trim().isEmpty == true
              ? null
              : data['parentId']?.toString(),
          likes: (data['likes'] as num?)?.toInt() ?? 0,
        );
        if (comment.id.isNotEmpty) mergedComments[comment.id] = comment;
      }
      widget.post.commentItems
        ..clear()
        ..addAll(mergedComments.values);
      if (mounted) setState(() {});
    } catch (_) {
      // Keep the local comments available if a legacy/missing comments collection is encountered.
    }

    commentsSubscription = FirebaseFirestore.instance
        .collection('feed_posts')
        .doc(widget.post.id)
        .collection('comments')
        .orderBy('createdAt')
        .snapshots()
        .listen((snapshot) {
          final incoming = <String, _CommunityComment>{};
          for (final doc in snapshot.docs) {
            final data = doc.data();
            incoming[doc.id] = _CommunityComment(
              id: doc.id,
              authorUid: (data['authorUid'] ?? '').toString(),
              author: (data['author'] ?? 'User').toString(),
              text: (data['text'] ?? '').toString(),
              creatorReply: data['creatorReply'] == true,
              parentId: (data['parentId'] ?? '').toString().trim().isEmpty
                  ? null
                  : (data['parentId'] ?? '').toString(),
              likes: (data['likes'] as num?)?.toInt() ?? 0,
            );
          }
          widget.post.commentItems
            ..removeWhere((c) => !incoming.containsKey(c.id))
            ..forEach((c) {
              if (incoming.containsKey(c.id)) incoming[c.id] = c;
            });
          for (final c in incoming.values) {
            final existing = widget.post.commentItems.indexWhere(
              (x) => x.id == c.id,
            );
            if (existing >= 0) {
              widget.post.commentItems[existing] = c;
            } else {
              widget.post.commentItems.add(c);
            }
          }
          widget.post.comments = snapshot.docs.length;
          _communityFeed.value = List<_CommunityPost>.from(
            _communityFeed.value,
          );
          if (sheetOpen && refreshComments != null) {
            refreshComments!(() {});
          }
        });

    String? replyTo;
    sheetOpen = true;
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: Colors.black.withValues(alpha: 0.68),
      builder: (sheetContext) {
        return StatefulBuilder(
          builder: (sheetContext, modalSetState) {
            refreshComments = modalSetState;
            final bottomInset = MediaQuery.of(sheetContext).viewInsets.bottom;
            final roots = widget.post.commentItems
                .where((c) => c.parentId == null)
                .toList();
            List<_CommunityComment> repliesFor(String id) => widget
                .post
                .commentItems
                .where((c) => c.parentId == id)
                .toList();

            Future<void> submit() async {
              final value = controller.text.trim();
              if (value.isEmpty) return;
              final parent = replyTo;
              try {
                final id = FeedService.newCommentId(widget.post.id);
                final author =
                    currentUser.displayName?.trim().isNotEmpty == true
                    ? currentUser.displayName!.trim()
                    : 'You';
                final optimistic = _CommunityComment(
                  id: id,
                  authorUid: currentUser.uid,
                  author: author,
                  text: value,
                  parentId: parent,
                  creatorReply: currentUser.uid == widget.post.authorUid,
                );
                widget.post.commentItems.add(optimistic);
                widget.post.comments += 1;
                controller.clear();
                replyTo = null;
                _communityFeed.value = List<_CommunityPost>.from(
                  _communityFeed.value,
                );
                modalSetState(() {});
                try {
                  await FeedService.addComment(
                    postId: widget.post.id,
                    authorUid: currentUser.uid,
                    author: author,
                    text: value,
                    parentId: parent,
                    creatorReply: currentUser.uid == widget.post.authorUid,
                    commentId: id,
                  );
                } catch (_) {
                  widget.post.commentItems.removeWhere((c) => c.id == id);
                  widget.post.comments = (widget.post.comments - 1)
                      .clamp(0, 1000000)
                      .toInt();
                  _communityFeed.value = List<_CommunityPost>.from(
                    _communityFeed.value,
                  );
                  if (sheetContext.mounted) modalSetState(() {});
                  if (sheetContext.mounted)
                    ScaffoldMessenger.of(sheetContext).showSnackBar(
                      const SnackBar(
                        content: Text(
                          'Could not post this comment. Please try again.',
                        ),
                      ),
                    );
                }
              } catch (_) {
                if (sheetContext.mounted) {
                  ScaffoldMessenger.of(sheetContext).showSnackBar(
                    const SnackBar(
                      content: Text(
                        'Could not post this comment. Please try again.',
                      ),
                    ),
                  );
                }
              }
            }

            Future<void> reportComment(_CommunityComment item) async {
              final reason = await _showContentReportDialog(
                sheetContext,
                'REPORT COMMENT',
              );
              if (reason == null) return;
              try {
                await FeedService.reportComment(
                  postId: widget.post.id,
                  commentId: item.id,
                  reporterUid: currentUser.uid,
                  reason: reason,
                );
                if (sheetContext.mounted)
                  ScaffoldMessenger.of(sheetContext).showSnackBar(
                    const SnackBar(content: Text('Comment reported.')),
                  );
              } catch (_) {
                if (sheetContext.mounted)
                  ScaffoldMessenger.of(sheetContext).showSnackBar(
                    const SnackBar(
                      content: Text('Could not submit the report.'),
                    ),
                  );
              }
            }

            Widget commentTile(_CommunityComment item, {bool reply = false}) {
              return Container(
                margin: EdgeInsets.only(left: reply ? 34 : 0, bottom: 8),
                padding: const EdgeInsets.fromLTRB(11, 9, 8, 9),
                decoration: BoxDecoration(
                  color: AppTheme.adaptiveWhite(alpha: reply ? 0.025 : 0.035),
                  borderRadius: BorderRadius.circular(14),
                  border: Border.all(color: AppTheme.fillFaint),
                ),
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    CircleAvatar(
                      radius: reply ? 12 : 14,
                      backgroundColor: AppTheme.adaptiveSurface(
                        Color(0xFF111A24),
                      ),
                      child: Icon(
                        Icons.person,
                        size: reply ? 13 : 15,
                        color: AppTheme.luxuryGold,
                      ),
                    ),
                    const SizedBox(width: 9),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
