  Future<void> _like() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null || widget.post.id.isEmpty) return;
    final next = !liked;
    setState(() {
      liked = next;
      widget.post.likes = (widget.post.likes + (next ? 1 : -1))
          .clamp(0, 1000000)
          .toInt();
    });
    try {
      await FeedService.togglePostLike(
        postId: widget.post.id,
        uid: user.uid,
        liked: next,
      );
      _sortFeed();
    } catch (_) {
      if (mounted) {
        setState(() {
          liked = !next;
          widget.post.likes = (widget.post.likes + (next ? -1 : 1))
              .clamp(0, 1000000)
              .toInt();
        });
      }
    }
  }

  Future<void> _follow() async {
    final user = FirebaseAuth.instance.currentUser;
    final targetUid = widget.post.authorUid.trim();
    if (user == null || targetUid.isEmpty || targetUid == user.uid) return;
    final next = !following;
    setState(() {
      following = next;
      widget.post.followers = (widget.post.followers + (next ? 1 : -1))
          .clamp(0, 1000000)
          .toInt();
    });
    final targetFollowerRef = FirebaseFirestore.instance
        .collection('users')
        .doc(targetUid)
        .collection('followers')
        .doc(user.uid);
    final myFollowingRef = FirebaseFirestore.instance
        .collection('users')
        .doc(user.uid)
        .collection('following')
        .doc(targetUid);
    try {
      final batch = FirebaseFirestore.instance.batch();
      if (next) {
        batch.set(targetFollowerRef, {
          'uid': user.uid,
          'createdAt': FieldValue.serverTimestamp(),
        });
        batch.set(myFollowingRef, {
          'uid': targetUid,
          'createdAt': FieldValue.serverTimestamp(),
        });
      } else {
        batch.delete(targetFollowerRef);
        batch.delete(myFollowingRef);
      }
      await batch.commit();

      try {
        final followerSnapshot = await FirebaseFirestore.instance
            .collection('users')
            .doc(targetUid)
            .collection('followers')
            .get();

        await FirebaseFirestore.instance.collection('users').doc(targetUid).set(
          {
            'alphaDenProfile': {'followers': followerSnapshot.docs.length},
          },
          SetOptions(merge: true),
        );
      } catch (_) {}

      _sortFeed();
    } catch (_) {
      if (mounted)
        setState(() {
          following = !next;
          widget.post.followers = (widget.post.followers + (next ? -1 : 1))
              .clamp(0, 1000000)
              .toInt();
        });
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not update follow status. Please try again.'),
          ),
        );
    }
  }

  Future<void> _sharePost() async {
    final post = widget.post;
    final author = post.nickname.trim().isNotEmpty
        ? post.nickname.trim()
        : post.username.trim();
    final content = post.text.trim();
    final tags = <String>[
      ...post.hashtags
          .map((tag) => '#${tag.trim()}')
          .where((tag) => tag != '#'),
      ...post.coins
          .map((coin) => '\$${coin.trim()}')
          .where((coin) => coin != '\$'),
    ];
    final baseUrl = Uri.base;
    final shareUrl = baseUrl
        .replace(
          queryParameters: <String, String>{
            ...baseUrl.queryParameters,
            'post': post.id,
          },
        )
        .toString();
    final textParts = <String>[
      if (content.isNotEmpty) content,
      if (tags.isNotEmpty) tags.join(' '),
      'Posted by ${author.isEmpty ? 'Crypto Doctors Hub' : author}',
      'Crypto Doctors Hub',
    ];
    final shareText = textParts.join('\n\n');
    final shareMessage = '$shareText\n\n$shareUrl';

    Future<void> openShareTarget(
      String name,
      Uri uri, {
      bool copyFirst = false,
    }) async {
      final user = FirebaseAuth.instance.currentUser;
      if (user != null) {
        try {
          await FeedService.recordShare(postId: post.id, uid: user.uid);
          setState(() => widget.post.shares += 1);
        } catch (_) {}
      }
      if (copyFirst) {
        await Clipboard.setData(ClipboardData(text: shareMessage));
      }
      try {
        final launched = await launchUrl(
          uri,
          mode: LaunchMode.externalApplication,
        );
        if (!launched && mounted) {
          ScaffoldMessenger.of(context)
              .showSnackBar(SnackBar(content: Text('Could not open $name.')));
        } else if (copyFirst && mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text('Post content copied. Continue sharing in $name.'),
            ),
          );
        }
      } catch (_) {
        if (mounted)
          ScaffoldMessenger.of(context)
              .showSnackBar(SnackBar(content: Text('Could not open $name.')));
      }
    }

    await showModalBottomSheet<void>(
      context: context,
      backgroundColor: Colors.transparent,
      isScrollControlled: true,
      builder: (sheetContext) {
        final options = <Map<String, dynamic>>[
          {
            'name': 'WhatsApp',
            'icon': Icons.chat_rounded,
            'uri': Uri.parse(
              'https://wa.me/?text=${Uri.encodeComponent(shareMessage)}',
            ),
          },
          {
            'name': 'Twitter / X',
            'icon': Icons.alternate_email_rounded,
            'uri': Uri.parse(
              'https://twitter.com/intent/tweet?text=${Uri.encodeComponent(shareText)}&url=${Uri.encodeComponent(shareUrl)}',
            ),
          },
          {
            'name': 'Discord',
            'icon': Icons.forum_rounded,
            'uri': Uri.parse('https://discord.com/app'),
            'copy': true,
          },
          {
            'name': 'Instagram',
            'icon': Icons.camera_alt_outlined,
            'uri': Uri.parse('https://www.instagram.com/'),
            'copy': true,
          },
          {
            'name': 'Telegram',
            'icon': Icons.send_rounded,
            'uri': Uri.parse(
              'https://t.me/share/url?url=${Uri.encodeComponent(shareUrl)}&text=${Uri.encodeComponent(shareText)}',
            ),
          },
          {
            'name': 'Reddit',
            'icon': Icons.forum_outlined,
            'uri': Uri.parse(
              'https://www.reddit.com/submit?url=${Uri.encodeComponent(shareUrl)}&title=${Uri.encodeComponent('Crypto Doctors Hub post by $author')}',
            ),
          },
        ];
        return SafeArea(
          child: Container(
            margin: const EdgeInsets.fromLTRB(10, 0, 10, 10),
            padding: const EdgeInsets.fromLTRB(14, 12, 14, 14),
            decoration: BoxDecoration(
              color: AppTheme.adaptiveSurface(Color(0xFF0B121A)),
              borderRadius: BorderRadius.circular(22),
              border: Border.all(color: const Color(0x334E9FC1)),
              boxShadow: const [
                BoxShadow(
                  color: Colors.black54,
                  blurRadius: 24,
                  offset: Offset(0, 10),
                ),
              ],
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  width: 38,
                  height: 4,
                  decoration: BoxDecoration(
                    color: AppTheme.borderSoft,
                    borderRadius: BorderRadius.circular(4),
                  ),
                ),
                const SizedBox(height: 12),
                const Text(
                  'SHARE POST',
                  style: TextStyle(
                    fontSize: 11,
                    fontWeight: FontWeight.w900,
                    letterSpacing: 1.1,
                  ),
                ),
                const SizedBox(height: 5),
                Text(
                  'Share the actual CD Feed post and its content.',
                  style: TextStyle(color: AppTheme.textMuted, fontSize: 9.5),
                ),
                const SizedBox(height: 14),
                Wrap(
                  alignment: WrapAlignment.center,
                  spacing: 10,
                  runSpacing: 10,
                  children: [
                    for (final option in options)
                      InkWell(
                        onTap: () {
                          Navigator.pop(sheetContext);
                          openShareTarget(
                            option['name'] as String,
                            option['uri'] as Uri,
                            copyFirst: option['copy'] == true,
                          );
                        },
                        borderRadius: BorderRadius.circular(15),
                        child: SizedBox(
                          width: 86,
                          child: Column(
                            children: [
                              Container(
                                width: 46,
                                height: 46,
                                decoration: BoxDecoration(
                                  color: AppTheme.adaptiveWhite(alpha: .055),
                                  borderRadius: BorderRadius.circular(15),
                                  border: Border.all(
                                    color: AppTheme.borderFaint,
                                  ),
                                ),
                                child: Icon(
                                  option['icon'] as IconData,
                                  color: AppTheme.textPrimary,
                                  size: 21,
                                ),
                              ),
                              const SizedBox(height: 6),
                              Text(
                                option['name'] as String,
