class _UserPayoutPaymentDetailsPage extends StatefulWidget {
  const _UserPayoutPaymentDetailsPage();
  @override
  State<_UserPayoutPaymentDetailsPage> createState() =>
      _UserPayoutPaymentDetailsPageState();
}

class _UserPayoutPaymentDetailsPageState
    extends State<_UserPayoutPaymentDetailsPage> {
  final TextEditingController _detailController = TextEditingController();
  static const _methods = ['TRC20', 'BEP20', 'ERC20', 'Easypaisa'];
  String _method = 'TRC20';
  String _uid = '';
  String _userName = '';
  bool _loading = true;
  bool _saving = false;
  bool _editing = false;
  bool _payoutProcessing = false;
  bool _payoutSuccess = false;
  String _payoutMessage = '';
  Timer? _payoutPollTimer;
  Timer? _dotsTimer;
  int _dotCount = 1;

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _payoutPollTimer?.cancel();
    _dotsTimer?.cancel();
    _detailController.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    final user = AuthService.currentUser;
    if (user == null) {
      if (mounted) setState(() => _loading = false);
      return;
    }
    _uid = user.uid;
    try {
      final profile = await ProfileService.loadUserProfile(user.uid);
      _userName = (profile?['displayName'] ?? user.displayName ?? '')
          .toString()
          .trim();
      final data = await PayoutService.load(uid: user.uid);
      if (data != null) {
        final savedMethod = (data['paymentMethod'] ?? '').toString().trim();
        if (_methods.contains(savedMethod)) _method = savedMethod;
        _detailController.text = (data['paymentDetail'] ?? '').toString();
        if (_userName.isEmpty)
          _userName = (data['userName'] ?? '').toString().trim();
        _editing = data['locked'] != true;
      }
    } catch (_) {}
    if (mounted) setState(() => _loading = false);
  }

  bool get _hasSavedDetails => _detailController.text.trim().isNotEmpty;

  String get _detailLabel {
    switch (_method) {
      case 'BEP20':
        return 'USDT wallet address Ã¢â‚¬â€ BEP20';
      case 'TRC20':
        return 'USDT wallet address Ã¢â‚¬â€ TRC20';
      case 'ERC20':
        return 'USDT wallet address Ã¢â‚¬â€ ERC20';
      default:
        return 'Easypaisa mobile/account number';
    }
  }

  String get _detailHint {
    switch (_method) {
      case 'BEP20':
        return 'Enter the wallet address that should receive your USDT on BEP20.';
      case 'TRC20':
        return 'Enter the wallet address that should receive your USDT on TRC20.';
      case 'ERC20':
        return 'Enter the wallet address that should receive your USDT on ERC20.';
      default:
        return 'Enter the Easypaisa number/account detail that should receive your manual payout.';
    }
  }

  Future<void> _editSavedDetails() async {
    if (_payoutProcessing) return;
    try {
      await PayoutService.unlock(uid: _uid);
      if (mounted) setState(() => _editing = true);
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not unlock payout details: $e')),
        );
    }
  }

  Future<void> _save() async {
    final user = AuthService.currentUser;
    if (user == null || _saving) return;
    final detail = _detailController.text.trim();
    if (detail.isEmpty) {
      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text('Enter your $_detailLabel.')));
      return;
    }
    if (_userName.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Please set your name in Edit Profile before saving payout details.',
          ),
        ),
      );
      return;
    }
    setState(() => _saving = true);
    try {
      await PayoutService.save(
        uid: user.uid,
        userName: _userName,
        paymentMethod: _method,
        paymentDetail: detail,
      );
      if (!mounted) return;
      setState(() => _editing = false);
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Your payout details were saved securely.'),
        ),
      );
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not save your payout details. $e')),
        );
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  void _startDots() {
    _dotsTimer?.cancel();
    _dotCount = 1;
    _dotsTimer = Timer.periodic(const Duration(milliseconds: 420), (_) {
      if (mounted && _payoutProcessing)
        setState(() => _dotCount = _dotCount % 3 + 1);
    });
  }

  void _stopDots() {
    _dotsTimer?.cancel();
    _dotsTimer = null;
  }

  Future<void> _requestPayout() async {
    if (_payoutProcessing || !_hasSavedDetails) return;
    setState(() {
      _payoutProcessing = true;
      _payoutSuccess = false;
      _payoutMessage = 'Sending';
    });
    _startDots();
    try {
      final result = await PayoutService.createPayoutRequest(uid: _uid);
      final request = Map<String, dynamic>.from(
        (result['payout'] as Map?) ?? result,
      );
      final status = (request['status'] ?? '').toString().toLowerCase();
      if (_method == 'Easypaisa' || status == 'pending_admin') {
        _startPayoutPolling((request['payoutRequestId'] ?? '').toString());
        return;
      }
      if (status == 'sent' || status == 'credited' || status == 'completed') {
        await _finishPayoutSuccess();
        return;
      }
      throw StateError(
        (result['message'] ?? 'The payout is still processing.').toString(),
      );
    } catch (e) {
      _stopDots();
      if (mounted)
        setState(() {
          _payoutProcessing = false;
          _payoutMessage = 'Payout could not be started: $e';
        });
    }
  }

  void _startPayoutPolling(String requestId) {
    if (requestId.isEmpty) {
      _stopDots();
      if (mounted)
        setState(() {
          _payoutProcessing = false;
          _payoutMessage = 'The payout request was created, but its tracking ID was missing.';
        });
      return;
    }
    _payoutPollTimer?.cancel();
    _payoutPollTimer = Timer.periodic(Duration(seconds: 5), (_) async {
      try {
        final result = await PayoutService.getPayoutRequest(requestId);
        final status = (result['payout']?['status'] ?? result['status'] ?? '')
            .toString()
            .toLowerCase();
        if (status == 'credited' || status == 'sent' || status == 'completed') {
          _payoutPollTimer?.cancel();
          await _finishPayoutSuccess();
        } else if (status == 'rejected' ||
            status == 'failed' ||
            status == 'cancelled') {
          _payoutPollTimer?.cancel();
          _stopDots();
          if (mounted)
            setState(() {
              _payoutProcessing = false;
              _payoutMessage = 'Payout status: ${status.toUpperCase()}';
            });
        }
      } catch (_) {
        // Keep waiting; transient polling errors must not create a false success.
      }
    });
  }

  Future<void> _finishPayoutSuccess() async {
    _payoutPollTimer?.cancel();
    _stopDots();
    if (!mounted) return;
    setState(() {
      _payoutSuccess = true;
      _payoutMessage = 'Successfully credited. Please check your account.';
    });
    await Future<void>.delayed(const Duration(milliseconds: 1500));
    if (!mounted) return;
    setState(() {
      _payoutProcessing = false;
      _payoutSuccess = false;
    });
  }

  InputDecoration _decoration(String label, IconData icon) => InputDecoration(
    labelText: label,
    helperText: _detailHint,
    helperMaxLines: 3,
    prefixIcon: Icon(icon, size: 18, color: AppTheme.luxuryGold),
    filled: true,
    fillColor: Theme.of(context).brightness == Brightness.light
        ? const Color(0xFFFFFCF6)
