class ReferralPaymentDetailsCard extends StatefulWidget {
  const ReferralPaymentDetailsCard({super.key});

  @override
  State<ReferralPaymentDetailsCard> createState() =>
      _ReferralPaymentDetailsCardState();
}

class _ReferralPaymentDetailsCardState
    extends State<ReferralPaymentDetailsCard> {
  final _recipientController = TextEditingController();
  final _trc20Controller = TextEditingController();
  final _bep20Controller = TextEditingController();
  final _erc20Controller = TextEditingController();
  final _easypaisaController = TextEditingController();
  String _country = 'Pakistan';
  String _preferredMethod = 'USDT TRC-20';
  bool _loading = true;
  bool _saving = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _recipientController.dispose();
    _trc20Controller.dispose();
    _bep20Controller.dispose();
    _erc20Controller.dispose();
    _easypaisaController.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    final user = AuthService.currentUser;
    if (user == null) {
      if (mounted) setState(() => _loading = false);
      return;
    }
    try {
      final data = await ProfileService.loadReferralPaymentDetails(
        uid: user.uid,
      );
      if (data != null) {
        _country = (data['country'] ?? 'Pakistan').toString();
        if (_country != 'Pakistan') _country = 'Other';
        _preferredMethod = (data['preferredMethod'] ?? 'USDT TRC-20')
            .toString();
        if (!const [
          'USDT TRC-20',
          'USDT BEP-20',
          'USDT ERC-20',
          'Easypaisa',
        ].contains(_preferredMethod))
          _preferredMethod = 'USDT TRC-20';
        _recipientController.text = (data['recipientName'] ?? '').toString();
        _trc20Controller.text = (data['usdtTrc20Address'] ?? '').toString();
        _bep20Controller.text = (data['usdtBep20Address'] ?? '').toString();
        _erc20Controller.text = (data['usdtErc20Address'] ?? '').toString();
        _easypaisaController.text = (data['easypaisaNumber'] ?? '').toString();
        if (_country != 'Pakistan' && _preferredMethod == 'Easypaisa')
          _preferredMethod = 'USDT TRC-20';
      }
    } catch (_) {}
    if (mounted) setState(() => _loading = false);
  }

  Future<void> _save() async {
    final user = AuthService.currentUser;
    if (user == null || _saving) return;
    final recipient = _recipientController.text.trim();
    final trc20 = _trc20Controller.text.trim();
    final bep20 = _bep20Controller.text.trim();
    final erc20 = _erc20Controller.text.trim();
    final easypaisa = _easypaisaController.text.trim();
    if (recipient.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Enter the recipient name for referral incentives.'),
        ),
      );
      return;
    }
    if (trc20.isEmpty &&
        bep20.isEmpty &&
        erc20.isEmpty &&
        (_country != 'Pakistan' || easypaisa.isEmpty)) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Add at least one USDT address or, for Pakistan, an Easypaisa number.',
          ),
        ),
      );
      return;
    }
    if (_preferredMethod == 'Easypaisa' && _country != 'Pakistan') {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Easypaisa is only available for direct PKR payments in Pakistan.',
          ),
        ),
      );
      return;
    }
    setState(() => _saving = true);
    try {
      await ProfileService.saveReferralPaymentDetails(
        uid: user.uid,
        country: _country,
        preferredMethod: _preferredMethod,
        recipientName: recipient,
        usdtTrc20Address: trc20,
        usdtBep20Address: bep20,
        usdtErc20Address: erc20,
        easypaisaNumber: easypaisa,
      );
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Payment details saved securely.')),
      );
    } catch (_) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not save payment details. Please try again.'),
          ),
        );
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

