class _ReferralCrownBadge extends StatefulWidget {
  final int referrals;
  final bool flamingAura;
  const _ReferralCrownBadge({
    required this.referrals,
    this.flamingAura = false,
  });
  @override
  State<_ReferralCrownBadge> createState() => _ReferralCrownBadgeState();
}

class _ReferralCrownBadgeState extends State<_ReferralCrownBadge>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 2400),
  )..repeat();

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final r = widget.referrals;
    final flame = widget.flamingAura || r >= 10;
    final purple = r >= 3 && r <= 4;
    final enhancedGold = r >= 8 && r <= 9;
    final gold = r >= 5 && r <= 9;
    final crown = widget.flamingAura
        ? const Color(0xFFE7C76B)
        : r == 0
        ? const Color(0xFF9A6748)
        : r <= 2
        ? const Color(0xFF4FA8FF)
        : purple
        ? const Color(0xFFB86CFF)
        : flame
        ? const Color(0xFFE7C76B)
        : const Color(0xFFFFD34D);
    final dark = r == 0
        ? const Color(0xFF382116)
        : r <= 2
        ? const Color(0xFF0B294D)
        : purple
        ? const Color(0xFF32104F)
        : flame
        ? const Color(0xFF07080A)
        : const Color(0xFF714700);

    return AnimatedBuilder(
      animation: _controller,
      builder: (_, _) {
        final t = _controller.value * math.pi * 2;
        final pulse = .72 + .28 * ((math.sin(t) + 1) / 2);
        final glowColor = purple
            ? const Color(0xFFB86CFF)
            : gold
            ? const Color(0xFFFFD34D)
            : crown;
        final glowStrength = flame
            ? 1.25
            : enhancedGold
            ? 1.12
            : purple
            ? .95
            : .62;
        return SizedBox(
          width: 27,
          height: flame ? 28 : 23,
          child: Stack(
            clipBehavior: Clip.none,
            alignment: Alignment.center,
            children: [
              if (flame)
                Positioned.fill(
                  child: CustomPaint(
                    painter: _MiniCrownFlamePainter(
                      progress: _controller.value,
                    ),
                  ),
                ),
              Container(
                width: 24,
                height: 20,
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(7),
                  gradient: LinearGradient(
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                    colors: flame
                        ? [
                            const Color(0xFF30343A),
                            const Color(0xFF08090B),
                            const Color(0xFF000000),
                          ]
                        : [
                            dark,
                            crown.withValues(alpha: .38),
                            const Color(0xFF080A0C),
                          ],
                  ),
                  border: Border.all(
                    color: flame
                        ? const Color(0xFFE7C76B)
                        : crown.withValues(alpha: .82),
                    width: flame ? 1.0 : .75,
                  ),
                  boxShadow: [
                    BoxShadow(
                      color: glowColor.withValues(
                        alpha: .17 + .20 * pulse * glowStrength,
                      ),
                      blurRadius: flame
                          ? 13
                          : enhancedGold
                          ? 9
                          : purple
                          ? 8
                          : 5,
                      spreadRadius: flame
                          ? 1.4
                          : enhancedGold
                          ? .8
                          : 0,
                    ),
                    if (flame)
                      BoxShadow(
                        color: const Color(0xFFFF5A2A)
                            .withValues(alpha: .20 + .12 * pulse),
                        blurRadius: 16,
                        spreadRadius: 2,
                      ),
                  ],
                ),
                child: CustomPaint(
                  painter: _ThreeDCrownPainter(
                    base: crown,
                    dark: dark,
                    progress: _controller.value,
                    blackGold: flame,
                  ),
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

class _ThreeDCrownPainter extends CustomPainter {
  final Color base, dark;
  final double progress;
  final bool blackGold;
  const _ThreeDCrownPainter({
    required this.base,
    required this.dark,
    required this.progress,
    this.blackGold = false,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final w = size.width;
    final h = size.height;

    final shadow = Path()
      ..moveTo(w * .08, h * .25)
      ..lineTo(w * .26, h * .43)
      ..lineTo(w * .50, h * .29)
      ..lineTo(w * .74, h * .43)
      ..lineTo(w * .92, h * .25)
      ..lineTo(w * .82, h * .83)
      ..quadraticBezierTo(w * .50, h * .96, w * .18, h * .83)
      ..close();
    canvas.drawPath(
      shadow,
      Paint()..color = Colors.black.withValues(alpha: .78),
    );

    final front = Path()
      ..moveTo(w * .07, h * .20)
      ..lineTo(w * .25, h * .42)
      ..lineTo(w * .50, h * .27)
      ..lineTo(w * .75, h * .42)
      ..lineTo(w * .93, h * .20)
      ..lineTo(w * .82, h * .70)
      ..quadraticBezierTo(w * .50, h * .86, w * .18, h * .70)
      ..close();

    final shader = LinearGradient(
      begin: Alignment.topLeft,
      end: Alignment.bottomRight,
      colors: blackGold
          ? [
              const Color(0xFFF5E3A0),
              const Color(0xFF8E7440),
              const Color(0xFF22252A),
              const Color(0xFF050608),
            ]
          : [AppTheme.adaptiveWhite(alpha: .88), base, dark],
      stops: blackGold ? const [.0, .28, .62, 1] : null,
    ).createShader(Rect.fromLTWH(0, 0, w, h));
    canvas.drawPath(front, Paint()..shader = shader);

    final edge = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = blackGold ? .9 : .7
      ..color = (blackGold ? const Color(0xFFFFE7A0) : AppTheme.textPrimary)
          .withValues(alpha: .38);
    canvas.drawPath(front, edge);

    final glintAlpha = .42 + .22 * ((math.sin(progress * math.pi * 2) + 1) / 2);
    final glint = Paint()
      ..color = AppTheme.adaptiveWhite(alpha: glintAlpha)
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, .7);
    canvas.drawCircle(Offset(w * .25, h * .42), 1.0, glint);
    canvas.drawCircle(Offset(w * .50, h * .28), 1.15, glint);
    canvas.drawCircle(Offset(w * .75, h * .42), 1.0, glint);

    if (blackGold) {
      final inner = Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = .55
        ..color = const Color(0xFFFFD86A).withValues(alpha: .42);
      final innerPath = Path()
        ..moveTo(w * .17, h * .57)
        ..quadraticBezierTo(w * .50, h * .75, w * .83, h * .57);
      canvas.drawPath(innerPath, inner);
    }
  }

  @override
  bool shouldRepaint(covariant _ThreeDCrownPainter oldDelegate) =>
      oldDelegate.progress != progress ||
      oldDelegate.base != base ||
      oldDelegate.dark != dark ||
      oldDelegate.blackGold != blackGold;
}

class _MiniCrownFlamePainter extends CustomPainter {
  final double progress;
  const _MiniCrownFlamePainter({required this.progress});

  @override
  void paint(Canvas canvas, Size size) {
    final t = progress * math.pi * 2;

    void drawCornerFlame(Offset base, double scale, double phase, bool mirror) {
      final sway = math.sin(t * 1.15 + phase) * scale * .13;
      final outer = Path()
        ..moveTo(base.dx - scale * .34, base.dy)
        ..quadraticBezierTo(
          base.dx - scale * .12 + sway,
          base.dy - scale * .34,
          base.dx + sway,
          base.dy - scale,
        )
        ..quadraticBezierTo(
          base.dx + scale * .18 + sway,
          base.dy - scale * .50,
          base.dx + scale * .38,
          base.dy,
        )
        ..close();
      canvas.drawPath(
        outer,
        Paint()
          ..color = const Color(0xFFFF3B22).withValues(alpha: .56)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 2.8),
      );
      final mid = Path()
        ..moveTo(base.dx - scale * .23, base.dy)
        ..quadraticBezierTo(
          base.dx - scale * .06 + sway,
          base.dy - scale * .32,
          base.dx + sway,
          base.dy - scale * .78,
        )
        ..quadraticBezierTo(
          base.dx + scale * .12 + sway,
          base.dy - scale * .39,
          base.dx + scale * .25,
          base.dy,
        )
        ..close();
      canvas.drawPath(
        mid,
        Paint()..color = const Color(0xFFFF8A24).withValues(alpha: .82),
      );
      final inner = Path()
        ..moveTo(base.dx - scale * .11, base.dy)
        ..quadraticBezierTo(
          base.dx + sway * .45,
          base.dy - scale * .28,
          base.dx + sway,
          base.dy - scale * .58,
        )
        ..quadraticBezierTo(
          base.dx + scale * .07 + sway,
          base.dy - scale * .30,
          base.dx + scale * .13,
          base.dy,
        )
        ..close();
      canvas.drawPath(
        inner,
        Paint()..color = const Color(0xFFFFE7A0).withValues(alpha: .94),
      );
    }

    // Flames originate from the four corners and rise outward, rather than
    // looking like a flat row underneath the crown.
    drawCornerFlame(Offset(3, size.height - 2), 9, 0.4, true);
    drawCornerFlame(Offset(size.width - 3, size.height - 2), 9, 2.1, true);
    drawCornerFlame(Offset(4, size.height * .72), 6.5, 3.4, true);
    drawCornerFlame(Offset(size.width - 4, size.height * .72), 6.5, 4.8, true);
  }

  @override
  bool shouldRepaint(covariant _MiniCrownFlamePainter oldDelegate) =>
      oldDelegate.progress != progress;
}

