class _LiveMarketStore {
  static const _url =
      'https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&order=market_cap_desc&per_page=100&page=1&sparkline=false&price_change_percentage=24h';
  static const _binanceUrl = 'https://api.binance.com/api/v3/ticker/24hr';
  static const Duration _cacheFreshFor = Duration(seconds: 25);

  static List<_MarketAsset>? _cachedAssets;
  static DateTime? _cachedAt;
  static Future<List<_MarketAsset>>? _inFlight;

  static List<_MarketAsset>? get cachedAssets => _cachedAssets;

  static bool get _hasFreshCache {
    final cachedAt = _cachedAt;
    final cached = _cachedAssets;
    if (cachedAt == null || cached == null || cached.isEmpty) return false;
    return DateTime.now().difference(cachedAt) < _cacheFreshFor;
  }

  static void _remember(List<_MarketAsset> assets) {
    if (assets.isEmpty) return;
    _cachedAssets = List<_MarketAsset>.unmodifiable(assets);
    _cachedAt = DateTime.now();
  }

  static Future<List<_MarketAsset>> fetchTop100({
    bool forceRefresh = false,
  }) {
    if (!forceRefresh && _hasFreshCache) {
      return Future<List<_MarketAsset>>.value(_cachedAssets!);
    }

    final activeRequest = _inFlight;
    if (activeRequest != null) return activeRequest;

    final request = _fetchTop100Network();
    _inFlight = request;
    request.whenComplete(() {
      if (identical(_inFlight, request)) _inFlight = null;
    });
    return request;
  }

  static Future<List<_MarketAsset>> _fetchTop100Network() async {
    try {
      final response = await html.HttpRequest.request(
        _url,
        method: 'GET',
        requestHeaders: const {'accept': 'application/json'},
      );
      if (response.status == 200) {
        final decoded = jsonDecode(response.responseText ?? '[]');
        if (decoded is List) {
          final assets = decoded
              .whereType<Map>()
              .map(
                (item) =>
                    _MarketAsset.fromJson(Map<String, dynamic>.from(item)),
              )
              .where((asset) => asset.price > 0)
              .toList();
          if (assets.length >= 4) {
            _remember(assets);
            return _cachedAssets!;
          }
        }
      }
    } catch (_) {
      // Try the Binance fallback below. If that also fails, the last
      // successful snapshot remains available to the UI.
    }

    try {
      final assets = await _fetchFromBinance();
      if (assets.isNotEmpty) {
        _remember(assets);
        return _cachedAssets!;
      }
    } catch (_) {
      final cached = _cachedAssets;
      if (cached != null && cached.isNotEmpty) return cached;
      rethrow;
    }

    final cached = _cachedAssets;
    if (cached != null && cached.isNotEmpty) return cached;
    throw Exception('Live market services are temporarily unavailable.');
  }

  static String _logoUrlForSymbol(String symbol) {
    const coinGeckoIds = <String, String>{
      'BTC': 'bitcoin',
      'ETH': 'ethereum',
      'SOL': 'solana',
      'XRP': 'ripple',
      'DOGE': 'dogecoin',
      'BNB': 'binancecoin',
      'ADA': 'cardano',
      'AVAX': 'avalanche-2',
      'LINK': 'chainlink',
      'TRX': 'tron',
      'DOT': 'polkadot',
      'LTC': 'litecoin',
      'BCH': 'bitcoin-cash',
      'UNI': 'uniswap',
      'ATOM': 'cosmos',
      'ETC': 'ethereum-classic',
    };
    final id = coinGeckoIds[symbol.toUpperCase()];
    if (id != null) {
      return 'https://coin-images.coingecko.com/coins/images/'
          '${_coinGeckoImageId(id)}/large/$id.png';
    }
    // Binance fallback symbols do not include a CoinGecko coin id.
    // CoinCap provides a direct PNG logo path keyed by symbol.
    return 'https://assets.coincap.io/assets/icons/${symbol.toLowerCase()}@2x.png';
  }

  static int _coinGeckoImageId(String id) {
    const imageIds = <String, int>{
      'bitcoin': 1,
      'ethereum': 279,
      'solana': 4128,
      'ripple': 44,
      'dogecoin': 5,
      'binancecoin': 825,
      'cardano': 975,
      'avalanche-2': 12559,
      'chainlink': 877,
      'tron': 1094,
      'polkadot': 12171,
      'litecoin': 2,
      'bitcoin-cash': 780,
      'uniswap': 12504,
      'cosmos': 5894,
      'ethereum-classic': 1321,
    };
    return imageIds[id] ?? 0;
  }

  static Future<List<_MarketAsset>> _fetchFromBinance() async {
    final response = await html.HttpRequest.request(
      _binanceUrl,
      method: 'GET',
      requestHeaders: const {'accept': 'application/json'},
    );
    if (response.status != 200)
      throw Exception('Live market services are temporarily unavailable.');
    final decoded = jsonDecode(response.responseText ?? '[]');
    if (decoded is! List) throw Exception('Invalid backup market response.');
    const preferred = <String>[
      'BTC',
      'ETH',
      'SOL',
      'XRP',
      'DOGE',
      'BNB',
      'ADA',
      'AVAX',
      'LINK',
      'TRX',
      'DOT',
      'LTC',
      'BCH',
      'UNI',
      'ATOM',
      'ETC',
    ];
    final rows = decoded
        .whereType<Map>()
        .map((raw) {
          final item = Map<String, dynamic>.from(raw);
          final symbol = (item['symbol'] ?? '').toString().toUpperCase();
          if (!symbol.endsWith('USDT')) return null;
          final base = symbol.substring(0, symbol.length - 4);
          if (base.isEmpty ||
              base.contains('UP') ||
              base.contains('DOWN') ||
              base.contains('BULL') ||
              base.contains('BEAR'))
            return null;
          final price =
              double.tryParse((item['lastPrice'] ?? '').toString()) ?? 0;
          final change =
              double.tryParse((item['priceChangePercent'] ?? '').toString()) ??
              0;
          final volume =
              double.tryParse((item['quoteVolume'] ?? '').toString()) ?? 0;
          if (price <= 0) return null;
          return <String, dynamic>{
            'symbol': base,
            'price': price,
            'change': change,
            'volume': volume,
          };
        })
        .whereType<Map<String, dynamic>>()
        .toList();
    final bySymbol = <String, Map<String, dynamic>>{
      for (final row in rows) row['symbol'] as String: row,
    };
    final selected = <Map<String, dynamic>>[];
    for (final symbol in preferred) {
      final row = bySymbol[symbol];
      if (row != null) selected.add(row);
    }
    final remainder =
        rows.where((row) => !preferred.contains(row['symbol'])).toList()..sort(
          (a, b) => (b['volume'] as double).compareTo(a['volume'] as double),
        );
    selected.addAll(remainder);
    return selected
        .take(100)
        .map(
          (row) => _MarketAsset(
            symbol: row['symbol'] as String,
            name: row['symbol'] as String,
            price: row['price'] as double,
            change24h: row['change'] as double,
            logoUrl: _logoUrlForSymbol(row['symbol'] as String),
          ),
        )
        .toList();
  }
}

class LiveMarketPreview extends StatefulWidget {
  const LiveMarketPreview({super.key});

  @override
  State<LiveMarketPreview> createState() => _LiveMarketPreviewState();
}

class _LiveMarketPreviewState extends State<LiveMarketPreview>
    with AutomaticKeepAliveClientMixin<LiveMarketPreview> {
  List<_MarketAsset>? _marketData;
  Timer? _marketTimer;
  bool _initialLoading = true;
  bool _backgroundRefreshRunning = false;

  @override
  bool get wantKeepAlive => true;

  @override
  void initState() {
    super.initState();
    final cached = _LiveMarketStore.cachedAssets;
    if (cached != null && cached.isNotEmpty) {
      _marketData = cached;
      _initialLoading = false;
      unawaited(_refreshInBackground());
    } else {
      unawaited(_loadInitialMarket());
    }
    _marketTimer = Timer.periodic(const Duration(seconds: 30), (_) {
      unawaited(_refreshInBackground());
    });
  }

  Future<void> _loadInitialMarket() async {
    if (_marketData == null && mounted) {
      setState(() => _initialLoading = true);
    }
    try {
      final assets = await _LiveMarketStore.fetchTop100();
      if (!mounted || assets.isEmpty) return;
      setState(() {
        _marketData = assets;
        _initialLoading = false;
      });
    } catch (_) {
      if (!mounted) return;
      setState(() => _initialLoading = false);
    }
  }

  Future<void> _refreshInBackground() async {
    if (!mounted || _backgroundRefreshRunning) return;
    _backgroundRefreshRunning = true;
    try {
      final latest = await _LiveMarketStore.fetchTop100(forceRefresh: true);
      if (!mounted || latest.isEmpty) return;
      setState(() {
        // Keep the existing tiles mounted while only their values update.
        // Never re-enter the initial loading spinner after first success.
        _marketData = latest;
      });
    } catch (_) {
      // Keep the last successful market snapshot visible.
    } finally {
      _backgroundRefreshRunning = false;
    }
  }

  @override
  void dispose() {
    _marketTimer?.cancel();
    super.dispose();
  }

  void _refresh() {
    if (_marketData == null) {
      unawaited(_loadInitialMarket());
    } else {
      unawaited(_refreshInBackground());
    }
  }

  @override
  Widget build(BuildContext context) {
    super.build(context);
    final data = _marketData;
    if (data == null && _initialLoading) {
      return const SizedBox(
        height: 170,
        child: Center(child: CircularProgressIndicator()),
      );
    }
    if (data == null || data.isEmpty) {
      return Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            'Live market data could not be loaded right now.',
            style: TextStyle(color: AppTheme.textSoft, fontSize: 12),
          ),
          const SizedBox(height: 8),
          TextButton.icon(
            onPressed: _refresh,
            icon: const Icon(Icons.refresh),
            label: const Text('RETRY'),
          ),
        ],
      );
    }

    final visible = data.take(4).toList();

    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Expanded(child: _MarketPreviewTile(asset: visible[0])),
            const SizedBox(width: 10),
            if (visible.length > 1)
              Expanded(child: _MarketPreviewTile(asset: visible[1]))
            else
              const Expanded(child: SizedBox()),
          ],
        ),
        const SizedBox(height: 10),
        Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            if (visible.length > 2)
              Expanded(child: _MarketPreviewTile(asset: visible[2]))
            else
              const Expanded(child: SizedBox()),
            const SizedBox(width: 10),
            if (visible.length > 3)
              Expanded(child: _MarketPreviewTile(asset: visible[3]))
            else
              const Expanded(child: SizedBox()),
          ],
        ),
        const SizedBox(height: 2),
        IconButton(
          tooltip: 'Open Top 100 market',
          onPressed: () {
            Navigator.of(context).push(
              MaterialPageRoute(
                builder: (_) => _Top100MarketPage(assets: data),
              ),
            );
          },
          icon: Icon(
            Icons.keyboard_arrow_down_rounded,
            color: AppTheme.textSecondary,
            size: 24,
          ),
          visualDensity: VisualDensity.compact,
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints(minWidth: 30, minHeight: 30),
        ),
      ],
    );
  }
}

