class _LiveCoinChartStore {
  static const supportedSymbols = <String>{'BTC', 'ETH', 'SOL', 'XRP'};

  static Future<_CoinChartData> fetch(String symbol) async {
    if (!supportedSymbols.contains(symbol)) {
      throw Exception('Chart is not enabled for this market asset.');
    }
    final pair = '${symbol}USDT';
    final uri = Uri.parse(
      'https://api.binance.com/api/v3/klines?symbol=$pair&interval=1m&limit=60',
    );
    final response = await html.HttpRequest.request(
      uri.toString(),
      method: 'GET',
      requestHeaders: const {'accept': 'application/json'},
    );
    if (response.status != 200) {
      throw Exception('Live chart data is temporarily unavailable.');
    }
    final decoded = jsonDecode(response.responseText ?? '[]');
    if (decoded is! List || decoded.isEmpty) {
      throw Exception('No live chart data is available.');
    }
    final closes = <double>[];
    for (final row in decoded) {
      if (row is! List || row.length < 5) continue;
      final close = double.tryParse(row[4].toString());
      if (close != null && close > 0) closes.add(close);
    }
    if (closes.length < 2)
      throw Exception('No usable live chart data is available.');
    return _CoinChartData(
      symbol: symbol,
      prices: closes,
      currentPrice: closes.last,
    );
  }
}

