class _LiveCoinChartPainter extends CustomPainter {
  final List<double> prices;
  final bool positive;
  _LiveCoinChartPainter({required this.prices, required this.positive});

  @override
  void paint(Canvas canvas, Size size) {
    if (prices.length < 2 || size.width <= 0 || size.height <= 0) return;
    final minPrice = prices.reduce(math.min);
    final maxPrice = prices.reduce(math.max);
    final range = math.max(maxPrice - minPrice, maxPrice * 0.000001);
    final chartRect = Rect.fromLTWH(
      10,
      10,
      math.max(1, size.width - 20),
      math.max(1, size.height - 24),
    );

    final grid = Paint()
      ..color = AppTheme.adaptiveWhite(alpha: 0.06)
      ..strokeWidth = 1;
    for (int i = 1; i < 5; i++) {
      final y = chartRect.top + chartRect.height * i / 5;
      canvas.drawLine(
        Offset(chartRect.left, y),
        Offset(chartRect.right, y),
        grid,
      );
    }

    final path = Path();
    for (int i = 0; i < prices.length; i++) {
      final x = chartRect.left + chartRect.width * i / (prices.length - 1);
      final y =
          chartRect.bottom -
          ((prices[i] - minPrice) / range) * chartRect.height;
      if (i == 0) {
        path.moveTo(x, y);
      } else {
        path.lineTo(x, y);
      }
    }

    final line = Paint()
      ..color = positive ? AppTheme.neonGreen : const Color(0xFFE05252)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2.2
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;
    canvas.drawPath(path, line);

    final fill = Path.from(path)
      ..lineTo(chartRect.right, chartRect.bottom)
      ..lineTo(chartRect.left, chartRect.bottom)
      ..close();
    final fillPaint = Paint()
      ..shader = LinearGradient(
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
        colors: [
          (positive ? AppTheme.neonGreen : const Color(0xFFE05252)).withValues(
            alpha: 0.16,
          ),
          Colors.transparent,
        ],
      ).createShader(chartRect);
    canvas.drawPath(fill, fillPaint);

    final lastX = chartRect.right;
    final lastY =
        chartRect.bottom -
        ((prices.last - minPrice) / range) * chartRect.height;
    final dot = Paint()
      ..color = positive ? AppTheme.neonGreen : const Color(0xFFE05252);
    canvas.drawCircle(Offset(lastX, lastY), 4, dot);
  }

  @override
  bool shouldRepaint(covariant _LiveCoinChartPainter oldDelegate) =>
      oldDelegate.prices != prices || oldDelegate.positive != positive;
}

String _formatMarketPrice(double price) {
  if (price >= 1000) return '\$${price.toStringAsFixed(2)}';
  if (price >= 1) return '\$${price.toStringAsFixed(2)}';
  if (price >= 0.01) return '\$${price.toStringAsFixed(4)}';
  return '\$${price.toStringAsFixed(8)}';
}

