}

class _Top100MarketPageState extends State<_Top100MarketPage> {
  late final ScrollController _controller;
  late List<_MarketAsset> _assets;
  Timer? _marketTimer;

  @override
  void initState() {
    super.initState();
    _controller = ScrollController();
    _assets = List<_MarketAsset>.from(widget.assets);
    _marketTimer = Timer.periodic(const Duration(seconds: 30), (_) async {
      try {
        final latest = await _LiveMarketStore.fetchTop100();
        if (!mounted) return;
        setState(() => _assets = latest);
      } catch (_) {}
    });
  }

  @override
  void dispose() {
    _marketTimer?.cancel();
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('TOP 100 LIVE MARKET')),
      body: RefreshIndicator(
        onRefresh: () async {
          try {
            final latest = await _LiveMarketStore.fetchTop100();
            if (!mounted) return;
            setState(() => _assets = latest);
          } catch (_) {}
        },
        child: AnimatedBuilder(
          animation: _controller,
          builder: (context, _) {
            return ListView.builder(
              controller: _controller,
              physics: const BouncingScrollPhysics(
                parent: AlwaysScrollableScrollPhysics(),
              ),
              padding: const EdgeInsets.fromLTRB(12, 12, 12, 24),
              itemCount: _assets.length,
              itemBuilder: (context, index) {
                final asset = _assets[index];
                final offset = _controller.hasClients
                    ? _controller.offset
                    : 0.0;
                final itemTop = index * 76.0;
                final distance = (itemTop - offset).abs();
                final factor = (1.0 - (distance / 420.0)).clamp(0.0, 1.0);
                return Transform.translate(
                  offset: Offset((1 - factor) * 12, 0),
                  child: Transform.scale(
                    scale: 0.97 + factor * 0.03,
                    child: Padding(
                      padding: const EdgeInsets.only(bottom: 8),
                      child: _MarketTop100Card(rank: index + 1, asset: asset),
                    ),
                  ),
                );
              },
            );
          },
        ),
      ),
    );
  }
}

