class _GalacticFeedTextPainter extends CustomPainter {
  final double progress;
  _GalacticFeedTextPainter({required this.progress});

  @override
  void paint(Canvas canvas, Size size) {
    final style = TextStyle(
      fontSize: 20,
      fontWeight: FontWeight.w900,
      letterSpacing: 1.3,
      color: AppTheme.textPrimary,
    );
    final tp = TextPainter(
      text: TextSpan(text: "CD's FEED", style: style),
      textDirection: TextDirection.ltr,
    )..layout(maxWidth: size.width);
    tp.paint(canvas, Offset.zero);

    // Stars are drawn into a layer and then masked by the exact glyph shapes,
    // so the moving particles stay inside every letter.
    canvas.saveLayer(Offset.zero & size, Paint());
    final starPaint = Paint();
    for (int i = 0; i < 42; i++) {
      final x =
          ((i * 47.0) % math.max(1.0, size.width)) +
          math.sin(progress * math.pi * 2 + i) * 7;
      final y = 8 + ((i * 23.0) % 42);
      final z =
          0.35 +
          0.65 *
              (0.5 +
                  0.5 *
                      math.sin(progress * math.pi * 2 * (1 + i % 3) + i * 1.7));
      starPaint.color = AppTheme.adaptiveWhite(alpha: z);
      canvas.drawCircle(Offset(x, y), i % 6 == 0 ? 1.6 : 0.75, starPaint);
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _GalacticFeedTextPainter oldDelegate) =>
      oldDelegate.progress != progress;
}

