}

class _Feed3DWorldPainter extends CustomPainter {
  final double progress;
  _Feed3DWorldPainter({required this.progress});

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width * 0.50, size.height * 0.50);
    final radius = math.min(size.width, size.height) * 0.39;

    // Original Web-3 globe: blue glass sphere, moving meridians, latitude lines,
    // a subtle atmosphere and a single slow orbital data ring.
    final shadow = Paint()
      ..color = Colors.black.withValues(alpha: 0.42)
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 5);
    canvas.drawOval(
      Rect.fromCenter(
        center: Offset(center.dx + 1.5, center.dy + radius * 0.86),
        width: radius * 1.45,
        height: radius * 0.28,
      ),
      shadow,
    );

    final sphereRect = Rect.fromCircle(center: center, radius: radius);
    final sphere = Paint()
      ..shader = RadialGradient(
        center: const Alignment(-0.34, -0.38),
        radius: 1.10,
        colors: const [
          Color(0xFFF7FCFF),
          Color(0xFF67B5FF),
          Color(0xFF176BDB),
          Color(0xFF041F61),
        ],
        stops: const [0.0, 0.28, 0.66, 1.0],
      ).createShader(sphereRect);
    canvas.drawCircle(center, radius, sphere);

    canvas.save();
    canvas.clipPath(Path()..addOval(sphereRect));

    final rotation = progress * math.pi * 2;
    final grid = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 0.72
      ..color = const Color(0xFFBDE2FF).withValues(alpha: 0.34);

    // Latitude bands.
    for (int i = -2; i <= 2; i++) {
      final y = center.dy + i * radius * 0.27;
      final widthFactor = 1.0 - i.abs() * 0.08;
      canvas.drawOval(
        Rect.fromCenter(
          center: Offset(center.dx, y),
          width: radius * 1.84 * widthFactor,
          height: radius * (0.30 + i.abs() * 0.035),
        ),
        grid,
      );
    }

    // Curved meridians create the 3D rotation effect.
    for (int i = -2; i <= 2; i++) {
      final phase = rotation + i * math.pi / 5;
      final x = math.sin(phase) * radius * 0.68;
      canvas.drawOval(
        Rect.fromCenter(
          center: Offset(center.dx + x, center.dy),
          width: radius * (0.72 + 0.18 * math.cos(phase).abs()),
          height: radius * 1.86,
        ),
        grid,
      );
    }

    // Minimal abstract land shapes Ã¢â‚¬â€ intentionally original rather than copied
    // from the supplied reference image.
    final land = Paint()
      ..color = const Color(0xFFE7F6FF).withValues(alpha: 0.82);
    final drift = math.sin(rotation) * radius * 0.10;
    final landPath = Path()
      ..moveTo(center.dx - radius * 0.56 + drift, center.dy - radius * 0.30)
      ..quadraticBezierTo(
        center.dx - radius * 0.34 + drift,
        center.dy - radius * 0.58,
        center.dx - radius * 0.10 + drift,
        center.dy - radius * 0.28,
      )
      ..quadraticBezierTo(
        center.dx - radius * 0.22 + drift,
        center.dy - radius * 0.03,
        center.dx - radius * 0.46 + drift,
        center.dy + radius * 0.05,
      )
      ..close();
    canvas.drawPath(landPath, land);

    final lowerLand = Path()
      ..moveTo(center.dx + radius * 0.02 + drift, center.dy + radius * 0.08)
      ..quadraticBezierTo(
        center.dx + radius * 0.35 + drift,
        center.dy - radius * 0.02,
        center.dx + radius * 0.31 + drift,
        center.dy + radius * 0.27,
      )
      ..quadraticBezierTo(
        center.dx + radius * 0.17 + drift,
        center.dy + radius * 0.52,
        center.dx - radius * 0.02 + drift,
        center.dy + radius * 0.36,
      )
      ..close();
    canvas.drawPath(lowerLand, land);

    canvas.restore();

    // Atmospheric rim.
    final rim = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.35
      ..color = const Color(0xFF9ED7FF).withValues(alpha: 0.92);
    canvas.drawCircle(center, radius * 0.985, rim);

    // Slow orbiting Web-3 data ring.
    final ringAngle = rotation * 0.55;
    canvas.save();
    canvas.translate(center.dx, center.dy);
    canvas.rotate(ringAngle);
    final ringPaint = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.1
      ..color = const Color(0xFF63D7FF).withValues(alpha: 0.70);
    canvas.drawOval(
      Rect.fromCenter(
        center: Offset.zero,
        width: radius * 2.18,
        height: radius * 0.62,
      ),
      ringPaint,
    );
    canvas.drawCircle(
      Offset(radius * 1.02, 0),
      2.2,
      Paint()..color = const Color(0xFFB9F2FF),
    );
    canvas.restore();

    final highlightAngle = rotation * 0.8;
    final highlight = Offset(
      center.dx + math.cos(highlightAngle) * radius * 0.43,
      center.dy + math.sin(highlightAngle) * radius * 0.25,
    );
    canvas.drawCircle(
      highlight,
      radius * 0.12,
      Paint()
        ..shader =
            RadialGradient(
              colors: [
                AppTheme.adaptiveWhite(alpha: 0.80),
                AppTheme.adaptiveWhite(alpha: 0.0),
              ],
            ).createShader(
              Rect.fromCircle(center: highlight, radius: radius * 0.12),
            ),
    );
  }

  @override
  bool shouldRepaint(covariant _Feed3DWorldPainter oldDelegate) =>
      oldDelegate.progress != progress;
}

