class GalaxyBackground extends StatefulWidget {
  final bool animatePlanets;
  final bool animateCryptoCoins;
  final bool cinematicEntrance;
  final Duration animationDuration;
  final bool pauseMotion;

  const GalaxyBackground({
    super.key,
    this.animatePlanets = false,
    this.animateCryptoCoins = false,
    this.cinematicEntrance = false,
    this.animationDuration = const Duration(seconds: 45),
    this.pauseMotion = false,
  });

  @override
  State<GalaxyBackground> createState() => _GalaxyBackgroundState();
}

class _GalaxyBackgroundState extends State<GalaxyBackground>
    with TickerProviderStateMixin {
  late final AnimationController motionController;
  late final AnimationController entranceController;

  @override
  void initState() {
    super.initState();
    motionController = AnimationController(
      vsync: this,
      duration: widget.animationDuration,
    );
    if (!widget.pauseMotion) {
      motionController.repeat();
    }
    entranceController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1400),
    );
    if (widget.cinematicEntrance) {
      entranceController.forward();
    } else {
      entranceController.value = 1;
    }
  }

  @override
  void didUpdateWidget(covariant GalaxyBackground oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.pauseMotion != oldWidget.pauseMotion) {
      if (widget.pauseMotion) {
        motionController.stop(canceled: false);
      } else if (!motionController.isAnimating) {
        motionController.repeat();
      }
    }
  }

  @override
  void dispose() {
    motionController.dispose();
    entranceController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (Theme.of(context).brightness == Brightness.light) {
      return Positioned.fill(child: Container(color: const Color(0xFFF4F0E8)));
    }
    return Positioned.fill(
      child: AnimatedBuilder(
        animation: Listenable.merge([motionController, entranceController]),
        builder: (context, child) {
          // The galaxy is deliberately slow. Repainting it on every 60Hz frame
          // competes with scrolling and touch input. Quantizing the slow motion
          // to ~20 visual updates/sec keeps the background alive while leaving
          // the UI thread more headroom for gestures and lists.
          final sampledMotion = (motionController.value * 900).floor() / 900.0;
          return RepaintBoundary(
            child: CustomPaint(
              painter: StarPainter(
                sampledMotion,
                animatePlanets: widget.animatePlanets,
                animateCryptoCoins: widget.animateCryptoCoins,
                lightMode: Theme.of(context).brightness == Brightness.light,
                matteBlackMode: appThemePreference.value == 'dark',
                reveal: Curves.easeOutCubic.transform(entranceController.value),
              ),
            ),
          );
        },
      ),
    );
  }
}

class StarPainter extends CustomPainter {
  final double progress;
  final bool animatePlanets;
  final bool animateCryptoCoins;
  final bool lightMode;
  final bool matteBlackMode;
  final double reveal;

  StarPainter(
    this.progress, {
    this.animatePlanets = false,
    this.animateCryptoCoins = false,
    this.lightMode = false,
    this.matteBlackMode = false,
    this.reveal = 1.0,
  });

  @override
  void paint(Canvas canvas, Size size) {
    // In the explicit Dark Theme, the background is a completely solid
    // matte black surface. No stars, shimmer, sweep, texture, or gradient
    // is painted behind the existing interface.
    if (matteBlackMode) {
      canvas.drawColor(Colors.black, BlendMode.srcOver);
      return;
    }

    final eased = Curves.easeInOutSine.transform(progress);
    final base = Paint()
      ..shader = LinearGradient(
        begin: Alignment.topLeft,
        end: Alignment.bottomRight,
        colors: lightMode
            ? const [Color(0xFFF1EBDD), Color(0xFFF8F4EA), Color(0xFFEAE4D7)]
            : const [Color(0xFF000000), Color(0xFF030303), Color(0xFF000000)],
      ).createShader(Offset.zero & size);
    canvas.drawRect(Offset.zero & size, base);

    // Matte-black luxury texture with dense micro-speckles and a very slow,
    // continuous shimmer. No planets, crypto logos or coin marks.
    final width = size.width;
    final height = size.height;
    for (int i = 0; i < 360; i++) {
      final seed = i * 17.371;
      final bx = ((math.sin(seed * 1.731) + 1) * 0.5) * width;
      final by = ((math.cos(seed * 1.193) + 1) * 0.5) * height;
      final drift = progress * math.pi * 2 * (0.020 + (i % 7) * 0.0025);
      final x = (bx + math.sin(drift + seed) * width * 0.010) % width;
      final y = (by + math.cos(drift * 0.73 + seed) * height * 0.008) % height;
      final twinkle =
          0.10 +
          0.52 *
              ((math.sin(
                        progress * math.pi * 2 * (0.18 + (i % 5) * 0.035) +
                            seed,
                      ) +
                      1) /
                  2);
      final radius = 0.35 + (i % 5) * 0.17;
      final speckleColor = lightMode
          ? const Color(0xFF7D7567)
          : AppTheme.textPrimary;
      final paint = Paint()
        ..color = speckleColor.withValues(
          alpha: twinkle * (i % 9 == 0 ? 0.52 : 0.30),
        );
      canvas.drawCircle(Offset(x, y), radius, paint);
      if (i % 17 == 0) {
        final glowColor = lightMode
            ? const Color(0xFF9A8C70)
            : AppTheme.textPrimary;
        final glow = Paint()
          ..color = glowColor.withValues(
            alpha: twinkle * (lightMode ? 0.07 : 0.16),
          )
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 4.0);
        canvas.drawCircle(Offset(x, y), radius * 3.8, glow);
      }
    }

    final sweepX = width * (-0.35 + eased * 1.70);
    final sweep = Paint()
      ..shader = RadialGradient(
        center: Alignment((sweepX / width) * 2 - 1, 0.05),
        radius: 1.15,
        colors: const [Color(0x1FFFFFFF), Color(0x08FFFFFF), Color(0x00000000)],
        stops: const [0.0, 0.22, 1.0],
      ).createShader(Offset.zero & size);
    canvas.drawRect(Offset.zero & size, sweep);

    for (int i = 0; i < 34; i++) {
      final seed = i * 29.17 + 4.0;
      final x0 = ((math.sin(seed) + 1) * 0.5) * width;
      final y0 = ((math.cos(seed * 0.71) + 1) * 0.5) * height;
      final phase = progress * math.pi * 2 * 0.055 + seed;
      final x = (x0 + math.sin(phase) * width * 0.022) % width;
      final y = (y0 + math.cos(phase * 0.81) * height * 0.018) % height;
      final alpha = 0.18 + 0.62 * ((math.sin(phase * 1.7) + 1) / 2);
      final p = Paint()
        ..color = (lightMode ? const Color(0xFF756C5D) : AppTheme.textPrimary)
            .withValues(alpha: alpha * (lightMode ? 0.42 : 1.0));
      canvas.drawCircle(Offset(x, y), 0.9 + (i % 3) * 0.35, p);
      if (i % 4 == 0) {
        final glow = Paint()
          ..color = AppTheme.adaptiveWhite(alpha: alpha * 0.22)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6);
        canvas.drawCircle(Offset(x, y), 4.5, glow);
      }
    }
  }

  @override
  bool shouldRepaint(covariant StarPainter oldDelegate) {
    return oldDelegate.progress != progress ||
        oldDelegate.animatePlanets != animatePlanets ||
        oldDelegate.animateCryptoCoins != animateCryptoCoins ||
        oldDelegate.matteBlackMode != matteBlackMode ||
        oldDelegate.reveal != reveal;
  }
}

