class _AlphaDenPortal3DOrbitPainter extends CustomPainter {
  final double progress;
  final double centerRadius;
  final Color color;

  const _AlphaDenPortal3DOrbitPainter({
    required this.progress,
    required this.centerRadius,
    required this.color,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height / 2);
    final t = progress * math.pi * 2;
    final green = AppTheme.neonGreen;

    final orbits = <_DashboardOrbit3D>[
      _DashboardOrbit3D(118, 30, -0.25, 0.62, color, 0.80, phase: 0.20),
      _DashboardOrbit3D(108, 40, 0.68, -0.54, green, 0.72, phase: 1.10),
      _DashboardOrbit3D(98, 50, -1.00, 0.46, color, 0.62, phase: 2.05),
      _DashboardOrbit3D(86, 60, 0.32, -0.38, green, 0.54, phase: 2.80),
      _DashboardOrbit3D(72, 70, 1.12, 0.30, color, 0.46, phase: 3.55),
    ];

    for (var i = 0; i < orbits.length; i++) {
      if (i.isOdd) continue;
      _drawOrbit(canvas, center, orbits[i], t, i, front: false);
    }

    final nucleusPaint = Paint()
      ..style = PaintingStyle.fill
      ..color = AppTheme.adaptiveSurface(Color(0xFF080B0F));
    canvas.drawCircle(center, centerRadius, nucleusPaint);

    final nucleusBorder = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.6
      ..color = color.withValues(alpha: 0.95);
    canvas.drawCircle(center, centerRadius, nucleusBorder);

    final glow = Paint()
      ..color = color.withValues(alpha: 0.16)
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 12);
    canvas.drawCircle(center, centerRadius - 2, glow);

    for (var i = 0; i < orbits.length; i++) {
      if (i.isEven) continue;
      _drawOrbit(canvas, center, orbits[i], t, i, front: true);
    }
  }

  void _drawOrbit(
    Canvas canvas,
    Offset center,
    _DashboardOrbit3D orbit,
    double t,
    int index, {
    required bool front,
  }) {
    final direction = index.isEven ? 1.0 : -1.0;
    final rotation = orbit.baseRotation + t * orbit.speed * direction;

    canvas.save();
    canvas.translate(center.dx, center.dy);
    canvas.rotate(rotation);

    final rect = Rect.fromCenter(
      center: Offset.zero,
      width: orbit.width,
      height: orbit.height,
    );

    final paint = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 0.9
      ..isAntiAlias = true
      ..color = orbit.color.withValues(
        alpha: front ? orbit.alpha : orbit.alpha * 0.48,
      );
    canvas.drawOval(rect, paint);

    final glow = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2.6
      ..isAntiAlias = true
      ..color = orbit.color.withValues(
        alpha: front ? orbit.alpha * 0.10 : orbit.alpha * 0.055,
      )
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 2.8);
    canvas.drawOval(rect, glow);

    final a = t * orbit.speed * direction + orbit.phase;
    final dot = Offset(
      math.cos(a) * orbit.width * 0.5,
      math.sin(a) * orbit.height * 0.5,
    );
    final dotPaint = Paint()
      ..color = orbit.color
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 2.0);
    canvas.drawCircle(dot, front ? 2.8 : 2.3, dotPaint);

    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _AlphaDenPortal3DOrbitPainter oldDelegate) {
    return oldDelegate.progress != progress ||
        oldDelegate.centerRadius != centerRadius ||
        oldDelegate.color != color;
  }
}

