class _MentorshipChatRoomPageState extends State<_MentorshipChatRoomPage> {
  final TextEditingController _controller = TextEditingController();
  final ScrollController _scrollController = ScrollController();
  bool _sending = false;
  int _cooldown = 0;
  Timer? _cooldownTimer;
  bool _showReactionsFor(String id) => _reactionMessageId == id;
  String? _reactionMessageId;
  final List<_OptimisticChatMessage> _optimisticMessages =
      <_OptimisticChatMessage>[];
  Uint8List? _pendingImageBytes;
  String? _pendingImageExtension;
  String? _pendingImageName;
  Future<String?>? _pendingUploadFuture;

  @override
  void dispose() {
    _cooldownTimer?.cancel();
    _controller.dispose();
    _scrollController.dispose();
    super.dispose();
  }

  Future<String> _currentName() async {
    final uid = AuthService.currentUser?.uid;
    if (uid == null) return 'Mentorship Student';
    final data = await MentorshipService.loadMyMentorship(uid) ?? {};
    return (data['displayName'] ??
            data['name'] ??
            AuthService.currentUser?.displayName ??
            'Mentorship Student')
        .toString();
  }

  void _startCooldown() {
    _cooldownTimer?.cancel();
    setState(() => _cooldown = 5);
    _cooldownTimer = Timer.periodic(const Duration(seconds: 1), (timer) {
      if (!mounted) return timer.cancel();
      if (_cooldown <= 1) {
        timer.cancel();
        setState(() => _cooldown = 0);
      } else {
        setState(() => _cooldown--);
      }
    });
  }

  Future<void> _send({String? imageUrl}) async {
    if (_sending || _cooldown > 0) return;
    final uid = AuthService.currentUser?.uid;
    if (uid == null) return;
    final text = _controller.text.trim();
    final hasPendingImage = _pendingImageBytes != null;
    if (text.isEmpty &&
        (imageUrl == null || imageUrl.isEmpty) &&
        !hasPendingImage)
      return;

    final name = AuthService.currentUser?.displayName?.trim().isNotEmpty == true
        ? AuthService.currentUser!.displayName!.trim()
        : 'Mentorship Student';
    final messageId = MentorshipService.newChatMessageId();

    setState(() => _sending = true);
    try {
      String? finalImageUrl = imageUrl;
      if (finalImageUrl == null && hasPendingImage) {
        // The upload begins when the screenshot is selected, so Send normally
        // waits only for the already-running upload rather than starting it.
        finalImageUrl = await (_pendingUploadFuture ??=
            _uploadPendingScreenshot(
              uid,
              _pendingImageBytes!,
              _pendingImageExtension ?? 'jpg',
            ));
        if (finalImageUrl == null || finalImageUrl.isEmpty) {
          throw StateError(
            'Screenshot upload failed. Please try sending the screenshot again.',
          );
        }
      }

      final optimistic = _OptimisticChatMessage(messageId, <String, dynamic>{
        'senderUid': uid,
        'senderName': name,
        'text': text,
        if (finalImageUrl != null && finalImageUrl.isNotEmpty)
          'imageUrl': finalImageUrl,
        'reactions': <String, dynamic>{},
        'createdAt': Timestamp.fromDate(DateTime.now()),
      });

      // Render locally first. Firebase synchronization continues immediately in
      // the background, while server-side rules remain authoritative.
      setState(() {
        _optimisticMessages.insert(0, optimistic);
        _controller.clear();
        _pendingImageBytes = null;
        _pendingImageExtension = null;
        _pendingImageName = null;
        _pendingUploadFuture = null;
        _reactionMessageId = null;
      });
      _startCooldown();

      await MentorshipService.sendChatMessage(
        uid: uid,
        name: name,
        text: text,
        imageUrl: finalImageUrl,
        messageId: messageId,
      );
      if (mounted) {
        setState(
          () => _optimisticMessages.removeWhere((m) => m.id == messageId),
        );
      }
    } catch (e) {
      if (mounted) {
        setState(
          () => _optimisticMessages.removeWhere((m) => m.id == messageId),
        );
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(e.toString().replaceFirst('Bad state: ', ''))),
        );
      }
    } finally {
      if (mounted) setState(() => _sending = false);
    }
  }

  Future<String?> _uploadPendingScreenshot(
    String uid,
    Uint8List bytes,
    String extension,
  ) async {
    try {
      return await MentorshipService.uploadChatScreenshot(
        uid: uid,
        bytes: bytes,
        extension: extension,
      );
    } catch (_) {
      return null;
    }
  }

  Future<void> _pickScreenshot() async {
    if (_sending || _cooldown > 0) return;
    final picked = await ImagePicker().pickImage(
      source: ImageSource.gallery,
      imageQuality: 70,
      maxWidth: 1600,
      maxHeight: 1600,
    );
    if (picked == null) return;
    final mime = (picked.mimeType ?? '').toLowerCase();
    final name = picked.name.toLowerCase();
    final allowed =
        mime.startsWith('image/') ||
        name.endsWith('.png') ||
        name.endsWith('.jpg') ||
        name.endsWith('.jpeg') ||
        name.endsWith('.webp');
    if (!allowed || name.endsWith('.gif')) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Only screenshot/image files are allowed.'),
          ),
        );
      return;
    }
    try {
      final bytes = await picked.readAsBytes();
      if (bytes.length > 4 * 1024 * 1024) {
        if (mounted)
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text(
                'Image is too large. Please choose an image under 4 MB.',
              ),
            ),
          );
        return;
      }
      final ext = name.contains('.') ? name.split('.').last : 'jpg';
      if (!mounted) return;
      setState(() {
        _pendingImageBytes = bytes;
        _pendingImageExtension = ext;
        _pendingImageName = picked.name;
        // Pre-upload immediately after selection. The user can continue typing
        // while the image upload runs in the background.
        _pendingUploadFuture = _uploadPendingScreenshot(
          AuthService.currentUser?.uid ?? '',
          bytes,
          ext,
        );
      });
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context)
            .showSnackBar(SnackBar(content: Text('Could not load image: $e')));
    }
  }

  void _removePendingImage() {
    if (!mounted) return;
    setState(() {
      _pendingImageBytes = null;
      _pendingImageExtension = null;
      _pendingImageName = null;
      _pendingUploadFuture = null;
    });
  }

  Future<void> _react(
    String messageId,
    String reaction,
    Map<String, dynamic> reactions,
  ) async {
    final uid = AuthService.currentUser?.uid;
    if (uid == null) return;
    try {
      if (reactions[uid] == reaction) {
        await MentorshipService.removeChatReaction(
          messageId: messageId,
          uid: uid,
        );
      } else {
        await MentorshipService.setChatReaction(
          messageId: messageId,
          uid: uid,
          reaction: reaction,
        );
      }
      if (mounted) setState(() => _reactionMessageId = null);
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not update reaction: $e')),
        );
    }
  }

  void _showReactionPicker(String messageId, Map<String, dynamic> reactions) {
    setState(
      () => _reactionMessageId = _reactionMessageId == messageId
          ? null
          : messageId,
    );
  }

  Future<void> _clearMentorshipChat() async {
    if (!widget.isAdmin) return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dc) => AlertDialog(
        backgroundColor: Colors.black,
        title: const Text(
          'CLEAR MENTORSHIP CHAT',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
        content: const Text(
          'This will permanently clear the current Mentorship Chat history for all authorized users. Public Chat, private chats, mentorship access, and notification settings are not affected.',
          style: TextStyle(color: Colors.white70),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dc, false),
            child: const Text('CANCEL'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dc, true),
            child: const Text('CLEAR CHAT'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    try {
      final count = await MentorshipService.adminClearMentorshipChat();
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Mentorship Chat cleared. $count messages removed.'),
          ),
        );
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Could not clear Mentorship Chat: $e')),
        );
    }
  }

