                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                Expanded(
                  child: members.isEmpty
                      ? Center(
                          child: Text(
                            'No chat members yet.',
                            style: TextStyle(color: AppTheme.textMuted),
                          ),
                        )
                      : ListView.separated(
                          itemCount: members.length,
                          separatorBuilder: (_, __) => Divider(
                            color: AppTheme.textPrimary.withOpacity(.08),
                          ),
                          itemBuilder: (_, i) {
                            final d = members[i].data();
                            final uid = members[i].id;
                            final active = d['active'] != false;
                            final banned = d['banned'] == true;
                            return ListTile(
                              contentPadding: EdgeInsets.zero,
                              title: Text(
                                (d['name'] ?? uid).toString(),
                                style: TextStyle(
                                  color: AppTheme.textPrimary,
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                              subtitle: Text(
                                banned
                                    ? 'BANNED'
                                    : (active ? 'ACTIVE' : 'REMOVED'),
                                style: TextStyle(
                                  color: banned
                                      ? Colors.redAccent
                                      : AppTheme.textMuted,
                                  fontSize: 10,
                                ),
                              ),
                              trailing: PopupMenuButton<String>(
                                icon: Icon(
                                  Icons.more_vert,
                                  color: AppTheme.textPrimary,
                                ),
                                onSelected: (action) async {
                                  try {
                                    if (action == 'remove')
                                      await MentorshipService.adminSetChatMember(
                                        uid: uid,
                                        active: false,
                                        banned: false,
                                      );
                                    if (action == 'restore')
                                      await MentorshipService.adminSetChatMember(
                                        uid: uid,
                                        active: true,
                                        banned: false,
                                      );
                                    if (action == 'ban')
                                      await MentorshipService.adminSetChatMember(
                                        uid: uid,
                                        active: false,
                                        banned: true,
                                      );
                                    if (action == '30')
                                      await MentorshipService.adminSetChatMember(
                                        uid: uid,
                                        active: true,
                                        banned: false,
                                        restrictedUntil: DateTime.now().add(
                                          const Duration(minutes: 30),
                                        ),
                                      );
                                    if (action == '5')
                                      await MentorshipService.adminSetChatMember(
                                        uid: uid,
                                        active: true,
                                        banned: false,
                                        restrictedUntil: DateTime.now().add(
                                          const Duration(minutes: 5),
                                        ),
                                      );
                                    if (sheetContext.mounted)
                                      Navigator.pop(sheetContext);
                                    if (mounted) _openModeration();
                                  } catch (e) {
                                    if (mounted)
                                      ScaffoldMessenger.of(context)
                                          .showSnackBar(
                                            SnackBar(
                                              content: Text(
                                                'Moderation action failed: $e',
                                              ),
                                            ),
                                          );
                                  }
                                },
                                itemBuilder: (_) => [
                                  if (!active || banned)
                                    const PopupMenuItem(
                                      value: 'restore',
                                      child: Text('Restore access'),
                                    ),
                                  if (active && !banned)
                                    const PopupMenuItem(
                                      value: 'remove',
                                      child: Text('Remove from group'),
                                    ),
                                  if (!banned)
                                    const PopupMenuItem(
                                      value: 'ban',
                                      child: Text('Ban messaging'),
                                    ),
                                  const PopupMenuItem(
                                    value: '5',
                                    child: Text('Restrict for 5 minutes'),
                                  ),
                                  const PopupMenuItem(
                                    value: '30',
                                    child: Text('Restrict for 30 minutes'),
                                  ),
                                ],
                              ),
                            );
                          },
                        ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

