  Widget _messageBubble(String messageId, Map<String, dynamic> d) {
    final uid = AuthService.currentUser?.uid ?? '';
    final mine = d['senderUid'] == uid;
    final reactions = Map<String, dynamic>.from((d['reactions'] as Map?) ?? {});
    final created = d['createdAt'];
    final time = created is Timestamp ? created.toDate().toLocal() : null;
    final imageUrl = (d['imageUrl'] ?? '').toString();
    final text = (d['text'] ?? '').toString();
    final grouped = <String, int>{};
    for (final r in reactions.values)
      grouped[r.toString()] = (grouped[r.toString()] ?? 0) + 1;
    return Align(
      alignment: mine ? Alignment.centerRight : Alignment.centerLeft,
      child: GestureDetector(
        onTap: () => _showReactionPicker(messageId, reactions),
        child: Container(
          constraints: BoxConstraints(
            maxWidth: MediaQuery.of(context).size.width * .78,
          ),
          margin: EdgeInsets.fromLTRB(mine ? 45 : 10, 4, mine ? 10 : 45, 4),
          padding: const EdgeInsets.fromLTRB(11, 8, 11, 7),
          decoration: BoxDecoration(
            color: mine ? const Color(0xFF075E54) : const Color(0xFF202C33),
            borderRadius: BorderRadius.only(
              topLeft: const Radius.circular(14),
              topRight: const Radius.circular(14),
              bottomLeft: Radius.circular(mine ? 14 : 4),
              bottomRight: Radius.circular(mine ? 4 : 14),
            ),
            border: Border.all(color: AppTheme.textPrimary.withOpacity(.10)),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              if (!mine)
                Padding(
                  padding: const EdgeInsets.only(bottom: 3),
                  child: Text(
                    (d['senderName'] ?? 'Mentorship Student').toString(),
                    style: TextStyle(
                      color: AppTheme.textPrimary,
                      fontSize: 10.5,
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                ),
              if (imageUrl.isNotEmpty)
                GestureDetector(
                  onTap: () => showDialog<void>(
                    context: context,
                    builder: (_) => Dialog(
                      backgroundColor: Colors.black,
                      insetPadding: const EdgeInsets.all(12),
                      child: InteractiveViewer(
                        minScale: 0.8,
                        maxScale: 4,
                        child: _DriveAwareImage(
                          source: imageUrl,
                          fit: BoxFit.contain,
                          errorText: 'Screenshot unavailable',
                        ),
                      ),
                    ),
                  ),
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(10),
                    child: _DriveAwareImage(
                      source: imageUrl,
                      width: 220,
                      fit: BoxFit.cover,
                      errorText: 'Screenshot unavailable',
                    ),
                  ),
