                      if (snap.hasError)
                        return Center(
                          child: Text(
                            'Unable to load chat.',
                            style: TextStyle(color: AppTheme.textMuted),
                          ),
                        );
                      if (!snap.hasData)
                        return const Center(child: CircularProgressIndicator());
                      final docs = snap.data!.docs;
                      final serverIds = docs.map((d) => d.id).toSet();
                      final pending = _optimisticMessages
                          .where((m) => !serverIds.contains(m.id))
                          .toList();
                      if (docs.isEmpty && pending.isEmpty)
                        return Center(
                          child: Text(
                            'No messages yet. Start the conversation.',
                            style: TextStyle(color: AppTheme.textMuted),
                          ),
                        );
