                        controller: _scrollController,
                        reverse: true,
                        padding: const EdgeInsets.fromLTRB(4, 12, 4, 12),
                        itemCount: docs.length + pending.length,
                        itemBuilder: (_, i) {
                          if (i < pending.length) {
                            final m = pending[i];
                            return _messageBubble(m.id, m.data);
                          }
                          final d = docs[i - pending.length];
                          return _messageBubble(d.id, d.data());
                        },
                      );
